window.KH_COURSES=[{"id":"KH001","code":"kh001","f":"KT","fn":"Kế toán","t":"Kế toán cho người mới bắt đầu: hiểu từ con số 0","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp người chưa từng học kế toán hiểu doanh nghiệp vận hành bằng con số như thế nào, từ một tờ hóa đơn đến bảng báo cáo cuối năm. Bạn học qua tình huống của một cửa hàng và một công ty nhỏ có thật về quy mô, dùng ngay bộ mẫu sổ thu chi và bảng tổng hợp đã thiết kế sẵn. Sau 8 giờ, bạn đọc được báo cáo cơ bản, tự ghi được bút toán đơn giản và biết đặt câu hỏi đúng cho kế toán hoặc trợ lý AI.","a":"Người mới bắt đầu, sinh viên trái ngành, chủ hộ kinh doanh và chủ doanh nghiệp nhỏ muốn tự hiểu và kiểm soát con số của chính mình.","o":["Phân loại đúng tài sản, nợ phải trả, vốn chủ sở hữu, doanh thu, chi phí cho ít nhất 20 nghiệp vụ thường gặp.","Ghi được bút toán Nợ – Có cho các nghiệp vụ thu, chi, mua, bán, góp vốn, vay cơ bản.","Lập được bảng cân đối tài khoản đơn giản và tự kiểm tra tổng Nợ bằng tổng Có.","Đọc được bảng cân đối kế toán và báo cáo kết quả kinh doanh của một doanh nghiệp nhỏ trong 10 phút.","Tự lập được sổ thu chi và báo cáo lãi lỗ hằng tháng cho cửa hàng hoặc hộ kinh doanh của mình."],"k":"Năm 2026 hộ kinh doanh tự kê khai, AI lo nhập liệu: ai không đọc được con số sẽ bị bỏ lại.","w":["Từ 01/01/2026 bỏ thuế khoán và lệ phí môn bài với hộ kinh doanh, chuyển sang tự kê khai: chủ hộ buộc phải có sổ sách và hiểu doanh thu, chi phí.","Hóa đơn điện tử, sao kê ngân hàng và phần mềm kế toán online đã số hóa gần như toàn bộ dữ liệu; người biết kế toán căn bản sẽ khai thác được dữ liệu đó thay vì chỉ nhìn số dư tài khoản.","AI đang đảm nhận phần nhập liệu lặp lại, nên thị trường cần người hiểu bản chất nghiệp vụ để kiểm tra, ra quyết định và chịu trách nhiệm với con số."],"dl":["Bộ mẫu Excel « Sổ kế toán tối giản »: sổ thu chi, sổ công nợ, bảng cân đối tài khoản và báo cáo lãi lỗ tự động.","Sơ đồ một trang « Từ chứng từ đến báo cáo » để dán bàn làm việc.","Checklist 30 nghiệp vụ thường gặp kèm bút toán mẫu cho người mới.","Bộ 15 câu lệnh AI (prompt) để nhờ trợ lý AI giải thích nghiệp vụ, kiểm tra bút toán và đọc báo cáo."],"ls":["Kế toán là ngôn ngữ của kinh doanh: vì sao ai cũng cần biết","Phương trình kế toán: một đẳng thức giải thích mọi thứ","Tài khoản và ghi sổ kép: đọc hiểu Nợ – Có không còn mơ hồ","Chứng từ: bằng chứng phía sau mọi con số","Doanh thu, chi phí và lợi nhuận: hiểu đúng để không tự lừa mình","Từ sổ sách đến báo cáo: chu trình kế toán trong một tháng","Dùng AI và phần mềm online làm trợ lý kế toán cá nhân","Đọc báo cáo tài chính trong 10 phút và lộ trình học tiếp"],"l1":{"t":"Kế toán là ngôn ngữ của kinh doanh: vì sao ai cũng cần biết","sum":"Bài mở đầu cho thấy kế toán không chỉ là ghi chép mà là hệ thống thông tin giúp chủ doanh nghiệp, ngân hàng, cơ quan thuế ra quyết định. Học viên hiểu ai dùng thông tin kế toán và họ cần gì.","points":["Kế toán thu thập, xử lý, kiểm tra, phân tích và cung cấp thông tin kinh tế, tài chính bằng thước đo giá trị, hiện vật và thời gian lao động.","Người dùng bên trong (chủ, quản lý) cần biết lãi lỗ, dòng tiền; người dùng bên ngoài (ngân hàng, nhà đầu tư, cơ quan thuế) cần báo cáo trung thực, đúng chuẩn mực.","Kế toán tài chính phục vụ báo cáo theo quy định; kế toán quản trị phục vụ quyết định nội bộ như định giá, cắt giảm chi phí.","Doanh nghiệp nhỏ và vừa thường áp dụng chế độ kế toán theo TT 133/2016; doanh nghiệp lớn áp dụng chế độ thay thế TT 200/2014 là TT 99/2025 từ 01/01/2026.","Một con số sai ở khâu ghi chép sẽ đi thẳng vào báo cáo và tờ khai thuế, nên hiểu nguyên tắc từ đầu rẻ hơn rất nhiều so với sửa sai về sau."],"case":"Chị Lan, chủ cửa hàng mỹ phẩm, thấy tài khoản ngân hàng có 300 triệu nên nghĩ đang lãi. Khi lập bảng đơn giản, chị phát hiện còn nợ nhà cung cấp 220 triệu và hàng tồn chậm bán 150 triệu, lãi thực chỉ khoảng 40 triệu. Từ đó chị tách tiền cá nhân khỏi tiền cửa hàng và ghi sổ thu chi hằng ngày.","trend":"Đến 2030, phần lớn nghiệp vụ ghi sổ sẽ được tự động hóa từ hóa đơn điện tử và dữ liệu ngân hàng; giá trị của người làm kế toán chuyển sang đọc hiểu và tư vấn. Hãy học để hiểu, không chỉ để nhập.","practice":"Liệt kê 10 khoản tiền vào và ra của bạn hoặc cửa hàng trong tuần qua, ghi rõ khoản nào là doanh thu, chi phí, vay, trả nợ hay rút vốn.","takeaway":"Tiền trong tài khoản không phải là lợi nhuận; kế toán giúp bạn thấy sự khác biệt đó."}},{"id":"KH002","code":"kh002","f":"KT","fn":"Kế toán","t":"Nguyên lý kế toán và hệ thống tài khoản theo Thông tư 133","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học xây nền nguyên lý kế toán vững chắc và giúp bạn sử dụng thành thạo hệ thống tài khoản theo TT 133/2016 cho doanh nghiệp nhỏ và vừa. Mỗi nhóm tài khoản được học qua tình huống thật của doanh nghiệp thương mại, dịch vụ, kèm bảng định khoản mẫu dùng ngay. Kết thúc khoá, bạn tự hạch toán trọn một tháng nghiệp vụ, kết chuyển lãi lỗ và lập được bảng cân đối số phát sinh chính xác.","a":"Kế toán mới vào nghề, sinh viên kế toán, kế toán hộ kinh doanh chuyển lên doanh nghiệp và chủ doanh nghiệp nhỏ muốn tự kiểm soát sổ sách.","o":["Trình bày được 8 nguyên tắc kế toán cơ bản và áp dụng đúng vào tình huống ghi nhận doanh thu, chi phí, tài sản.","Sử dụng đúng tài khoản cấp 1 và cấp 2 của TT 133 cho ít nhất 50 nghiệp vụ phổ biến.","Hạch toán trọn một tháng nghiệp vụ của doanh nghiệp thương mại nhỏ với sai sót dưới 5%.","Thực hiện đúng các bút toán kết chuyển cuối kỳ về TK 911 và xác định lợi nhuận, thuế TNDN tạm tính.","Lập được bảng cân đối số phát sinh và tự phát hiện, sửa lỗi bằng 3 phương pháp chữa sổ."],"k":"Phần mềm và AI tự hạch toán, nhưng chỉ người vững tài khoản TT 133 mới biết máy sai ở đâu.","w":["Hộ kinh doanh bỏ thuế khoán từ 01/01/2026 và nhiều hộ lớn chuyển lên doanh nghiệp, kéo theo nhu cầu lớn về kế toán thành thạo TT 133.","Luật TNDN 67/2025/QH15 áp thuế suất 15% và 17% cho doanh nghiệp nhỏ theo doanh thu; hạch toán đúng doanh thu, chi phí quyết định trực tiếp số thuế phải nộp.","Phần mềm kế toán online và AI tự gợi ý định khoản; người hiểu nguyên lý sẽ chuyển từ vai trò nhập liệu sang vai trò kiểm soát, có thu nhập cao hơn."],"dl":["Bảng tra hệ thống tài khoản TT 133 bằng tiếng Việt dễ hiểu, kèm ví dụ nghiệp vụ cho từng tài khoản.","Bộ mẫu Excel thực hành: nhật ký chung, sổ cái, bảng cân đối số phát sinh có công thức kiểm tra tự động.","Checklist khóa sổ cuối tháng 15 bước cho doanh nghiệp nhỏ và vừa.","Bộ 20 câu lệnh AI (prompt) hỗ trợ định khoản, rà soát sổ cái và giải thích chênh lệch số dư."],"ls":["Tám nguyên tắc kế toán: luật chơi đứng sau mọi bút toán","Bản đồ hệ thống tài khoản TT 133: đọc một lần, nhớ lâu","Kế toán tiền, công nợ và thuế GTGT: các bút toán xuất hiện mỗi ngày","Hàng tồn kho, tài sản cố định và chi phí trả trước theo TT 133","Lương, bảo hiểm và các khoản phải trả khác","Kết chuyển cuối kỳ và xác định kết quả kinh doanh","Bảng cân đối số phát sinh và kỹ thuật tìm, sửa sai sót","Tự động hóa sổ sách với phần mềm online và AI: từ người ghi sổ thành người kiểm soát"],"l1":{"t":"Tám nguyên tắc kế toán: luật chơi đứng sau mọi bút toán","sum":"Bài học làm rõ các nguyên tắc kế toán nền tảng và cách chúng quyết định thời điểm, giá trị ghi sổ. Học viên hiểu vì sao cùng một nghiệp vụ có thể ghi đúng hoặc sai.","points":["Cơ sở dồn tích: ghi nhận khi phát sinh, không phụ thuộc thời điểm thu chi tiền.","Giá gốc: tài sản ghi theo giá mua cộng chi phí liên quan trực tiếp đến khi sẵn sàng sử dụng.","Phù hợp: chi phí ghi nhận tương ứng với doanh thu mà nó tạo ra trong cùng kỳ.","Thận trọng: không đánh giá cao hơn giá trị tài sản và thu nhập, không đánh giá thấp nợ phải trả và chi phí; lập dự phòng khi có bằng chứng tổn thất.","Hoạt động liên tục, nhất quán, trọng yếu và kỳ kế toán giúp báo cáo so sánh được giữa các kỳ và giữa các doanh nghiệp."],"case":"Công ty TNHH Minh An ký hợp đồng bảo trì 12 tháng, thu trước 120 triệu vào tháng 1. Kế toán ghi toàn bộ vào doanh thu tháng 1 khiến tháng này lãi lớn, các tháng sau lỗ. Áp dụng nguyên tắc dồn tích và phù hợp, kế toán ghi nhận doanh thu chưa thực hiện và phân bổ 10 triệu mỗi tháng.","trend":"Chuẩn mực quốc tế IFRS đang được Việt Nam áp dụng theo lộ trình QĐ 345/QĐ-BTC; nắm vững nguyên tắc nền giúp bạn chuyển đổi sang IFRS dễ dàng hơn trong 2026–2030.","practice":"Phân tích 8 tình huống trong phiếu bài tập, chỉ ra nguyên tắc nào bị vi phạm và đề xuất cách ghi đúng.","takeaway":"Nắm nguyên tắc là nắm được lý do của mọi bút toán."}},{"id":"KH003","code":"kh003","f":"KT","fn":"Kế toán","t":"Hệ thống tài khoản theo Thông tư 200 cho doanh nghiệp lớn","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp kế toán doanh nghiệp quy mô lớn làm chủ hệ thống tài khoản theo TT 200/2014 và chuẩn bị chuyển đổi sang chế độ kế toán TT 99/2025 có hiệu lực từ 01/01/2026. Bạn học bằng tình huống của doanh nghiệp sản xuất, thương mại có nhiều chi nhánh, với bảng định khoản, bảng mapping tài khoản và checklist chuyển đổi dùng ngay. Kết thúc khoá, bạn tự tin xử lý các nhóm nghiệp vụ phức tạp và lập được kế hoạch chuyển đổi hệ thống tài khoản cho doanh nghiệp của mình.","a":"Kế toán tổng hợp, kế toán phần hành và trưởng nhóm kế toán tại doanh nghiệp lớn, công ty có vốn đầu tư nước ngoài, công ty đại chúng.","o":["Sử dụng đúng tài khoản cấp 1, cấp 2 cho các nhóm nghiệp vụ lớn: đầu tư tài chính, chi phí sản xuất, doanh thu, thuế hoãn lại.","Phân biệt được điểm khác nhau cơ bản giữa chế độ cho doanh nghiệp lớn và TT 133/2016 để tư vấn lựa chọn chế độ phù hợp.","Lập được bảng mapping số dư từ hệ thống tài khoản cũ sang hệ thống mới và kiểm tra tổng số dư không đổi.","Hạch toán chính xác các nghiệp vụ nội bộ giữa công ty mẹ, chi nhánh và đơn vị phụ thuộc.","Xây dựng được kế hoạch chuyển đổi chế độ kế toán 2026 gồm phạm vi, mốc thời gian và người chịu trách nhiệm."],"k":"TT 99/2025 thay TT 200 từ 2026: doanh nghiệp lớn cần kế toán vững hệ thống cũ, chuyển đổi đúng chế độ mới.","w":["TT 99/2025 thay thế TT 200/2014 từ 01/01/2026; số dư chuyển sang, chính sách kế toán và báo cáo năm 2026 phải được xử lý đúng ngay từ kỳ đầu.","Lộ trình áp dụng IFRS theo QĐ 345/QĐ-BTC tiếp tục mở rộng; nắm chắc hệ thống tài khoản Việt Nam là nền để mapping sang IFRS và lập báo cáo hợp nhất.","Doanh nghiệp lớn đang triển khai ERP và tự động hóa đóng sổ; người hiểu cấu trúc tài khoản sẽ là cầu nối giữa nghiệp vụ và đội công nghệ."],"dl":["Bảng mapping tài khoản Excel từ TT 200 sang TT 99 có cột ghi chú cần đối chiếu văn bản gốc và kiểm tra tổng tự động.","Checklist chuyển đổi chế độ kế toán 2026 gồm 25 đầu việc từ chính sách đến phần mềm.","Bộ định khoản mẫu cho 80 nghiệp vụ phức tạp của doanh nghiệp lớn.","Bộ 15 câu lệnh AI (prompt) hỗ trợ rà soát chính sách kế toán, mapping tài khoản và giải trình biến động số dư."],"ls":["Bức tranh chế độ kế toán doanh nghiệp 2026: TT 200, TT 99 và TT 133","Tài sản ngắn hạn: tiền, đầu tư tài chính, phải thu và dự phòng","Chi phí sản xuất trên hệ thống tài khoản doanh nghiệp lớn: 621, 622, 627, 154","Doanh thu, thu nhập và các khoản giảm trừ: ghi nhận đúng thời điểm","Nợ phải trả, vốn chủ sở hữu và thuế thu nhập hoãn lại","Nghiệp vụ nội bộ: công ty mẹ, chi nhánh và đơn vị phụ thuộc","Chuyển đổi hệ thống tài khoản sang chế độ mới: phương pháp mapping an toàn","Hệ thống tài khoản cho ERP, dữ liệu và IFRS: thiết kế cho 5 năm tới"],"l1":{"t":"Bức tranh chế độ kế toán doanh nghiệp 2026: TT 200, TT 99 và TT 133","sum":"Bài học đặt hệ thống tài khoản vào bối cảnh pháp lý mới: chế độ nào áp dụng cho ai, từ khi nào và doanh nghiệp phải chuẩn bị gì. Học viên hiểu rõ phạm vi để không áp dụng nhầm.","points":["TT 200/2014 là chế độ cho doanh nghiệp lớn đến hết năm tài chính 2025; TT 99/2025 thay thế từ 01/01/2026.","Doanh nghiệp nhỏ và vừa thường áp dụng TT 133/2016 nhưng có thể lựa chọn chế độ cho doanh nghiệp lớn nếu thông báo với cơ quan thuế và áp dụng nhất quán.","Chế độ kế toán gồm bốn phần: hệ thống tài khoản, chứng từ, sổ kế toán và báo cáo tài chính; mỗi phần đều cần rà soát khi chuyển đổi.","Các nội dung chi tiết của TT 99/2025 về tài khoản, biểu mẫu cần đối chiếu trực tiếp văn bản gốc; không áp dụng theo tóm tắt chưa kiểm chứng.","Chính sách kế toán thay đổi phải được thuyết minh trên báo cáo tài chính và xử lý số liệu so sánh theo chuẩn mực về thay đổi chính sách kế toán."],"case":"Công ty Cổ phần Minh An có 3 chi nhánh, đóng sổ năm 2025 theo TT 200. Tháng 1/2026 phần mềm vẫn chạy danh mục cũ nên báo cáo quý 1 không đúng biểu mẫu mới. Kế toán trưởng lập tổ chuyển đổi, rà soát danh mục, chuyển số dư theo bảng mapping và chạy song song một tháng trước khi khóa.","trend":"Giai đoạn 2026–2030, chế độ kế toán Việt Nam dự kiến tiếp tục tiệm cận IFRS; doanh nghiệp nên xây dựng hệ thống tài khoản chi tiết linh hoạt để đáp ứng cả báo cáo theo VAS và IFRS.","practice":"Lập bảng so sánh một trang giữa chế độ cho doanh nghiệp lớn và TT 133 cho doanh nghiệp của bạn, đề xuất chế độ phù hợp kèm 3 lý do.","takeaway":"Chọn đúng chế độ trước, rồi mới bàn đến chọn đúng tài khoản."}},{"id":"KH004","code":"kh004","f":"KT","fn":"Kế toán","t":"Chứng từ kế toán: lập, kiểm tra và lưu trữ đúng luật","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp bạn lập, kiểm tra và lưu trữ chứng từ kế toán đúng luật trong bối cảnh hóa đơn điện tử, chữ ký số và lưu trữ số đã trở thành chuẩn. Bạn học qua các hồ sơ chứng từ thật đã được ẩn danh, phân tích lỗi thường gặp và dùng ngay bộ mẫu phiếu thu, phiếu chi, đề nghị thanh toán, quy trình duyệt. Kết thúc khoá, bạn tự xây được bộ hồ sơ chứng từ sạch, tra cứu nhanh và sẵn sàng khi cơ quan thuế hay kiểm toán yêu cầu.","a":"Kế toán mới, nhân viên hành chính – thủ quỹ, chủ hộ kinh doanh chuyển sang tự kê khai và quản lý bộ phận cần duyệt chứng từ.","o":["Lập đúng 10 loại chứng từ phổ biến: phiếu thu, phiếu chi, đề nghị thanh toán, phiếu nhập, phiếu xuất, biên bản giao nhận, bảng chấm công, bảng lương, biên bản kiểm kê, giấy đề nghị tạm ứng.","Kiểm tra được tính hợp pháp, hợp lệ của hóa đơn điện tử đầu vào theo checklist 10 điểm trong dưới 2 phút mỗi hóa đơn.","Xây dựng được bộ hồ sơ chứng từ hoàn chỉnh cho một khoản chi gồm hợp đồng, hóa đơn, chứng từ thanh toán, biên bản nghiệm thu.","Thiết lập quy trình luân chuyển và phê duyệt chứng từ có phân quyền rõ ràng cho doanh nghiệp nhỏ.","Tổ chức lưu trữ chứng từ giấy và điện tử theo cấu trúc chuẩn, tìm lại một chứng từ bất kỳ trong dưới 3 phút."],"k":"Một hóa đơn sai, một khoản tiền mặt từ 5 triệu có thể mất chi phí được trừ năm 2026.","w":["Quy định hóa đơn điện tử theo NĐ 123/2020 sửa bởi NĐ 70/2025 từ 01/06/2025 mở rộng hóa đơn khởi tạo từ máy tính tiền, thay đổi cách lập và kiểm tra chứng từ bán lẻ.","Điều kiện thanh toán không dùng tiền mặt từ 5 triệu đồng theo NĐ 181/2025 khiến chứng từ thanh toán ngân hàng trở thành điều kiện để được khấu trừ và tính chi phí.","Cơ quan thuế đối chiếu dữ liệu hóa đơn, ngân hàng và tờ khai bằng công cụ phân tích; xử phạt theo NĐ 125/2020 sửa bởi NĐ 310/2025 hiệu lực từ 16/01/2026."],"dl":["Bộ mẫu chứng từ nội bộ Word và Excel: phiếu thu, phiếu chi, đề nghị thanh toán, tạm ứng, biên bản giao nhận, có hướng dẫn điền.","Checklist kiểm tra hóa đơn đầu vào 10 điểm và checklist hồ sơ chi phí theo từng loại khoản chi.","Quy trình SOP luân chuyển, phê duyệt và lưu trữ chứng từ kèm sơ đồ và quy tắc đặt tên file.","Bộ 12 câu lệnh AI (prompt) để đọc hóa đơn, đối chiếu chứng từ và lập bảng kê tự động."],"ls":["Chứng từ kế toán là gì và vì sao nó quyết định số thuế bạn phải nộp","Hóa đơn điện tử 2026: đọc, kiểm tra và xử lý sai sót","Chứng từ tiền: phiếu thu, phiếu chi, chứng từ ngân hàng và quy tắc 5 triệu","Chứng từ hàng hóa, tài sản và lao động: đủ bộ mới an toàn","Quy trình luân chuyển và phê duyệt: ai lập, ai kiểm, ai duyệt","Số hóa chứng từ: quét, đặt tên, lưu trữ và tra cứu trong 3 phút","AI đọc chứng từ: tự động hóa bảng kê và đối chiếu","Sẵn sàng khi bị kiểm tra: hồ sơ chứng từ chuẩn kiểm toán và thanh tra"],"l1":{"t":"Chứng từ kế toán là gì và vì sao nó quyết định số thuế bạn phải nộp","sum":"Bài mở đầu làm rõ khái niệm, vai trò pháp lý của chứng từ kế toán và mối liên hệ trực tiếp với chi phí được trừ, thuế được khấu trừ. Học viên hiểu vì sao chứng từ là bằng chứng chứ không phải thủ tục.","points":["Chứng từ kế toán là giấy tờ, vật mang tin phản ánh nghiệp vụ kinh tế đã phát sinh và hoàn thành, là căn cứ ghi sổ theo Luật Kế toán.","Một chứng từ đầy đủ có tên, số, ngày lập, thông tin các bên, nội dung nghiệp vụ, số lượng, đơn giá, số tiền và chữ ký người có liên quan.","Chi phí được trừ khi tính thuế TNDN cần gắn với hoạt động kinh doanh, có hóa đơn chứng từ hợp pháp và chứng từ thanh toán không dùng tiền mặt khi từ 5 triệu đồng.","Chứng từ sai hoặc thiếu có thể khiến chi phí bị loại, thuế GTGT không được khấu trừ, phát sinh tiền chậm nộp 0,03%/ngày và tiền phạt.","Chứng từ điện tử có giá trị như chứng từ giấy khi đáp ứng yêu cầu về giao dịch điện tử và chữ ký số."],"case":"Công ty TNHH Minh An chi 60 triệu thuê xe chở hàng trong năm nhưng chỉ có phiếu chi tiền mặt, không có hợp đồng và hóa đơn. Khi quyết toán, toàn bộ khoản này có nguy cơ bị loại khỏi chi phí được trừ. Kế toán đề xuất ký hợp đồng khung với nhà xe, nhận hóa đơn theo tháng và thanh toán chuyển khoản.","trend":"Quản lý thuế số đang chuyển sang đối chiếu dữ liệu tự động giữa hóa đơn, ngân hàng và tờ khai; chứng từ thiếu nhất quán sẽ bị cảnh báo sớm hơn. Hãy chuẩn hóa từ khâu lập.","practice":"Chọn 3 khoản chi gần nhất của doanh nghiệp, liệt kê các chứng từ đang có và đánh dấu chứng từ còn thiếu theo checklist hồ sơ chi phí.","takeaway":"Chứng từ không phải giấy tờ thủ tục; đó là bằng chứng bảo vệ doanh nghiệp."}},{"id":"KH005","code":"kh005","f":"KT","fn":"Kế toán","t":"Kế toán vốn bằng tiền: quỹ tiền mặt và tiền gửi ngân hàng","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp bạn quản lý và hạch toán chính xác tiền mặt, tiền gửi ngân hàng và tiền đang chuyển trong bối cảnh thanh toán số bùng nổ. Bạn thực hành trên sổ quỹ, sổ phụ ngân hàng và các tình huống chênh lệch thật, kèm bộ mẫu kiểm kê quỹ, bảng đối chiếu ngân hàng và quy trình kiểm soát dòng tiền. Kết thúc khoá, bạn khóa sổ tiền đúng hạn mỗi tháng, phát hiện sớm sai lệch và lập được báo cáo dòng tiền cho chủ doanh nghiệp.","a":"Kế toán thanh toán, thủ quỹ, kế toán tổng hợp ở doanh nghiệp nhỏ và vừa, chủ doanh nghiệp muốn kiểm soát dòng tiền chặt chẽ.","o":["Hạch toán đúng 30 nghiệp vụ thu chi tiền mặt, tiền gửi, tiền đang chuyển và ngoại tệ cơ bản theo TT 133.","Thực hiện kiểm kê quỹ và lập biên bản kiểm kê, xử lý chênh lệch thừa thiếu đúng quy trình.","Lập bảng đối chiếu số dư ngân hàng hằng tháng và giải thích 100% chênh lệch.","Thiết lập quy trình kiểm soát thu chi tiền với hạn mức, phân quyền và phê duyệt.","Lập báo cáo dòng tiền 13 tuần đơn giản giúp chủ doanh nghiệp dự báo thiếu hụt tiền."],"k":"QR, ví điện tử, hàng trăm giao dịch mỗi ngày: quỹ và tiền gửi lệch một đồng là không khóa sổ được.","w":["Điều kiện thanh toán không dùng tiền mặt từ 5 triệu đồng theo NĐ 181/2025 khiến cách tổ chức thu chi ảnh hưởng trực tiếp đến thuế GTGT được khấu trừ và chi phí được trừ.","Thanh toán QR, ví điện tử, cổng thanh toán và sàn thương mại điện tử làm số giao dịch tăng gấp nhiều lần; đối chiếu thủ công không còn theo kịp.","Kết nối ngân hàng trực tiếp với phần mềm kế toán và công cụ tự động đối soát đang phổ biến; kế toán tiền cần kỹ năng mới về dữ liệu và kiểm soát."],"dl":["Bộ mẫu Excel: sổ quỹ tiền mặt, sổ tiền gửi theo ngân hàng, bảng đối chiếu ngân hàng tự động đánh dấu chênh lệch.","Mẫu biên bản kiểm kê quỹ và quy trình SOP kiểm kê định kỳ, đột xuất.","Mẫu báo cáo dòng tiền 13 tuần và dashboard tiền mặt cho chủ doanh nghiệp.","Bộ 12 câu lệnh AI (prompt) đối soát sao kê, phân loại giao dịch và soạn giải trình chênh lệch."],"ls":["Vốn bằng tiền: tài sản nhạy cảm nhất và nguyên tắc quản lý","Kế toán tiền mặt: sổ quỹ, phiếu thu chi và kiểm kê","Kế toán tiền gửi ngân hàng và tiền đang chuyển","Đối chiếu ngân hàng hằng tháng: giải thích từng đồng chênh lệch","Thanh toán số: QR, ví điện tử, cổng thanh toán và sàn thương mại điện tử","Ngoại tệ trong vốn bằng tiền: quy đổi và đánh giá lại","Kiểm soát nội bộ chu trình tiền: phòng ngừa thất thoát và gian lận","Dự báo dòng tiền và dashboard tiền mặt với dữ liệu, AI"],"l1":{"t":"Vốn bằng tiền: tài sản nhạy cảm nhất và nguyên tắc quản lý","sum":"Bài mở đầu giới thiệu các loại vốn bằng tiền, nguyên tắc hạch toán và rủi ro thường gặp. Học viên hiểu vì sao tiền cần kiểm soát chặt hơn mọi tài sản khác.","points":["Vốn bằng tiền gồm tiền mặt TK 111, tiền gửi ngân hàng TK 112 và tiền đang chuyển; doanh nghiệp lớn dùng thêm TK 113.","Hạch toán theo đơn vị tiền tệ kế toán, ngoại tệ phải quy đổi theo tỷ giá giao dịch thực tế và theo dõi nguyên tệ.","Mọi khoản thu chi phải có chứng từ hợp lệ và người có thẩm quyền phê duyệt trước khi thực hiện.","Tiền là tài sản dễ bị thất thoát, nhầm lẫn và gian lận nhất, nên cần tách bạch chức năng giữ tiền, ghi sổ và phê duyệt.","Số dư tiền phải được đối chiếu với thực tế: tiền mặt với kiểm kê, tiền gửi với sổ phụ ngân hàng, tối thiểu mỗi tháng."],"case":"Công ty TNHH Minh An để thủ quỹ kiêm ghi sổ quỹ và đối chiếu ngân hàng. Sau 8 tháng, kiểm tra đột xuất phát hiện thiếu 46 triệu. Doanh nghiệp tách nhiệm vụ, kiểm kê quỹ hằng tuần và giao kế toán tổng hợp đối chiếu ngân hàng.","trend":"Doanh nghiệp đang giảm mạnh tiền mặt, chuyển sang thanh toán số; quỹ tiền mặt nhỏ lại nhưng giao dịch ngân hàng tăng nhanh, kỹ năng đối soát dữ liệu trở nên quan trọng hơn.","practice":"Liệt kê các luồng tiền vào ra của doanh nghiệp, xác định người lập, người duyệt, người giữ tiền và người ghi sổ cho từng luồng, đánh dấu điểm kiêm nhiệm cần tách.","takeaway":"Với tiền, tin tưởng là tốt nhưng kiểm soát mới an toàn."}},{"id":"KH006","code":"kh006","f":"KT","fn":"Kế toán","t":"Kế toán mua hàng và công nợ phải trả","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp bạn hạch toán chuẩn chu trình mua hàng từ đặt hàng, nhận hàng, nhận hóa đơn đến thanh toán và đối chiếu công nợ nhà cung cấp. Bạn học trên bộ hồ sơ mua hàng thật của doanh nghiệp thương mại, dịch vụ, với bảng định khoản, mẫu đối chiếu công nợ và lịch thanh toán dùng ngay. Kết thúc khoá, bạn kiểm soát được công nợ phải trả, tối ưu thời hạn thanh toán và bảo vệ quyền khấu trừ thuế của doanh nghiệp.","a":"Kế toán mua hàng, kế toán công nợ, kế toán tổng hợp doanh nghiệp nhỏ và vừa, nhân viên thu mua muốn hiểu yêu cầu chứng từ.","o":["Hạch toán đúng 30 nghiệp vụ mua hàng trong nước, mua dịch vụ, chiết khấu, giảm giá, trả lại hàng mua.","Kiểm tra được bộ hồ sơ mua hàng 3 bên khớp nhau: đơn đặt hàng, phiếu nhập, hóa đơn trước khi ghi nhận công nợ.","Lập sổ chi tiết công nợ phải trả theo nhà cung cấp và báo cáo tuổi nợ phải trả.","Thực hiện đối chiếu công nợ định kỳ và xử lý chênh lệch với nhà cung cấp.","Xây dựng lịch thanh toán tối ưu giúp tận dụng thời hạn tín dụng và chiết khấu thanh toán sớm."],"k":"Trả tiền sai cách là mất thuế đầu vào; quản tốt công nợ phải trả là giữ cả tiền lẫn uy tín.","w":["NĐ 181/2025 yêu cầu chứng từ thanh toán không dùng tiền mặt từ 5 triệu đồng để khấu trừ thuế GTGT, khiến cách thanh toán nhà cung cấp phải thay đổi.","Hóa đơn điện tử theo NĐ 70/2025 và dữ liệu đối chiếu của cơ quan thuế giúp phát hiện nhanh hóa đơn rủi ro, nhà cung cấp bỏ địa chỉ; kế toán mua hàng phải kiểm tra kỹ đầu vào.","Chuỗi cung ứng biến động và lãi suất vốn lưu động khiến quản trị kỳ hạn thanh toán trở thành công cụ tối ưu dòng tiền quan trọng."],"dl":["Bộ định khoản mẫu chu trình mua hàng theo TT 133, kèm bảng so sánh với chế độ doanh nghiệp lớn.","Mẫu Excel sổ chi tiết công nợ phải trả, báo cáo tuổi nợ và lịch thanh toán tự cập nhật.","Mẫu biên bản đối chiếu công nợ và checklist hồ sơ mua hàng đủ điều kiện khấu trừ, tính chi phí.","Bộ 12 câu lệnh AI (prompt) kiểm tra hóa đơn đầu vào, đối chiếu ba bên và soạn thư đối chiếu công nợ."],"ls":["Chu trình mua hàng: từ nhu cầu đến thanh toán","Hạch toán mua hàng hóa, vật tư và dịch vụ trong nước","Thuế GTGT đầu vào: điều kiện khấu trừ và bẫy thường gặp","Chiết khấu, giảm giá, trả lại hàng và các tình huống điều chỉnh","Quản lý công nợ phải trả: sổ chi tiết, tuổi nợ và đối chiếu","Thanh toán thông minh: lịch trả nợ, chiết khấu sớm và dòng tiền","Tự động hóa chu trình mua hàng với hóa đơn điện tử và AI","Kiểm soát rủi ro và đánh giá nhà cung cấp theo hướng bền vững"],"l1":{"t":"Chu trình mua hàng: từ nhu cầu đến thanh toán","sum":"Bài mở đầu mô tả toàn bộ chu trình mua hàng và vai trò của kế toán ở từng bước. Học viên hiểu điểm kiểm soát nào ngăn mua sai, trả thừa.","points":["Các bước chuẩn: đề nghị mua, chọn nhà cung cấp, đơn đặt hàng hoặc hợp đồng, nhận hàng, nhận hóa đơn, ghi nhận công nợ, thanh toán.","Đối chiếu ba bên: số lượng, đơn giá trên đơn đặt hàng, phiếu nhập kho và hóa đơn phải khớp trước khi duyệt thanh toán.","Nhà cung cấp mới cần kiểm tra mã số thuế, trạng thái hoạt động, thông tin tài khoản ngân hàng đứng tên doanh nghiệp.","Kế toán ghi nhận công nợ khi đã nhận hàng hoặc dịch vụ, không chờ đến khi thanh toán.","Tách chức năng người đặt hàng, người nhận hàng và người duyệt thanh toán để phòng gian lận."],"case":"Công ty TNHH Minh An thanh toán đủ 120 triệu cho một lô vật tư nhưng kho chỉ nhận 90% số lượng. Do không đối chiếu ba bên, sai lệch chỉ được phát hiện khi kiểm kê. Doanh nghiệp đòi lại 12 triệu và đưa bước đối chiếu bắt buộc vào quy trình duyệt chi.","trend":"Hệ thống mua hàng điện tử (e-procurement) và đối chiếu ba bên tự động đang lan xuống doanh nghiệp vừa; kế toán cần thiết kế quy tắc khớp và ngưỡng chênh lệch cho phép.","practice":"Vẽ sơ đồ chu trình mua hàng của doanh nghiệp bạn, đánh dấu 5 điểm kiểm soát và người phụ trách mỗi điểm.","takeaway":"Chỉ trả tiền cho những gì đã đặt, đã nhận và đã có hóa đơn đúng."}},{"id":"KH007","code":"kh007","f":"KT","fn":"Kế toán","t":"Kế toán bán hàng, doanh thu và công nợ phải thu","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp bạn ghi nhận doanh thu đúng thời điểm, đúng giá trị và quản lý công nợ phải thu hiệu quả trong môi trường bán hàng đa kênh. Bạn thực hành với dữ liệu bán hàng thật từ cửa hàng, sàn thương mại điện tử và hợp đồng dịch vụ, kèm mẫu báo cáo tuổi nợ, quy trình thu nợ và bảng đối soát dùng ngay. Kết thúc khoá, bạn khớp được doanh thu giữa sổ sách, hóa đơn và tờ khai, đồng thời rút ngắn số ngày thu tiền của doanh nghiệp.","a":"Kế toán bán hàng, kế toán công nợ phải thu, kế toán tổng hợp doanh nghiệp thương mại – dịch vụ và chủ shop bán hàng đa kênh.","o":["Ghi nhận đúng doanh thu cho 30 tình huống bán hàng: bán lẻ, bán buôn, bán qua sàn, khuyến mại, bán trả chậm, dịch vụ nhiều kỳ.","Khớp doanh thu giữa sổ kế toán, bảng kê hóa đơn đầu ra và tờ khai thuế GTGT với chênh lệch được giải thích đầy đủ.","Lập báo cáo tuổi nợ phải thu và tính chỉ số số ngày thu tiền bình quân.","Xây dựng quy trình thu nợ 5 bước và mẫu thư nhắc nợ chuyên nghiệp.","Đánh giá và lập dự phòng phải thu khó đòi có căn cứ."],"k":"Bán đa kênh, khách trả chậm: ghi sai doanh thu một lần là lệch cả tờ khai lẫn dòng tiền.","w":["NĐ 70/2025 sửa NĐ 123/2020 từ 01/06/2025 mở rộng hóa đơn điện tử khởi tạo từ máy tính tiền, đòi hỏi kế toán khớp dữ liệu bán lẻ hằng ngày.","NĐ 117/2025 yêu cầu sàn thương mại điện tử khấu trừ, nộp thay thuế cho hộ, cá nhân kinh doanh từ 01/07/2025; dữ liệu doanh thu trên sàn được cơ quan thuế nắm trực tiếp.","Bán hàng đa kênh và thanh toán số tăng mạnh, trong khi lãi suất vốn lưu động khiến mỗi ngày thu tiền chậm đều là chi phí thật."],"dl":["Bộ định khoản mẫu chu trình bán hàng theo TT 133 cho 30 tình huống thực tế.","Mẫu Excel sổ chi tiết công nợ phải thu, báo cáo tuổi nợ và bảng đối chiếu doanh thu – hóa đơn – tờ khai.","Quy trình SOP thu nợ 5 bước kèm bộ mẫu thư nhắc nợ, biên bản đối chiếu công nợ.","Bộ 12 câu lệnh AI (prompt) phân tích tuổi nợ, soạn thư nhắc nợ và đối soát đơn hàng đa kênh."],"ls":["Doanh thu ghi nhận khi nào: nguyên tắc nền cho mọi kênh bán","Hạch toán bán hàng, thuế GTGT đầu ra và giá vốn","Khuyến mại, chiết khấu, hàng bán bị trả lại và giảm giá","Bán hàng đa kênh: cửa hàng, máy tính tiền, website và sàn thương mại điện tử","Công nợ phải thu: theo dõi, tuổi nợ và đối chiếu khách hàng","Thu nợ chuyên nghiệp và dự phòng phải thu khó đòi","Khớp doanh thu: sổ sách – hóa đơn – tờ khai thuế","Phân tích doanh thu và dự báo thu tiền với dữ liệu và AI"],"l1":{"t":"Doanh thu ghi nhận khi nào: nguyên tắc nền cho mọi kênh bán","sum":"Bài mở đầu làm rõ điều kiện và thời điểm ghi nhận doanh thu theo chuẩn mực kế toán Việt Nam. Học viên phân biệt doanh thu kế toán, doanh thu tính thuế và thời điểm xuất hóa đơn.","points":["Doanh thu bán hàng ghi nhận khi đã chuyển giao phần lớn rủi ro và lợi ích, không còn quyền kiểm soát hàng, xác định được doanh thu và chi phí liên quan.","Doanh thu dịch vụ ghi nhận theo phần công việc đã hoàn thành tại ngày lập báo cáo.","Thời điểm lập hóa đơn theo quy định về hóa đơn điện tử có thể khác thời điểm ghi nhận doanh thu kế toán; kế toán cần theo dõi chênh lệch.","Tiền khách trả trước chưa giao hàng là khoản người mua trả tiền trước, chưa phải doanh thu.","Doanh thu ghi theo giá bán chưa thuế GTGT, sau khi trừ chiết khấu thương mại đã thể hiện trên hóa đơn."],"case":"Công ty TNHH Minh An nhận đặt cọc 300 triệu cho đơn hàng giao vào tháng sau và ghi ngay vào doanh thu. Báo cáo tháng phóng đại lãi và tờ khai bị lệch thời điểm. Kế toán chuyển khoản này về TK 131 chi tiết khách trả trước và ghi nhận doanh thu khi giao hàng.","trend":"Chuẩn mực quốc tế IFRS 15 với mô hình 5 bước đang ảnh hưởng ngày càng lớn theo lộ trình QĐ 345/QĐ-BTC; doanh nghiệp có hợp đồng phức tạp nên làm quen sớm.","practice":"Phân tích 10 giao dịch bán hàng mẫu, xác định thời điểm ghi nhận doanh thu, thời điểm xuất hóa đơn và lập bút toán tương ứng.","takeaway":"Tiền nhận trước chưa phải doanh thu; giao hàng xong mới là doanh thu."}},{"id":"KH008","code":"kh008","f":"KT","fn":"Kế toán","t":"Kế toán hàng tồn kho và giá vốn","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp bạn làm chủ kế toán hàng tồn kho từ xác định giá gốc, tính giá xuất kho, kiểm kê đến lập dự phòng và phân tích vòng quay hàng tồn. Bạn thực hành với dữ liệu kho thật của doanh nghiệp thương mại và sản xuất nhỏ, dùng ngay bộ mẫu Excel tính giá bình quân, nhập trước xuất trước, bảng kiểm kê và báo cáo tồn kho chậm luân chuyển. Kết thúc khoá, bạn tính giá vốn chính xác, khớp kho với sổ cái và đưa ra cảnh báo tồn kho có giá trị cho ban giám đốc.","a":"Kế toán kho, kế toán giá thành, kế toán tổng hợp doanh nghiệp thương mại – sản xuất, quản lý kho muốn hiểu nghiệp vụ kế toán.","o":["Xác định đúng giá gốc hàng tồn kho gồm giá mua, chi phí thu mua, thuế không được hoàn lại và các khoản giảm trừ.","Tính giá xuất kho chính xác theo bình quân gia quyền cuối kỳ, bình quân liên hoàn, nhập trước xuất trước và đích danh.","Tổ chức kiểm kê, lập biên bản và xử lý chênh lệch thừa thiếu đúng quy trình.","Lập dự phòng giảm giá hàng tồn kho dựa trên giá trị thuần có thể thực hiện được.","Lập báo cáo vòng quay, tuổi tồn kho và danh sách hàng chậm luân chuyển hằng tháng."],"k":"Hàng tồn kho thường là tài sản lớn nhất: tính sai giá vốn một chút, lợi nhuận và thuế lệch cả năm.","w":["Chế độ kế toán TT 99/2025 thay TT 200/2014 từ 01/01/2026 và TT 133/2016 cho doanh nghiệp nhỏ đều yêu cầu áp dụng nhất quán phương pháp tính giá và lập dự phòng có căn cứ.","Mã vạch, QR, phần mềm kho trên điện thoại và hóa đơn điện tử giúp dữ liệu nhập xuất có theo thời gian thực; kế toán cần biết khai thác để đóng sổ nhanh.","Chuỗi cung ứng biến động và chi phí vốn khiến tồn kho dư thừa trở thành gánh nặng; doanh nghiệp cần kế toán biết phân tích và cảnh báo."],"dl":["Bộ mẫu Excel tính giá xuất kho theo 4 phương pháp, tự kiểm tra tồn cuối khớp nhập xuất.","Quy trình SOP kiểm kê kho kèm mẫu biên bản kiểm kê và bảng xử lý chênh lệch.","Mẫu báo cáo tồn kho quản trị: vòng quay, tuổi tồn, hàng chậm luân chuyển, đề xuất dự phòng.","Bộ 12 câu lệnh AI (prompt) đối chiếu kho – sổ cái, phân tích tồn kho và soạn báo cáo cảnh báo."],"ls":["Hàng tồn kho và giá gốc: tính đúng ngay từ khi hàng về","Bốn phương pháp tính giá xuất kho và cách chọn phù hợp","Hạch toán nhập xuất kho trong doanh nghiệp thương mại và sản xuất","Kiểm kê kho: tổ chức, xử lý chênh lệch và khớp sổ","Dự phòng giảm giá hàng tồn kho: thận trọng có căn cứ","Giá vốn hàng bán: kiểm tra, phân tích và khớp với doanh thu","Quản trị tồn kho bằng số liệu: vòng quay, tuổi tồn và vốn bị chôn","Tự động hóa kế toán kho: mã vạch, phần mềm online và AI"],"l1":{"t":"Hàng tồn kho và giá gốc: tính đúng ngay từ khi hàng về","sum":"Bài mở đầu xác định phạm vi hàng tồn kho và nguyên tắc xác định giá gốc theo chuẩn mực hiện hành. Học viên biết khoản nào được cộng vào giá gốc, khoản nào phải ghi chi phí.","points":["Hàng tồn kho gồm hàng hóa, nguyên vật liệu, công cụ dụng cụ, sản phẩm dở dang, thành phẩm, hàng gửi bán và hàng mua đang đi đường.","Giá gốc gồm giá mua, thuế nhập khẩu và thuế không được hoàn lại, chi phí vận chuyển, bốc xếp, bảo quản trong quá trình mua.","Chiết khấu thương mại và giảm giá hàng mua được trừ khỏi giá gốc.","Chi phí bảo quản sau khi nhập kho, chi phí bán hàng, chi phí quản lý không tính vào giá gốc.","Thuế GTGT đầu vào được khấu trừ không tính vào giá gốc; nếu không được khấu trừ thì cộng vào giá gốc."],"case":"Công ty TNHH Minh An nhập 5 tấn nguyên liệu giá 400 triệu, chi phí vận chuyển 12 triệu, phí lưu kho tại cảng 3 triệu. Kế toán ghi toàn bộ 15 triệu vào chi phí quản lý. Điều chỉnh đúng là cộng cả 15 triệu vào giá gốc, giá mỗi tấn là 83 triệu đồng.","trend":"Hóa đơn điện tử, chứng từ vận tải và tờ khai hải quan điện tử cho phép tự động ghép chi phí mua vào lô hàng; kế toán nên chuẩn hóa mã lô để phân bổ tự động.","practice":"Tính giá gốc cho 5 lô hàng mẫu có chi phí thu mua, chiết khấu và thuế, lập bút toán nhập kho từng lô.","takeaway":"Giá gốc đúng là điểm khởi đầu của giá vốn đúng."}},{"id":"KH009","code":"kh009","f":"KT","fn":"Kế toán","t":"Kế toán tài sản cố định và khấu hao","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp bạn quản lý trọn vòng đời tài sản cố định từ ghi nhận, khấu hao, sửa chữa, đánh giá lại đến thanh lý, kể cả tài sản vô hình như phần mềm và quyền sử dụng đất. Bạn học bằng hồ sơ tài sản thật của doanh nghiệp sản xuất, dịch vụ, dùng ngay bộ mẫu thẻ tài sản, bảng tính khấu hao tự động và checklist hồ sơ được trừ chi phí. Kết thúc khoá, bạn lập được sổ tài sản chuẩn, tính khấu hao chính xác và tư vấn ban giám đốc về đầu tư, thanh lý tài sản.","a":"Kế toán tài sản, kế toán tổng hợp, kế toán trưởng doanh nghiệp vừa và nhỏ, chủ doanh nghiệp chuẩn bị đầu tư máy móc, công nghệ.","o":["Xác định đúng tiêu chuẩn ghi nhận và nguyên giá tài sản cố định hữu hình, vô hình theo quy định hiện hành.","Tính khấu hao theo đường thẳng, số dư giảm dần có điều chỉnh và theo sản lượng bằng bảng tính tự động.","Phân biệt và hạch toán đúng chi phí sửa chữa thường xuyên, sửa chữa lớn và nâng cấp tài sản.","Hạch toán thanh lý, nhượng bán, điều chuyển và kiểm kê tài sản cố định đầy đủ hồ sơ.","Lập sổ tài sản cố định và kế hoạch đầu tư, thay thế tài sản 3 năm cho doanh nghiệp."],"k":"Ghi sai một tài sản cố định là sai khấu hao nhiều năm và dễ bị loại chi phí khi quyết toán.","w":["Chế độ kế toán TT 99/2025 thay TT 200/2014 từ 01/01/2026; doanh nghiệp cần rà soát chính sách tài sản cố định và khấu hao khi chuyển đổi.","Đầu tư chuyển đổi số tăng mạnh: phần mềm, hệ thống ERP, thiết bị tự động hóa đặt ra câu hỏi mới về vốn hóa và thời gian khấu hao tài sản vô hình.","Báo cáo bền vững và đầu tư thiết bị tiết kiệm năng lượng khiến dữ liệu tài sản trở thành nguồn thông tin ESG và quản trị chi phí quan trọng."],"dl":["Bộ mẫu Excel sổ tài sản cố định và bảng khấu hao tự động theo 3 phương pháp, có phân bổ theo bộ phận.","Checklist hồ sơ tài sản cố định đủ điều kiện ghi nhận và khấu hao được trừ khi tính thuế.","Quy trình SOP mua sắm, đưa vào sử dụng, kiểm kê và thanh lý tài sản cùng bộ biên bản mẫu.","Bộ 10 câu lệnh AI (prompt) đọc hợp đồng mua tài sản, lập thẻ tài sản và phân tích quyết định đầu tư."],"ls":["Tài sản cố định là gì: tiêu chuẩn ghi nhận và phân loại","Xác định nguyên giá: mua sắm, tự xây dựng, nhận góp vốn","Khấu hao: phương pháp, thời gian và tác động đến lợi nhuận","Sửa chữa, nâng cấp và đánh giá lại tài sản","Thanh lý, nhượng bán, điều chuyển và kiểm kê tài sản","Tài sản cố định dưới góc độ thuế: khấu hao được trừ và rủi ro","Tài sản số và chuyển đổi số: phần mềm, ERP, điện toán đám mây","Quản trị tài sản bằng dữ liệu: hiệu suất, thay thế và ESG"],"l1":{"t":"Tài sản cố định là gì: tiêu chuẩn ghi nhận và phân loại","sum":"Bài mở đầu giúp học viên nhận diện tài sản nào là tài sản cố định, tài sản nào là công cụ dụng cụ hay chi phí. Đây là quyết định đầu tiên ảnh hưởng đến lợi nhuận nhiều năm.","points":["Tài sản cố định thỏa mãn đồng thời: chắc chắn mang lại lợi ích kinh tế tương lai, thời gian sử dụng trên 1 năm và nguyên giá đạt ngưỡng theo quy định hiện hành (hiện là từ 30 triệu đồng).","Tài sản cố định hữu hình gồm nhà cửa, máy móc, phương tiện vận tải, thiết bị quản lý; vô hình gồm quyền sử dụng đất có thời hạn, phần mềm, bản quyền, nhãn hiệu.","Tài sản không đủ tiêu chuẩn được ghi nhận là công cụ dụng cụ và phân bổ vào chi phí qua TK 242.","Tài sản thuê tài chính và thuê hoạt động có cách ghi nhận khác nhau, phụ thuộc bản chất hợp đồng thuê.","Phân loại theo bộ phận sử dụng giúp phân bổ khấu hao đúng vào giá thành, chi phí bán hàng, chi phí quản lý."],"case":"Công ty TNHH Minh An mua 10 bộ máy tính, mỗi bộ 18 triệu, và ghi toàn bộ 180 triệu là một tài sản cố định. Theo tiêu chuẩn, mỗi bộ hoạt động độc lập và không đạt ngưỡng nguyên giá. Kế toán điều chỉnh ghi nhận là công cụ dụng cụ và phân bổ 24 tháng.","trend":"Tài sản vô hình như phần mềm, dữ liệu, nền tảng số chiếm tỷ trọng ngày càng lớn trong doanh nghiệp; kế toán cần nắm vững tiêu chuẩn vốn hóa chi phí phát triển và triển khai phần mềm.","practice":"Phân loại 20 khoản đầu tư mẫu thành tài sản cố định hữu hình, vô hình, công cụ dụng cụ hoặc chi phí, nêu căn cứ cho từng khoản.","takeaway":"Phân loại đúng hôm nay tránh được điều chỉnh trong nhiều năm sau."}},{"id":"KH010","code":"kh010","f":"KT","fn":"Kế toán","t":"Báo cáo ESG và kế toán phát triển bền vững","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp kế toán và nhà quản lý hiểu ESG từ góc nhìn con số: thu thập dữ liệu môi trường, xã hội, quản trị, tính phát thải khí nhà kính cơ bản và lập báo cáo bền vững đáng tin cậy. Bạn học qua tình huống doanh nghiệp xuất khẩu, sản xuất Việt Nam đang chịu yêu cầu từ khách hàng quốc tế, với bộ mẫu thu thập dữ liệu, bảng tính phát thải và khung báo cáo dùng ngay. Kết thúc khoá, bạn lập được báo cáo ESG cơ bản đầu tiên cho doanh nghiệp và biết lộ trình nâng cấp theo chuẩn quốc tế.","a":"Kế toán, kế toán trưởng, nhân sự phụ trách báo cáo, quản lý doanh nghiệp sản xuất – xuất khẩu và người muốn bước vào lĩnh vực tư vấn bền vững.","o":["Giải thích được ESG, các khung báo cáo GRI, ISSB và tác động của chúng đến doanh nghiệp Việt Nam.","Xác định được các chủ đề trọng yếu cho doanh nghiệp bằng phương pháp đánh giá trọng yếu đơn giản.","Tính được phát thải khí nhà kính phạm vi 1 và 2 từ dữ liệu nhiên liệu, điện năng có sẵn trong sổ kế toán.","Thiết lập hệ thống thu thập dữ liệu ESG gắn với tài khoản kế toán và chứng từ.","Lập được báo cáo ESG cơ bản 10–15 trang cho doanh nghiệp vừa và nhỏ."],"k":"Từ 2026 khách châu Âu hỏi số liệu phát thải trước khi hỏi giá: kế toán làm được ESG đang rất hiếm.","w":["Cơ chế điều chỉnh biên giới carbon (CBAM) của EU bước vào giai đoạn áp dụng chính thức từ năm 2026 với một số nhóm hàng; doanh nghiệp xuất khẩu Việt Nam phải cung cấp dữ liệu phát thải cho nhà nhập khẩu.","Chuẩn mực báo cáo bền vững quốc tế ISSB (IFRS S1, IFRS S2) và GRI đang được nhiều thị trường áp dụng; ngân hàng, nhà đầu tư dùng dữ liệu ESG khi cấp vốn.","Việt Nam đã cam kết mục tiêu phát thải ròng bằng 0 vào năm 2050 và đang xây dựng thị trường carbon; dữ liệu phát thải đáng tin cậy sẽ là tài sản của doanh nghiệp."],"dl":["Bộ mẫu Excel thu thập dữ liệu ESG theo tháng, gắn với tài khoản chi phí điện, nhiên liệu, nước, lao động.","Bảng tính phát thải phạm vi 1 và 2 có hướng dẫn nhập hệ số phát thải từ nguồn chính thức.","Khung báo cáo ESG mẫu cho doanh nghiệp vừa và nhỏ cùng checklist chất lượng dữ liệu.","Bộ 12 câu lệnh AI (prompt) hỗ trợ đánh giá trọng yếu, soạn nội dung báo cáo và rà soát tính nhất quán."],"ls":["ESG là gì và vì sao kế toán đứng ở trung tâm","Bản đồ chuẩn mực: GRI, ISSB, CBAM và yêu cầu tại Việt Nam","Đánh giá trọng yếu: báo cáo điều gì thực sự quan trọng","Tính phát thải khí nhà kính phạm vi 1 và 2 từ dữ liệu kế toán","Chỉ số xã hội và quản trị: lao động, an toàn, minh bạch","Kế toán bền vững: chi phí môi trường, đầu tư xanh và rủi ro khí hậu","Hệ thống dữ liệu ESG: số hóa, tự động hóa và dùng AI đúng cách","Lập báo cáo ESG đầu tiên và lộ trình nâng cấp"],"l1":{"t":"ESG là gì và vì sao kế toán đứng ở trung tâm","sum":"Bài mở đầu giải thích ESG bằng ngôn ngữ kinh doanh và chỉ ra vì sao dữ liệu ESG cần kỷ luật kế toán. Học viên thấy rõ cơ hội nghề nghiệp mới.","points":["ESG gồm Môi trường (năng lượng, phát thải, nước, chất thải), Xã hội (lao động, an toàn, cộng đồng) và Quản trị (minh bạch, chống tham nhũng, cơ cấu quản trị).","Người dùng thông tin ESG là khách hàng quốc tế, ngân hàng, nhà đầu tư, cơ quan quản lý và chính người lao động.","Dữ liệu ESG cần đầy đủ, chính xác, có bằng chứng và kiểm chứng được, giống như dữ liệu tài chính.","Rất nhiều dữ liệu ESG đã nằm sẵn trong sổ kế toán: hóa đơn điện, nhiên liệu, chi phí xử lý chất thải, bảng lương, bảo hiểm, đào tạo.","Báo cáo ESG sai hoặc phóng đại (greenwashing) gây rủi ro pháp lý và uy tín không kém báo cáo tài chính sai."],"case":"Công ty TNHH Dệt May Minh An nhận yêu cầu từ khách hàng châu Âu cung cấp lượng điện tiêu thụ và phát thải năm trước. Bộ phận kỹ thuật không có số liệu tổng hợp. Kế toán trích từ hóa đơn điện 12 tháng và chi phí dầu diesel trong sổ chi phí, lập bảng số liệu trong 3 ngày và giữ được đơn hàng.","trend":"Giai đoạn 2026–2030, báo cáo bền vững dự kiến chuyển từ tự nguyện sang bắt buộc ở nhiều thị trường và chuỗi cung ứng; kế toán nên chuẩn bị ngay kỹ năng thu thập và kiểm soát dữ liệu phi tài chính.","practice":"Liệt kê 15 dữ liệu ESG mà doanh nghiệp bạn đã có trong sổ kế toán hoặc hồ sơ nhân sự, ghi rõ tài khoản hoặc nguồn chứng từ.","takeaway":"Dữ liệu ESG tốt nhất bắt đầu từ chứng từ kế toán tốt."}},{"id":"KH011","code":"kh011","f":"KT","fn":"Kế toán","t":"Kế toán tiền lương và các khoản trích theo lương","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp bạn lập bảng lương chuẩn, tính đúng bảo hiểm bắt buộc, kinh phí công đoàn, thuế TNCN và hạch toán đầy đủ chi phí tiền lương theo quy định cập nhật năm 2026. Bạn thực hành trên dữ liệu chấm công, hợp đồng lao động và quy chế lương thật đã ẩn danh, dùng ngay bộ mẫu bảng lương Excel tự động và hồ sơ chứng minh chi phí lương được trừ. Kết thúc khoá, bạn tự tin vận hành trọn chu trình lương hằng tháng, quyết toán TNCN cuối năm và tư vấn chính sách lương hợp pháp, tối ưu.","a":"Kế toán tiền lương, nhân viên C&B, kế toán tổng hợp doanh nghiệp nhỏ và vừa, chủ doanh nghiệp muốn kiểm soát chi phí nhân sự.","o":["Lập được bảng lương tháng cho 20 nhân viên gồm lương, phụ cấp, làm thêm giờ, bảo hiểm, công đoàn và thuế TNCN.","Tính đúng các khoản trích theo lương: doanh nghiệp 21,5% và người lao động 10,5% bảo hiểm bắt buộc, kinh phí công đoàn 2%.","Tính thuế TNCN theo biểu lũy tiến 7 bậc với giảm trừ gia cảnh mới và xử lý các khoản thu nhập miễn thuế.","Hạch toán đầy đủ chu trình lương theo TT 133 và lập hồ sơ chứng minh chi phí lương được trừ.","Thực hiện quyết toán TNCN năm và đối chiếu số liệu lương – bảo hiểm – thuế – sổ kế toán."],"k":"Giảm trừ gia cảnh lên 15,5 triệu, Luật BHXH 2024 đã hiệu lực: bảng lương 2026 sai là sai cả trăm người.","w":["Từ kỳ tính thuế 2026, giảm trừ gia cảnh tăng lên 15,5 triệu đồng/tháng cho bản thân và 6,2 triệu đồng/tháng cho mỗi người phụ thuộc; bảng lương và khấu trừ TNCN phải cập nhật ngay.","Luật BHXH 2024 có hiệu lực từ 01/07/2025 thay đổi nhiều quy định về đối tượng, căn cứ đóng; sai sót dẫn đến truy thu và tiền chậm đóng.","Chấm công điện tử, bảng lương tự động và dữ liệu nhân sự kết nối với cơ quan quản lý đòi hỏi kế toán lương có kỹ năng số và bảo vệ dữ liệu cá nhân theo Luật 91/2025/QH15."],"dl":["Bộ mẫu Excel bảng lương tự động: chấm công, tính lương, bảo hiểm, thuế TNCN, phiếu lương từng người.","Mẫu quy chế lương thưởng, phụ cấp tham khảo và checklist hồ sơ chi phí lương được trừ.","Quy trình SOP lương hằng tháng từ chốt công đến chi trả, có bảng đối chiếu 4 chiều lương – bảo hiểm – thuế – sổ cái.","Bộ 12 câu lệnh AI (prompt) kiểm tra công thức bảng lương, giải thích phiếu lương và soạn thông báo chính sách."],"ls":["Tiền lương theo pháp luật lao động: nền móng của mọi bảng lương","Chấm công và tính lương: thời gian, sản phẩm, khoán và làm thêm","Bảo hiểm bắt buộc và kinh phí công đoàn theo quy định 2026","Thuế TNCN từ tiền lương: giảm trừ mới và biểu lũy tiến","Hạch toán tiền lương và các khoản trích theo TT 133","Chi phí lương được trừ và hồ sơ chứng minh khi quyết toán","Quyết toán TNCN cuối năm và đối chiếu 4 chiều","Bảng lương thông minh: tự động hóa, AI và bảo vệ dữ liệu cá nhân"],"l1":{"t":"Tiền lương theo pháp luật lao động: nền móng của mọi bảng lương","sum":"Bài mở đầu giới thiệu khung pháp lý về tiền lương theo Bộ luật Lao động 2019 và các văn bản hướng dẫn. Học viên hiểu những khoản nào cấu thành tiền lương và nghĩa vụ tối thiểu của doanh nghiệp.","points":["Tiền lương gồm mức lương theo công việc hoặc chức danh, phụ cấp lương và các khoản bổ sung khác theo thỏa thuận.","Mức lương trả cho người lao động làm đủ thời giờ bình thường không thấp hơn lương tối thiểu vùng theo quy định hiện hành.","Làm thêm giờ được trả ít nhất 150% ngày thường, 200% ngày nghỉ hằng tuần, 300% ngày lễ, Tết theo Bộ luật Lao động 2019.","Hợp đồng lao động, thang bảng lương, quy chế lương thưởng là hồ sơ nền tảng để tính lương và chứng minh chi phí.","Kỳ hạn trả lương, hình thức trả và các khoản khấu trừ phải được thỏa thuận rõ và thực hiện đúng."],"case":"Công ty TNHH Minh An trả làm thêm giờ ngày chủ nhật bằng 150% do hiểu nhầm quy định. Khi người lao động khiếu nại, doanh nghiệp phải truy trả phần chênh lệch 50% cho 6 tháng. Kế toán cập nhật hệ số làm thêm theo từng loại ngày vào bảng lương tự động.","trend":"Chính sách lương linh hoạt, làm việc từ xa và trả lương theo hiệu suất đang phổ biến; kế toán lương cần hiểu cả pháp luật lao động và dữ liệu hiệu suất để tính đúng.","practice":"Rà soát một hợp đồng lao động và quy chế lương mẫu, liệt kê các thành phần thu nhập và quy tắc tính cho từng khoản.","takeaway":"Bảng lương đúng bắt đầu từ hợp đồng và quy chế rõ ràng."}},{"id":"KH012","code":"kh012","f":"KT","fn":"Kế toán","t":"Kế toán thuế GTGT, TNDN, TNCN trên sổ sách","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp bạn hạch toán, kê khai và đối chiếu ba sắc thuế chính GTGT, TNDN, TNCN ngay trên sổ kế toán, đảm bảo sổ sách và tờ khai luôn khớp nhau. Bạn thực hành trên bộ số liệu cả năm của doanh nghiệp thương mại – dịch vụ, với bảng đối chiếu sổ – tờ khai, bảng điều chỉnh chi phí không được trừ và lịch thuế dùng ngay. Kết thúc khoá, bạn tự lập được tờ khai, quyết toán, giải thích mọi chênh lệch và chủ động phòng ngừa rủi ro truy thu.","a":"Kế toán thuế, kế toán tổng hợp, kế toán trưởng doanh nghiệp nhỏ và vừa, người làm dịch vụ kế toán – thuế.","o":["Hạch toán đúng các bút toán thuế GTGT đầu vào, đầu ra, khấu trừ, nộp, hoàn và điều chỉnh.","Tính và hạch toán thuế TNDN tạm nộp quý, quyết toán năm, đảm bảo tổng 4 quý đạt ít nhất 80% số quyết toán.","Lập bảng điều chỉnh từ lợi nhuận kế toán sang thu nhập tính thuế với đầy đủ chi phí không được trừ.","Đối chiếu số dư TK 133, 3331, 3334, 3335 với tờ khai và dữ liệu nghĩa vụ thuế, giải thích mọi chênh lệch.","Xây dựng lịch thuế năm và quy trình tự kiểm tra trước khi nộp tờ khai."],"k":"Luật thuế mới, ngưỡng tiền mặt 5 triệu, xử phạt sửa đổi 2026: sổ sách lệch tờ khai là rủi ro thật.","w":["Luật TNDN 67/2025/QH15 áp dụng từ kỳ tính thuế 2025 với thuế suất 15%, 17%, 20% theo doanh thu; Luật GTGT 48/2024/QH15 và thuế suất 8% đến hết 31/12/2026 theo NQ 204/2025/QH15.","NĐ 181/2025 hạ ngưỡng thanh toán không dùng tiền mặt xuống 5 triệu đồng; NĐ 310/2025 sửa đổi xử phạt vi phạm hành chính về thuế, hóa đơn hiệu lực từ 16/01/2026.","Cơ quan thuế quản lý bằng dữ liệu hóa đơn điện tử, ngân hàng và phân tích rủi ro tự động; chênh lệch giữa sổ sách và tờ khai bị phát hiện nhanh hơn bao giờ hết."],"dl":["Bộ mẫu Excel đối chiếu sổ – tờ khai cho GTGT, TNDN, TNCN theo tháng, quý, năm.","Bảng điều chỉnh lợi nhuận kế toán sang thu nhập tính thuế kèm danh mục chi phí không được trừ thường gặp.","Lịch thuế năm 2026 và checklist tự kiểm tra 20 điểm trước khi nộp tờ khai.","Bộ 15 câu lệnh AI (prompt) rà soát bảng kê hóa đơn, tìm chênh lệch và soạn văn bản giải trình."],"ls":["Bức tranh thuế doanh nghiệp 2026: những thay đổi phải nắm","Kế toán thuế GTGT: từ hóa đơn đến bút toán khấu trừ","Kê khai GTGT và đối chiếu: sổ, bảng kê, tờ khai, dữ liệu hóa đơn","Thuế TNDN tạm nộp quý: tính đúng, nộp đủ, không bị phạt","Quyết toán TNDN: từ lợi nhuận kế toán đến thu nhập tính thuế","Thuế TNCN trên sổ sách: khấu trừ, kê khai và quyết toán","Đối chiếu nghĩa vụ thuế và quản trị rủi ro kiểm tra","Kế toán thuế số: tự động hóa đối chiếu và dùng AI an toàn"],"l1":{"t":"Bức tranh thuế doanh nghiệp 2026: những thay đổi phải nắm","sum":"Bài mở đầu tổng hợp các thay đổi chính sách thuế đang có hiệu lực và ảnh hưởng trực tiếp đến sổ sách. Học viên có danh sách việc cần cập nhật ngay.","points":["Thuế TNDN: 15% với doanh nghiệp có doanh thu năm từ 3 tỷ trở xuống, 17% từ trên 3 tỷ đến 50 tỷ, 20% với doanh nghiệp còn lại theo Luật 67/2025/QH15 từ kỳ tính thuế 2025.","Thuế GTGT theo Luật 48/2024/QH15; thuế suất 8% áp dụng đến hết 31/12/2026 cho nhiều nhóm hàng theo NQ 204/2025/QH15, trừ một số ngành.","Thanh toán không dùng tiền mặt từ 5 triệu đồng là điều kiện khấu trừ GTGT và tính chi phí theo NĐ 181/2025 từ 01/07/2025.","Giảm trừ gia cảnh TNCN 15,5 triệu đồng/tháng cho bản thân, 6,2 triệu đồng/tháng cho người phụ thuộc từ kỳ tính thuế 2026.","Quản lý thuế theo Luật 38/2019/QH14 và NĐ 126/2020; xử phạt theo NĐ 125/2020 sửa bởi NĐ 310/2025 hiệu lực 16/01/2026; tiền chậm nộp 0,03%/ngày."],"case":"Công ty TNHH Minh An có doanh thu 2,6 tỷ nhưng năm 2025 vẫn tạm nộp TNDN theo 20%. Khi cập nhật luật mới, kế toán xác định thuế suất 15% và điều chỉnh số tạm nộp các quý sau, đồng thời giữ hồ sơ căn cứ doanh thu. Doanh nghiệp tránh nộp thừa khoảng 25 triệu đồng.","trend":"Chính sách thuế dự kiến tiếp tục điều chỉnh mạnh giai đoạn 2026–2030 theo hướng đơn giản hóa và số hóa; kế toán thuế cần thói quen cập nhật văn bản gốc và lưu nhật ký thay đổi chính sách.","practice":"Lập bảng tác động của 5 thay đổi chính sách thuế đến doanh nghiệp của bạn: nội dung, hiệu lực, tài khoản, tờ khai liên quan và việc cần làm.","takeaway":"Cập nhật chính sách trước, hạch toán sau."}},{"id":"KH013","code":"kh013","f":"KT","fn":"Kế toán","t":"Kế toán doanh nghiệp thương mại thực hành","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học đưa bạn làm trọn một năm kế toán cho doanh nghiệp thương mại, từ mở sổ, mua hàng, bán hàng đa kênh, kho, công nợ, lương, thuế đến báo cáo tài chính. Bạn thực hành trên bộ dữ liệu mô phỏng sát thực tế của một công ty phân phối, có hóa đơn điện tử, sao kê, báo cáo sàn, kèm checklist và mẫu biểu dùng ngay. Kết thúc khoá, bạn đủ năng lực đảm nhận vị trí kế toán tổng hợp doanh nghiệp thương mại và có bộ hồ sơ thực hành làm minh chứng năng lực.","a":"Kế toán viên muốn lên kế toán tổng hợp, người chuyển việc sang doanh nghiệp thương mại, chủ doanh nghiệp phân phối – bán lẻ muốn hiểu sổ sách.","o":["Thiết lập hệ thống tài khoản, danh mục hàng hóa, khách hàng, nhà cung cấp chuẩn cho doanh nghiệp thương mại.","Hạch toán trọn chu trình mua – bán – kho – tiền – công nợ của 12 tháng với số dư khớp chứng từ.","Đối soát doanh thu đa kênh: cửa hàng, bán sỉ, website, sàn thương mại điện tử.","Lập tờ khai thuế GTGT, tạm nộp TNDN, khấu trừ TNCN và quyết toán năm cho doanh nghiệp thương mại.","Lập báo cáo tài chính năm và báo cáo quản trị lãi gộp theo kênh, nhóm hàng."],"k":"Bán sỉ, bán lẻ, bán trên sàn: kế toán thương mại 2026 là làm chủ dữ liệu hàng, tiền và thuế.","w":["Thương mại điện tử và bán hàng đa kênh tăng mạnh; NĐ 117/2025 về khấu trừ thuế qua sàn và hóa đơn khởi tạo từ máy tính tiền theo NĐ 70/2025 thay đổi cách ghi nhận doanh thu bán lẻ.","Hộ kinh doanh lớn chuyển lên doanh nghiệp sau khi bỏ thuế khoán từ 01/01/2026, tạo nhu cầu lớn về kế toán thương mại thành thạo.","Luật TNDN 67/2025/QH15 với thuế suất theo doanh thu, ngưỡng tiền mặt 5 triệu và thuế suất GTGT 8% đến hết 2026 khiến doanh nghiệp thương mại biên lợi nhuận mỏng rất cần kế toán chính xác."],"dl":["Bộ dữ liệu thực hành 12 tháng của một công ty phân phối: hóa đơn, sao kê, phiếu kho, báo cáo sàn, bảng lương.","Bộ mẫu Excel kế toán thương mại: sổ chi tiết hàng hóa, công nợ, đối soát đa kênh, báo cáo lãi gộp.","Checklist đóng sổ tháng và quyết toán năm dành riêng cho doanh nghiệp thương mại.","Bộ 15 câu lệnh AI (prompt) đối soát đơn hàng, phân tích lãi gộp và rà soát báo cáo trước khi nộp."],"ls":["Khởi tạo hệ thống kế toán cho doanh nghiệp thương mại","Mua hàng và nhập kho: giá gốc, chứng từ, thuế đầu vào","Bán hàng đa kênh: sỉ, lẻ, website và sàn thương mại điện tử","Kho, giá vốn và kiểm kê trong doanh nghiệp thương mại","Tiền, công nợ và lương: đóng sổ tháng đúng hạn","Thuế của doanh nghiệp thương mại: kê khai, tạm nộp và quyết toán","Báo cáo tài chính năm và hồ sơ quyết toán hoàn chỉnh","Kế toán quản trị thương mại với dữ liệu và AI"],"l1":{"t":"Khởi tạo hệ thống kế toán cho doanh nghiệp thương mại","sum":"Bài mở đầu hướng dẫn thiết lập nền tảng: chế độ kế toán, danh mục, phương pháp tính giá và quy trình. Cài đặt đúng từ đầu tiết kiệm hàng tháng sửa sai.","points":["Doanh nghiệp nhỏ và vừa thường chọn TT 133/2016; doanh nghiệp lớn áp dụng TT 99/2025 thay TT 200/2014 từ 01/01/2026.","Danh mục hàng hóa cần mã thống nhất, đơn vị tính, quy đổi thùng – hộp – cái, nhóm hàng và thuế suất GTGT.","Đăng ký phương pháp tính giá xuất kho phù hợp; doanh nghiệp nhiều mã hàng, nhập liên tục thường dùng bình quân.","Mở chi tiết doanh thu, giá vốn theo kênh bán và nhóm hàng bằng mã thống kê để phân tích lãi gộp.","Thiết lập quy trình chứng từ mua, bán, kho, tiền và phân quyền phê duyệt ngay từ đầu."],"case":"Công ty TNHH Phân Phối Minh An kinh doanh 800 mã hàng nhưng một sản phẩm có 3 mã khác nhau do nhập từ 3 nhà cung cấp. Báo cáo tồn kho sai lệch, không tính được lãi gộp. Kế toán chuẩn hóa còn 520 mã, có bảng quy đổi, và báo cáo lãi gộp theo nhóm hàng chạy đúng từ tháng sau.","trend":"Phần mềm kế toán online, phần mềm bán hàng và sàn thương mại điện tử đang kết nối qua API; danh mục hàng hóa chuẩn là chìa khóa để dữ liệu chảy tự động giữa các hệ thống.","practice":"Thiết lập danh mục 50 mã hàng, 20 khách hàng, 10 nhà cung cấp và cấu trúc mã thống kê kênh bán cho doanh nghiệp mẫu.","takeaway":"Một danh mục chuẩn tiết kiệm trăm giờ sửa sai."}},{"id":"KH014","code":"kh014","f":"KT","fn":"Kế toán","t":"Kế toán doanh nghiệp dịch vụ thực hành","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học đưa bạn làm trọn chu trình kế toán doanh nghiệp dịch vụ: tư vấn, công nghệ, đào tạo, logistics, nhà hàng – khách sạn, từ hợp đồng, ghi nhận doanh thu theo tiến độ, tập hợp chi phí dự án đến thuế và báo cáo. Bạn thực hành trên bộ dữ liệu thật của một công ty dịch vụ với hợp đồng, bảng chấm công dự án, hóa đơn, kèm mẫu tính giá vốn dịch vụ, theo dõi doanh thu chưa thực hiện dùng ngay. Kết thúc khoá, bạn hạch toán chính xác, biết lãi lỗ từng hợp đồng và tư vấn được cách định giá dịch vụ.","a":"Kế toán doanh nghiệp dịch vụ, kế toán dự án, kế toán tổng hợp công ty tư vấn – công nghệ – đào tạo – du lịch, chủ doanh nghiệp dịch vụ nhỏ.","o":["Xác định đúng thời điểm và giá trị ghi nhận doanh thu cho dịch vụ một lần, nhiều kỳ, theo tiến độ và thuê bao.","Tập hợp chi phí và tính giá vốn dịch vụ theo từng hợp đồng, dự án qua TK 154 và 632.","Theo dõi doanh thu chưa thực hiện, khách hàng trả trước và chi phí trả trước chính xác.","Lập tờ khai, quyết toán thuế và xử lý các vấn đề thuế đặc thù của doanh nghiệp dịch vụ.","Lập báo cáo lãi lỗ theo hợp đồng, khách hàng và tỷ lệ sử dụng nhân sự."],"k":"Dịch vụ không có kho hàng nhưng có hợp đồng và giờ công: ghi sai thời điểm doanh thu là sai cả năm.","w":["Mô hình thuê bao, gói dịch vụ trả trước và hợp đồng nhiều giai đoạn tăng mạnh; ghi nhận doanh thu đúng kỳ ảnh hưởng trực tiếp tới thuế TNDN theo Luật 67/2025/QH15.","Chi phí nhân sự chiếm tỷ trọng lớn trong doanh nghiệp dịch vụ, trong khi giảm trừ gia cảnh mới từ 2026, Luật BHXH 2024 và ngưỡng chuyển khoản 5 triệu thay đổi cách tính và hồ sơ chi phí.","Dịch vụ số, cung cấp dịch vụ xuyên biên giới và công cụ quản lý dự án trực tuyến tạo ra lượng dữ liệu lớn mà kế toán cần khai thác để tính lãi lỗ từng hợp đồng."],"dl":["Bộ dữ liệu thực hành 6 tháng của một công ty dịch vụ tư vấn – công nghệ: hợp đồng, timesheet, hóa đơn, sao kê.","Mẫu Excel tính giá vốn dịch vụ theo dự án, phân bổ chi phí chung và báo cáo lãi lỗ từng hợp đồng.","Mẫu theo dõi doanh thu chưa thực hiện, lịch ghi nhận doanh thu thuê bao và checklist đóng sổ ngành dịch vụ.","Bộ 12 câu lệnh AI (prompt) đọc hợp đồng dịch vụ, xác định nghĩa vụ và lịch ghi nhận doanh thu."],"ls":["Đặc thù kế toán doanh nghiệp dịch vụ: không kho hàng, nhiều hợp đồng","Ghi nhận doanh thu dịch vụ: một lần, nhiều kỳ, theo tiến độ","Giá vốn dịch vụ: tập hợp chi phí theo hợp đồng và dự án","Chi phí nhân sự, cộng tác viên và thuê ngoài: hồ sơ và thuế","Kế toán theo ngành dịch vụ: nhà hàng, logistics, công nghệ, đào tạo","Thuế doanh nghiệp dịch vụ: GTGT, TNDN, nhà thầu và rủi ro","Đóng sổ, báo cáo tài chính và báo cáo lãi lỗ theo hợp đồng","Tỷ lệ sử dụng nhân sự, định giá dịch vụ và tự động hóa với AI"],"l1":{"t":"Đặc thù kế toán doanh nghiệp dịch vụ: không kho hàng, nhiều hợp đồng","sum":"Bài mở đầu làm rõ điểm khác biệt của kế toán dịch vụ so với thương mại và sản xuất. Học viên hiểu nơi rủi ro sai sót tập trung.","points":["Sản phẩm dịch vụ không lưu kho, được tạo ra và tiêu dùng gần như đồng thời; chi phí chủ yếu là nhân công và chi phí chung.","Hợp đồng là trung tâm: phạm vi, tiến độ, điều kiện nghiệm thu, thanh toán quyết định cách ghi nhận doanh thu.","Theo TT 133, chi phí dịch vụ dở dang tập hợp trên TK 154, khi hoàn thành chuyển sang giá vốn 632.","Rủi ro chính: ghi nhận doanh thu sai kỳ, không tập hợp được chi phí theo hợp đồng, chi phí nhân sự thiếu hồ sơ.","Mỗi ngành dịch vụ có đặc thù riêng: nhà hàng có nguyên liệu, logistics có chi phí thuê ngoài, công nghệ có phần mềm và thuê bao."],"case":"Công ty TNHH Tư Vấn Minh An ghi toàn bộ chi phí nhân sự vào chi phí quản lý, nên không biết hợp đồng nào lãi, hợp đồng nào lỗ. Sau khi áp dụng timesheet theo dự án và tập hợp qua TK 154, doanh nghiệp phát hiện 3 hợp đồng lỗ do vượt giờ 40%. Hợp đồng mới được định giá lại theo giờ công thực tế.","trend":"Kinh tế dịch vụ và dịch vụ số đang chiếm tỷ trọng ngày càng lớn; kế toán dịch vụ cần kỹ năng đọc hợp đồng và dữ liệu dự án nhiều hơn kỹ năng kho.","practice":"Phân tích mô hình kinh doanh của doanh nghiệp dịch vụ bạn quen thuộc: nguồn doanh thu, cấu trúc chi phí, điểm rủi ro kế toán chính.","takeaway":"Trong doanh nghiệp dịch vụ, hợp đồng và giờ công là hàng tồn kho thực sự."}},{"id":"KH015","code":"kh015","f":"KT","fn":"Kế toán","t":"Kế toán doanh nghiệp sản xuất và tính giá thành","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học nâng cao giúp bạn tổ chức kế toán chi phí và tính giá thành chuyên sâu cho doanh nghiệp sản xuất, từ định mức, tập hợp chi phí, đánh giá dở dang đến phân tích chênh lệch và giá thành theo hoạt động. Bạn thực hành trên dữ liệu thật của nhà máy thực phẩm, nhựa, may mặc với bảng tính giá thành đa phương pháp, mẫu phân tích chênh lệch và báo cáo quản trị chi phí dùng ngay. Kết thúc khoá, bạn xây được hệ thống giá thành đáng tin cậy, phát hiện lãng phí và tư vấn định giá, cắt giảm chi phí cho ban giám đốc.","a":"Kế toán giá thành, kế toán tổng hợp và kế toán trưởng doanh nghiệp sản xuất, kiểm soát viên tài chính nhà máy, chủ doanh nghiệp sản xuất.","o":["Xây dựng hệ thống định mức nguyên vật liệu, nhân công, máy móc và kiểm soát tiêu hao theo định mức.","Tập hợp chi phí sản xuất theo phân xưởng, sản phẩm, đơn hàng và phân bổ chi phí sản xuất chung theo công suất bình thường.","Đánh giá sản phẩm dở dang và tính giá thành theo phương pháp giản đơn, hệ số, tỷ lệ, phân bước và đơn đặt hàng.","Phân tích chênh lệch giá và lượng giữa chi phí thực tế và định mức, chỉ ra nguyên nhân và trách nhiệm.","Lập báo cáo giá thành, lãi gộp theo sản phẩm và đề xuất cắt giảm chi phí có định lượng."],"k":"Nguyên liệu biến động, khách ép giá, châu Âu đòi số liệu carbon: nhà máy sống còn nhờ giá thành chính xác.","w":["Chế độ kế toán TT 99/2025 thay TT 200/2014 từ 01/01/2026 cho doanh nghiệp lớn; doanh nghiệp sản xuất cần rà soát lại hệ thống tài khoản chi phí và phương pháp tính giá thành.","Thị trường xuất khẩu yêu cầu dữ liệu phát thải gắn với sản phẩm, như CBAM của EU áp dụng chính thức từ 2026 với một số nhóm hàng; giá thành và carbon trên mỗi sản phẩm đang dần đi cùng nhau.","IoT, MES và tự động hóa nhà máy tạo dữ liệu sản xuất theo thời gian thực; kế toán giá thành biết khai thác dữ liệu sẽ chuyển từ người tính sổ sang người tối ưu chi phí."],"dl":["Bộ mẫu Excel tính giá thành 5 phương pháp có đánh giá dở dang và kiểm tra cân đối tự động.","Mẫu xây dựng định mức và bảng phân tích chênh lệch giá – lượng cho nguyên liệu, nhân công, chi phí chung.","Quy trình SOP khóa sổ giá thành tháng và checklist kiểm soát chi phí nhà máy.","Bộ 15 câu lệnh AI (prompt) phân tích biến động giá thành, phát hiện tiêu hao bất thường và soạn báo cáo quản trị."],"ls":["Tổ chức kế toán chi phí sản xuất: đối tượng, kỳ tính và hệ thống tài khoản","Định mức chi phí: thước đo để kiểm soát và định giá","Tập hợp chi phí nguyên vật liệu, nhân công và chi phí sản xuất chung","Đánh giá sản phẩm dở dang và các phương pháp tính giá thành","Phế liệu, sản phẩm hỏng, hao hụt và gia công","Phân tích chênh lệch: tìm nguyên nhân sau mỗi đồng vượt chi phí","Giá thành theo hoạt động và giá thành carbon: góc nhìn mới cho quyết định","Nhà máy số: tự động hóa giá thành, dashboard và AI"],"l1":{"t":"Tổ chức kế toán chi phí sản xuất: đối tượng, kỳ tính và hệ thống tài khoản","sum":"Bài mở đầu xác định nền tảng của hệ thống giá thành: đối tượng tập hợp chi phí, đối tượng tính giá thành và kỳ tính. Lựa chọn sai ở bước này khiến mọi con số sau đều lệch.","points":["Đối tượng tập hợp chi phí có thể là phân xưởng, dây chuyền, công đoạn, đơn hàng; đối tượng tính giá thành là sản phẩm, bán thành phẩm hoặc đơn hàng.","Chế độ cho doanh nghiệp lớn tập hợp qua TK 621, 622, 627 rồi kết chuyển 154; TT 133 tập hợp trực tiếp trên TK 154 chi tiết theo khoản mục.","Kỳ tính giá thành thường theo tháng với sản xuất liên tục, theo đơn hàng hoàn thành với sản xuất theo đơn.","Thiết kế mã chi phí theo khoản mục, phân xưởng, sản phẩm để vừa phục vụ báo cáo tài chính vừa phục vụ quản trị.","Doanh nghiệp lớn chuyển sang TT 99/2025 từ 01/01/2026 cần đối chiếu văn bản gốc để rà soát hệ thống tài khoản chi phí."],"case":"Công ty Cổ phần Thực Phẩm Minh An sản xuất 3 dòng sản phẩm trên 2 dây chuyền nhưng tập hợp chi phí chung cho cả nhà máy. Giá thành 3 dòng gần bằng nhau dù quy trình khác hẳn. Sau khi chuyển đối tượng tập hợp về từng dây chuyền, giá thành dòng cao cấp tăng 18%, dòng phổ thông giảm 9%, phản ánh đúng thực tế.","trend":"Hệ thống ERP và MES cho phép tập hợp chi phí đến từng lệnh sản xuất; kế toán giá thành nên thiết kế đối tượng chi phí chi tiết vừa đủ để khai thác dữ liệu mà không quá tải.","practice":"Xác định đối tượng tập hợp chi phí, đối tượng tính giá thành, kỳ tính và cấu trúc mã chi phí cho nhà máy mẫu có 3 phân xưởng, 5 sản phẩm.","takeaway":"Chọn đúng đối tượng chi phí là nửa thành công của hệ thống giá thành."}},{"id":"KH016","code":"kh016","f":"KT","fn":"Kế toán","t":"Kế toán doanh nghiệp xây lắp","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học nâng cao giúp bạn tổ chức kế toán doanh nghiệp xây lắp theo từng công trình, hạng mục: dự toán, tập hợp chi phí, giá thành, doanh thu theo tiến độ, nghiệm thu, thanh quyết toán và thuế đặc thù ngành. Bạn thực hành trên hồ sơ công trình thật với dự toán, biên bản nghiệm thu, hợp đồng thầu phụ, kèm mẫu theo dõi chi phí công trình và bảng đối chiếu dự toán – thực tế dùng ngay. Kết thúc khoá, bạn kiểm soát được lãi lỗ từng công trình, lập hồ sơ thuế chặt chẽ và cảnh báo sớm rủi ro vượt chi phí cho ban giám đốc.","a":"Kế toán công trình, kế toán tổng hợp và kế toán trưởng doanh nghiệp xây dựng, cán bộ quản lý dự án muốn hiểu tài chính công trình.","o":["Tổ chức hệ thống theo dõi chi phí theo công trình, hạng mục và khoản mục gắn với dự toán.","Hạch toán chính xác chi phí vật liệu, nhân công, máy thi công, chi phí chung và thầu phụ.","Xác định doanh thu, giá vốn theo tiến độ hoặc theo khối lượng nghiệm thu phù hợp chuẩn mực về hợp đồng xây dựng.","Xử lý đúng hóa đơn, thuế GTGT, thuế TNDN, thuế TNCN đặc thù công trình, kể cả công trình ngoại tỉnh.","Lập báo cáo lãi lỗ công trình, so sánh dự toán – thực tế và cảnh báo vượt chi phí."],"k":"Công trình kéo dài nhiều năm, chi phí rải khắp công trường: kế toán giỏi biết từng công trình lãi hay lỗ.","w":["Chế độ kế toán TT 99/2025 thay TT 200/2014 từ 01/01/2026; doanh nghiệp xây lắp quy mô lớn cần rà soát hệ thống tài khoản chi phí, doanh thu hợp đồng xây dựng.","Điều kiện thanh toán không dùng tiền mặt từ 5 triệu đồng theo NĐ 181/2025 và xử phạt sửa đổi theo NĐ 310/2025 tác động mạnh đến ngành có nhiều chi phí vật tư, nhân công thời vụ ở công trường.","BIM, quản lý dự án số và yêu cầu công trình xanh đang làm thay đổi cách lập dự toán, theo dõi chi phí và báo cáo; kế toán xây lắp cần kỹ năng dữ liệu mới."],"dl":["Bộ mẫu Excel theo dõi chi phí công trình theo khoản mục, so sánh dự toán – thực tế – khối lượng nghiệm thu.","Checklist hồ sơ công trình: hợp đồng, dự toán, nhật ký, nghiệm thu, thanh quyết toán, hồ sơ thuế.","Mẫu quản lý thầu phụ, tạm ứng, bảo lãnh, giữ lại bảo hành và bảng đối chiếu công nợ công trình.","Bộ 12 câu lệnh AI (prompt) đọc hợp đồng xây dựng, so sánh dự toán – quyết toán và soạn báo cáo cảnh báo."],"ls":["Đặc thù kế toán xây lắp: công trình là trung tâm của mọi con số","Dự toán và hợp đồng xây dựng: đọc đúng để hạch toán đúng","Tập hợp chi phí công trình: vật liệu, nhân công, máy thi công, chi phí chung","Thầu phụ, tạm ứng, bảo lãnh và giữ lại bảo hành","Doanh thu và giá vốn hợp đồng xây dựng theo tiến độ","Thuế trong xây lắp: hóa đơn, GTGT công trình ngoại tỉnh, TNDN, TNCN","Quyết toán công trình và báo cáo lãi lỗ: dự toán – thực tế – nghiệm thu","Xây lắp số và công trình xanh: BIM, dữ liệu, AI và ESG"],"l1":{"t":"Đặc thù kế toán xây lắp: công trình là trung tâm của mọi con số","sum":"Bài mở đầu làm rõ đặc điểm sản xuất xây lắp và tác động đến tổ chức kế toán. Học viên hiểu vì sao mỗi công trình cần được quản lý như một doanh nghiệp nhỏ.","points":["Sản phẩm xây lắp đơn chiếc, thời gian dài, giá trị lớn, thi công ngoài trời và phân tán theo địa bàn.","Đối tượng tập hợp chi phí và tính giá thành là công trình, hạng mục công trình hoặc giai đoạn hoàn thành.","Dự toán và hợp đồng là căn cứ để kiểm soát chi phí, xác định doanh thu và lợi nhuận dự kiến.","Chi phí tập hợp qua TK 154 chi tiết theo công trình; doanh nghiệp lớn tập hợp theo khoản mục vật liệu, nhân công, máy thi công, chi phí chung.","Tổ chức kế toán có thể tập trung tại văn phòng hoặc có kế toán công trường; cần quy trình luân chuyển chứng từ chặt chẽ."],"case":"Công ty Cổ phần Xây Dựng Minh An thi công 6 công trình nhưng chỉ có một tài khoản chi phí chung. Cuối năm có lãi tổng nhưng không biết công trình nào lỗ. Kế toán mở chi tiết TK 154 theo công trình và khoản mục, phát hiện 2 công trình lỗ do chi phí máy thuê vượt dự toán 35%.","trend":"Quản lý dự án số và BIM đang được khuyến khích áp dụng trong ngành xây dựng; dữ liệu khối lượng từ mô hình số giúp kế toán đối chiếu chi phí với tiến độ chính xác hơn.","practice":"Thiết kế cấu trúc mã chi phí công trình gồm công trình, hạng mục, khoản mục cho doanh nghiệp mẫu có 4 công trình đang thi công.","takeaway":"Mỗi công trình phải có sổ sách như một doanh nghiệp riêng."}},{"id":"KH017","code":"kh017","f":"KT","fn":"Kế toán","t":"Kế toán doanh nghiệp xuất nhập khẩu và ngoại tệ","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học nâng cao giúp bạn hạch toán chính xác toàn bộ nghiệp vụ xuất nhập khẩu và ngoại tệ: điều kiện Incoterms, giá nhập khẩu, thuế tại khâu hải quan, doanh thu xuất khẩu, hoàn thuế, chênh lệch tỷ giá và đánh giá lại cuối kỳ. Bạn thực hành trên bộ hồ sơ thật gồm hợp đồng ngoại thương, tờ khai hải quan, vận đơn, chứng từ ngân hàng, với mẫu tính giá nhập khẩu, bảng theo dõi ngoại tệ và checklist hồ sơ thuế 0% dùng ngay. Kết thúc khoá, bạn tự tin quản lý kế toán cho doanh nghiệp xuất nhập khẩu, bảo vệ quyền hoàn thuế và kiểm soát rủi ro tỷ giá.","a":"Kế toán xuất nhập khẩu, kế toán tổng hợp và kế toán trưởng doanh nghiệp thương mại quốc tế, sản xuất xuất khẩu, logistics; nhân viên chứng từ muốn hiểu kế toán.","o":["Xác định đúng thời điểm chuyển giao rủi ro, ghi nhận hàng và doanh thu theo các điều kiện Incoterms phổ biến.","Tính giá nhập kho hàng nhập khẩu gồm giá mua, chi phí vận chuyển, bảo hiểm, thuế nhập khẩu và các thuế không được hoàn lại.","Hạch toán doanh thu xuất khẩu, thuế suất GTGT 0% và lập hồ sơ đề nghị hoàn thuế đủ điều kiện.","Hạch toán chênh lệch tỷ giá phát sinh và đánh giá lại khoản mục tiền tệ có gốc ngoại tệ cuối kỳ chính xác.","Lập báo cáo vị thế ngoại tệ và đề xuất biện pháp quản trị rủi ro tỷ giá cho doanh nghiệp."],"k":"Tỷ giá biến động, hải quan số, CBAM từ 2026: xuất nhập khẩu cần kế toán hiểu cả ngoại thương lẫn sổ sách.","w":["CBAM của EU áp dụng chính thức từ 2026 với một số nhóm hàng và yêu cầu minh bạch chuỗi cung ứng ngày càng tăng; dữ liệu kế toán – sản xuất trở thành điều kiện để giữ đơn hàng xuất khẩu.","Luật GTGT 48/2024/QH15 và các quy định về thanh toán không dùng tiền mặt từ 5 triệu đồng theo NĐ 181/2025 đặt ra yêu cầu chặt chẽ hơn về hồ sơ thuế suất 0% và khấu trừ, hoàn thuế.","Hải quan số, chứng từ điện tử và biến động tỷ giá khiến kế toán phải xử lý dữ liệu nhanh và quản trị rủi ro ngoại tệ chủ động thay vì chỉ ghi nhận cuối kỳ."],"dl":["Bộ mẫu Excel tính giá nhập kho hàng nhập khẩu phân bổ chi phí theo lô, theo tờ khai.","Bảng theo dõi ngoại tệ theo nguyên tệ và quy đổi, tự tính chênh lệch tỷ giá thực hiện và đánh giá lại cuối kỳ.","Checklist hồ sơ xuất khẩu đủ điều kiện thuế suất 0% và hồ sơ đề nghị hoàn thuế GTGT.","Bộ 12 câu lệnh AI (prompt) đọc hợp đồng ngoại thương, đối chiếu tờ khai – hóa đơn – chứng từ ngân hàng và soạn báo cáo rủi ro tỷ giá."],"ls":["Thương mại quốc tế cho kế toán: Incoterms, chứng từ và dòng chảy hàng – tiền","Nguyên tắc kế toán ngoại tệ: tỷ giá nào cho giao dịch nào","Kế toán nhập khẩu: giá nhập kho, thuế tại khâu hải quan và khấu trừ","Kế toán xuất khẩu: doanh thu, thuế suất 0% và hồ sơ hoàn thuế","Đánh giá lại ngoại tệ cuối kỳ và trình bày báo cáo tài chính","Giao dịch liên kết, gia công xuất khẩu và thuế tối thiểu toàn cầu","Quản trị rủi ro tỷ giá: vị thế ngoại tệ và công cụ phòng ngừa","Xuất nhập khẩu số: hải quan điện tử, dữ liệu chuỗi cung ứng, CBAM và AI"],"l1":{"t":"Thương mại quốc tế cho kế toán: Incoterms, chứng từ và dòng chảy hàng – tiền","sum":"Bài mở đầu trang bị kiến thức ngoại thương cần thiết để hạch toán đúng. Học viên hiểu Incoterms quyết định khi nào hàng thuộc về ai và chi phí nào do ai chịu.","points":["Incoterms 2020 quy định nghĩa vụ giao hàng, chuyển giao rủi ro và phân chia chi phí giữa người bán và người mua.","Với FOB, rủi ro chuyển khi hàng xếp lên tàu tại cảng đi; với CIF, người bán trả cước và bảo hiểm nhưng rủi ro cũng chuyển tại cảng đi; với DDP, người bán chịu đến khi giao tại nơi đến.","Bộ chứng từ chính: hợp đồng, hóa đơn thương mại, phiếu đóng gói, vận đơn, tờ khai hải quan, chứng nhận xuất xứ, chứng từ thanh toán.","Phương thức thanh toán phổ biến: chuyển tiền (T/T), thư tín dụng (L/C), nhờ thu; mỗi phương thức có rủi ro và chứng từ khác nhau.","Thời điểm ghi nhận hàng mua, doanh thu bán phải căn cứ vào điều kiện giao hàng chứ không chỉ ngày hóa đơn."],"case":"Công ty TNHH Xuất Khẩu Minh An bán hàng theo điều kiện FOB, tàu chạy ngày 30/12 nhưng kế toán chờ nhận tiền tháng 1 mới ghi doanh thu. Doanh thu năm bị thiếu 2,4 tỷ. Rà soát theo Incoterms, kế toán ghi nhận doanh thu tại ngày xếp hàng lên tàu theo vận đơn.","trend":"Vận đơn điện tử, chứng từ thương mại số và hệ thống một cửa quốc gia đang rút ngắn thời gian thông quan; kế toán cần đọc và lưu chứng từ số thay vì chờ bản giấy.","practice":"Với 6 hợp đồng mẫu có Incoterms khác nhau, xác định thời điểm ghi nhận hàng hoặc doanh thu và bên chịu từng loại chi phí.","takeaway":"Incoterms là ngôn ngữ chung giữa hợp đồng ngoại thương và sổ kế toán."}},{"id":"KH018","code":"kh018","f":"KT","fn":"Kế toán","t":"Khóa sổ cuối kỳ và bút toán kết chuyển","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp kế toán xây dựng quy trình khóa sổ tháng, quý, năm bài bản: đối chiếu, trích lập, phân bổ, kết chuyển và xác định kết quả kinh doanh. Học qua tình huống thật tại doanh nghiệp Việt Nam, kèm checklist, bảng đối chiếu Excel và bút toán mẫu dùng ngay theo TT 133/2016 và TT 99/2025. Sau khoá, bạn rút ngắn thời gian khóa sổ, giảm sai sót và có bộ số liệu sạch cho báo cáo tài chính, tờ khai thuế.","a":"Kế toán viên đã vững nghiệp vụ hằng ngày, muốn tự chủ khóa sổ và chuẩn bị bước lên kế toán tổng hợp.","o":["Lập được checklist khóa sổ tháng, quý, năm phù hợp doanh nghiệp mình với người phụ trách và hạn hoàn thành.","Đối chiếu khớp được tiền, công nợ, hàng tồn kho, tài sản cố định với chứng từ và dữ liệu bên ngoài trước khi khóa.","Thực hiện đúng các bút toán trích trước, phân bổ, dồn tích và kết chuyển theo TT 133/2016 hoặc TT 99/2025.","Tự kiểm tra được bảng cân đối số phát sinh và giải thích được mọi số dư bất thường.","Rút ngắn được thời gian khóa sổ tháng nhờ lịch khóa sổ chuẩn và các bước tự động hóa đơn giản."],"k":"Mỗi cuối tháng bạn vẫn thức khuya chạy số, sửa lệch rồi lại lệch? Khóa sổ có thể nhanh, sạch và chủ động hơn nhiều.","w":["Từ 01/01/2026, TT 99/2025 thay TT 200/2014, nhiều doanh nghiệp phải rà lại hệ thống tài khoản và bút toán kết chuyển cuối kỳ.","Cơ quan thuế quản lý dựa trên dữ liệu hóa đơn điện tử và sao kê, số liệu sổ sách lệch so với dữ liệu thuế sẽ bị phát hiện nhanh hơn.","Xu hướng khóa sổ nhanh (fast close) bằng tự động hóa và AI đang trở thành tiêu chuẩn đánh giá năng lực kế toán ở doanh nghiệp hiện đại."],"dl":["Bộ checklist khóa sổ tháng – quý – năm (Excel) có cột người phụ trách, hạn, trạng thái.","Bộ mẫu Excel đối chiếu tiền, công nợ, hàng tồn kho, TSCĐ và bảng phân bổ chi phí trả trước.","Quy trình SOP khóa sổ cuối kỳ kèm danh mục bút toán kết chuyển mẫu.","Bộ câu lệnh AI (prompt) hỗ trợ rà soát số dư bất thường và soạn ghi chú giải trình cuối kỳ."],"ls":["Khóa sổ là gì và vì sao nó quyết định chất lượng mọi báo cáo","Hoàn thiện chứng từ và nghiệp vụ trước giờ khóa","Đối chiếu tiền mặt, tiền gửi ngân hàng không còn lệch một đồng","Đối chiếu công nợ: khách hàng và nhà cung cấp cùng xác nhận","Hàng tồn kho, giá vốn và tài sản cố định cuối kỳ","Bút toán trích trước, phân bổ và dồn tích đúng bản chất","Thuế cuối kỳ: GTGT, TNDN tạm nộp và TNCN khớp với sổ","Kết chuyển, xác định kết quả và khóa sổ thông minh với AI"],"l1":{"t":"Khóa sổ là gì và vì sao nó quyết định chất lượng mọi báo cáo","sum":"Bài mở đầu làm rõ bản chất khóa sổ, mối liên hệ giữa khóa sổ với báo cáo thuế và báo cáo tài chính. Học viên nắm trình tự tổng thể từ rà soát chứng từ đến kết chuyển lãi lỗ.","points":["Khóa sổ là chốt số liệu một kỳ kế toán; sau khi khóa, mọi sửa đổi phải qua quy trình điều chỉnh có phê duyệt, không sửa thẳng chứng từ.","Trình tự chuẩn gồm 5 nhóm việc: hoàn thiện chứng từ, đối chiếu, bút toán cuối kỳ, kết chuyển, kiểm tra và khóa trên phần mềm.","Khóa sổ tháng phục vụ quản trị và tờ khai GTGT; khóa sổ quý phục vụ tạm nộp TNDN; khóa sổ năm phục vụ báo cáo tài chính và quyết toán.","Số liệu khóa sổ sai kéo theo sai tờ khai, sai báo cáo tài chính và rủi ro bị phạt theo NĐ 125/2020 sửa bởi NĐ 310/2025.","Doanh nghiệp tốt thường đặt mục tiêu khóa sổ tháng trong 3–5 ngày làm việc đầu tháng sau, có lịch cố định và người chịu trách nhiệm từng phần."],"case":"Công ty TNHH Minh An khóa sổ tháng thường mất 12 ngày vì chứng từ về muộn và không ai chịu trách nhiệm đối chiếu ngân hàng. Kế toán trưởng lập lịch khóa sổ 5 ngày, giao từng phần hành cho người cụ thể và chốt hạn nhận chứng từ ngày 2 hằng tháng; sau 3 tháng thời gian khóa sổ giảm còn 5 ngày.","trend":"Fast close và continuous accounting (ghi nhận, đối chiếu liên tục trong tháng) là xu hướng 2026–2030. Học viên nên tập chia nhỏ việc đối chiếu ra hằng tuần thay vì dồn cuối tháng.","practice":"Vẽ sơ đồ quy trình khóa sổ hiện tại của doanh nghiệp bạn, đánh dấu 3 điểm nghẽn tốn thời gian nhất và đề xuất cách xử lý.","takeaway":"Khóa sổ nhanh không đến từ làm gấp, mà từ làm đều trong tháng."}},{"id":"KH019","code":"kh019","f":"KT","fn":"Kế toán","t":"Lập báo cáo tài chính doanh nghiệp nhỏ và vừa","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học hướng dẫn lập trọn bộ báo cáo tài chính năm cho doanh nghiệp nhỏ và vừa theo TT 133/2016, từ chuẩn bị số liệu đến thuyết minh và nộp hồ sơ. Học viên thực hành trên bộ số liệu mẫu của một doanh nghiệp Việt Nam, dùng bảng mapping Excel và checklist kiểm tra chéo dùng ngay. Kết quả là bạn tự lập được bộ báo cáo đúng, khớp, giải thích được từng chỉ tiêu và nộp đúng hạn.","a":"Kế toán doanh nghiệp nhỏ và vừa, kế toán dịch vụ và người chuẩn bị đảm nhận vai trò kế toán tổng hợp.","o":["Lập được Báo cáo tình hình tài chính, Báo cáo kết quả hoạt động kinh doanh, Báo cáo lưu chuyển tiền tệ và Thuyết minh cho DNNVV.","Xây dựng được bảng mapping từ bảng cân đối số phát sinh lên từng chỉ tiêu báo cáo bằng Excel.","Tự kiểm tra được tính khớp đúng giữa các báo cáo và với tờ khai quyết toán TNDN.","Phát hiện và sửa được ít nhất 10 lỗi trình bày thường gặp trước khi nộp.","Nộp báo cáo tài chính đúng hạn và lưu trữ hồ sơ đúng quy định."],"k":"Báo cáo tài chính là tấm danh thiếp của doanh nghiệp trước ngân hàng, nhà đầu tư và cơ quan thuế. Bạn có tự tin ký vào nó?","w":["TT 99/2025 thay TT 200/2014 từ 01/01/2026 khiến nhiều doanh nghiệp cân nhắc lại chế độ kế toán áp dụng, kế toán DNNVV cần nắm vững TT 133/2016 và điểm khác biệt.","Ngân hàng, nhà đầu tư và cơ quan thuế ngày càng đối chiếu báo cáo tài chính với dữ liệu hóa đơn điện tử, sao kê và tờ khai, sai lệch dễ bị phát hiện.","Lộ trình IFRS và xu hướng báo cáo phi tài chính (ESG) đòi hỏi kế toán hiểu sâu bản chất báo cáo, không chỉ bấm phần mềm."],"dl":["Bộ mẫu Excel lập báo cáo tài chính DNNVV có bảng mapping tài khoản – chỉ tiêu.","Checklist 40 điểm kiểm tra chéo báo cáo tài chính trước khi ký.","Mẫu thuyết minh báo cáo tài chính có sẵn câu chữ chính sách kế toán phổ biến.","Bộ câu lệnh AI (prompt) hỗ trợ soạn thuyết minh và giải trình biến động số liệu."],"ls":["Bộ báo cáo tài chính DNNVV: đọc đúng trước khi lập","Chuẩn bị số liệu sạch: nền móng của báo cáo đúng","Lập Báo cáo tình hình tài chính bằng bảng mapping","Báo cáo kết quả kinh doanh: lợi nhuận đến từ đâu","Báo cáo lưu chuyển tiền tệ: nỗi sợ thành kỹ năng","Thuyết minh báo cáo tài chính chuyên nghiệp, viết nhanh với AI","Kiểm tra chéo: 10 lỗi khiến báo cáo bị trả về","Nộp báo cáo, lưu trữ hồ sơ và chuẩn bị cho năm sau"],"l1":{"t":"Bộ báo cáo tài chính DNNVV: đọc đúng trước khi lập","sum":"Bài giới thiệu hệ thống báo cáo tài chính theo TT 133/2016, đối tượng sử dụng và nguyên tắc lập. Học viên hiểu mỗi báo cáo trả lời câu hỏi gì cho người đọc.","points":["Bộ báo cáo năm gồm Báo cáo tình hình tài chính, Báo cáo kết quả hoạt động kinh doanh, Báo cáo lưu chuyển tiền tệ, Thuyết minh và Bảng cân đối tài khoản nộp kèm cơ quan thuế.","Doanh nghiệp nhỏ và vừa được chọn áp dụng TT 133/2016 hoặc chế độ kế toán doanh nghiệp chung; từ 2026 chế độ chung là TT 99/2025.","Các nguyên tắc nền tảng: hoạt động liên tục, cơ sở dồn tích, nhất quán, trọng yếu, bù trừ có giới hạn và có số liệu so sánh.","Người đọc chính là chủ sở hữu, ngân hàng, cơ quan thuế, nhà đầu tư; mỗi nhóm quan tâm chỉ tiêu khác nhau.","Kế toán lập, kế toán trưởng hoặc người phụ trách kế toán kiểm tra và người đại diện theo pháp luật ký duyệt."],"case":"Công ty TNHH Nội thất Gia Huy vay vốn ngân hàng nhưng bị yêu cầu giải trình vì báo cáo kết quả có lãi trong khi dòng tiền kinh doanh âm 1,2 tỷ đồng. Kế toán chuẩn bị thuyết minh về hàng tồn kho tăng mạnh và công nợ phải thu kéo dài, giúp ngân hàng hiểu đúng tình hình.","trend":"Báo cáo tài chính đang chuyển sang dạng dữ liệu số có thể đọc bằng máy. Kế toán nên làm quen với chuẩn dữ liệu và trình bày nhất quán để dễ chia sẻ, phân tích.","practice":"Lấy báo cáo tài chính năm trước của doanh nghiệp bạn, viết 1 câu tóm tắt thông điệp chính của từng báo cáo.","takeaway":"Lập báo cáo là kể câu chuyện tài chính bằng con số, phải đúng và nhất quán."}},{"id":"KH020","code":"kh020","f":"KT","fn":"Kế toán","t":"Đọc hiểu và phân tích báo cáo tài chính","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học trang bị tư duy và công cụ để đọc, phân tích báo cáo tài chính như một chuyên gia: cấu trúc vốn, chất lượng lợi nhuận, dòng tiền, chỉ số và dấu hiệu bất thường. Học viên phân tích báo cáo của các doanh nghiệp Việt Nam điển hình bằng mô hình Excel dựng sẵn, kết hợp AI để tăng tốc. Kết quả là bạn viết được báo cáo phân tích có kết luận rõ ràng và khuyến nghị hành động cho ban giám đốc, ngân hàng hoặc nhà đầu tư.","a":"Kế toán tổng hợp, chuyên viên tài chính, tín dụng, nhà đầu tư và chủ doanh nghiệp muốn ra quyết định dựa trên số liệu.","o":["Đọc và tóm tắt được bức tranh tài chính của một doanh nghiệp trong 30 phút theo khung 5 câu hỏi.","Tính và diễn giải được tối thiểu 15 chỉ số thanh khoản, hiệu quả, đòn bẩy và sinh lời.","Đánh giá được chất lượng lợi nhuận qua đối chiếu lợi nhuận với dòng tiền kinh doanh.","Nhận diện được ít nhất 8 dấu hiệu cảnh báo sai lệch hoặc rủi ro tài chính.","Viết được báo cáo phân tích 2 trang có kết luận và khuyến nghị cụ thể."],"k":"Doanh nghiệp báo lãi vẫn có thể cạn tiền. Đọc đúng báo cáo tài chính giúp bạn thấy rủi ro trước khi nó thành khủng hoảng.","w":["Giai đoạn 2026 trở đi, ngân hàng và nhà đầu tư thẩm định chặt hơn, đòi hỏi doanh nghiệp tự phân tích và giải trình được sức khỏe tài chính.","TT 99/2025 có hiệu lực từ 01/01/2026 và lộ trình IFRS khiến cách trình bày, chỉ tiêu báo cáo thay đổi, người đọc cần cập nhật để so sánh đúng.","AI và công cụ phân tích dữ liệu giúp xử lý hàng chục báo cáo trong vài phút, giá trị của chuyên gia chuyển sang khả năng diễn giải và phán đoán."],"dl":["Mô hình Excel phân tích báo cáo tài chính tự động tính chỉ số, biểu đồ xu hướng và so sánh ngành.","Checklist 25 dấu hiệu bất thường trên báo cáo tài chính.","Mẫu báo cáo phân tích tài chính 2 trang cho ban giám đốc và ngân hàng.","Bộ câu lệnh AI (prompt) phân tích, so sánh và viết nhận định từ báo cáo tài chính."],"ls":["Tư duy đọc báo cáo tài chính: 5 câu hỏi của chuyên gia","Cơ cấu tài sản và nguồn vốn: ai đang nuôi doanh nghiệp","Chất lượng lợi nhuận: lãi thật hay lãi trên giấy","Phân tích dòng tiền: nhịp tim của doanh nghiệp","Bộ chỉ số tài chính: thanh khoản, hiệu quả, đòn bẩy, sinh lời","Dấu hiệu bất thường và rủi ro sai lệch báo cáo","Phân tích tăng tốc với AI và dashboard","Viết báo cáo phân tích và khuyến nghị thuyết phục"],"l1":{"t":"Tư duy đọc báo cáo tài chính: 5 câu hỏi của chuyên gia","sum":"Bài xây dựng khung tư duy trước khi tính chỉ số. Học viên biết đọc báo cáo theo mục đích và bối cảnh ngành.","points":["5 câu hỏi cốt lõi: doanh nghiệp kiếm tiền bằng gì, lợi nhuận có thật không, tiền đi đâu, ai đang tài trợ tài sản, rủi ro lớn nhất là gì.","Luôn đọc báo cáo kiểm toán và ý kiến kiểm toán trước, chú ý ý kiến ngoại trừ hoặc đoạn nhấn mạnh.","Đọc thuyết minh chính sách kế toán để hiểu cách ghi nhận doanh thu, khấu hao, dự phòng trước khi so sánh.","So sánh tối thiểu 3 năm và với doanh nghiệp cùng ngành; một con số đơn lẻ không nói lên điều gì.","Gắn phân tích với mục đích: cho vay quan tâm khả năng trả nợ, đầu tư quan tâm sinh lời và tăng trưởng, quản trị quan tâm hiệu quả vận hành."],"case":"Một chuyên viên tín dụng đọc báo cáo của Công ty CP Xây lắp Trường Sơn thấy lợi nhuận tăng 30% nhưng kiểm toán có đoạn nhấn mạnh về khoản phải thu 45 tỷ đồng chưa được xác nhận. Ngân hàng yêu cầu bổ sung đối chiếu công nợ trước khi giải ngân.","trend":"Phân tích tài chính đang kết hợp dữ liệu phi tài chính như đánh giá khách hàng, dữ liệu ngành, chỉ số ESG. Học viên nên mở rộng nguồn dữ liệu ngoài báo cáo.","practice":"Chọn báo cáo tài chính một doanh nghiệp niêm yết, trả lời 5 câu hỏi cốt lõi trong tối đa 1 trang.","takeaway":"Hỏi đúng câu hỏi quan trọng hơn tính nhiều chỉ số."}},{"id":"KH021","code":"kh021","f":"KT","fn":"Kế toán","t":"Kế toán tổng hợp từ A đến Z","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học đưa bạn đi trọn chu trình kế toán tổng hợp: tổ chức bộ máy, kiểm soát từng phần hành, khóa sổ, lập báo cáo tài chính, báo cáo thuế và quyết toán. Phương pháp học xoay quanh một doanh nghiệp mẫu xuyên suốt 12 tháng, với bộ SOP, checklist và mẫu Excel dùng ngay. Kết quả là bạn đủ năng lực đảm nhận vị trí kế toán tổng hợp và kiểm soát số liệu của cả phòng kế toán.","a":"Kế toán viên phần hành có từ 1–2 năm kinh nghiệm muốn lên kế toán tổng hợp, hoặc kế toán tổng hợp muốn hệ thống lại kiến thức theo quy định 2026.","o":["Thiết lập được hệ thống tài khoản, danh mục và số dư đầu kỳ chuẩn cho một doanh nghiệp.","Kiểm soát được 6 phần hành chính: tiền, mua hàng, bán hàng, kho, tài sản, tiền lương bằng checklist định kỳ.","Khóa sổ và lập được bộ báo cáo tài chính, báo cáo thuế khớp số liệu.","Lập được hồ sơ quyết toán thuế TNDN và TNCN năm.","Xây dựng được bộ SOP và lịch công việc tháng cho phòng kế toán."],"k":"Kế toán tổng hợp không chỉ là người làm báo cáo, mà là người nhìn thấy toàn bộ dòng chảy tài chính của doanh nghiệp.","w":["Năm 2026 có nhiều thay đổi đồng thời: TT 99/2025 thay TT 200/2014, Luật TNDN 67/2025/QH15, NĐ 181/2025 về thanh toán không dùng tiền mặt từ 5 triệu đồng, đòi hỏi kế toán tổng hợp cập nhật toàn diện.","Phần mềm và AI tự động hóa nhập liệu, nên giá trị của kế toán chuyển sang kiểm soát, phân tích và tư vấn.","Doanh nghiệp ngày càng cần người nắm cả kế toán, thuế và dữ liệu, vị trí kế toán tổng hợp giỏi luôn thiếu trên thị trường lao động."],"dl":["Bộ SOP kế toán tổng hợp cho 6 phần hành, có điểm kiểm soát và người phụ trách.","Lịch công việc kế toán – thuế 12 tháng (Excel) có nhắc hạn.","Bộ mẫu Excel đối chiếu số liệu giữa sổ sách, hóa đơn, tờ khai và báo cáo tài chính.","Bộ câu lệnh AI (prompt) hỗ trợ rà soát sổ, viết giải trình và soạn văn bản làm việc với cơ quan thuế."],"ls":["Vai trò kế toán tổng hợp và tổ chức bộ máy kế toán hiện đại","Hệ thống tài khoản, danh mục và số dư đầu kỳ chuẩn","Kiểm soát phần hành tiền, mua hàng và công nợ phải trả","Kiểm soát bán hàng, doanh thu và công nợ phải thu","Hàng tồn kho, tài sản cố định và chi phí trả trước","Tiền lương, bảo hiểm và thuế TNCN đúng luật 2026","Khóa sổ, báo cáo tài chính và báo cáo thuế khớp ba chiều","Quyết toán thuế và làm việc tự tin với cơ quan thuế"],"l1":{"t":"Vai trò kế toán tổng hợp và tổ chức bộ máy kế toán hiện đại","sum":"Bài làm rõ vị trí, trách nhiệm của kế toán tổng hợp và cách tổ chức bộ máy hiệu quả. Học viên thiết kế được sơ đồ phân công phù hợp quy mô doanh nghiệp.","points":["Kế toán tổng hợp kiểm soát số liệu phần hành, khóa sổ, lập báo cáo và là đầu mối với kiểm toán, cơ quan thuế.","Nguyên tắc bất kiêm nhiệm: người giữ tiền không ghi sổ tiền, người mua hàng không phê duyệt thanh toán.","Doanh nghiệp nhỏ có thể kết hợp kế toán nội bộ với dịch vụ kế toán bên ngoài, nhưng phải phân định trách nhiệm bằng hợp đồng.","Xây dựng quy chế luân chuyển chứng từ: ai lập, ai duyệt, chuyển kế toán trong bao lâu.","Chọn chế độ kế toán phù hợp: TT 133/2016 cho DNNVV hoặc TT 99/2025 cho doanh nghiệp áp dụng chế độ chung từ 2026."],"case":"Công ty TNHH Thương mại Việt Phát có 4 kế toán nhưng số liệu thường xuyên lệch vì không ai chịu trách nhiệm tổng hợp. Sau khi bổ nhiệm kế toán tổng hợp, lập quy chế luân chuyển chứng từ và lịch khóa sổ, báo cáo tháng được nộp đúng ngày 5.","trend":"Mô hình phòng kế toán tinh gọn kết hợp phần mềm đám mây, tự động hóa và dịch vụ thuê ngoài đang tăng nhanh. Kế toán tổng hợp cần kỹ năng quản lý quy trình và dữ liệu.","practice":"Vẽ sơ đồ tổ chức và bảng phân công phần hành cho phòng kế toán doanh nghiệp bạn, đánh dấu các điểm vi phạm bất kiêm nhiệm.","takeaway":"Bộ máy rõ người rõ việc là nền của số liệu đáng tin."}},{"id":"KH022","code":"kh022","f":"KT","fn":"Kế toán","t":"Kế toán trưởng: vai trò, trách nhiệm và kiểm soát","lv":5,"ln":"Chuyên gia","h":32,"p":499000,"d":"Khoá học giúp kế toán trưởng và người chuẩn bị lên vị trí này làm chủ vai trò pháp lý, xây dựng quy chế tài chính, hệ thống kiểm soát nội bộ, quản trị rủi ro thuế và dòng tiền. Học viên làm việc trên tình huống thật của doanh nghiệp Việt Nam, nhận bộ quy chế, ma trận kiểm soát và công cụ quản trị dùng ngay. Kết quả là bạn kiểm soát được bộ máy tài chính – kế toán, bảo vệ doanh nghiệp và chính mình trước rủi ro, đồng thời trở thành người tham mưu chiến lược cho ban giám đốc.","a":"Kế toán trưởng, phụ trách kế toán, kế toán tổng hợp lâu năm và giám đốc tài chính doanh nghiệp nhỏ và vừa.","o":["Xác định được đầy đủ quyền hạn, trách nhiệm pháp lý của kế toán trưởng và giới hạn chữ ký của mình.","Xây dựng được quy chế tài chính và bộ chính sách kế toán phù hợp doanh nghiệp.","Thiết kế được ma trận rủi ro – kiểm soát cho các chu trình doanh thu, chi phí, tài sản, tiền lương.","Lập được bản đồ rủi ro thuế và kế hoạch kiểm soát hằng quý.","Lập được dự báo dòng tiền 13 tuần và báo cáo tham mưu tài chính tháng cho ban giám đốc."],"k":"Chữ ký của kế toán trưởng gắn với trách nhiệm pháp lý thật. Năm 2026, người giữ vị trí này phải vừa vững luật vừa giỏi dữ liệu.","w":["Hàng loạt thay đổi có hiệu lực 2025–2026 như TT 99/2025, Luật TNDN 67/2025/QH15, Luật BHXH 2024, NĐ 310/2025 về xử phạt và Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 làm tăng trách nhiệm kiểm soát tuân thủ của kế toán trưởng.","Cơ quan thuế quản lý dựa trên dữ liệu số và phân tích rủi ro, sai sót hệ thống được phát hiện nhanh và trách nhiệm cá nhân rõ hơn.","Doanh nghiệp cần kế toán trưởng đóng vai trò đối tác chiến lược: dự báo dòng tiền, dẫn dắt chuyển đổi số và ứng dụng AI trong tài chính."],"dl":["Mẫu quy chế tài chính nội bộ và bộ chính sách kế toán có thể chỉnh sửa ngay.","Ma trận rủi ro – kiểm soát (RCM) cho 5 chu trình chính bằng Excel.","Bản đồ rủi ro thuế và checklist kiểm soát thuế hằng quý.","Bộ câu lệnh AI (prompt) cho kế toán trưởng: rà soát quy chế, phân tích biến động, soạn giải trình và báo cáo tham mưu."],"ls":["Kế toán trưởng: quyền hạn, trách nhiệm và ranh giới pháp lý","Quy chế tài chính và chính sách kế toán: luật chơi của doanh nghiệp","Hệ thống kiểm soát nội bộ tài chính – kế toán","Kiểm soát chu trình doanh thu, chi phí, tài sản và tiền lương","Quản trị rủi ro thuế trong kỷ nguyên quản lý thuế số","Quản trị dòng tiền và tham mưu tài chính cho ban giám đốc","Làm việc với kiểm toán, thanh tra và kiểm tra thuế","Lãnh đạo đội ngũ kế toán và dẫn dắt chuyển đổi số"],"l1":{"t":"Kế toán trưởng: quyền hạn, trách nhiệm và ranh giới pháp lý","sum":"Bài làm rõ vị trí pháp lý của kế toán trưởng theo pháp luật kế toán và các luật liên quan. Học viên biết bảo vệ mình khi bất đồng với lãnh đạo.","points":["Kế toán trưởng giúp người đại diện theo pháp luật tổ chức công tác kế toán, chịu trách nhiệm về số liệu kế toán theo Luật Kế toán 2015 và văn bản hướng dẫn.","Tiêu chuẩn, điều kiện bổ nhiệm kế toán trưởng (trình độ, kinh nghiệm, chứng chỉ bồi dưỡng) thực hiện theo quy định hiện hành.","Kế toán trưởng có quyền độc lập về chuyên môn và có quyền từ chối, bằng văn bản, các nghiệp vụ trái pháp luật.","Trách nhiệm có thể là hành chính, dân sự hoặc hình sự tùy mức độ sai phạm; ký chứng từ, báo cáo là xác nhận trách nhiệm.","Luật Doanh nghiệp sửa đổi 2025 bổ sung yêu cầu thông tin chủ sở hữu hưởng lợi (hiệu lực 01/07/2025), kế toán trưởng cần phối hợp lưu giữ thông tin này."],"case":"Giám đốc Công ty TNHH Thương mại Đại Phát yêu cầu kế toán trưởng hạch toán khoản chi 300 triệu đồng không có hóa đơn vào chi phí hợp lệ. Kế toán trưởng gửi văn bản nêu rõ rủi ro pháp lý và đề xuất xử lý vào chi phí không được trừ, được giám đốc chấp thuận.","trend":"Trách nhiệm giải trình cá nhân trong quản trị doanh nghiệp đang tăng, cùng yêu cầu minh bạch dữ liệu. Kế toán trưởng nên lưu vết các quyết định chuyên môn bằng văn bản.","practice":"Lập bảng phân định thẩm quyền ký của doanh nghiệp bạn: loại chứng từ, người lập, người kiểm tra, người duyệt, hạn mức.","takeaway":"Chữ ký là trách nhiệm, đừng ký điều bạn không bảo vệ được."}},{"id":"KH023","code":"kh023","f":"KT","fn":"Kế toán","t":"Rà soát sổ sách trước kiểm toán và quyết toán thuế","lv":5,"ln":"Chuyên gia","h":32,"p":499000,"d":"Khoá học trang bị phương pháp rà soát sổ sách theo tư duy kiểm toán viên trước khi kiểm toán độc lập vào cuộc và trước khi nộp quyết toán thuế, bao trùm số dư, doanh thu, chi phí, nghĩa vụ thuế và hồ sơ chứng minh. Học viên làm việc trên tình huống thật của doanh nghiệp Việt Nam, dùng ngay bộ chương trình rà soát, bảng đối chiếu và bộ câu lệnh AI để phân tích dữ liệu. Kết quả là một bộ hồ sơ cuối năm sạch, giải trình được, giảm tối đa bút toán điều chỉnh và rủi ro truy thu, xử phạt.","a":"Kế toán trưởng, kế toán tổng hợp, trưởng nhóm dịch vụ kế toán thuế và kiểm soát viên nội bộ chịu trách nhiệm chốt sổ, làm việc với kiểm toán và lập quyết toán thuế.","o":["Lập được kế hoạch rà soát cuối năm có mức trọng yếu, danh sách khoản mục rủi ro và lịch hoàn thành trong 10 ngày làm việc.","Tự đối chiếu được 100% số dư tiền, công nợ, hàng tồn kho, tài sản cố định với chứng cứ bên ngoài và lập biên bản giải trình chênh lệch.","Xác định và loại đúng các khoản chi phí không được trừ khi tính thuế TNDN, lập được bảng điều chỉnh lợi nhuận kế toán sang thu nhập tính thuế.","Đối chiếu được doanh thu, thuế GTGT đầu ra, đầu vào giữa sổ sách, tờ khai và dữ liệu hóa đơn điện tử, phát hiện chênh lệch trước khi cơ quan thuế phát hiện.","Hoàn thiện được bộ hồ sơ quyết toán và bộ hồ sơ làm việc với kiểm toán, giảm số bút toán điều chỉnh do kiểm toán đề xuất."],"k":"Một bút toán sai phát hiện khi kiểm toán đã vào cuộc có thể kéo theo truy thu, tiền chậm nộp và một mùa quyết toán mất ngủ.","w":["Từ 01/01/2026 doanh nghiệp áp dụng TT 99/2025 thay TT 200/2014, năm tài chính 2026 là năm đầu chốt số dư theo hệ thống mới nên rủi ro sai lệch chuyển đổi rất cao.","Luật TNDN 67/2025/QH15 áp dụng từ kỳ tính thuế 2025, điều kiện thanh toán không dùng tiền mặt từ 5 triệu đồng theo NĐ 181/2025 và chế tài xử phạt sửa đổi theo NĐ 310/2025 khiến sai sót cũ nay trả giá đắt hơn.","Cơ quan thuế đã quản lý bằng dữ liệu hóa đơn điện tử, kiểm toán viên dùng phần mềm phân tích toàn bộ sổ nhật ký, nên kế toán cũng phải rà soát bằng dữ liệu và AI thay vì soi chọn mẫu thủ công."],"dl":["Bộ chương trình rà soát Excel 12 khoản mục: mục tiêu, thủ tục, chứng từ cần có, cột kết luận và tham chiếu giấy làm việc.","Checklist 60 điểm rủi ro thuế cuối năm cho thuế GTGT, TNDN, TNCN và hóa đơn điện tử, có cột mức độ ưu tiên.","Quy trình SOP chốt sổ cuối năm và mẫu thư giải trình, biên bản đối chiếu công nợ, biên bản kiểm kê dùng ngay.","Bộ câu lệnh AI (prompt) phân tích sổ nhật ký chung: tìm bút toán bất thường, giao dịch cuối kỳ, chi tiền mặt lớn, nhà cung cấp rủi ro."],"ls":["Rà soát như kiểm toán viên: kế hoạch, trọng yếu và bản đồ rủi ro","Tiền, vay và chênh lệch tỷ giá: khoản mục nhỏ, lỗi lớn","Công nợ phải thu, phải trả: xác nhận, tuổi nợ và dự phòng","Hàng tồn kho và tài sản cố định: kiểm kê, giá trị và khấu hao","Doanh thu và thuế GTGT đầu ra: khớp ba chiều sổ, tờ khai, hóa đơn","Chi phí được trừ và không được trừ theo Luật TNDN mới","Dùng AI và phân tích dữ liệu để soi toàn bộ sổ nhật ký","Bút toán điều chỉnh, thư giải trình và bộ hồ sơ quyết toán hoàn chỉnh"],"l1":{"t":"Rà soát như kiểm toán viên: kế hoạch, trọng yếu và bản đồ rủi ro","sum":"Bài nền tảng giúp chuyển từ tư duy kiểm tra từng chứng từ sang tư duy rủi ro của kiểm toán viên. Học viên lập được kế hoạch rà soát có trọng tâm, biết chỗ nào phải soi kỹ, chỗ nào chỉ cần phân tích.","points":["Bắt đầu bằng phân tích sơ bộ: so sánh báo cáo năm nay với năm trước và kế hoạch, đánh dấu khoản mục biến động lớn hoặc ngược chiều với hoạt động kinh doanh.","Mức trọng yếu tổng thể thường được kiểm toán viên ước tính theo thông lệ dựa trên lợi nhuận trước thuế, doanh thu hoặc tổng tài sản; kế toán nên dùng mức thấp hơn để chủ động phát hiện trước.","Lập bản đồ rủi ro theo từng khoản mục: rủi ro hiện hữu, đầy đủ, đúng kỳ, đánh giá; doanh thu thường rủi ro ghi nhận sớm, chi phí thường rủi ro ghi thiếu hoặc không đủ chứng từ.","Năm 2026 thêm một rủi ro đặc thù: số dư đầu kỳ chuyển từ hệ thống tài khoản TT 200/2014 sang TT 99/2025, cần đối chiếu bảng chuyển đổi từng tài khoản.","Phân công và chốt lịch: rà soát xong trước khi kiểm toán vào cuộc ít nhất 1–2 tuần để còn thời gian thu thập chứng từ bổ sung."],"case":"Công ty TNHH Minh An doanh thu 120 tỷ, lợi nhuận trước thuế 6 tỷ, chi phí bán hàng tăng 45% trong khi doanh thu chỉ tăng 8%. Kế toán trưởng đưa chi phí bán hàng vào nhóm rủi ro cao, rà soát và phát hiện 1,2 tỷ hoa hồng thiếu hợp đồng, kịp bổ sung hồ sơ trước khi kiểm toán đến.","trend":"Kiểm toán đang chuyển sang phân tích toàn bộ dữ liệu thay vì chọn mẫu, kết hợp AI để chấm điểm rủi ro bút toán. Kế toán nên chuẩn hóa dữ liệu xuất từ phần mềm để tự chạy phân tích trước kiểm toán.","practice":"Từ báo cáo tài chính 2 năm của doanh nghiệp mình, lập bảng phân tích biến động, đánh dấu 5 khoản mục rủi ro cao nhất và ghi lý do cho từng khoản.","takeaway":"Rà soát hiệu quả không phải soi hết mà là soi đúng chỗ rủi ro nhất."}},{"id":"KH024","code":"kh024","f":"KT","fn":"Kế toán","t":"Lộ trình áp dụng IFRS tại Việt Nam 2025–2030","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học giúp kế toán và chuyên viên tài chính nắm các chuẩn mực IFRS trọng yếu, khác biệt then chốt với chuẩn mực và chế độ kế toán Việt Nam, và lộ trình áp dụng IFRS tại Việt Nam theo QĐ 345/QĐ-BTC năm 2020. Mỗi bài đi kèm tình huống chuyển đổi số liệu thật, bảng điều chỉnh VAS sang IFRS và mẫu Excel dùng ngay. Kết quả là học viên tự lập được bảng chuyển đổi báo cáo cơ bản và tự tin tham gia dự án áp dụng IFRS của doanh nghiệp.","a":"Kế toán tổng hợp, kế toán trưởng, kiểm toán viên và chuyên viên tài chính làm việc với công ty mẹ nước ngoài, nhà đầu tư quốc tế, hoặc đang chuẩn bị học ACCA, CPA.","o":["Giải thích được cấu trúc hệ thống IFRS, khung khái niệm và lộ trình áp dụng tại Việt Nam cho ban giám đốc trong 10 phút.","Lập được bảng so sánh khác biệt VAS và IFRS cho 8 khoản mục trọng yếu của chính doanh nghiệp mình.","Áp dụng được mô hình 5 bước IFRS 15 để xác định thời điểm và giá trị doanh thu của một hợp đồng thực tế.","Tính được tài sản quyền sử dụng và nợ thuê theo IFRS 16, dự phòng tổn thất tín dụng dự kiến đơn giản theo IFRS 9.","Lập được bảng chuyển đổi báo cáo tình hình tài chính và kết quả kinh doanh từ VAS sang IFRS có bút toán điều chỉnh kèm giải thích."],"k":"Nhà đầu tư ngoại, công ty mẹ và ngân hàng quốc tế đọc báo cáo bằng IFRS; kế toán chỉ biết VAS đang tự thu hẹp cơ hội của mình.","w":["QĐ 345/QĐ-BTC năm 2020 đặt lộ trình áp dụng IFRS tự nguyện trước, bắt buộc sau cho một số nhóm đối tượng; giai đoạn sau 2025 đang tới gần nên doanh nghiệp lớn cần nhân sự sẵn sàng.","Hệ thống IFRS tiếp tục thay đổi: IFRS 18 thay thế IAS 1 về trình bày báo cáo tài chính, chuẩn mực công bố bền vững IFRS S1, S2 của ISSB được nhiều thị trường tiếp nhận.","Dòng vốn FDI, M&A và vay quốc tế đòi hỏi báo cáo theo IFRS; kế toán biết IFRS có lợi thế rõ rệt về vị trí và thu nhập trong giai đoạn 2026–2030."],"dl":["Bộ mẫu Excel chuyển đổi VAS sang IFRS: bảng mapping tài khoản, bảng bút toán điều chỉnh, báo cáo sau chuyển đổi tự động.","Bảng tra nhanh khác biệt VAS và IFRS cho các chuẩn mực trọng yếu, kèm câu hỏi kiểm tra cho từng khoản mục.","Mô hình tính IFRS 16 (lịch nợ thuê, khấu hao tài sản quyền sử dụng) và ma trận tổn thất tín dụng dự kiến theo IFRS 9.","Bộ câu lệnh AI (prompt) đọc hợp đồng để nhận diện nghĩa vụ thực hiện, điều khoản thuê, và soạn thuyết minh IFRS song ngữ."],"ls":["Bản đồ IFRS và lộ trình áp dụng tại Việt Nam đến 2030","Khung khái niệm, trình bày báo cáo và bước chuyển sang IFRS 18","Doanh thu theo IFRS 15: mô hình 5 bước cho hợp đồng thực tế","Hàng tồn kho, tài sản và suy giảm giá trị theo IAS 2, IAS 16, IAS 36","Thuê tài sản theo IFRS 16: đưa hợp đồng thuê lên bảng cân đối","Công cụ tài chính theo IFRS 9 và giá trị hợp lý theo IFRS 13","Thuế thu nhập hoãn lại, thuế tối thiểu toàn cầu và công bố bền vững","Dự án chuyển đổi VAS sang IFRS: IFRS 1, bảng mapping và tự động hóa"],"l1":{"t":"Bản đồ IFRS và lộ trình áp dụng tại Việt Nam đến 2030","sum":"Bài mở đầu giới thiệu IFRS là gì, ai ban hành, cấu trúc hệ thống và vì sao Việt Nam theo lộ trình riêng. Học viên định vị được doanh nghiệp mình đang ở đâu trên lộ trình.","points":["IFRS do Hội đồng Chuẩn mực Kế toán Quốc tế (IASB) ban hành, gồm các chuẩn mực IFRS và các chuẩn mực IAS cũ còn hiệu lực cùng các hướng dẫn giải thích IFRIC.","QĐ 345/QĐ-BTC năm 2020 phê duyệt đề án áp dụng chuẩn mực báo cáo tài chính tại Việt Nam: giai đoạn chuẩn bị, giai đoạn áp dụng tự nguyện, sau đó là giai đoạn bắt buộc cho một số đối tượng theo hướng dẫn của Bộ Tài chính.","Doanh nghiệp có thể áp dụng tự nguyện nếu có nhu cầu và đủ nguồn lực, thường là công ty niêm yết lớn, ngân hàng, công ty con của tập đoàn nước ngoài.","Song song, từ 01/01/2026 TT 99/2025 thay TT 200/2014 làm chế độ kế toán doanh nghiệp; sổ sách vẫn ghi theo chế độ Việt Nam, IFRS thường lập bằng chuyển đổi hoặc song song.","Phạm vi và thời điểm bắt buộc cụ thể cho từng nhóm đối tượng cần theo dõi văn bản hướng dẫn hiện hành, không nên tự suy đoán."],"case":"Công ty Cổ phần Thực phẩm Hoàng Long là công ty con của một tập đoàn Nhật, hằng quý phải gửi báo cáo IFRS cho công ty mẹ. Trước đây kế toán thuê ngoài chuyển đổi mất 3 tuần mỗi quý; sau khi xây dựng bảng mapping và bút toán điều chỉnh chuẩn, đội nội bộ tự làm trong 5 ngày.","trend":"Giai đoạn 2026–2030 dự kiến số doanh nghiệp lập báo cáo IFRS tại Việt Nam tăng theo lộ trình và nhu cầu vốn quốc tế. Học viên nên bắt đầu bằng việc lập báo cáo song song cho đơn vị mình.","practice":"Xác định doanh nghiệp mình thuộc nhóm nào trên lộ trình áp dụng IFRS, liệt kê 3 bên liên quan cần báo cáo IFRS và ước tính các khoản mục bị ảnh hưởng nhiều nhất.","takeaway":"IFRS không thay sổ sách Việt Nam ngay, nhưng sẽ thay cách thế giới đọc số liệu của bạn."}},{"id":"KH025","code":"kh025","f":"KT","fn":"Kế toán","t":"Kế toán quản trị và dự báo ngân sách bằng dữ liệu","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học giúp kế toán chuyển từ ghi chép quá khứ sang dự báo tương lai: phân tích chi phí, giá thành, điểm hòa vốn, lập ngân sách theo động lực kinh doanh và dự báo dòng tiền bằng dữ liệu. Học viên thực hành trên mô hình Excel và Power BI dùng ngay, kết hợp AI để phân tích chênh lệch và viết nhận định quản trị. Kết quả là một hệ thống ngân sách, dự báo cuốn chiếu và báo cáo quản trị mà ban giám đốc thực sự dùng để ra quyết định.","a":"Kế toán tổng hợp, kế toán quản trị, chuyên viên FP&A, quản lý tài chính và chủ doanh nghiệp vừa và nhỏ muốn kiểm soát chi phí và chủ động dòng tiền.","o":["Phân loại được toàn bộ chi phí của doanh nghiệp thành biến đổi, cố định, hỗn hợp và tính được biên đóng góp theo sản phẩm, kênh, khách hàng.","Tính được điểm hòa vốn, doanh thu mục tiêu và đánh giá được tác động của thay đổi giá bán, chi phí lên lợi nhuận.","Lập được ngân sách tổng thể 12 tháng theo động lực kinh doanh, gồm doanh thu, chi phí, lợi nhuận và dòng tiền.","Xây dựng được mô hình dự báo dòng tiền 13 tuần và dự báo cuốn chiếu cập nhật hằng tháng.","Lập được dashboard quản trị và báo cáo phân tích chênh lệch kèm đề xuất hành động trong vòng 3 ngày làm việc sau khóa sổ."],"k":"Giám đốc không cần thêm một báo cáo cuối tháng; họ cần biết tháng sau tiền còn bao nhiêu và nên cắt chi phí nào.","w":["Môi trường kinh doanh 2026 biến động nhanh về chi phí đầu vào, lãi suất và thuế (Luật TNDN 67/2025/QH15, VAT 8% chỉ áp dụng đến hết 31/12/2026), ngân sách tĩnh lập một lần mỗi năm không còn theo kịp.","Dữ liệu hóa đơn điện tử, ngân hàng số và phần mềm kế toán online giúp có số liệu gần thời gian thực, mở ra khả năng dự báo hằng tuần thay vì hằng năm.","AI và công cụ BI đang tự động hóa phần nhập liệu và báo cáo, giá trị của kế toán dịch chuyển sang phân tích, dự báo và tư vấn quyết định."],"dl":["Bộ mô hình Excel ngân sách tổng thể 12 tháng có liên kết doanh thu, sản xuất, chi phí, lợi nhuận, dòng tiền và kịch bản tốt, cơ sở, xấu.","Mẫu dự báo dòng tiền 13 tuần và mẫu dự báo cuốn chiếu theo động lực kinh doanh.","Mẫu dashboard quản trị Power BI hoặc Excel với KPI biên lợi nhuận, điểm hòa vốn, vòng quay vốn lưu động, chênh lệch ngân sách.","Bộ câu lệnh AI (prompt) phân tích chênh lệch, viết nhận định quản trị cho giám đốc và rà soát giả định ngân sách."],"ls":["Từ kế toán ghi sổ đến đối tác kinh doanh: vai trò mới của kế toán quản trị","Hiểu hành vi chi phí: biến đổi, cố định và biên đóng góp","Giá thành sản phẩm, dịch vụ và chi phí theo hoạt động (ABC)","Phân tích CVP và điểm hòa vốn cho quyết định giá, khuyến mại, mở rộng","Thông tin thích hợp cho quyết định ngắn hạn: nhận đơn, tự làm hay thuê ngoài","Lập ngân sách theo động lực kinh doanh và kịch bản","Dự báo dòng tiền 13 tuần và dự báo cuốn chiếu bằng dữ liệu","Dashboard quản trị, phân tích chênh lệch và AI viết nhận định cho ban giám đốc"],"l1":{"t":"Từ kế toán ghi sổ đến đối tác kinh doanh: vai trò mới của kế toán quản trị","sum":"Bài mở đầu phân biệt kế toán quản trị với kế toán tài chính và xác định những câu hỏi ban giám đốc thực sự cần trả lời. Học viên định hình vai trò của mình trong chu trình hoạch định, kiểm soát và ra quyết định.","points":["Kế toán tài chính phục vụ bên ngoài, tuân thủ chế độ kế toán (TT 133/2016 hoặc TT 99/2025); kế toán quản trị phục vụ nội bộ, linh hoạt về hình thức và hướng tới tương lai.","Ba câu hỏi cốt lõi của giám đốc: đang lãi ở đâu và lỗ ở đâu, tiền sẽ đủ hay thiếu, nên làm gì tiếp theo; báo cáo quản trị phải trả lời được cả ba.","Thiết kế hệ thống mã quản trị ngay trong phần mềm kế toán: theo bộ phận, sản phẩm, kênh, dự án, để số liệu tự phân tích thay vì tách tay cuối tháng.","Nguyên tắc thông tin quản trị: kịp thời hơn hoàn hảo, đủ chính xác để quyết định, tập trung vào chỉ tiêu có thể hành động.","Chu trình quản trị hiện đại: kế hoạch năm, dự báo cuốn chiếu hằng tháng, đo lường KPI, phân tích chênh lệch, hành động điều chỉnh."],"case":"Công ty TNHH Nội thất Gia Bảo có 3 showroom và 1 kênh online, sổ sách chỉ cho biết tổng lãi 1,8 tỷ. Kế toán thêm mã bộ phận trên phần mềm, sau 1 quý phát hiện kênh online lỗ 400 triệu do chi phí quảng cáo và hoàn hàng, giúp giám đốc điều chỉnh ngân sách quảng cáo kịp thời.","trend":"Vai trò kế toán đang dịch chuyển sang phân tích và tư vấn khi AI xử lý phần ghi chép. Học viên nên rèn kỹ năng kể chuyện bằng số liệu và hiểu mô hình kinh doanh, không chỉ hiểu tài khoản.","practice":"Phỏng vấn giám đốc hoặc trưởng bộ phận để liệt kê 5 quyết định họ phải ra trong quý tới, xác định thông tin cần có và thiết kế mã quản trị tương ứng trên phần mềm.","takeaway":"Báo cáo quản trị có giá trị khi nó thay đổi được một quyết định."}},{"id":"KH026","code":"kh026","f":"THUE","fn":"Thuế","t":"Thuế cho chủ doanh nghiệp: hiểu đủ để không sợ","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp chủ doanh nghiệp không chuyên kế toán nắm bức tranh thuế tổng thể năm 2026: các loại thuế phải nộp, cách tính cơ bản, lịch nộp và những thay đổi mới nhất về thuế TNDN, GTGT, TNCN, hóa đơn điện tử. Mỗi bài dùng tình huống thật của doanh nghiệp nhỏ Việt Nam, ngôn ngữ đời thường, kèm checklist và câu hỏi để kiểm tra kế toán. Sau khoá, bạn tự đọc được tờ khai, chủ động lịch thuế, tránh các lỗi bị phạt phổ biến và làm việc với kế toán, dịch vụ thuê ngoài như một người quản lý hiểu chuyện.","a":"Chủ doanh nghiệp, giám đốc công ty TNHH, cổ phần nhỏ, chủ hộ kinh doanh đang lên công ty và người chuẩn bị khởi nghiệp chưa có nền tảng kế toán.","o":["Kể tên và giải thích được bằng lời của mình các loại thuế, bảo hiểm doanh nghiệp đang phải nộp và căn cứ tính của từng loại.","Lập được lịch thuế 12 tháng năm 2026 của doanh nghiệp mình với đủ hạn khai, hạn nộp và người phụ trách.","Tự kiểm tra được 7 lỗi thuế phổ biến trên sổ sách, hóa đơn và chi tiền mặt của doanh nghiệp mình trong 1 buổi.","Đọc được tờ khai thuế GTGT và tờ khai quyết toán TNDN ở mức hiểu các chỉ tiêu chính trước khi ký.","Đặt được 10 câu hỏi kiểm soát hằng tháng cho kế toán hoặc dịch vụ thuê ngoài và nhận báo cáo thuế 1 trang."],"k":"Bạn ký tờ khai thuế mỗi tháng nhưng không chắc mình đang ký gì; 8 giờ học này giúp bạn hiểu đủ để ngủ ngon.","w":["Từ kỳ tính thuế 2025, Luật TNDN 67/2025/QH15 áp dụng thuế suất 15% và 17% cho doanh nghiệp nhỏ, nhưng chỉ chủ doanh nghiệp hiểu điều kiện mới tận dụng đúng.","Từ 01/01/2026 bỏ lệ phí môn bài và bỏ thuế khoán hộ kinh doanh theo NQ 198/2025/QH15, đồng thời xử phạt sửa đổi theo NĐ 310/2025 hiệu lực 16/01/2026: luật chơi đã khác.","Cơ quan thuế quản lý bằng dữ liệu hóa đơn điện tử và giao dịch ngân hàng, sai sót bị phát hiện tự động và nhanh hơn, chủ doanh nghiệp không thể giao phó hoàn toàn cho kế toán."],"dl":["Lịch thuế 2026 dạng Excel tự nhắc hạn, chọn kỳ khai tháng hoặc quý.","Checklist 7 lỗi thuế phổ biến và cách tự kiểm tra, có cột người phụ trách và ngày hoàn thành.","Mẫu báo cáo thuế 1 trang hằng tháng kế toán gửi chủ doanh nghiệp và bộ 10 câu hỏi kiểm soát.","Bộ câu lệnh AI (prompt) giúp chủ doanh nghiệp đọc hiểu thông báo của cơ quan thuế và soạn câu hỏi cho kế toán."],"ls":["Bức tranh thuế của doanh nghiệp năm 2026 trong 30 phút","Thuế GTGT: tiền của khách, bạn chỉ giữ hộ","Thuế TNDN: lợi nhuận nào bị tính thuế và chi phí nào được trừ","Lương, thuế TNCN và bảo hiểm: chi phí con người cần làm đúng","Hóa đơn điện tử: chủ doanh nghiệp cần nắm những gì","Lịch thuế 2026 và cách không bao giờ trễ hạn","7 lỗi thuế phổ biến khiến doanh nghiệp nhỏ bị phạt và truy thu","Làm sếp hiểu chuyện: quản lý kế toán, dịch vụ thuê ngoài và dùng AI"],"l1":{"t":"Bức tranh thuế của doanh nghiệp năm 2026 trong 30 phút","sum":"Bài mở đầu vẽ bản đồ các loại thuế, phí, bảo hiểm mà một công ty nhỏ thường phải nộp và những thay đổi lớn từ 2026. Chủ doanh nghiệp nhìn thuế như một chi phí có thể hoạch định, không phải nỗi sợ.","points":["Ba loại thuế chính: thuế giá trị gia tăng (GTGT) thu trên giá bán, thuế thu nhập doanh nghiệp (TNDN) tính trên lợi nhuận, thuế thu nhập cá nhân (TNCN) doanh nghiệp khấu trừ thay người lao động.","Tùy ngành có thể phát sinh thêm thuế nhập khẩu, xuất khẩu, tiêu thụ đặc biệt, tài nguyên, bảo vệ môi trường hoặc thuế nhà thầu khi trả tiền cho tổ chức, cá nhân nước ngoài.","Từ 01/01/2026 bỏ lệ phí môn bài theo NQ 198/2025/QH15, doanh nghiệp không còn khai nộp khoản này từ năm 2026.","Bảo hiểm bắt buộc không phải thuế nhưng là nghĩa vụ lớn: doanh nghiệp đóng 21,5%, người lao động đóng 10,5% trên tiền lương đóng bảo hiểm, cộng kinh phí công đoàn 2%.","Người chịu trách nhiệm pháp lý cuối cùng về thuế là người đại diện theo pháp luật, kể cả khi thuê dịch vụ kế toán."],"case":"Anh Tuấn, giám đốc Công ty TNHH Minh An kinh doanh thiết bị văn phòng, nghĩ chỉ cần nộp thuế GTGT là đủ. Khi rà soát, công ty phát hiện chưa khấu trừ thuế TNCN cho 2 nhân viên lương cao và chưa đóng bảo hiểm cho 1 người đã ký hợp đồng chính thức, kịp khắc phục trước khi bị kiểm tra.","trend":"Cơ quan thuế đang tiến tới hồ sơ thuế số của mỗi doanh nghiệp, tổng hợp từ hóa đơn, ngân hàng, bảo hiểm. Chủ doanh nghiệp nên chủ động tra cứu tài khoản thuế điện tử của mình mỗi tháng.","practice":"Liệt kê tất cả các khoản thuế, phí, bảo hiểm doanh nghiệp đã nộp trong 12 tháng gần nhất từ sao kê ngân hàng, đánh dấu khoản nào mình chưa hiểu để hỏi kế toán.","takeaway":"Bạn không cần làm kế toán, nhưng phải biết mình đang nộp những gì và vì sao."}},{"id":"KH027","code":"kh027","f":"THUE","fn":"Thuế","t":"Đăng ký thuế và thủ tục thuế ban đầu cho công ty mới","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp công ty mới thành lập hoàn tất toàn bộ thủ tục thuế ban đầu theo đúng thứ tự: tài khoản ngân hàng, chữ ký số, thuế điện tử, phương pháp tính thuế, hóa đơn điện tử, lao động và kỳ khai đầu tiên. Mỗi bài đi kèm tình huống thật của doanh nghiệp vừa thành lập và mẫu biểu dùng ngay. Học xong, học viên tự tin đưa công ty vào vận hành hợp pháp từ tháng đầu tiên, không bỏ sót nghĩa vụ và không mất tiền phạt vô lý.","a":"Chủ doanh nghiệp mới thành lập, kế toán mới vào nghề, nhân viên dịch vụ thành lập doanh nghiệp và người chuẩn bị khởi nghiệp.","o":["Lập được checklist 30 ngày đầu với hơn 20 đầu việc thuế – kế toán – lao động, xếp đúng thứ tự ưu tiên và người phụ trách.","Tự đăng ký được tài khoản thuế điện tử, nộp thuế điện tử và kiểm tra thông báo của cơ quan thuế mà không cần thuê ngoài.","Lựa chọn và lập được hồ sơ đăng ký sử dụng hóa đơn điện tử đúng loại, đúng thông tin pháp lý trong 1 buổi làm việc.","Xác định đúng phương pháp tính thuế GTGT, kỳ khai quý và các nghĩa vụ TNDN, TNCN, bảo hiểm của năm đầu.","Nộp đúng hạn tờ khai kỳ đầu tiên, kể cả khi chưa có doanh thu, tránh 100% các lỗi phạt phổ biến của công ty mới."],"k":"Vừa nhận giấy phép kinh doanh mà chưa biết bắt đầu từ đâu về thuế? Một bước sai trong 30 ngày đầu có thể kéo theo tiền phạt cả năm.","w":["Từ 01/01/2026 bỏ lệ phí môn bài, bỏ thuế khoán hộ kinh doanh và áp dụng TT 99/2025 thay TT 200/2014: nhiều hướng dẫn cũ trên mạng đã lỗi thời, công ty mới cần làm đúng ngay theo quy định mới.","Quản lý thuế ngày càng số hóa: khai, nộp, nhận thông báo đều qua tài khoản điện tử, dữ liệu hóa đơn và ngân hàng được đối chiếu tự động nên sai sót ban đầu bị phát hiện rất sớm.","Luật Doanh nghiệp sửa đổi 2025 bổ sung nghĩa vụ thông tin chủ sở hữu hưởng lợi và Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 có hiệu lực từ 01/01/2026: công ty mới phải tuân thủ ngay từ hồ sơ đầu tiên."],"dl":["Checklist Excel 30 ngày đầu cho công ty mới: đầu việc, hạn chót, hồ sơ cần chuẩn bị, trạng thái hoàn thành.","Lịch thuế năm đầu tự động: nhập ngày thành lập, tự sinh hạn nộp tờ khai GTGT, TNCN, TNDN tạm nộp và quyết toán.","Quy trình SOP mở sổ kế toán ban đầu: chọn chế độ kế toán, danh mục tài khoản, lưu chứng từ góp vốn và chi phí thành lập.","Bộ câu lệnh AI (prompt) soạn quy chế lương thưởng, hợp đồng lao động mẫu và rà soát hồ sơ thuế ban đầu."],"ls":["30 ngày vàng sau khi có giấy phép: lộ trình không bỏ sót","Tài khoản ngân hàng và chữ ký số: hai chìa khóa vận hành","Thuế điện tử từ A đến Z: đăng ký, khai, nộp và tra cứu","Chọn phương pháp tính thuế và kỳ khai: quyết định đầu tiên định hình cả năm","Đăng ký hóa đơn điện tử đúng ngay lần đầu","Dựng bộ máy kế toán từ ngày đầu: chế độ, phần mềm và lưu trữ","Nhân sự đầu tiên: hợp đồng, bảo hiểm, thuế TNCN và dữ liệu cá nhân","Kỳ khai đầu tiên và lá chắn rủi ro với AI"],"l1":{"t":"30 ngày vàng sau khi có giấy phép: lộ trình không bỏ sót","sum":"Bài mở đầu vẽ bức tranh toàn cảnh các việc cần làm sau khi nhận Giấy chứng nhận đăng ký doanh nghiệp. Học viên có lộ trình theo thứ tự ưu tiên và hiểu vì sao làm sai thứ tự sẽ tốn thời gian gấp đôi.","points":["Mã số doanh nghiệp đồng thời là mã số thuế; thông tin đăng ký thuế được chuyển từ hệ thống đăng ký kinh doanh sang cơ quan thuế quản lý.","Thứ tự gợi ý: khắc dấu (nếu dùng) → mở tài khoản ngân hàng → mua chữ ký số → đăng ký thuế điện tử → đăng ký hóa đơn điện tử → treo biển tại trụ sở.","Từ 01/01/2026 doanh nghiệp không còn phải khai và nộp lệ phí môn bài theo NQ 198/2025/QH15, nên bỏ hẳn bước này khỏi checklist cũ.","Góp đủ vốn điều lệ trong thời hạn 90 ngày kể từ ngày được cấp giấy chứng nhận theo Luật Doanh nghiệp; nên góp qua tài khoản ngân hàng để có chứng từ rõ ràng.","Rà soát và lưu hồ sơ thông tin chủ sở hữu hưởng lợi theo Luật Doanh nghiệp sửa đổi 2025 (hiệu lực 01/07/2025) ngay từ đầu để sẵn sàng cung cấp khi được yêu cầu."],"case":"Công ty TNHH Minh An nhận giấy phép ngày 05/03 nhưng 2 tháng sau mới mua chữ ký số, dẫn đến trễ đăng ký hóa đơn và phải hoãn ký hợp đồng 400 triệu đồng với khách đầu tiên. Sau khi lập checklist theo thứ tự chuẩn, các công ty cùng hệ thống của chủ sở hữu hoàn tất thủ tục trong 10 ngày làm việc.","trend":"Xu hướng 2026–2030 là liên thông dữ liệu giữa đăng ký kinh doanh, thuế, ngân hàng và bảo hiểm, nhiều bước sẽ tự động hơn. Học viên nên làm quen với định danh điện tử tổ chức và các cổng dịch vụ công trực tuyến.","practice":"Dùng checklist mẫu của khoá, điền ngày thành lập của một công ty giả định và lập lịch hoàn thành 30 ngày đầu, ghi rõ người phụ trách từng việc.","takeaway":"Làm đúng thứ tự trong 30 ngày đầu tiết kiệm cho bạn 3 tháng sửa sai về sau."}},{"id":"KH028","code":"kh028","f":"THUE","fn":"Thuế","t":"Hóa đơn điện tử 2026: lập, điều chỉnh, thay thế và rủi ro","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp kế toán làm chủ hóa đơn điện tử theo NĐ 123/2020 sửa bởi NĐ 70/2025: từ nội dung bắt buộc, thời điểm lập đến điều chỉnh, thay thế, thông báo sai sót và kiểm soát hóa đơn đầu vào. Phương pháp học dựa trên tình huống thật, bảng quyết định xử lý sai sót và mẫu văn bản dùng ngay. Học xong, học viên xử lý tự tin mọi tình huống hóa đơn, giảm rủi ro bị phạt và bị loại khấu trừ.","a":"Kế toán bán hàng, kế toán thuế, nhân viên lập hóa đơn, kế toán dịch vụ và chủ doanh nghiệp nhỏ.","o":["Lập được hóa đơn điện tử đầy đủ nội dung bắt buộc, đúng thuế suất và đúng thời điểm cho 6 loại giao dịch phổ biến.","Tự xác định được trong vài phút cách xử lý đúng cho từng loại sai sót: thông báo, điều chỉnh hay thay thế.","Soạn được văn bản thỏa thuận sai sót, biên bản trả hàng, hủy giao dịch theo mẫu chuẩn của khoá.","Kiểm tra được tính hợp pháp của 100% hóa đơn đầu vào trước khi kê khai khấu trừ.","Thiết lập được quy trình kiểm soát, lưu trữ hóa đơn nội bộ giúp giảm số hóa đơn sai sót mỗi tháng."],"k":"Một hóa đơn lập sai thời điểm hay xử lý sai cách có thể khiến cả bạn và khách hàng mất quyền khấu trừ thuế năm 2026.","w":["NĐ 70/2025 sửa đổi NĐ 123/2020 có hiệu lực từ 01/06/2025 đã thay đổi nhiều quy định về thời điểm lập, xử lý sai sót và hóa đơn máy tính tiền; quy trình cũ không còn phù hợp.","Chế tài vi phạm hóa đơn được cập nhật tại NĐ 125/2020 sửa bởi NĐ 310/2025 hiệu lực 16/01/2026, đồng thời cơ quan thuế dùng dữ liệu hóa đơn và phân tích tự động để phát hiện bất thường.","Thuế suất GTGT 8% kéo dài đến hết 31/12/2026 theo NQ 204/2025/QH15 và điều kiện thanh toán không dùng tiền mặt từ 5 triệu đồng theo NĐ 181/2025 khiến sai sót thuế suất và chứng từ thanh toán dễ xảy ra hơn."],"dl":["Bảng quyết định xử lý hóa đơn sai sót (dạng cây quyết định Excel): loại sai sót → cách xử lý → mẫu cần dùng → kỳ kê khai.","Bộ mẫu văn bản: thỏa thuận điều chỉnh, biên bản trả hàng, biên bản hủy giao dịch, nhật ký xử lý hóa đơn sai sót.","Checklist kiểm tra hóa đơn đầu vào 10 bước và mẫu Excel đối chiếu hóa đơn với hợp đồng, chứng từ thanh toán.","Bộ câu lệnh AI (prompt) rà soát dữ liệu hóa đơn xuất từ hệ thống, phát hiện thuế suất sai, trùng lặp và nhà cung cấp rủi ro."],"ls":["Bản đồ hóa đơn điện tử 2026: khung pháp lý và các loại hóa đơn","Nội dung bắt buộc: lập một hóa đơn không thể bắt lỗi","Thời điểm lập hóa đơn: quy tắc vàng theo từng giao dịch","Hóa đơn sai sót phần 1: điều chỉnh tăng, giảm đúng chuẩn","Hóa đơn sai sót phần 2: thay thế, thông báo và cây quyết định","Tình huống đặc thù: trả hàng, chiết khấu, khuyến mại, hủy giao dịch","Kiểm soát hóa đơn đầu vào bằng dữ liệu và AI","Lưu trữ, quy trình nội bộ và phòng tránh xử phạt"],"l1":{"t":"Bản đồ hóa đơn điện tử 2026: khung pháp lý và các loại hóa đơn","sum":"Bài mở đầu hệ thống hóa quy định hóa đơn điện tử hiện hành và các loại hóa đơn. Học viên phân biệt rõ hóa đơn có mã, không mã và khởi tạo từ máy tính tiền để chọn đúng cho doanh nghiệp.","points":["Văn bản chính là NĐ 123/2020 được sửa đổi, bổ sung bởi NĐ 70/2025 có hiệu lực từ 01/06/2025; xử phạt theo NĐ 125/2020 sửa bởi NĐ 310/2025.","Hóa đơn GTGT dùng cho người khai thuế theo phương pháp khấu trừ; hóa đơn bán hàng dùng cho phương pháp trực tiếp; ngoài ra có các loại khác như tem, vé, thẻ.","Hóa đơn có mã được cơ quan thuế cấp mã trước khi gửi người mua; hóa đơn không mã do doanh nghiệp đủ điều kiện tự gửi và chuyển dữ liệu cho cơ quan thuế.","Hóa đơn khởi tạo từ máy tính tiền có mã của cơ quan thuế, kết nối chuyển dữ liệu, dành cho hoạt động bán trực tiếp đến người tiêu dùng.","Mỗi lần thay đổi thông tin như loại hóa đơn, nhà cung cấp, chữ ký số đều phải đăng ký thay đổi thông tin sử dụng hóa đơn theo quy định."],"case":"Công ty TNHH Minh An vừa bán buôn cho đại lý vừa bán lẻ tại 2 cửa hàng. Kế toán chọn hóa đơn GTGT có mã cho bán buôn và hóa đơn khởi tạo từ máy tính tiền cho cửa hàng, khai báo ký hiệu riêng để theo dõi doanh thu từng kênh.","trend":"Giai đoạn 2026–2030 dự kiến dữ liệu hóa đơn được dùng làm nền cho tờ khai gợi ý sẵn và phân tích rủi ro tự động. Học viên nên quản trị hóa đơn như quản trị dữ liệu, không chỉ là chứng từ.","practice":"Vẽ sơ đồ các loại hóa đơn doanh nghiệp đang hoặc sẽ sử dụng, gắn với từng kênh bán hàng và ký hiệu hóa đơn tương ứng.","takeaway":"Chọn đúng loại hóa đơn cho từng kênh là bước đầu tiên của quản trị thuế."}},{"id":"KH029","code":"kh029","f":"THUE","fn":"Thuế","t":"Hóa đơn điện tử khởi tạo từ máy tính tiền","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học hướng dẫn triển khai hóa đơn điện tử khởi tạo từ máy tính tiền theo NĐ 123/2020 sửa bởi NĐ 70/2025: xác định đối tượng, chọn giải pháp, đăng ký, vận hành tại quầy, xử lý sai sót, đối chiếu doanh thu và kê khai. Phương pháp học bám sát tình huống cửa hàng, nhà hàng, nhà thuốc thật cùng bộ SOP và biểu mẫu dùng ngay. Kết quả là điểm bán chuyển đổi suôn sẻ, doanh thu minh bạch, kế toán khớp số và giảm rủi ro bị truy thu.","a":"Chủ cửa hàng bán lẻ, nhà hàng, quán ăn, siêu thị mini, nhà thuốc, hộ kinh doanh chuyển sang tự kê khai, kế toán và quản lý vận hành chuỗi bán lẻ.","o":["Xác định được trong 15 phút doanh nghiệp, hộ kinh doanh có thuộc diện và có nên dùng hóa đơn từ máy tính tiền hay không.","Lựa chọn được giải pháp máy tính tiền theo bảng 10 tiêu chí và lập kế hoạch triển khai cho từng điểm bán.","Hoàn tất được hồ sơ đăng ký sử dụng, khai báo điểm bán, ký hiệu hóa đơn và chạy thử trước khi phát hành chính thức.","Vận hành được quy trình xuất hóa đơn, xử lý sai sót, trả hàng tại quầy có phân quyền chống gian lận.","Đối chiếu được doanh thu cuối ngày giữa hóa đơn, tiền mặt, thẻ, chuyển khoản và kê khai thuế khớp với dữ liệu hóa đơn."],"k":"Từ 2026 hộ kinh doanh bỏ thuế khoán, doanh thu bán lẻ hiện rõ qua từng hóa đơn máy tính tiền: cửa hàng của bạn đã sẵn sàng chưa?","w":["NĐ 70/2025 (hiệu lực 01/06/2025) mở rộng và làm rõ việc sử dụng hóa đơn điện tử khởi tạo từ máy tính tiền cho hoạt động bán trực tiếp đến người tiêu dùng.","Từ 01/01/2026 bỏ thuế khoán hộ kinh doanh theo NQ 198/2025/QH15, hộ chuyển sang tự kê khai nên dữ liệu hóa đơn tại quầy trở thành căn cứ chính để xác định doanh thu và thuế.","Thanh toán không tiền mặt, ví điện tử, QR và POS thông minh phát triển nhanh, dữ liệu thanh toán và hóa đơn ngày càng dễ đối chiếu chéo, chênh lệch sẽ bị phát hiện sớm."],"dl":["Bảng tự đánh giá đối tượng áp dụng và bảng so sánh giải pháp máy tính tiền theo 10 tiêu chí.","SOP vận hành tại quầy: mở ca, xuất hóa đơn, xử lý sai sót, trả hàng, đóng ca và bàn giao tiền.","Mẫu Excel đối chiếu doanh thu cuối ngày theo kênh thanh toán và theo dõi tiền đang chuyển từ thẻ, ví điện tử.","Bộ câu lệnh AI (prompt) phân tích dữ liệu bán hàng, phát hiện hủy hóa đơn bất thường và soạn báo cáo doanh thu tuần cho chủ cửa hàng."],"ls":["Hóa đơn từ máy tính tiền: hiểu đúng để làm đúng","Ai phải áp dụng: đối tượng và lộ trình theo NĐ 70/2025","Chọn hạ tầng và giải pháp: đầu tư đúng, không lãng phí","Đăng ký, kết nối và chạy thử trước ngày áp dụng","Vận hành tại quầy: nhanh, đúng và khách hài lòng","Sai sót, hủy, trả hàng và chống gian lận thu ngân","Đối chiếu doanh thu và hạch toán: từ quầy đến sổ cái","Kê khai thuế và quản trị rủi ro bằng dữ liệu"],"l1":{"t":"Hóa đơn từ máy tính tiền: hiểu đúng để làm đúng","sum":"Bài mở đầu giải thích bản chất hóa đơn điện tử khởi tạo từ máy tính tiền và điểm khác so với hóa đơn điện tử thông thường. Học viên hiểu mục tiêu quản lý và lợi ích thực tế cho điểm bán.","points":["Hóa đơn khởi tạo từ máy tính tiền có mã của cơ quan thuế, được tạo trực tiếp từ hệ thống bán hàng có kết nối chuyển dữ liệu điện tử với cơ quan thuế.","Khác với hóa đơn có mã thông thường, người bán không phải chờ cấp mã từng hóa đơn, phù hợp giao dịch nhanh tại quầy.","Quy định về chữ ký số, nội dung trên hóa đơn loại này được đơn giản hóa so với hóa đơn thông thường theo NĐ 123/2020 sửa bởi NĐ 70/2025.","Mục tiêu quản lý là minh bạch doanh thu bán lẻ, giảm thất thu ở khâu bán trực tiếp người tiêu dùng.","Lợi ích cho người bán: xuất hóa đơn tức thì, khách tra cứu được, dữ liệu bán hàng chuẩn hóa phục vụ quản trị và kế toán."],"case":"Nhà hàng Hương Quê có 2 cơ sở, trước đây xuất hóa đơn điện tử thủ công cuối ngày cho khách yêu cầu nên thường sót. Sau khi chuyển sang hóa đơn từ máy tính tiền, mọi giao dịch đều có hóa đơn ngay khi thanh toán và chủ nhà hàng xem doanh thu từng cơ sở theo giờ.","trend":"Giai đoạn 2026–2030 dự kiến hóa đơn máy tính tiền trở thành chuẩn cho bán lẻ, dịch vụ ăn uống và kết nối sâu với thanh toán số. Học viên nên xem đây là cơ hội số hóa vận hành, không chỉ là nghĩa vụ thuế.","practice":"Liệt kê quy trình bán hàng hiện tại của một cửa hàng, đánh dấu các điểm sẽ thay đổi khi áp dụng hóa đơn từ máy tính tiền.","takeaway":"Hóa đơn máy tính tiền biến mỗi lần thanh toán thành một dòng dữ liệu đáng tin."}},{"id":"KH030","code":"kh030","f":"THUE","fn":"Thuế","t":"Thuế GTGT: khấu trừ, hoàn thuế và kê khai","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp kế toán nắm chắc thuế GTGT theo Luật GTGT 48/2024/QH15 và NĐ 181/2025: đối tượng chịu thuế, thuế suất, điều kiện khấu trừ, lập tờ khai 01/GTGT, khai bổ sung và hoàn thuế cơ bản. Phương pháp học dựa trên tình huống doanh nghiệp thật, ví dụ định khoản và mẫu Excel đối chiếu dùng ngay. Học xong, học viên tự kê khai GTGT hằng kỳ chính xác, giữ trọn số thuế được khấu trừ và sẵn sàng giải trình khi bị kiểm tra.","a":"Kế toán viên, kế toán thuế mới vào nghề, kế toán dịch vụ và chủ doanh nghiệp nhỏ muốn tự kê khai thuế GTGT.","o":["Phân loại đúng hàng hóa, dịch vụ vào nhóm không chịu thuế, không phải kê khai, 0%, 5%, 8% hoặc 10% cho danh mục sản phẩm của doanh nghiệp.","Tự kiểm tra được điều kiện khấu trừ cho 100% hóa đơn đầu vào trước khi kê khai, đặc biệt điều kiện thanh toán từ 5 triệu đồng.","Lập và nộp được tờ khai 01/GTGT tháng hoặc quý, kèm phụ lục giảm thuế, khớp số dư TK 133 và TK 3331.","Xử lý được khai bổ sung và tính đúng tiền chậm nộp 0,03%/ngày khi phát hiện sai sót.","Nhận diện được trường hợp đủ điều kiện hoàn thuế GTGT và chuẩn bị hồ sơ hoàn cơ bản."],"k":"Luật GTGT mới, thuế suất 8% đến hết 2026, ngưỡng 5 triệu đồng: chỉ một hóa đơn trả tiền mặt cũng đủ làm bạn mất quyền khấu trừ.","w":["Luật GTGT 48/2024/QH15 hiệu lực từ 01/07/2025 cùng NĐ 181/2025 thay đổi đối tượng không chịu thuế, điều kiện khấu trừ và hoàn thuế; kiến thức GTGT trước 2025 cần được cập nhật toàn diện.","Thuế suất giảm 8% kéo dài đến hết 31/12/2026 theo NQ 204/2025/QH15 với danh mục loại trừ phức tạp, sau đó dự kiến trở lại mức thông thường: kế toán phải quản lý thuế suất từng mặt hàng thật chặt.","Cơ quan thuế đối chiếu tự động dữ liệu hóa đơn điện tử đầu ra – đầu vào với tờ khai; sai lệch nhỏ cũng sinh cảnh báo, và chế tài theo NĐ 125/2020 sửa bởi NĐ 310/2025 áp dụng từ 16/01/2026."],"dl":["Mẫu Excel lập tờ khai 01/GTGT từ bảng kê hóa đơn, tự tính thuế phải nộp hoặc còn được khấu trừ chuyển kỳ sau.","Checklist điều kiện khấu trừ thuế GTGT đầu vào và bảng tra nhanh thuế suất, nhóm không được giảm 8%.","Quy trình SOP kê khai GTGT hằng kỳ: tải dữ liệu, đối chiếu, lập tờ khai, kiểm tra chéo, nộp và lưu hồ sơ.","Bộ câu lệnh AI (prompt) phân loại thuế suất sơ bộ, rà soát bảng kê hóa đơn và soạn dự thảo giải trình chênh lệch."],"ls":["Thuế GTGT 2026: bản chất và những thay đổi lớn của Luật 48/2024/QH15","Chịu thuế, không chịu thuế, không phải kê khai: phân loại không nhầm","Thuế suất và chính sách giảm thuế 8% đến hết 2026","Điều kiện khấu trừ đầu vào: giữ trọn từng đồng thuế","Lập tờ khai 01/GTGT từng chỉ tiêu, khớp từng con số","Kỳ khai, thời hạn và khai bổ sung không sợ sai","Hoàn thuế GTGT: biến số thuế chờ khấu trừ thành dòng tiền","Đối chiếu dữ liệu và kiểm soát rủi ro GTGT với Excel và AI"],"l1":{"t":"Thuế GTGT 2026: bản chất và những thay đổi lớn của Luật 48/2024/QH15","sum":"Bài mở đầu giúp học viên hiểu bản chất thuế GTGT và khung pháp lý mới. Học viên nắm các thay đổi quan trọng để không áp dụng nhầm quy định cũ.","points":["Thuế GTGT tính trên phần giá trị tăng thêm qua từng khâu sản xuất, lưu thông; người tiêu dùng cuối cùng là người chịu thuế, doanh nghiệp là người nộp thay.","Luật GTGT 48/2024/QH15 có hiệu lực từ 01/07/2025, được hướng dẫn bởi NĐ 181/2025; điều chỉnh đối tượng không chịu thuế, thuế suất, điều kiện khấu trừ và hoàn thuế.","Hai phương pháp tính: khấu trừ (thuế đầu ra trừ thuế đầu vào được khấu trừ) và trực tiếp trên doanh thu nhân tỷ lệ phần trăm.","Việc khai, nộp, hoàn thuế thực hiện theo Luật Quản lý thuế 38/2019/QH14 và NĐ 126/2020.","Ví dụ: mua hàng 100 triệu đồng thuế 10 triệu, bán 150 triệu đồng thuế 15 triệu, doanh nghiệp nộp 5 triệu đồng, tương ứng 10% của phần giá trị tăng thêm 50 triệu đồng."],"case":"Công ty TNHH Minh An vẫn áp dụng danh mục không chịu thuế cũ cho một nhóm sản phẩm sau 01/07/2025. Khi rà soát theo Luật 48/2024/QH15, kế toán phát hiện cần xác định lại nghĩa vụ, khai bổ sung các kỳ liên quan và cập nhật danh mục thuế trên phần mềm.","trend":"Giai đoạn 2026–2030 dự kiến cơ quan thuế tiếp tục tăng cường tờ khai gợi ý sẵn từ dữ liệu hóa đơn. Học viên nên chuyển vai trò từ người nhập số liệu sang người kiểm soát và giải thích số liệu.","practice":"Lập bảng so sánh 5 điểm thay đổi chính của Luật GTGT 48/2024/QH15 ảnh hưởng đến doanh nghiệp bạn và việc cần làm tương ứng.","takeaway":"Hiểu bản chất giá trị tăng thêm thì mọi quy định GTGT đều có logic."}},{"id":"KH031","code":"kh031","f":"THUE","fn":"Thuế","t":"Thuế GTGT nâng cao: các trường hợp đặc thù","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học giải quyết các tình huống thuế GTGT khó nhất trong thực tế: khuyến mại, biếu tặng, xuất khẩu, dự án đầu tư, xây dựng, bất động sản, phân bổ đầu vào, tái cấu trúc và hoàn thuế theo Luật GTGT 48/2024/QH15. Mỗi bài được dạy qua tình huống thật tại doanh nghiệp Việt Nam, kèm mẫu bảng tính và checklist hồ sơ dùng ngay. Học xong, học viên tự tin xử lý nghiệp vụ đặc thù, lập hồ sơ hoàn thuế chặt chẽ và giải trình thuyết phục trước cơ quan thuế.","a":"Kế toán trưởng, kế toán tổng hợp, chuyên viên thuế và tư vấn viên đã nắm vững kê khai GTGT cơ bản, muốn làm chủ các trường hợp đặc thù và hồ sơ hoàn thuế.","o":["Xác định đúng giá tính thuế và nghĩa vụ lập hóa đơn cho hàng khuyến mại, biếu tặng, tiêu dùng nội bộ trong ít nhất 10 tình huống mẫu.","Lập được bảng phân bổ thuế GTGT đầu vào dùng chung theo tỷ lệ doanh thu, có kiểm soát số liệu theo tháng và điều chỉnh cuối năm.","Tự kiểm tra được đủ điều kiện áp dụng thuế suất 0% cho hàng hóa, dịch vụ xuất khẩu trước khi xuất hóa đơn.","Chuẩn bị được bộ hồ sơ hoàn thuế GTGT cho dự án đầu tư hoặc xuất khẩu đúng quy định, giảm tối đa yêu cầu bổ sung.","Rút ngắn được thời gian rà soát rủi ro GTGT hàng tháng nhờ quy trình đối chiếu dữ liệu và bộ câu lệnh AI hỗ trợ."],"k":"Một nghiệp vụ GTGT đặc thù xử lý sai có thể khiến doanh nghiệp mất cả khoản hoàn thuế hàng tỷ đồng sau một lần kiểm tra.","w":["Luật GTGT 48/2024/QH15 và các nghị định hướng dẫn, trong đó có NĐ 181/2025, đã thay đổi nhiều điều kiện khấu trừ, hoàn thuế và đối tượng chịu thuế; cách làm cũ không còn an toàn.","Cơ quan thuế đang đẩy mạnh quản lý thuế số: dữ liệu hóa đơn điện tử, tờ khai hải quan và giao dịch ngân hàng được đối chiếu tự động, sai lệch bị phát hiện nhanh hơn bao giờ hết.","Thuế suất 8% áp dụng đến hết 31/12/2026 theo NQ 204/2025/QH15 với nhiều ngành bị loại trừ, khiến việc xác định đúng thuế suất cho từng mặt hàng trở thành điểm rủi ro hàng đầu."],"dl":["Bộ mẫu Excel: bảng phân bổ thuế đầu vào dùng chung, bảng theo dõi hoàn thuế lũy kế, bảng đối chiếu tờ khai 01/GTGT với hóa đơn.","Checklist 40 điểm kiểm tra điều kiện khấu trừ, thuế suất 0% và hồ sơ hoàn thuế theo Luật GTGT 48/2024/QH15.","Quy trình SOP xử lý nghiệp vụ GTGT đặc thù: khuyến mại, biếu tặng, xây dựng, bất động sản, tái cấu trúc doanh nghiệp.","Bộ câu lệnh AI (prompt) rà soát hóa đơn bất thường, soạn giải trình thuế và tóm tắt văn bản hướng dẫn mới."],"ls":["Khuyến mại, biếu tặng, tiêu dùng nội bộ: xử lý đúng ngay từ hóa đơn","Thuế suất 0% cho hàng hóa, dịch vụ xuất khẩu: điều kiện và bẫy thường gặp","Phân bổ thuế GTGT đầu vào dùng chung: làm đúng, làm nhanh, giải trình được","Thuế GTGT trong dự án đầu tư: kê khai riêng, bù trừ và hoàn thuế","Xây dựng, lắp đặt và bất động sản: thời điểm, giá tính thuế và hóa đơn","Tái cấu trúc doanh nghiệp: sáp nhập, chia tách, giải thể và đổi phương pháp tính thuế","Hồ sơ hoàn thuế GTGT nâng cao: chuẩn bị như một bộ hồ sơ kiểm toán","Ứng dụng AI và dữ liệu để kiểm soát rủi ro GTGT, xử lý kiểm tra sau hoàn"],"l1":{"t":"Khuyến mại, biếu tặng, tiêu dùng nội bộ: xử lý đúng ngay từ hóa đơn","sum":"Bài học phân biệt ba nhóm nghiệp vụ thường bị nhầm lẫn và hậu quả thuế của từng nhóm. Học viên nắm cách xác định giá tính thuế, cách lập hóa đơn và hồ sơ chứng minh.","points":["Hàng khuyến mại thực hiện đúng quy định pháp luật thương mại (có đăng ký hoặc thông báo khi phải làm) thì giá tính thuế GTGT bằng 0, nhưng vẫn phải lập hóa đơn ghi rõ hàng khuyến mại.","Hàng biếu, tặng, cho không thuộc chương trình khuyến mại phải tính thuế GTGT theo giá tính thuế của hàng hóa cùng loại hoặc tương đương tại thời điểm phát sinh.","Hàng hóa luân chuyển nội bộ để tiếp tục quá trình sản xuất kinh doanh được xử lý khác với hàng dùng cho mục đích phúc lợi, tiêu dùng cá nhân; cần đối chiếu quy định hiện hành cho từng trường hợp.","Hồ sơ chứng minh gồm: kế hoạch, thể lệ chương trình, văn bản thông báo hoặc đăng ký khuyến mại, danh sách khách nhận hàng và hóa đơn tương ứng.","Ví dụ định khoản biếu tặng hàng hóa giá vốn 10 triệu, giá bán tương đương 12 triệu, thuế suất 10%: Nợ 642 / Có 156 10 triệu; thuế GTGT đầu ra phải nộp 1,2 triệu ghi Nợ 642 / Có 33311."],"case":"Công ty TNHH Minh An tặng 200 thùng sản phẩm cho đại lý dịp Tết nhưng không có văn bản chương trình khuyến mại, giá bán tương đương 500.000 đồng/thùng. Khi kiểm tra, cơ quan thuế xác định đây là hàng biếu tặng, truy thu GTGT 10% trên 100 triệu đồng là 10 triệu kèm tiền chậm nộp. Cách đúng là lập chương trình khuyến mại hợp lệ từ đầu hoặc tự kê khai thuế đầu ra ngay khi biếu tặng.","trend":"Dữ liệu hóa đơn điện tử giá 0 đồng được cơ quan thuế phân tích tự động theo tần suất và giá trị; giai đoạn 2026–2030 dự kiến các doanh nghiệp có tỷ lệ hàng khuyến mại cao sẽ bị chọn kiểm tra theo rủi ro. Học viên nên chuẩn hóa hồ sơ khuyến mại dạng số, lưu cùng hóa đơn.","practice":"Lấy 3 chương trình tặng hàng gần nhất của doanh nghiệp, phân loại từng chương trình là khuyến mại hợp lệ hay biếu tặng, tính thuế GTGT phải nộp và ghi lại hồ sơ còn thiếu.","takeaway":"Không có hồ sơ khuyến mại hợp lệ thì hàng tặng chính là hàng bán phải chịu thuế."}},{"id":"KH032","code":"kh032","f":"THUE","fn":"Thuế","t":"Thuế thu nhập cá nhân từ tiền lương, tiền công","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp kế toán và người làm nhân sự tính, khấu trừ và kê khai thuế TNCN từ tiền lương, tiền công chính xác theo mức giảm trừ gia cảnh mới từ kỳ 2026 và biểu thuế lũy tiến hiện hành. Phương pháp học dựa trên bảng lương thật, tình huống thường gặp tại doanh nghiệp Việt Nam và bộ mẫu Excel tính thuế dùng ngay. Kết thúc khoá, học viên tự lập được bảng lương có thuế TNCN chuẩn, kê khai đúng hạn và giải thích rõ ràng cho người lao động.","a":"Kế toán mới vào nghề, nhân viên nhân sự – tiền lương, chủ doanh nghiệp nhỏ và người lao động muốn tự hiểu, tự kiểm tra thuế TNCN trên phiếu lương của mình.","o":["Lập được bảng lương có tính thuế TNCN tự động theo biểu lũy tiến 7 bậc và mức giảm trừ gia cảnh 2026.","Phân loại chính xác các khoản thu nhập chịu thuế và không chịu thuế trong ít nhất 15 khoản mục phổ biến của phiếu lương.","Tính đúng thuế cho các trường hợp đặc thù: lương tháng 13, thưởng, lương NET, lao động thời vụ khấu trừ 10%.","Kê khai và nộp tờ khai thuế TNCN theo tháng hoặc quý đúng hạn, không phát sinh tiền chậm nộp.","Tự kiểm tra được số thuế trên phiếu lương của từng nhân viên trong dưới 2 phút nhờ công thức tính nhanh."],"k":"Từ kỳ 2026 mức giảm trừ gia cảnh tăng lên 15,5 triệu đồng mỗi tháng: bảng lương của bạn đã tính đúng chưa?","w":["Mức giảm trừ gia cảnh mới 15,5 triệu đồng/tháng cho bản thân và 6,2 triệu đồng/tháng cho mỗi người phụ thuộc áp dụng từ kỳ tính thuế 2026, mọi bảng lương phải cập nhật lại công thức.","Luật BHXH 2024 có hiệu lực từ 01/07/2025 làm thay đổi một số quy định về đối tượng và căn cứ đóng bảo hiểm, ảnh hưởng trực tiếp đến khoản được trừ khi tính thuế TNCN.","Cơ quan thuế đang số hóa mạnh: chứng từ khấu trừ thuế điện tử, dữ liệu người phụ thuộc và thu nhập được đối chiếu tự động, sai sót nhỏ cũng dễ bị phát hiện."],"dl":["Bộ mẫu Excel bảng lương có thuế TNCN tự động: biểu lũy tiến, giảm trừ gia cảnh 2026, quy đổi lương NET sang GROSS.","Checklist phân loại thu nhập chịu thuế và không chịu thuế cho các khoản phụ cấp, phúc lợi phổ biến.","Quy trình SOP đăng ký người phụ thuộc, khấu trừ, kê khai, nộp thuế và cấp chứng từ khấu trừ điện tử.","Bộ câu lệnh AI (prompt) kiểm tra bảng lương, soạn thông báo giải thích thuế cho người lao động và rà soát quy chế lương."],"ls":["Bức tranh thuế TNCN từ tiền lương năm 2026: ai nộp, ai khấu trừ, ai chịu trách nhiệm","Thu nhập chịu thuế và khoản không tính thuế: đọc phiếu lương như chuyên gia","Giảm trừ gia cảnh 2026 và người phụ thuộc: đăng ký đúng, trừ đủ","Biểu thuế lũy tiến 7 bậc và công thức tính nhanh","Khấu trừ 10%, cam kết thu nhập và lao động thời vụ","Thu nhập đặc thù: lương tháng 13, thưởng, lương NET và lao động nước ngoài","Kê khai, nộp thuế và chứng từ khấu trừ điện tử: làm đúng hạn mỗi kỳ","Tự động hóa bảng lương với Excel và AI: chính xác, minh bạch, bảo mật"],"l1":{"t":"Bức tranh thuế TNCN từ tiền lương năm 2026: ai nộp, ai khấu trừ, ai chịu trách nhiệm","sum":"Bài học mở đầu giúp học viên hiểu vai trò của tổ chức trả thu nhập và người lao động trong nghĩa vụ thuế TNCN. Học viên phân biệt cá nhân cư trú, không cư trú và cách tính thuế khác nhau.","points":["Tổ chức trả thu nhập có trách nhiệm khấu trừ thuế TNCN trước khi chi trả, kê khai, nộp thay và cấp chứng từ khấu trừ cho người lao động.","Cá nhân cư trú (thường là có mặt tại Việt Nam từ 183 ngày trong năm hoặc có nơi ở thường xuyên theo quy định) tính thuế theo biểu lũy tiến từng phần sau giảm trừ.","Cá nhân không cư trú có thu nhập từ tiền lương, tiền công tại Việt Nam chịu thuế suất toàn phần 20% trên thu nhập chịu thuế, không được giảm trừ gia cảnh.","Mã số thuế cá nhân hiện được hợp nhất với số định danh cá nhân theo lộ trình quản lý thuế số; kế toán cần cập nhật thông tin nhân viên chính xác.","Nền tảng pháp lý chính: Luật Thuế TNCN và các văn bản hướng dẫn hiện hành, Luật Quản lý thuế 38/2019/QH14, NĐ 126/2020."],"case":"Công ty TNHH Minh An tuyển một chuyên gia Hàn Quốc làm việc 5 tháng tại Việt Nam với lương 80 triệu đồng/tháng nhưng vẫn tính thuế theo biểu lũy tiến và trừ gia cảnh. Rà soát cho thấy chuyên gia là cá nhân không cư trú, phải chịu thuế 20% trên toàn bộ thu nhập chịu thuế. Công ty đã tính lại, khai bổ sung và trao đổi với chuyên gia về số thuế chênh lệch.","trend":"Quản lý thuế cá nhân đang chuyển sang dựa trên định danh điện tử và dữ liệu dân cư; dự kiến giai đoạn 2026–2030 việc đối chiếu thu nhập từ nhiều nguồn sẽ gần như tự động. Kế toán cần làm sạch dữ liệu nhân sự ngay từ bây giờ.","practice":"Lập danh sách toàn bộ nhân viên hiện có, xác định tình trạng cư trú, loại hợp đồng và phương pháp tính thuế phù hợp cho từng người.","takeaway":"Xác định đúng tình trạng cư trú là bước đầu tiên và quan trọng nhất của mọi phép tính thuế TNCN."}},{"id":"KH033","code":"kh033","f":"THUE","fn":"Thuế","t":"Quyết toán thuế TNCN cuối năm","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học hướng dẫn trọn quy trình quyết toán thuế TNCN năm cho tổ chức trả thu nhập và cá nhân tự quyết toán: xác định nghĩa vụ, điều kiện ủy quyền, tính lại thuế cả năm, lập tờ khai và xử lý nộp thừa, nộp thiếu. Học viên thực hành trên bộ dữ liệu bảng lương 12 tháng, mẫu Excel quyết toán và tình huống đặc thù thường gặp tại doanh nghiệp Việt Nam. Kết thúc khoá, học viên hoàn thành quyết toán đúng hạn, số liệu khớp, giải trình được và giảm thiểu rủi ro bị phạt.","a":"Kế toán tổng hợp, kế toán tiền lương, chuyên viên nhân sự và dịch vụ kế toán phụ trách quyết toán thuế TNCN cho doanh nghiệp hoặc cho khách hàng cá nhân.","o":["Xác định chính xác cá nhân nào được ủy quyền quyết toán và cá nhân nào phải tự quyết toán trong danh sách nhân viên.","Tính lại được thuế TNCN cả năm cho từng nhân viên và xác định số nộp thừa, nộp thiếu khớp với số đã khấu trừ.","Lập được tờ khai quyết toán của tổ chức trả thu nhập kèm phụ lục chi tiết, đối chiếu khớp với tờ khai tháng, quý trong năm.","Hướng dẫn được cá nhân tự quyết toán và đề nghị hoàn thuế trực tuyến trên cổng thuế điện tử.","Hoàn thành quyết toán trước hạn ít nhất 10 ngày nhờ lịch công việc và checklist chuẩn bị dữ liệu từ tháng 12."],"k":"Quyết toán thuế TNCN năm 2026 là năm đầu áp dụng mức giảm trừ mới: làm sai một lần, sai cho cả trăm nhân viên.","w":["Kỳ quyết toán năm 2026 là kỳ đầu tiên áp dụng mức giảm trừ gia cảnh 15,5 triệu đồng/tháng cho bản thân và 6,2 triệu đồng/tháng cho người phụ thuộc, mọi bảng tính quyết toán cũ phải cập nhật.","Cơ quan thuế đã triển khai tờ khai quyết toán điện tử điền sẵn thông tin và đối chiếu tự động thu nhập từ nhiều nơi; sai lệch giữa doanh nghiệp và cá nhân bị phát hiện nhanh.","Mức xử phạt vi phạm hành chính về thuế được cập nhật theo NĐ 125/2020 sửa bởi NĐ 310/2025 hiệu lực 16/01/2026, rủi ro của việc nộp chậm hoặc khai sai tăng lên."],"dl":["Bộ mẫu Excel quyết toán: tổng hợp thu nhập 12 tháng, tính lại thuế năm, xác định thừa thiếu, đối chiếu với tờ khai khấu trừ.","Checklist điều kiện ủy quyền quyết toán và danh mục hồ sơ cần thu thập từ nhân viên.","Quy trình SOP quyết toán thuế TNCN từ khóa sổ lương tháng 12 đến nộp tờ khai, xử lý thừa thiếu và lưu trữ.","Bộ câu lệnh AI (prompt) rà soát dữ liệu quyết toán, soạn thông báo gửi nhân viên và soạn văn bản giải trình."],"ls":["Ai phải quyết toán, quyết toán khi nào: nắm chắc nghĩa vụ năm 2026","Ủy quyền quyết toán: điều kiện, thủ tục và các trường hợp ranh giới","Chuẩn bị dữ liệu quyết toán: khóa sổ lương và làm sạch dữ liệu","Tính lại thuế cả năm: công thức, ví dụ và các điểm dễ sai","Lập tờ khai quyết toán của tổ chức trả thu nhập và phụ lục chi tiết","Cá nhân tự quyết toán thuế trực tuyến: hướng dẫn từng bước","Xử lý nộp thừa, nộp thiếu và hoàn thuế TNCN","Tình huống đặc biệt, lỗi thường gặp và ứng dụng AI trong mùa quyết toán"],"l1":{"t":"Ai phải quyết toán, quyết toán khi nào: nắm chắc nghĩa vụ năm 2026","sum":"Bài học làm rõ nghĩa vụ quyết toán của tổ chức trả thu nhập và cá nhân. Học viên nắm thời hạn và các trường hợp không phải quyết toán.","points":["Tổ chức trả thu nhập từ tiền lương, tiền công có trách nhiệm khai quyết toán thuế TNCN và quyết toán thay cho cá nhân có ủy quyền, kể cả năm không phát sinh khấu trừ theo quy định hiện hành.","Hạn nộp hồ sơ quyết toán năm của tổ chức là ngày cuối cùng của tháng thứ 3 kể từ khi kết thúc năm dương lịch.","Cá nhân trực tiếp quyết toán nộp hồ sơ chậm nhất ngày cuối cùng của tháng thứ 4 kể từ khi kết thúc năm dương lịch; nếu ngày cuối là ngày nghỉ thì chuyển sang ngày làm việc tiếp theo.","Một số trường hợp cá nhân không phải quyết toán, ví dụ số thuế phải nộp thêm sau quyết toán nhỏ theo ngưỡng quy định hoặc đã được khấu trừ 10% với thu nhập vãng lai nhỏ và không có yêu cầu hoàn.","Căn cứ pháp lý: Luật Quản lý thuế 38/2019/QH14, NĐ 126/2020 và các văn bản hướng dẫn thuế TNCN hiện hành."],"case":"Công ty TNHH Minh An cho rằng năm nay không có nhân viên nào phải nộp thuế nên không nộp tờ khai quyết toán. Cơ quan thuế xác định doanh nghiệp vẫn có nghĩa vụ quyết toán do có trả thu nhập từ tiền lương, không phụ thuộc có phát sinh khấu trừ hay không, và xử phạt hành vi không nộp hồ sơ. Từ năm sau, doanh nghiệp đưa quyết toán TNCN vào lịch thuế cố định.","trend":"Cơ quan thuế ngày càng dựa vào dữ liệu khấu trừ điện tử và định danh cá nhân để tự động xác định đối tượng phải quyết toán. Kế toán nên chuẩn hóa mã số thuế, định danh của toàn bộ nhân viên trước mùa quyết toán.","practice":"Lập lịch quyết toán thuế TNCN cho năm 2026 của doanh nghiệp mình: các mốc khóa sổ lương, thu thập ủy quyền, lập tờ khai, nộp, xử lý thừa thiếu.","takeaway":"Có trả lương là có nghĩa vụ quyết toán, dù số thuế bằng 0."}},{"id":"KH034","code":"kh034","f":"THUE","fn":"Thuế","t":"Thuế TNCN với cá nhân kinh doanh, cho thuê tài sản","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp hộ, cá nhân kinh doanh và cá nhân cho thuê tài sản hiểu và thực hiện đúng nghĩa vụ thuế trong giai đoạn chuyển đổi lớn từ năm 2026: bỏ thuế khoán, bỏ lệ phí môn bài, chuyển sang tự kê khai và quản lý thuế trên nền tảng số. Phương pháp học dựa trên tình huống thật của hộ bán lẻ, quán ăn, người bán online, chủ nhà cho thuê, kèm mẫu sổ sách, bảng tính thuế và lịch kê khai dùng ngay. Kết thúc khoá, học viên tự kê khai được hoặc tư vấn chính xác cho khách hàng, hạn chế tối đa rủi ro truy thu và xử phạt.","a":"Chủ hộ kinh doanh, người bán hàng online, cá nhân cho thuê nhà, mặt bằng, xe, cùng kế toán dịch vụ và tư vấn viên phục vụ nhóm khách hàng này.","o":["Xác định đúng phương pháp tính thuế, ngưỡng doanh thu và tỷ lệ thuế áp dụng cho từng nhóm ngành nghề của hộ, cá nhân kinh doanh.","Tự lập được tờ khai thuế cho hộ kinh doanh kê khai và cho cá nhân cho thuê tài sản theo kỳ phù hợp.","Lập được bộ sổ theo dõi doanh thu, chi phí, hóa đơn đơn giản đáp ứng yêu cầu quản lý thuế từ 2026.","Đối chiếu được doanh thu tự khai với số thuế sàn thương mại điện tử đã khấu trừ, nộp thay để tránh khai trùng hoặc thiếu.","Đánh giá được thời điểm và lợi ích của việc chuyển đổi từ hộ kinh doanh lên doanh nghiệp bằng bảng so sánh định lượng."],"k":"Từ 01/01/2026 thuế khoán chấm dứt: hàng triệu hộ kinh doanh và chủ nhà cho thuê phải tự kê khai, bạn đã sẵn sàng chưa?","w":["NQ 198/2025/QH15 bỏ lệ phí môn bài và bỏ thuế khoán đối với hộ kinh doanh từ 01/01/2026, hộ kinh doanh chuyển sang tự kê khai, cần nắm quy trình mới ngay từ đầu năm.","Từ 01/07/2025 các sàn thương mại điện tử, nền tảng số có chức năng thanh toán khấu trừ, nộp thay thuế cho hộ, cá nhân kinh doanh trên sàn theo NĐ 117/2025, thay đổi cách người bán online kê khai.","Hóa đơn điện tử khởi tạo từ máy tính tiền, thanh toán không dùng tiền mặt và dữ liệu ngân hàng giúp cơ quan thuế nhìn rõ doanh thu thực tế của hộ kinh doanh hơn bao giờ hết."],"dl":["Bộ mẫu Excel: sổ doanh thu, chi phí hộ kinh doanh, bảng tính thuế theo tỷ lệ trên doanh thu, bảng theo dõi hợp đồng cho thuê tài sản.","Checklist chuyển đổi từ thuế khoán sang tự kê khai năm 2026 cho hộ kinh doanh.","Quy trình SOP kê khai, nộp thuế, xuất hóa đơn và lưu trữ chứng từ cho hộ kinh doanh và chủ nhà cho thuê.","Bộ câu lệnh AI (prompt) phân loại giao dịch ngân hàng, tổng hợp doanh thu đa kênh và soạn hợp đồng cho thuê có điều khoản thuế."],"ls":["Bức tranh mới của hộ, cá nhân kinh doanh từ 2026: hết khoán, tự kê khai","Phương pháp tính thuế và tỷ lệ thuế trên doanh thu theo ngành nghề","Thuế đối với cá nhân cho thuê tài sản: nhà, mặt bằng, xe, máy móc","Doanh nghiệp khai thay, nộp thay cho cá nhân cho thuê tài sản","Kê khai, thời hạn và nơi nộp hồ sơ: lịch thuế của hộ kinh doanh","Sổ sách, hóa đơn và thanh toán: chuẩn hóa hộ kinh doanh theo yêu cầu mới","Kinh doanh online, sàn thương mại điện tử và mạng xã hội: thuế trong thời đại số","Chuyển đổi từ hộ kinh doanh lên doanh nghiệp và quản trị rủi ro thuế"],"l1":{"t":"Bức tranh mới của hộ, cá nhân kinh doanh từ 2026: hết khoán, tự kê khai","sum":"Bài học giúp học viên hiểu thay đổi căn bản trong quản lý thuế hộ kinh doanh từ 01/01/2026. Học viên nắm đối tượng, nghĩa vụ và các văn bản nền tảng.","points":["Theo NQ 198/2025/QH15, từ 01/01/2026 bỏ lệ phí môn bài và bỏ phương pháp thuế khoán đối với hộ kinh doanh; hộ kinh doanh chuyển sang tự kê khai, tự nộp thuế.","Hộ, cá nhân kinh doanh chủ yếu chịu thuế GTGT và thuế TNCN tính theo tỷ lệ phần trăm trên doanh thu, có thể có thêm thuế tiêu thụ đặc biệt, tài nguyên, bảo vệ môi trường tùy ngành.","Ngưỡng doanh thu năm không phải nộp thuế GTGT và TNCN áp dụng theo quy định hiện hành; hộ dưới ngưỡng vẫn có thể phải khai báo doanh thu theo hướng dẫn.","Văn bản nền tảng: Luật Quản lý thuế 38/2019/QH14, NĐ 126/2020, Luật GTGT 48/2024/QH15, NQ 198/2025/QH15 và văn bản hướng dẫn hộ kinh doanh hiện hành; cần theo dõi văn bản mới vì giai đoạn chuyển đổi có nhiều cập nhật.","Hộ kinh doanh vẫn phải tuân thủ các nghĩa vụ khác: đăng ký kinh doanh, hóa đơn, an toàn thực phẩm hoặc điều kiện ngành nghề khi có."],"case":"Bà Hoa có cửa hàng tạp hóa ở Cần Thơ, nhiều năm nộp thuế khoán theo thông báo của cơ quan thuế. Từ năm 2026 bà vẫn chờ thông báo thuế như trước nên không kê khai quý đầu tiên. Được tư vấn kịp thời, bà đăng ký kê khai, lập sổ doanh thu và nộp tờ khai bổ sung, chỉ chịu tiền chậm nộp nhỏ.","trend":"Quản lý thuế hộ kinh doanh đang chuyển sang dựa trên dữ liệu thực: hóa đơn điện tử, thanh toán không dùng tiền mặt, dữ liệu sàn thương mại điện tử. Giai đoạn 2026–2030 dự kiến khoảng cách giữa hộ kinh doanh và doanh nghiệp nhỏ về yêu cầu minh bạch sẽ thu hẹp dần.","practice":"Lập phiếu tự đánh giá cho một hộ kinh doanh (của bạn hoặc khách hàng): ngành nghề, doanh thu năm ước tính, kênh bán, hình thức thanh toán, nghĩa vụ thuế từ 2026.","takeaway":"Từ 2026, không còn chờ cơ quan thuế giao số: hộ kinh doanh tự khai, tự chịu trách nhiệm."}},{"id":"KH035","code":"kh035","f":"THUE","fn":"Thuế","t":"Thuế thu nhập doanh nghiệp: chi phí được trừ và không được trừ","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp kế toán phân định rõ chi phí được trừ và không được trừ khi tính thuế TNDN theo Luật TNDN 67/2025/QH15, để không bị xuất toán và không nộp thừa thuế. Mỗi bài đi từ điều kiện pháp lý đến tình huống thật tại doanh nghiệp Việt Nam, kèm mẫu hồ sơ và checklist dùng ngay. Kết thúc khoá, học viên tự rà soát được toàn bộ chi phí trong năm và lập được bảng điều chỉnh chi phí không được trừ trước khi quyết toán.","a":"Kế toán tổng hợp, kế toán thuế và chủ doanh nghiệp nhỏ và vừa muốn kiểm soát chi phí đúng luật, tránh bị loại chi phí khi quyết toán hoặc thanh tra.","o":["Áp dụng được ba điều kiện chung để phân loại đúng từng khoản chi là được trừ hay không được trừ.","Tự kiểm tra được hồ sơ chi phí tiền lương, khấu hao, lãi vay và chi phí mua hàng không hóa đơn theo checklist.","Lập được bảng tổng hợp chi phí không được trừ để đưa vào chỉ tiêu điều chỉnh tăng thu nhập trên tờ khai quyết toán.","Phát hiện và khắc phục được ít nhất 10 lỗi chi phí phổ biến trước khi cơ quan thuế phát hiện.","Xây dựng được quy chế chi tiêu nội bộ và quy trình phê duyệt chứng từ giúp chi phí được trừ ngay từ khâu phát sinh."],"k":"Một hóa đơn trên 5 triệu trả bằng tiền mặt có thể khiến cả khoản chi bị loại khi quyết toán TNDN 2026.","w":["Luật TNDN 67/2025/QH15 áp dụng từ kỳ tính thuế 2025 với thuế suất 15% cho doanh nghiệp doanh thu đến 3 tỷ và 17% cho doanh thu từ 3 đến 50 tỷ, nên việc xác định đúng thu nhập tính thuế càng quan trọng để hưởng đúng mức thuế suất.","Ngưỡng thanh toán không dùng tiền mặt hạ xuống từ 5 triệu đồng theo NĐ 181/2025 từ 01/07/2025, khiến nhiều khoản chi quen thuộc trước đây nay có nguy cơ bị loại.","Cơ quan thuế đã kết nối dữ liệu hóa đơn điện tử, ngân hàng và bảo hiểm xã hội, giúp phát hiện chi phí bất thường bằng phân tích dữ liệu thay vì kiểm tra thủ công như trước."],"dl":["Bộ checklist 3 điều kiện chi phí được trừ theo từng nhóm chi phí (nhân công, tài sản, tài chính, mua hàng, dịch vụ).","Mẫu Excel bảng tổng hợp chi phí không được trừ có liên kết sang chỉ tiêu điều chỉnh trên tờ khai quyết toán TNDN.","Bộ mẫu hồ sơ: quy chế chi tiêu nội bộ, bảng kê thu mua không hóa đơn, hợp đồng lao động và quy chế lương thưởng.","Bộ câu lệnh AI (prompt) rà soát sổ chi phí, đánh dấu khoản chi thiếu chứng từ thanh toán hoặc vượt ngưỡng tiền mặt."],"ls":["Bức tranh thuế TNDN 2026: vì sao chi phí quyết định số thuế phải nộp","Ba điều kiện vàng để một khoản chi được trừ","Chi phí nhân công: lương, thưởng, phúc lợi và bảo hiểm","Khấu hao tài sản và chi phí tài sản: đúng khung, đúng đối tượng","Lãi vay, chênh lệch tỷ giá và chi phí tài chính","Bản đồ chi phí không được trừ thường gặp và cách phòng tránh","Chi phí không hóa đơn, bảng kê thu mua và giao dịch với cá nhân","Dùng AI và dữ liệu để rà soát chi phí trước quyết toán"],"l1":{"t":"Bức tranh thuế TNDN 2026: vì sao chi phí quyết định số thuế phải nộp","sum":"Bài nền tảng giúp học viên hiểu công thức tính thuế TNDN và vị trí của chi phí được trừ trong công thức đó. Học viên nắm các điểm mới của Luật TNDN 67/2025/QH15 ảnh hưởng trực tiếp đến kế toán chi phí.","points":["Thu nhập tính thuế bằng doanh thu trừ chi phí được trừ, cộng thu nhập khác, trừ thu nhập miễn thuế và lỗ được chuyển; mỗi đồng chi phí bị loại làm tăng thuế đúng bằng thuế suất áp dụng.","Từ kỳ tính thuế 2025, thuế suất 15% áp dụng cho doanh nghiệp có tổng doanh thu năm không quá 3 tỷ đồng, 17% cho doanh thu từ trên 3 đến 50 tỷ đồng, còn lại 20%, theo Luật TNDN 67/2025/QH15 và hướng dẫn hiện hành.","Lợi nhuận kế toán khác thu nhập tính thuế: kế toán ghi nhận theo chuẩn mực, còn thuế chỉ chấp nhận chi phí đáp ứng điều kiện của luật thuế; phần chênh lệch được điều chỉnh trên tờ khai quyết toán.","Doanh nghiệp tạm nộp thuế theo quý, tổng số tạm nộp 4 quý không thấp hơn 80% số quyết toán; nếu loại chi phí sai, doanh nghiệp vừa thiếu thuế vừa có thể phát sinh tiền chậm nộp 0,03%/ngày.","Ví dụ: doanh nghiệp có lợi nhuận kế toán 800 triệu, chi phí không được trừ 150 triệu, thuế suất 20% thì thuế TNDN là (800 + 150) x 20% = 190 triệu, cao hơn 30 triệu so với nếu chi phí hợp lệ."],"case":"Công ty TNHH Minh An doanh thu 2,8 tỷ đồng năm 2025, lợi nhuận kế toán 320 triệu nhưng có 60 triệu chi phí thiếu chứng từ thanh toán qua ngân hàng. Kế toán xác định thuế suất 15% do doanh thu dưới 3 tỷ, thu nhập tính thuế 380 triệu, thuế phải nộp 57 triệu; đồng thời bổ sung quy trình thanh toán qua ngân hàng để năm sau không lặp lại.","trend":"Giai đoạn 2026–2030, quản lý thuế chuyển mạnh sang phân tích dữ liệu lớn và rủi ro tự động. Kế toán nên chuẩn hóa mã chi phí trong phần mềm để có thể tách chi phí được trừ và không được trừ ngay khi hạch toán.","practice":"Lấy số liệu lợi nhuận kế toán năm gần nhất của doanh nghiệp bạn, liệt kê 5 khoản chi bạn nghi ngờ không được trừ và tính thử số thuế tăng thêm nếu các khoản này bị loại.","takeaway":"Chi phí không chỉ cần có thật, mà phải chứng minh được bằng hồ sơ đúng luật."}},{"id":"KH036","code":"kh036","f":"THUE","fn":"Thuế","t":"Quyết toán thuế TNDN và lập báo cáo tài chính nộp thuế","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học giúp kế toán khóa sổ, lập báo cáo tài chính năm và tờ khai quyết toán thuế TNDN khớp nhau tuyệt đối, đúng hạn ngày cuối tháng thứ 3 sau năm tài chính. Học viên đi qua trọn quy trình trên một bộ số liệu doanh nghiệp thật, với file Excel đối chiếu, checklist khóa sổ và mẫu thuyết minh dùng ngay. Kết quả là một bộ hồ sơ quyết toán sạch, có dấu vết kiểm tra, sẵn sàng giải trình khi cơ quan thuế kiểm tra.","a":"Kế toán tổng hợp, kế toán trưởng và chuyên viên dịch vụ kế toán chịu trách nhiệm lập báo cáo tài chính và quyết toán thuế TNDN hằng năm.","o":["Hoàn thành được checklist khóa sổ cuối năm với các bút toán điều chỉnh, kết chuyển và đối chiếu số dư.","Lập được bộ báo cáo tài chính năm gồm báo cáo tình hình tài chính, kết quả kinh doanh, lưu chuyển tiền tệ và thuyết minh theo chế độ kế toán áp dụng.","Lập được tờ khai quyết toán TNDN và các phụ lục, xác định đúng thu nhập tính thuế, lỗ chuyển kỳ và thuế suất.","Đối chiếu được số tạm nộp 4 quý với số quyết toán, xử lý chênh lệch và tiền chậm nộp nếu tạm nộp dưới 80%.","Tự kiểm tra chéo được ít nhất 15 điểm khớp giữa báo cáo tài chính, tờ khai thuế và sổ sách trước khi nộp."],"k":"Quyết toán năm 2025 là mùa đầu tiên áp dụng Luật TNDN mới và chế độ kế toán mới, sai một chỉ tiêu là kéo theo cả bộ hồ sơ.","w":["TT 99/2025 thay thế TT 200/2014 từ 01/01/2026, doanh nghiệp phải chuyển đổi số dư và mẫu biểu báo cáo, trong khi doanh nghiệp nhỏ và vừa tiếp tục dùng TT 133/2016.","Luật TNDN 67/2025/QH15 áp dụng từ kỳ tính thuế 2025 với thuế suất 15% và 17% cho doanh nghiệp nhỏ, đòi hỏi xác định đúng doanh thu để chọn thuế suất khi quyết toán.","Cơ quan thuế ứng dụng phân tích dữ liệu để đối chiếu tự động báo cáo tài chính, tờ khai GTGT, TNCN và hóa đơn điện tử, mọi chênh lệch đều có thể bị yêu cầu giải trình."],"dl":["Checklist khóa sổ cuối năm 60 bước theo phần hành, có cột người thực hiện và người soát xét.","File Excel đối chiếu chéo báo cáo tài chính, tờ khai quyết toán TNDN, tờ khai GTGT và quyết toán TNCN với công thức cảnh báo chênh lệch.","Bộ mẫu thuyết minh báo cáo tài chính và mẫu bảng tổng hợp điều chỉnh thu nhập tính thuế.","Bộ câu lệnh AI (prompt) phân tích biến động số dư, soạn thuyết minh và rà soát lỗi trình bày báo cáo."],"ls":["Lịch quyết toán năm và bản đồ hồ sơ phải nộp","Khóa sổ cuối năm và các bút toán điều chỉnh bắt buộc","Lập báo cáo tài chính năm theo TT 99/2025 và TT 133/2016","Từ lợi nhuận kế toán đến thu nhập tính thuế","Lập tờ khai quyết toán TNDN và các phụ lục","Đối chiếu tạm nộp 4 quý và xử lý chênh lệch","Đối chiếu chéo bằng dữ liệu và AI trước khi nộp","Nộp hồ sơ, khai bổ sung và lưu trữ số"],"l1":{"t":"Lịch quyết toán năm và bản đồ hồ sơ phải nộp","sum":"Bài nền tảng giúp học viên lên kế hoạch mùa quyết toán ngay từ tháng 12. Học viên nắm hạn nộp, thành phần hồ sơ và người chịu trách nhiệm từng phần.","points":["Hạn nộp hồ sơ quyết toán thuế TNDN và báo cáo tài chính năm là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm tài chính, với năm dương lịch là 31/03 năm sau, theo Luật Quản lý thuế 38/2019/QH14.","Hồ sơ quyết toán gồm tờ khai quyết toán TNDN, các phụ lục theo trường hợp (ưu đãi, chuyển lỗ, giao dịch liên kết) và báo cáo tài chính năm.","Cùng kỳ còn có quyết toán thuế TNCN thay người lao động, nên lập kế hoạch song song để số liệu tiền lương khớp giữa hai bộ hồ sơ.","Hạn nộp tiền thuế còn thiếu theo quyết toán trùng hạn nộp hồ sơ; nộp chậm phát sinh tiền chậm nộp 0,03%/ngày.","Lập lịch ngược: khóa sổ trước 15/01, hoàn thiện báo cáo trước 28/02, soát xét và đối chiếu trong tháng 3, nộp sớm trước hạn ít nhất 5 ngày để xử lý sự cố hệ thống."],"case":"Công ty TNHH Phương Nam năm trước nộp quyết toán vào ngày cuối cùng và gặp lỗi chữ ký số, bị nộp chậm 2 ngày. Năm nay kế toán trưởng lập lịch ngược với 4 mốc kiểm soát, hoàn thành nộp hồ sơ ngày 20/03 và không phát sinh phạt.","trend":"Hồ sơ thuế ngày càng được nộp và xử lý hoàn toàn trên môi trường điện tử, cơ quan thuế tiến tới cung cấp tờ khai gợi ý từ dữ liệu sẵn có. Kế toán nên chuẩn hóa dữ liệu để chủ động đối chiếu với số liệu cơ quan thuế nắm giữ.","practice":"Lập lịch quyết toán năm cho doanh nghiệp của bạn với ít nhất 12 đầu việc, mốc thời gian, người thực hiện và người soát xét.","takeaway":"Mùa quyết toán thắng hay thua được quyết định từ tháng 12."}},{"id":"KH037","code":"kh037","f":"THUE","fn":"Thuế","t":"Thuế nhà thầu nước ngoài","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học giúp doanh nghiệp Việt Nam xác định đúng nghĩa vụ thuế nhà thầu khi thanh toán cho tổ chức, cá nhân nước ngoài, từ phạm vi áp dụng, cách tính net và gross đến kê khai, hạch toán và áp dụng hiệp định thuế. Học viên làm việc trên các hợp đồng thực tế phổ biến như bản quyền phần mềm, quảng cáo trực tuyến, dịch vụ kỹ thuật, lãi vay nước ngoài, với file tính thuế và mẫu điều khoản hợp đồng dùng ngay. Kết thúc khoá, học viên tự lập được hồ sơ thuế nhà thầu chuẩn và kiểm soát được rủi ro ngay từ khâu đàm phán hợp đồng.","a":"Kế toán trưởng, kế toán thuế, chuyên viên pháp chế và mua hàng tại doanh nghiệp thường xuyên ký hợp đồng, thanh toán cho đối tác nước ngoài.","o":["Xác định được giao dịch nào thuộc diện chịu thuế nhà thầu và giao dịch nào không thuộc phạm vi áp dụng.","Tính đúng thuế GTGT và TNDN nhà thầu theo phương pháp trực tiếp cho cả hợp đồng giá net và giá gross.","Lập được tờ khai thuế nhà thầu, nộp thuế thay và hạch toán chính xác các bút toán liên quan.","Lập được hồ sơ đề nghị áp dụng hiệp định tránh đánh thuế hai lần cho trường hợp phù hợp.","Soạn được điều khoản thuế trong hợp đồng nước ngoài giúp phân bổ rõ trách nhiệm và chi phí thuế."],"k":"Trả phí phần mềm, quảng cáo hay tư vấn cho đối tác nước ngoài mà chưa khấu trừ thuế nhà thầu, doanh nghiệp đang gánh rủi ro thay họ.","w":["Chi phí dịch vụ số xuyên biên giới như phần mềm đám mây, quảng cáo trực tuyến, công cụ AI tăng mạnh, khiến gần như mọi doanh nghiệp đều phát sinh giao dịch thuộc diện xem xét thuế nhà thầu.","Cơ quan thuế tăng cường quản lý nhà cung cấp nước ngoài không có cơ sở thường trú qua cổng thông tin điện tử riêng và đối chiếu dữ liệu thanh toán qua ngân hàng.","Luật GTGT 48/2024/QH15 và Luật TNDN 67/2025/QH15 cùng các văn bản hướng dẫn mới đòi hỏi doanh nghiệp cập nhật lại cách xác định nghĩa vụ đối với các khoản thanh toán ra nước ngoài."],"dl":["File Excel tính thuế nhà thầu tự động cho hợp đồng net và gross, có bảng tỷ lệ theo ngành nghề để tùy chỉnh.","Checklist 12 câu hỏi xác định nghĩa vụ thuế nhà thầu trước khi ký hợp đồng nước ngoài.","Bộ mẫu điều khoản thuế song ngữ Việt Anh cho hợp đồng dịch vụ, bản quyền và cho vay nước ngoài.","Bộ câu lệnh AI (prompt) đọc nhanh hợp đồng tiếng Anh, nhận diện bản chất thu nhập và rủi ro thuế nhà thầu."],"ls":["Thuế nhà thầu là gì và vì sao doanh nghiệp Việt phải nộp thay","Ranh giới: trường hợp không thuộc diện chịu thuế nhà thầu","Ba phương pháp nộp thuế nhà thầu và khi nào chọn phương pháp nào","Tỷ lệ thuế GTGT và TNDN theo ngành nghề","Tính thuế khi giá hợp đồng là net hoặc gross","Kê khai, nộp thuế và hạch toán thuế nhà thầu","Hiệp định tránh đánh thuế hai lần: áp dụng đúng để tiết kiệm hợp pháp","Kiểm soát rủi ro hợp đồng nước ngoài bằng quy trình và AI"],"l1":{"t":"Thuế nhà thầu là gì và vì sao doanh nghiệp Việt phải nộp thay","sum":"Bài nền tảng giải thích bản chất thuế nhà thầu, đối tượng áp dụng và vai trò của bên Việt Nam trong việc khấu trừ, nộp thay. Học viên nắm rủi ro khi bỏ qua nghĩa vụ này.","points":["Thuế nhà thầu không phải sắc thuế riêng mà là cách thu thuế GTGT và thuế TNDN (hoặc TNCN với cá nhân) đối với thu nhập tổ chức, cá nhân nước ngoài có được từ Việt Nam.","Đối tượng áp dụng là tổ chức, cá nhân nước ngoài kinh doanh tại Việt Nam hoặc có thu nhập phát sinh tại Việt Nam trên cơ sở hợp đồng với bên Việt Nam.","Bên Việt Nam ký hợp đồng và thanh toán thường có trách nhiệm khấu trừ, kê khai và nộp thay; nếu không khấu trừ, doanh nghiệp vẫn bị truy thu, tính tiền chậm nộp 0,03%/ngày và có thể bị phạt.","Các hình thức thu nhập thường gặp: phí dịch vụ, bản quyền, lãi vay, phí bảo hiểm, cước vận chuyển quốc tế, phí quảng cáo, phí sử dụng phần mềm.","Chi phí trả cho nhà thầu nước ngoài muốn được trừ khi tính thuế TNDN của bên Việt Nam cần có hợp đồng, chứng từ thanh toán qua ngân hàng và hồ sơ thực hiện nghĩa vụ thuế nhà thầu."],"case":"Công ty TNHH Thương mại Điện tử Minh Quang trả 1,5 tỷ đồng phí phần mềm quản lý kho cho một công ty Singapore trong 2 năm mà không khấu trừ thuế nhà thầu. Khi kiểm tra, doanh nghiệp bị truy thu thuế và tiền chậm nộp; sau đó kế toán lập quy trình rà soát mọi khoản thanh toán ra nước ngoài trước khi chuyển tiền.","trend":"Các quốc gia, trong đó có Việt Nam, đang tăng cường đánh thuế kinh tế số xuyên biên giới. Kế toán nên lập danh mục toàn bộ nhà cung cấp nước ngoài và theo dõi tình trạng đăng ký thuế của họ tại Việt Nam.","practice":"Liệt kê toàn bộ khoản thanh toán ra nước ngoài của doanh nghiệp trong 12 tháng qua, phân loại theo bản chất thu nhập và đánh dấu khoản đã hoặc chưa thực hiện thuế nhà thầu.","takeaway":"Tiền chuyển đi nước ngoài, nghĩa vụ thuế ở lại Việt Nam."}},{"id":"KH038","code":"kh038","f":"THUE","fn":"Thuế","t":"Giao dịch liên kết, chuyển giá và thuế tối thiểu toàn cầu","lv":5,"ln":"Chuyên gia","h":32,"p":499000,"d":"Khoá học chuyên gia trang bị năng lực quản trị toàn diện giao dịch liên kết: xác định quan hệ liên kết, kê khai, lập hồ sơ xác định giá, lựa chọn phương pháp, giới hạn lãi vay, và đánh giá tác động của thuế tối thiểu toàn cầu theo NQ 107/2023/QH15. Học viên phân tích các mô hình tập đoàn thật như gia công, phân phối, dịch vụ nội bộ tập đoàn, bản quyền, với bộ công cụ phân tích chức năng, khung hồ sơ và mô hình tính thuế bổ sung. Kết quả là học viên tự thiết kế được chính sách giá chuyển nhượng có thể bảo vệ trước cơ quan thuế và đánh giá được vị thế của doanh nghiệp trong bối cảnh thuế quốc tế mới.","a":"Giám đốc tài chính, kế toán trưởng, trưởng phòng thuế và chuyên gia tư vấn tại doanh nghiệp FDI, tập đoàn trong nước có công ty thành viên hoặc đầu tư ra nước ngoài.","o":["Xác định chính xác các bên liên kết, giao dịch liên kết và nghĩa vụ kê khai, miễn trừ hồ sơ của doanh nghiệp.","Thực hiện được phân tích chức năng, tài sản, rủi ro và lựa chọn phương pháp xác định giá có lập luận vững chắc.","Tính toán được giới hạn chi phí lãi vay và đánh giá khả năng được trừ của phí dịch vụ nội bộ, bản quyền.","Ước tính được thuế suất thực tế và thuế bổ sung theo quy tắc thuế tối thiểu toàn cầu cho một thực thể tại Việt Nam.","Xây dựng được chính sách giá chuyển nhượng, kế hoạch hồ sơ và chiến lược giải trình khi thanh tra."],"k":"Với thuế tối thiểu toàn cầu 15%, chuyển giá không còn là bài toán tối ưu thuế mà là bài toán chứng minh bản chất kinh tế.","w":["Thuế tối thiểu toàn cầu theo NQ 107/2023/QH15 áp dụng từ năm 2024 cho tập đoàn có doanh thu hợp nhất từ 750 triệu EUR, khiến nhiều ưu đãi và cấu trúc chuyển giá cũ mất tác dụng và phát sinh nghĩa vụ thuế bổ sung.","Giao dịch liên kết tiếp tục là trọng tâm thanh tra, kiểm tra thuế, với cơ sở dữ liệu so sánh và trao đổi thông tin quốc tế ngày càng đầy đủ.","Luật TNDN 67/2025/QH15 và xu hướng minh bạch thông tin chủ sở hữu hưởng lợi theo Luật Doanh nghiệp sửa đổi 2025 làm tăng yêu cầu chứng minh bản chất giao dịch nội bộ tập đoàn."],"dl":["Bộ khung hồ sơ xác định giá giao dịch liên kết (hồ sơ quốc gia) có hướng dẫn từng phần.","Ma trận phân tích chức năng, tài sản, rủi ro và cây quyết định lựa chọn phương pháp xác định giá.","Mô hình Excel tính giới hạn lãi vay theo EBITDA và ước tính thuế suất thực tế, thuế bổ sung tối thiểu.","Bộ câu lệnh AI (prompt) hỗ trợ soạn phân tích ngành, rà soát hợp đồng nội bộ và chuẩn bị câu hỏi giải trình."],"ls":["Chuyển giá trong kỷ nguyên thuế quốc tế mới","Xác định bên liên kết và bản đồ giao dịch liên kết","Nghĩa vụ kê khai, miễn trừ và bộ ba hồ sơ xác định giá","Phân tích chức năng và lựa chọn phương pháp xác định giá","Lãi vay liên kết, phí dịch vụ nội bộ và bản quyền","Thuế tối thiểu toàn cầu: cơ chế và tác động tại Việt Nam","Thanh tra chuyển giá và chiến lược giải trình","Thiết kế chính sách giá chuyển nhượng bền vững với dữ liệu và AI"],"l1":{"t":"Chuyển giá trong kỷ nguyên thuế quốc tế mới","sum":"Bài nền tảng về nguyên tắc giá giao dịch độc lập, khung pháp lý Việt Nam và bối cảnh quốc tế. Học viên hiểu vì sao bản chất kinh tế là trung tâm của mọi cuộc thanh tra chuyển giá hiện nay.","points":["Nguyên tắc giá giao dịch độc lập: điều kiện giao dịch giữa các bên liên kết phải tương đương với giao dịch giữa các bên độc lập trong hoàn cảnh tương đồng.","Khung pháp lý gồm Luật Quản lý thuế 38/2019/QH14, NĐ 126/2020 và nghị định riêng về quản lý thuế đối với doanh nghiệp có giao dịch liên kết (NĐ 132/2020) cùng văn bản sửa đổi, hướng dẫn hiện hành.","Nguyên tắc bản chất quyết định hình thức: cơ quan thuế có thể xác định lại giao dịch không có bản chất kinh tế hoặc không phù hợp với hành vi của bên độc lập.","Dấu hiệu rủi ro: lỗ kéo dài nhưng vẫn mở rộng, chi trả lớn phí quản lý, bản quyền cho công ty mẹ, mua bán chủ yếu với bên liên kết, biên lợi nhuận thấp hơn ngành.","Bối cảnh quốc tế: dự án chống xói mòn cơ sở thuế và chuyển lợi nhuận, trao đổi thông tin tự động và thuế tối thiểu toàn cầu khiến các cấu trúc chỉ dựa trên chênh lệch thuế suất ngày càng khó tồn tại."],"case":"Công ty TNHH May mặc Thiên Phúc vốn Hàn Quốc lỗ 5 năm liên tục trong khi tăng gấp đôi công suất. Phân tích cho thấy doanh nghiệp chỉ thực hiện gia công nhưng chịu rủi ro thị trường; tư vấn đề xuất chuyển sang mô hình gia công hưởng lợi nhuận ổn định trên chi phí, phù hợp chức năng thực tế.","trend":"Giai đoạn 2026–2030, quản lý chuyển giá dự kiến dựa nhiều hơn vào dữ liệu đa quốc gia và phân tích tự động. Chuyên gia cần kết hợp kiến thức kinh tế, pháp lý và dữ liệu để bảo vệ chính sách giá.","practice":"Phân tích một mô hình FDI giả định của khoá, liệt kê 5 dấu hiệu rủi ro chuyển giá và xếp hạng mức độ rủi ro cho từng dấu hiệu.","takeaway":"Lợi nhuận phải nằm ở nơi tạo ra giá trị."}},{"id":"KH039","code":"kh039","f":"THUE","fn":"Thuế","t":"Ưu đãi thuế TNDN và cách áp dụng","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học giúp doanh nghiệp xác định đúng ưu đãi thuế TNDN được hưởng theo lĩnh vực, địa bàn, quy mô và dự án đầu tư mới, áp dụng đúng thời điểm, tách thu nhập và kê khai có hồ sơ chứng minh vững chắc theo Luật TNDN 67/2025/QH15 và văn bản hướng dẫn hiện hành. Học viên làm việc với các tình huống thật về dự án mở rộng, doanh nghiệp công nghệ, doanh nghiệp nhỏ, kèm cây quyết định ưu đãi và file tính phân bổ dùng ngay. Kết quả là học viên tự đánh giá, áp dụng và bảo vệ được ưu đãi thuế cho doanh nghiệp, đồng thời nhận diện được tác động của thuế tối thiểu toàn cầu.","a":"Kế toán trưởng, giám đốc tài chính, chủ doanh nghiệp và chuyên viên tư vấn thuế tại doanh nghiệp có dự án đầu tư, hoạt động trong lĩnh vực hoặc địa bàn được khuyến khích.","o":["Xác định được doanh nghiệp, dự án có đủ điều kiện hưởng loại ưu đãi nào: thuế suất ưu đãi, miễn thuế, giảm thuế.","Xác định đúng thời điểm bắt đầu tính thời gian ưu đãi và thời gian miễn, giảm còn lại.","Tách riêng và phân bổ được thu nhập, chi phí giữa hoạt động được ưu đãi và không được ưu đãi theo phương pháp có căn cứ.","Kê khai đúng phụ lục ưu đãi trên tờ khai quyết toán TNDN và lập được bộ hồ sơ chứng minh điều kiện.","Nhận diện được ít nhất 8 rủi ro làm mất ưu đãi và có kế hoạch phòng ngừa cụ thể."],"k":"Nhiều doanh nghiệp đủ điều kiện ưu đãi thuế TNDN nhưng không dám áp dụng, số khác áp dụng sai rồi bị truy thu cả gốc lẫn tiền chậm nộp.","w":["Luật TNDN 67/2025/QH15 áp dụng từ kỳ tính thuế 2025 sắp xếp lại hệ thống ưu đãi, kể cả thuế suất 15% và 17% cho doanh nghiệp có doanh thu đến 3 tỷ và đến 50 tỷ đồng, đòi hỏi doanh nghiệp rà soát lại quyền hưởng ưu đãi.","Thuế tối thiểu toàn cầu theo NQ 107/2023/QH15 khiến ưu đãi của tập đoàn lớn có thể bị vô hiệu bởi thuế bổ sung, cần đánh giá lại hiệu quả ưu đãi thực tế.","Thanh tra, kiểm tra ưu đãi thuế ngày càng dựa vào dữ liệu đăng ký đầu tư, hóa đơn và báo cáo tài chính, sai sót về điều kiện hoặc tách thu nhập dễ bị phát hiện."],"dl":["Cây quyết định xác định ưu đãi thuế TNDN theo lĩnh vực, địa bàn, quy mô dự án và loại hình doanh nghiệp.","File Excel tính thời gian ưu đãi còn lại và phân bổ thu nhập, chi phí cho hoạt động được ưu đãi.","Checklist hồ sơ chứng minh điều kiện ưu đãi theo từng loại ưu đãi phổ biến.","Bộ câu lệnh AI (prompt) rà soát giấy chứng nhận đầu tư, ngành nghề và đối chiếu điều kiện ưu đãi."],"ls":["Bản đồ ưu đãi thuế TNDN từ năm 2025","Ưu đãi theo lĩnh vực đầu tư: công nghệ, đổi mới sáng tạo, sản xuất","Ưu đãi theo địa bàn và dự án đầu tư mới, dự án mở rộng","Thời điểm bắt đầu ưu đãi và tính thời gian miễn, giảm","Doanh nghiệp nhỏ, doanh nghiệp mới và hộ kinh doanh chuyển đổi","Tách thu nhập được ưu đãi và phân bổ chi phí chung","Kê khai ưu đãi, hồ sơ chứng minh và tác động thuế tối thiểu toàn cầu","Rủi ro mất ưu đãi và bài học từ thanh tra"],"l1":{"t":"Bản đồ ưu đãi thuế TNDN từ năm 2025","sum":"Bài nền tảng giới thiệu cấu trúc hệ thống ưu đãi thuế TNDN và nguyên tắc áp dụng. Học viên hiểu sự khác biệt giữa thuế suất ưu đãi, miễn thuế, giảm thuế và các mức thuế suất theo quy mô doanh thu.","points":["Ưu đãi thuế TNDN gồm hai nhóm chính: thuế suất ưu đãi có thời hạn hoặc trong suốt thời gian hoạt động, và miễn thuế, giảm thuế có thời hạn; mức cụ thể theo Luật TNDN 67/2025/QH15 và văn bản hướng dẫn hiện hành.","Căn cứ hưởng ưu đãi chủ yếu là lĩnh vực đầu tư được khuyến khích, địa bàn có điều kiện kinh tế xã hội khó khăn hoặc khu kinh tế, khu công nghệ cao, và quy mô dự án đầu tư mới.","Thuế suất 15% cho doanh nghiệp doanh thu năm không quá 3 tỷ và 17% cho doanh thu từ trên 3 đến 50 tỷ là mức thuế suất theo quy mô, áp dụng từ kỳ tính thuế 2025, khác với ưu đãi theo dự án.","Ưu đãi chỉ áp dụng cho thu nhập từ hoạt động đáp ứng điều kiện; thu nhập khác như thanh lý tài sản, chuyển nhượng vốn, chênh lệch tỷ giá nhiều trường hợp không được ưu đãi theo quy định hiện hành.","Doanh nghiệp tự xác định điều kiện ưu đãi, tự kê khai và chịu trách nhiệm; cơ quan thuế kiểm tra sau, vì vậy hồ sơ chứng minh là yếu tố sống còn."],"case":"Công ty TNHH Công nghệ Phần mềm Lạc Hồng có doanh thu 2,5 tỷ đồng năm 2025 và đồng thời hoạt động trong lĩnh vực sản xuất phần mềm. Kế toán lập bảng so sánh giữa áp dụng thuế suất theo quy mô và ưu đãi theo lĩnh vực, chọn phương án có lợi theo quy định và lưu đủ hồ sơ chứng minh.","trend":"Chính sách ưu đãi giai đoạn 2026–2030 được dự kiến tập trung vào công nghệ cao, đổi mới sáng tạo, chuyển đổi số và chuyển đổi xanh. Doanh nghiệp nên gắn chiến lược đầu tư với định hướng ưu đãi.","practice":"Dựa trên giấy chứng nhận đăng ký doanh nghiệp, đầu tư của doanh nghiệp bạn, liệt kê các hoạt động có thể thuộc diện ưu đãi và loại ưu đãi tương ứng cần kiểm tra.","takeaway":"Ưu đãi là quyền lợi, nhưng phải tự chứng minh mới giữ được."}},{"id":"KH040","code":"kh040","f":"THUE","fn":"Thuế","t":"Thuế xuất nhập khẩu và thủ tục hải quan cơ bản","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp kế toán và nhân viên xuất nhập khẩu hiểu đúng cách tính thuế, đọc tờ khai và phối hợp thủ tục hải quan điện tử mà không phụ thuộc hoàn toàn vào đại lý. Mỗi bài đi từ quy định hiện hành đến tình huống thật tại doanh nghiệp Việt Nam, kèm mẫu Excel tính thuế, checklist bộ chứng từ và cách định khoản. Kết thúc khoá, học viên tự tính được thuế nhập khẩu, GTGT hàng nhập khẩu, hạch toán đúng và chủ động phòng ngừa rủi ro khi bị kiểm tra.","a":"Kế toán, nhân viên chứng từ xuất nhập khẩu và chủ doanh nghiệp vừa và nhỏ có hoạt động mua bán hàng hóa với nước ngoài.","o":["Tự tính được thuế nhập khẩu, thuế tiêu thụ đặc biệt (nếu có) và thuế GTGT khâu nhập khẩu cho một lô hàng từ bộ chứng từ thương mại.","Đọc và đối chiếu được các chỉ tiêu chính trên tờ khai hải quan với hợp đồng, hóa đơn thương mại, vận đơn và sổ kế toán.","Lập được quy trình 7 bước tra cứu mã HS và kiểm tra điều kiện hưởng thuế ưu đãi đặc biệt theo C/O hoặc chứng từ tự chứng nhận xuất xứ.","Hạch toán đúng hàng nhập khẩu, thuế phải nộp, chênh lệch tỷ giá và khấu trừ thuế GTGT khâu nhập khẩu.","Tự kiểm tra được hồ sơ của doanh nghiệp theo checklist kiểm tra sau thông quan và xác định trước các điểm rủi ro."],"k":"Một mã HS sai hay một C/O lỗi có thể khiến lô hàng chịu thêm hàng trăm triệu thuế và bị kiểm tra sau thông quan.","w":["Hải quan Việt Nam đang đẩy mạnh hải quan số và quản lý rủi ro dựa trên dữ liệu, nên sai lệch giữa tờ khai, hóa đơn và sổ sách được phát hiện nhanh hơn trước.","Các hiệp định thương mại tự do như EVFTA, CPTPP, RCEP mở ra mức thuế ưu đãi đặc biệt, nhưng chỉ doanh nghiệp làm đúng quy tắc xuất xứ mới được hưởng.","Luật Thuế GTGT 48/2024/QH15 và quy định thanh toán không dùng tiền mặt từ 5 triệu đồng theo NĐ 181/2025 ảnh hưởng trực tiếp đến việc khấu trừ thuế GTGT hàng nhập khẩu và chi phí liên quan."],"dl":["Bộ mẫu Excel tính thuế nhập khẩu, GTGT hàng nhập khẩu và phân bổ chi phí vào giá vốn theo từng mặt hàng.","Checklist bộ chứng từ xuất khẩu và nhập khẩu, kèm bảng đối chiếu tờ khai với hóa đơn và sổ kế toán.","Quy trình SOP phối hợp giữa phòng mua hàng, kế toán và đại lý hải quan cho một lô hàng nhập khẩu.","Bộ câu lệnh AI (prompt) hỗ trợ mô tả hàng hóa, gợi ý nhóm mã HS để tra cứu và rà soát chứng từ trước khi khai báo."],"ls":["Bức tranh thuế xuất nhập khẩu: ai nộp, nộp gì, khi nào","Thủ tục hải quan điện tử: từ khai báo đến thông quan","Mã HS: tra cứu đúng để nộp thuế đúng","Trị giá hải quan và xuất xứ: hai chìa khóa của số thuế","Tính thuế thực chiến: nhập khẩu, tiêu thụ đặc biệt, bảo vệ môi trường và GTGT","Hạch toán hàng nhập khẩu, tỷ giá và khấu trừ thuế GTGT","Miễn, giảm, hoàn thuế và các loại hình đặc thù","Kiểm tra sau thông quan và ứng dụng dữ liệu để tự kiểm soát"],"l1":{"t":"Bức tranh thuế xuất nhập khẩu: ai nộp, nộp gì, khi nào","sum":"Bài mở đầu giúp học viên nắm các loại thuế phát sinh khi hàng hóa qua biên giới và vai trò của cơ quan hải quan. Học viên hiểu đối tượng chịu thuế, người nộp thuế và thời điểm tính thuế.","points":["Hàng hóa xuất nhập khẩu có thể chịu nhiều sắc thuế cùng lúc: thuế xuất khẩu, thuế nhập khẩu, thuế tiêu thụ đặc biệt, thuế bảo vệ môi trường và thuế GTGT khâu nhập khẩu.","Cơ quan hải quan là bên thu các khoản thuế khâu nhập khẩu, còn thuế GTGT đầu vào sau đó được doanh nghiệp kê khai khấu trừ với cơ quan thuế nội địa.","Thời điểm tính thuế gắn với ngày đăng ký tờ khai hải quan, nên thuế suất và tỷ giá áp dụng là của thời điểm đăng ký tờ khai.","Thuế nhập khẩu có ba nhóm thuế suất chính: thuế suất thông thường, thuế suất ưu đãi (MFN) và thuế suất ưu đãi đặc biệt theo hiệp định thương mại tự do.","Khung pháp lý gồm Luật Hải quan, Luật Thuế xuất khẩu, thuế nhập khẩu, Luật Quản lý thuế 38/2019/QH14 và các văn bản hướng dẫn hiện hành; doanh nghiệp cần tra văn bản mới nhất trước mỗi lô hàng lớn."],"case":"Công ty TNHH Minh An nhập lô máy nén khí trị giá tính thuế 800 triệu đồng, thuế suất nhập khẩu ưu đãi 5%. Kế toán chỉ dự trù thuế nhập khẩu 40 triệu đồng mà quên thuế GTGT khâu nhập khẩu 10% trên (800 + 40) triệu, tức 84 triệu đồng, khiến dòng tiền thiếu hụt khi thông quan. Cách đúng là lập bảng dự toán đủ các sắc thuế ngay từ khi ký hợp đồng mua.","trend":"Giai đoạn 2026–2030, hải quan dự kiến kết nối dữ liệu sâu hơn với cơ quan thuế và ngân hàng. Học viên nên quen với việc mọi số liệu trên tờ khai sẽ được đối chiếu tự động với hóa đơn và tờ khai thuế nội địa.","practice":"Chọn một lô hàng nhập khẩu gần nhất của doanh nghiệp, liệt kê đủ các sắc thuế phát sinh và lập bảng dự toán tiền thuế phải chuẩn bị trước ngày thông quan.","takeaway":"Dự toán thuế nhập khẩu mà quên thuế GTGT khâu nhập khẩu là thiếu gần một nửa số tiền cần chuẩn bị."}},{"id":"KH041","code":"kh041","f":"THUE","fn":"Thuế","t":"Thuế thương mại điện tử và kinh doanh trên nền tảng số","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp người bán hàng online, hộ kinh doanh và kế toán hiểu rõ nghĩa vụ thuế khi kinh doanh trên sàn thương mại điện tử, mạng xã hội và nền tảng số trong bối cảnh quy định mới từ 2025–2026. Nội dung đi từ cách xác định doanh thu, cơ chế sàn khấu trừ nộp thay, đến kê khai khi tự bán qua website, mạng xã hội và hạch toán cho doanh nghiệp, kèm tình huống thật và mẫu đối soát dùng ngay. Học xong, học viên tự xác định được mình nộp thuế theo cách nào, đối soát được dữ liệu sàn với sổ sách và tránh được các rủi ro truy thu phổ biến.","a":"Chủ shop online, hộ và cá nhân kinh doanh trên nền tảng số, nhà sáng tạo nội dung, KOC và kế toán doanh nghiệp có kênh bán hàng thương mại điện tử.","o":["Xác định được mình thuộc nhóm nào: cá nhân bán trên sàn được khấu trừ nộp thay, hộ kinh doanh tự kê khai hay doanh nghiệp, và nghĩa vụ thuế tương ứng.","Tính được số thuế GTGT và TNCN theo tỷ lệ trên doanh thu cho một tháng bán hàng online từ báo cáo của sàn.","Lập được bảng đối soát doanh thu giữa báo cáo sàn, sao kê ngân hàng và đơn hàng tự bán qua mạng xã hội.","Hạch toán đúng doanh thu, phí sàn, phí vận chuyển, khuyến mãi và hoàn hàng cho doanh nghiệp bán hàng đa kênh.","Tự kiểm tra được hồ sơ thuế của shop theo checklist 10 điểm rủi ro trước khi cơ quan thuế đối chiếu dữ liệu."],"k":"Bán hàng trên Shopee, TikTok Shop hay livestream năm 2026: sàn đã khấu trừ thuế, nhưng bạn đã nộp đủ và đúng chưa?","w":["Từ 01/07/2025, sàn thương mại điện tử có chức năng thanh toán phải khấu trừ, nộp thay thuế cho hộ, cá nhân kinh doanh trên sàn theo NĐ 117/2025, nên dữ liệu doanh thu của người bán đã nằm trong tay cơ quan thuế.","Từ 01/01/2026, thuế khoán hộ kinh doanh và lệ phí môn bài được bỏ theo NQ 198/2025/QH15, hộ kinh doanh chuyển sang tự kê khai, đòi hỏi người bán online phải biết ghi chép và kê khai.","Cơ quan thuế ứng dụng dữ liệu lớn, đối chiếu dữ liệu từ sàn, ngân hàng và nền tảng mạng xã hội, nên việc bán hàng không kê khai ngày càng dễ bị phát hiện."],"dl":["Mẫu Excel đối soát doanh thu đa kênh: sàn, website, mạng xã hội, kèm cột thuế đã bị khấu trừ và thuế còn phải kê khai.","Checklist 10 điểm rủi ro thuế cho người bán hàng online và hộ kinh doanh trên nền tảng số.","Quy trình SOP lưu chứng từ hàng tháng: tải báo cáo sàn, chứng từ khấu trừ thuế, sao kê ngân hàng và hóa đơn đầu vào.","Bộ câu lệnh AI (prompt) để tổng hợp báo cáo sàn, phân loại khoản thu – phí và soạn giải trình khi cơ quan thuế đề nghị."],"ls":["Kinh doanh trên nền tảng số: ai phải nộp thuế và nộp theo cách nào","Doanh thu tính thuế: đọc đúng báo cáo của sàn","Cơ chế sàn khấu trừ, nộp thay thuế theo NĐ 117/2025","Tự bán qua mạng xã hội, website và livestream: tự kê khai đúng","KOL, KOC, affiliate và nhà sáng tạo nội dung: thuế của thu nhập số","Doanh nghiệp bán hàng đa kênh: hóa đơn và hạch toán","Đối soát dữ liệu đa kênh bằng Excel và AI","Phòng ngừa rủi ro và lộ trình phát triển kinh doanh số bền vững"],"l1":{"t":"Kinh doanh trên nền tảng số: ai phải nộp thuế và nộp theo cách nào","sum":"Bài mở đầu phân loại các mô hình bán hàng online và tư cách nộp thuế tương ứng. Học viên xác định đúng vị trí của mình trước khi đi vào cách tính.","points":["Thu nhập từ bán hàng, cung cấp dịch vụ qua sàn, website, mạng xã hội, livestream hay tiếp thị liên kết đều là thu nhập chịu thuế theo quy định hiện hành, không phân biệt kênh bán.","Có ba nhóm chính: cá nhân, hộ kinh doanh bán trên sàn có chức năng thanh toán; hộ, cá nhân tự bán qua mạng xã hội hoặc website; và doanh nghiệp bán hàng đa kênh.","Với nhóm bán trên sàn có chức năng thanh toán, sàn khấu trừ, nộp thay thuế theo NĐ 117/2025 từ 01/07/2025.","Hộ kinh doanh từ 01/01/2026 không còn nộp thuế khoán và lệ phí môn bài theo NQ 198/2025/QH15, mà chuyển sang tự kê khai theo doanh thu thực tế.","Doanh nghiệp bán hàng online thực hiện nghĩa vụ như mọi doanh nghiệp: xuất hóa đơn điện tử, kê khai GTGT, tạm nộp và quyết toán TNDN."],"case":"Chị Lan bán mỹ phẩm qua cả Shopee và Facebook, tổng doanh thu tháng 150 triệu đồng, trong đó 90 triệu qua sàn. Chị nghĩ sàn đã khấu trừ hết thuế nên không kê khai phần 60 triệu bán qua Facebook. Cách đúng là phần doanh thu qua sàn đã được khấu trừ, còn phần tự bán phải tự kê khai, nộp thuế theo quy định cho hộ, cá nhân kinh doanh.","trend":"Giai đoạn 2026–2030, cơ quan thuế dự kiến mở rộng kết nối dữ liệu với sàn, ví điện tử và ngân hàng. Người bán nên chủ động gom toàn bộ doanh thu đa kênh về một bảng theo dõi duy nhất.","practice":"Liệt kê tất cả kênh bán hàng của bạn trong 3 tháng gần nhất, ghi doanh thu từng kênh và đánh dấu kênh nào đã được sàn khấu trừ thuế, kênh nào phải tự kê khai.","takeaway":"Sàn chỉ nộp thay phần bán trên sàn, phần còn lại vẫn là trách nhiệm của bạn."}},{"id":"KH042","code":"kh042","f":"THUE","fn":"Thuế","t":"Khai thuế điện tử: eTax, eTax Mobile và chữ ký số từ xa","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá nhập môn giúp người mới làm kế toán, chủ hộ kinh doanh và cá nhân tự thao tác khai, nộp thuế điện tử trên cổng thuế điện tử eTax, ứng dụng eTax Mobile và ký hồ sơ bằng chữ ký số, kể cả chữ ký số từ xa. Học viên được hướng dẫn từng bước theo tình huống thật, kèm checklist thao tác và lịch hạn nộp dùng ngay. Kết thúc khoá, học viên tự đăng ký, nộp tờ khai, nộp tiền thuế, tra cứu nghĩa vụ và xử lý được các lỗi thường gặp mà không phải nhờ dịch vụ.","a":"Người mới làm kế toán, chủ hộ kinh doanh, cá nhân kinh doanh online và người lao động cần tự khai, nộp và quyết toán thuế điện tử.","o":["Tự đăng nhập, cập nhật thông tin và tra cứu được nghĩa vụ thuế trên cổng thuế điện tử và ứng dụng eTax Mobile.","Nộp được một tờ khai thuế điện tử đúng mẫu, đúng kỳ và kiểm tra được thông báo chấp nhận của cơ quan thuế.","Nộp tiền thuế điện tử qua ngân hàng liên kết hoặc ứng dụng, lưu được giấy nộp tiền và đối chiếu số đã nộp.","Đăng ký, sử dụng được chữ ký số từ xa để ký hồ sơ thuế và hiểu cách bảo vệ tài khoản, chữ ký.","Lập được lịch hạn nộp thuế cá nhân hoặc doanh nghiệp trong 12 tháng và tự xử lý được 10 lỗi thao tác thường gặp."],"k":"Năm 2026, mọi tờ khai, mọi khoản nộp thuế đều đi qua môi trường số: bạn đã tự tin bấm nộp mà không sợ sai?","w":["Từ 01/01/2026, hộ kinh doanh chuyển từ thuế khoán sang tự kê khai theo NQ 198/2025/QH15, nên hàng triệu hộ cần biết tự khai, nộp thuế điện tử.","Định danh điện tử và số định danh cá nhân đang được dùng làm mã số thuế cá nhân theo quy định hiện hành, giúp đăng nhập, tra cứu và nộp thuế trên điện thoại nhanh hơn.","Chữ ký số từ xa trên điện thoại cho phép ký tờ khai, hóa đơn mọi lúc mọi nơi, thay dần USB token truyền thống."],"dl":["Checklist từng bước nộp tờ khai và nộp tiền thuế trên cổng thuế điện tử và eTax Mobile, có ảnh minh họa thao tác.","Mẫu lịch hạn nộp thuế 12 tháng cho doanh nghiệp, hộ kinh doanh và cá nhân, dạng Excel có nhắc việc.","Bảng tra 10 lỗi thường gặp khi khai, nộp thuế điện tử và cách khắc phục.","Bộ câu lệnh AI (prompt) để đọc thông báo của cơ quan thuế, tóm tắt yêu cầu và soạn email hỏi đáp gửi cơ quan thuế."],"ls":["Thuế điện tử là gì và vì sao ai cũng cần biết từ 2026","Đăng nhập, kích hoạt và bảo mật tài khoản thuế điện tử","Chữ ký số và chữ ký số từ xa: chọn, đăng ký và sử dụng an toàn","Nộp tờ khai điện tử từng bước và kiểm tra kết quả","Nộp tiền thuế điện tử và tra cứu nghĩa vụ","eTax Mobile cho cá nhân và hộ kinh doanh","Xử lý lỗi thường gặp và khai bổ sung","Tự động hóa lịch thuế và dùng AI hỗ trợ tuân thủ"],"l1":{"t":"Thuế điện tử là gì và vì sao ai cũng cần biết từ 2026","sum":"Bài mở đầu giới thiệu hệ sinh thái thuế điện tử: cổng thuế điện tử, ứng dụng eTax Mobile, hóa đơn điện tử, chữ ký số và ngân hàng liên kết. Học viên hiểu bức tranh tổng thể trước khi thao tác.","points":["Thuế điện tử là việc đăng ký, khai, nộp, tra cứu và nhận thông báo thuế qua môi trường điện tử theo Luật Quản lý thuế 38/2019/QH14 và các văn bản hướng dẫn hiện hành.","Doanh nghiệp thường dùng cổng thuế điện tử trên máy tính; cá nhân và hộ kinh doanh dùng thêm ứng dụng eTax Mobile trên điện thoại.","Hồ sơ điện tử có giá trị pháp lý như hồ sơ giấy khi được ký bằng chữ ký số hợp lệ hoặc xác thực theo phương thức cơ quan thuế chấp nhận.","Mọi thông báo của cơ quan thuế như chấp nhận hồ sơ, đề nghị giải trình, nhắc nợ đều được gửi qua tài khoản điện tử và email đăng ký, nên phải kiểm tra thường xuyên.","Từ 2026, hộ kinh doanh bỏ thuế khoán và tự kê khai theo NQ 198/2025/QH15, nên kỹ năng thuế điện tử trở thành kỹ năng bắt buộc."],"case":"Chị Hoa mở hộ kinh doanh tạp hóa và trước đây chỉ nộp thuế khoán theo thông báo. Từ 2026 chị phải tự khai theo doanh thu thực tế nhưng chưa từng đăng nhập cổng thuế. Sau khi kích hoạt tài khoản, cài eTax Mobile và đăng ký email nhận thông báo, chị chủ động khai đúng kỳ đầu tiên.","trend":"Quản lý thuế giai đoạn 2026–2030 hướng tới mô hình thuế số, nhiều thủ tục dự kiến được tự động điền sẵn từ dữ liệu hóa đơn và ngân hàng. Người học nên làm chủ tài khoản thuế điện tử của mình ngay từ bây giờ.","practice":"Vẽ sơ đồ hệ sinh thái thuế điện tử của bạn gồm tài khoản thuế, email nhận thông báo, ngân hàng liên kết, chữ ký số và người phụ trách, ghi rõ ai giữ thông tin nào.","takeaway":"Tài khoản thuế điện tử là hồ sơ thuế của bạn, hãy tự nắm giữ nó."}},{"id":"KH043","code":"kh043","f":"THUE","fn":"Thuế","t":"Xử phạt vi phạm hành chính về thuế và hóa đơn","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp kế toán, chủ doanh nghiệp nhận diện chính xác các hành vi vi phạm về thuế và hóa đơn, hiểu cách xác định mức phạt và quyền của doanh nghiệp theo NĐ 125/2020 sửa bởi NĐ 310/2025. Mỗi bài phân tích tình huống thật tại doanh nghiệp Việt Nam, kèm cách tính tiền phạt, tiền chậm nộp và mẫu văn bản giải trình dùng ngay. Học xong, học viên tự đánh giá được rủi ro, xử lý sai sót đúng cách để giảm thiệt hại và xây dựng được hệ thống kiểm soát phòng ngừa.","a":"Kế toán trưởng, kế toán thuế, chủ doanh nghiệp và người làm dịch vụ kế toán – thuế cần xử lý và phòng ngừa vi phạm về thuế, hóa đơn.","o":["Phân loại được hành vi vi phạm về thủ tục thuế, khai sai dẫn đến thiếu thuế, trốn thuế và vi phạm về hóa đơn trong từng tình huống cụ thể.","Tính được số thuế truy thu, tiền phạt 20% khai thiếu và tiền chậm nộp 0,03%/ngày cho một hồ sơ sai sót.","Xác định được thời hiệu xử phạt và nhận diện tình tiết giảm nhẹ, tăng nặng để kiểm tra tính đúng của biên bản, quyết định xử phạt.","Soạn được văn bản giải trình, đề nghị xem xét tình tiết giảm nhẹ và hiểu quy trình khiếu nại khi không đồng ý quyết định.","Xây dựng được bộ kiểm soát nội bộ về thuế và hóa đơn gồm checklist tháng, quý, năm để giảm rủi ro bị xử phạt."],"k":"Từ 16/01/2026, quy định xử phạt thuế và hóa đơn đã thay đổi, và cơ quan thuế phát hiện sai sót nhanh hơn bao giờ hết.","w":["NĐ 310/2025 sửa đổi NĐ 125/2020 về xử phạt vi phạm hành chính thuế, hóa đơn có hiệu lực từ 16/01/2026, nhiều quy định và cách áp dụng cần được cập nhật lại.","Hóa đơn điện tử theo NĐ 123/2020 sửa bởi NĐ 70/2025 và dữ liệu hóa đơn tập trung giúp cơ quan thuế đối chiếu tự động, sai sót bị phát hiện chỉ sau vài kỳ khai.","Quản lý rủi ro bằng dữ liệu lớn và AI đang được cơ quan thuế ứng dụng, nên doanh nghiệp cần năng lực tự kiểm tra tương đương để chủ động phòng ngừa."],"dl":["Bảng tra nhóm hành vi vi phạm về thuế và hóa đơn, kèm căn cứ pháp lý và cách xử lý khuyến nghị.","Mẫu Excel tính số thuế truy thu, tiền phạt khai thiếu và tiền chậm nộp theo ngày.","Bộ mẫu văn bản: giải trình với cơ quan thuế, đề nghị áp dụng tình tiết giảm nhẹ và đơn khiếu nại quyết định xử phạt.","Bộ câu lệnh AI (prompt) để rà soát chênh lệch hóa đơn – tờ khai, phân tích biên bản kiểm tra và soạn dàn ý giải trình."],"ls":["Khung pháp lý xử phạt thuế và hóa đơn từ 2026","Vi phạm thủ tục thuế: đăng ký, khai, nộp hồ sơ","Khai sai dẫn đến thiếu thuế và trốn thuế: ranh giới phải phân biệt rõ","Vi phạm về hóa đơn điện tử: lỗi nhỏ, hậu quả lớn","Xác định mức phạt: tình tiết giảm nhẹ, tăng nặng và nguyên tắc áp dụng","Thời hiệu, quy trình xử phạt và quyền của doanh nghiệp","Tự rà soát rủi ro bằng dữ liệu và AI trước khi cơ quan thuế phát hiện","Xây dựng hệ thống kiểm soát nội bộ về thuế và hóa đơn"],"l1":{"t":"Khung pháp lý xử phạt thuế và hóa đơn từ 2026","sum":"Bài mở đầu hệ thống hóa các văn bản điều chỉnh xử phạt vi phạm về thuế và hóa đơn đang có hiệu lực. Học viên hiểu nguyên tắc xử phạt và đối tượng bị xử phạt.","points":["Nền tảng gồm Luật Quản lý thuế 38/2019/QH14, Luật Xử lý vi phạm hành chính, NĐ 125/2020 về xử phạt thuế, hóa đơn được sửa đổi bởi NĐ 310/2025 có hiệu lực từ 16/01/2026.","Quy định về hóa đơn điện tử là NĐ 123/2020 sửa bởi NĐ 70/2025 từ 01/06/2025; vi phạm các quy định này bị xử phạt theo nghị định xử phạt thuế, hóa đơn.","Mức phạt tiền quy định trong nghị định xử phạt chủ yếu áp dụng cho tổ chức; cá nhân vi phạm cùng hành vi thường chịu mức bằng một nửa theo quy định hiện hành.","Ngoài tiền phạt, doanh nghiệp còn phải khắc phục hậu quả như nộp đủ tiền thuế thiếu, tiền chậm nộp 0,03%/ngày hoặc hủy, điều chỉnh hóa đơn sai.","Áp dụng văn bản theo thời điểm hành vi vi phạm và nguyên tắc áp dụng quy định có lợi cho người vi phạm khi văn bản mới giảm nhẹ trách nhiệm."],"case":"Công ty TNHH Phát Đạt bị kiểm tra năm 2026 về các sai sót phát sinh năm 2024 và 2025. Kế toán chỉ tra cứu quy định mới và tranh luận sai căn cứ. Sau khi phân biệt quy định áp dụng theo thời điểm vi phạm và đề nghị áp dụng điểm có lợi của văn bản mới, doanh nghiệp được xem xét đúng mức phạt.","trend":"Quy định quản lý thuế tiếp tục được sửa đổi nhanh trong giai đoạn 2026–2030 để theo kịp kinh tế số. Học viên nên duy trì bảng theo dõi hiệu lực văn bản và cập nhật định kỳ hằng quý.","practice":"Lập bảng theo dõi văn bản pháp lý về xử phạt thuế, hóa đơn gồm tên văn bản, phạm vi, ngày hiệu lực và nội dung chính ảnh hưởng đến doanh nghiệp bạn.","takeaway":"Xác định đúng văn bản áp dụng là bước đầu tiên để không bị phạt sai."}},{"id":"KH044","code":"kh044","f":"THUE","fn":"Thuế","t":"Thanh tra, kiểm tra thuế: chuẩn bị và giải trình","lv":5,"ln":"Chuyên gia","h":32,"p":499000,"d":"Khoá học giúp doanh nghiệp chủ động trước thanh tra, kiểm tra thuế: hiểu cách cơ quan thuế chọn đối tượng, tự rà soát rủi ro, chuẩn bị hồ sơ và giải trình bằng lập luận có căn cứ. Phương pháp học dựa trên tình huống kiểm tra thật, bộ mẫu văn bản giải trình và bảng đối chiếu dữ liệu dùng ngay. Kết thúc khoá, học viên tự tổ chức được một cuộc làm việc với đoàn kiểm tra và giảm thiểu số thuế bị truy thu, tiền phạt, tiền chậm nộp.","a":"Kế toán trưởng, trưởng phòng thuế, giám đốc tài chính, chuyên viên tư vấn thuế và chủ doanh nghiệp đang hoặc sắp bị kiểm tra, thanh tra thuế.","o":["Phân biệt được kiểm tra tại trụ sở cơ quan thuế, kiểm tra tại trụ sở người nộp thuế và thanh tra thuế, xác định đúng quyền và nghĩa vụ của doanh nghiệp ở từng giai đoạn.","Lập được bảng tự rà soát rủi ro thuế 3 năm gần nhất với ít nhất 20 chỉ tiêu đối chiếu giữa sổ sách, tờ khai, hóa đơn và sao kê ngân hàng.","Soạn được văn bản giải trình có cấu trúc: sự việc, căn cứ pháp lý, chứng từ chứng minh và đề xuất xử lý.","Tự tính được số thuế truy thu, tiền phạt và tiền chậm nộp 0,03%/ngày dự kiến để chủ động đàm phán và lập dự phòng.","Tổ chức được quy trình làm việc với đoàn kiểm tra, rà soát dự thảo biên bản và thực hiện quyền khiếu nại khi chưa đồng ý kết luận."],"k":"Năm 2026 cơ quan thuế chọn doanh nghiệp kiểm tra bằng dữ liệu hóa đơn và ngân hàng: bạn đã sẵn sàng giải trình chưa?","w":["Khung xử phạt vi phạm hành chính về thuế, hóa đơn đã được sửa đổi bởi NĐ 310/2025 (hiệu lực 16/01/2026), cùng với Luật GTGT 48/2024/QH15 và Luật TNDN 67/2025/QH15 làm thay đổi nhiều điểm thường bị điều chỉnh khi kiểm tra.","Dữ liệu hóa đơn điện tử, hóa đơn khởi tạo từ máy tính tiền và dữ liệu ngân hàng giúp cơ quan thuế phân tích rủi ro tự động, đối chiếu chéo trước cả khi đoàn kiểm tra đến doanh nghiệp.","Xu hướng quản lý thuế số giai đoạn 2026–2030 dịch chuyển từ kiểm tra diện rộng sang kiểm tra có trọng điểm theo chấm điểm rủi ro, doanh nghiệp chuẩn bị tốt sẽ rút ngắn thời gian và chi phí tuân thủ."],"dl":["Bộ mẫu Excel tự rà soát rủi ro thuế: đối chiếu doanh thu tờ khai – sổ sách – hóa đơn, chi phí không được trừ, thanh toán không dùng tiền mặt từ 5 triệu đồng.","Checklist 60 đầu việc chuẩn bị hồ sơ trước, trong và sau buổi làm việc với đoàn kiểm tra.","Bộ mẫu văn bản giải trình, công văn đề nghị, ý kiến đối với dự thảo biên bản và đơn khiếu nại tham khảo.","Bộ câu lệnh AI (prompt) hỗ trợ phân tích bất thường dữ liệu, tóm tắt hồ sơ và soạn khung giải trình, kèm quy tắc bảo mật dữ liệu khi dùng AI."],"ls":["Bản đồ kiểm tra và thanh tra thuế: hiểu luật chơi trước khi vào trận","Cơ quan thuế chọn bạn như thế nào: đọc vị chấm điểm rủi ro","Tự rà soát trước kiểm tra: khám sức khỏe thuế 3 năm","Chuẩn bị hồ sơ và tổ chức buổi làm việc với đoàn kiểm tra","Nghệ thuật giải trình bằng văn bản: lập luận thuyết phục, chứng cứ vững","Những điểm nóng thường bị điều chỉnh và cách phòng thủ","Biên bản, kết luận và bài toán tài chính sau kiểm tra","Khiếu nại, đối thoại và xây hệ thống tuân thủ sau kiểm tra"],"l1":{"t":"Bản đồ kiểm tra và thanh tra thuế: hiểu luật chơi trước khi vào trận","sum":"Bài nền tảng phân biệt các hình thức kiểm tra, thanh tra thuế theo Luật Quản lý thuế 38/2019/QH14 và NĐ 126/2020. Học viên nắm được trình tự, thời hạn và quyền của doanh nghiệp ở từng bước.","points":["Kiểm tra tại trụ sở cơ quan thuế là việc rà soát hồ sơ khai thuế; khi phát hiện dấu hiệu bất thường, cơ quan thuế gửi thông báo đề nghị giải trình, bổ sung thông tin trước khi chuyển sang kiểm tra tại trụ sở người nộp thuế.","Kiểm tra tại trụ sở người nộp thuế được thực hiện theo quyết định kiểm tra; doanh nghiệp có quyền yêu cầu xuất trình quyết định, được biết nội dung, thời kỳ và thời hạn kiểm tra.","Thanh tra thuế có phạm vi và mức độ sâu hơn, thường áp dụng khi có dấu hiệu vi phạm nghiêm trọng hoặc theo kế hoạch đối với doanh nghiệp quy mô lớn, rủi ro cao.","Doanh nghiệp có quyền giải trình, được bảo mật thông tin, được nhận biên bản, kết luận và có quyền khiếu nại, khởi kiện theo quy định hiện hành.","Nghĩa vụ đi kèm: cung cấp đầy đủ, kịp thời hồ sơ, tài liệu; chấp hành quyết định kiểm tra; ký biên bản và thực hiện kết luận, quyết định xử lý."],"case":"Công ty TNHH Minh An nhận thông báo giải trình chênh lệch doanh thu 1,2 tỷ đồng giữa tờ khai GTGT và dữ liệu hóa đơn. Kế toán chứng minh chênh lệch do hóa đơn điều chỉnh giảm lập sai kỳ, nộp bảng đối chiếu kèm hóa đơn điều chỉnh, hồ sơ được chấp nhận ngay tại trụ sở cơ quan thuế mà không chuyển sang kiểm tra tại doanh nghiệp.","trend":"Giai đoạn 2026–2030, giải trình tại trụ sở cơ quan thuế ngày càng thực hiện trực tuyến dựa trên dữ liệu điện tử. Học viên nên chuẩn hóa hồ sơ số và quen soạn giải trình gửi qua cổng thuế điện tử.","practice":"Vẽ sơ đồ quy trình từ thông báo giải trình đến kết luận kiểm tra cho doanh nghiệp của bạn, ghi rõ ai phụ trách, hồ sơ cần có và mốc thời gian ở từng bước.","takeaway":"Hiểu đúng quy trình là nửa thắng của mọi cuộc kiểm tra thuế."}},{"id":"KH045","code":"kh045","f":"THUE","fn":"Thuế","t":"Tiền chậm nộp, miễn giảm và gia hạn nộp thuế","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp doanh nghiệp làm chủ ba công cụ tài chính thuế ít được khai thác: tính đúng tiền chậm nộp, tận dụng gia hạn và đề nghị miễn, giảm khi đủ điều kiện. Học viên học qua tình huống thật, bảng tính tiền chậm nộp và mẫu hồ sơ đề nghị dùng ngay. Kết quả là doanh nghiệp kiểm soát được nghĩa vụ thuế theo ngày, tránh cưỡng chế và tiết kiệm chi phí tài chính.","a":"Kế toán tổng hợp, kế toán thuế, kế toán trưởng và chủ doanh nghiệp vừa và nhỏ cần quản lý nợ thuế, dòng tiền nộp thuế.","o":["Tính chính xác tiền chậm nộp 0,03%/ngày cho mọi tình huống: khai bổ sung, truy thu sau kiểm tra, nộp thiếu tạm nộp TNDN quý.","Nhận diện được các trường hợp không tính hoặc được miễn tiền chậm nộp và lập được hồ sơ đề nghị.","Lập được hồ sơ đề nghị gia hạn nộp thuế theo Luật Quản lý thuế và theo chính sách gia hạn từng năm khi có hiệu lực.","Đối chiếu được sổ thuế nội bộ với tra cứu nghĩa vụ thuế trên cổng điện tử, xử lý chênh lệch trong vòng 1 tuần.","Xây dựng được lịch và kế hoạch dòng tiền thuế 12 tháng, giảm tối thiểu 80% số lần phát sinh tiền chậm nộp."],"k":"Mỗi ngày nộp thuế chậm tốn 0,03% số thuế nợ: bạn có biết doanh nghiệp mình đang mất bao nhiêu mỗi năm?","w":["Khung xử phạt và quản lý thuế được cập nhật: NĐ 125/2020 sửa đổi bởi NĐ 310/2025 hiệu lực 16/01/2026, cùng Luật Quản lý thuế 38/2019/QH14 và NĐ 126/2020 là nền tảng tính tiền chậm nộp, gia hạn, nộp dần.","Hệ thống thuế điện tử tự động tính tiền chậm nộp và gửi thông báo, doanh nghiệp cần đối chiếu số liệu thường xuyên để phát hiện sai lệch và tránh bị cưỡng chế qua tài khoản ngân hàng.","Dòng tiền là ưu tiên sống còn trong giai đoạn 2026–2030, các chính sách gia hạn, hỗ trợ thường được ban hành theo từng năm và chỉ người theo dõi sát mới tận dụng kịp."],"dl":["Bảng tính Excel tiền chậm nộp tự động theo ngày, hỗ trợ nhiều khoản nợ, nhiều lần nộp.","Bộ mẫu văn bản: đề nghị gia hạn, đề nghị miễn tiền chậm nộp, đề nghị điều chỉnh nghĩa vụ, đề nghị nộp dần tiền thuế nợ (tham khảo, cần đối chiếu biểu mẫu hiện hành).","Checklist đối chiếu nghĩa vụ thuế hằng tháng và quy trình SOP xử lý thông báo tiền chậm nộp.","Bộ câu lệnh AI (prompt) giúp tóm tắt thông báo thuế, lập lịch nghĩa vụ và dự báo dòng tiền nộp thuế."],"ls":["Tiền chậm nộp: bản chất, công thức và những hiểu lầm đắt giá","Tiền chậm nộp trong các tình huống đặc thù","Không tính và miễn tiền chậm nộp: quyền lợi ít người dùng","Gia hạn nộp thuế theo Luật Quản lý thuế","Chính sách gia hạn theo từng năm: theo dõi và tận dụng kịp thời","Miễn, giảm thuế và xóa nợ: điều kiện, hồ sơ và giới hạn","Nợ thuế, cưỡng chế và nộp dần: xử lý trước khi tài khoản bị phong tỏa","Quản trị nghĩa vụ thuế chủ động bằng dữ liệu và tự động hóa"],"l1":{"t":"Tiền chậm nộp: bản chất, công thức và những hiểu lầm đắt giá","sum":"Bài nền tảng giải thích tiền chậm nộp là gì, khác tiền phạt thế nào và cách tính chuẩn. Học viên tự kiểm tra được mọi con số trên thông báo của cơ quan thuế.","points":["Tiền chậm nộp là khoản bù đắp cho việc chiếm dụng tiền ngân sách, không phải tiền phạt; mức tính 0,03%/ngày trên số tiền thuế chậm nộp.","Công thức: Tiền chậm nộp = Số thuế chậm nộp x 0,03% x Số ngày chậm nộp; số ngày tính liên tục từ ngày kế tiếp ngày hết hạn nộp đến ngày liền kề trước ngày nộp vào ngân sách.","Ví dụ: thuế GTGT tháng 50 triệu đồng nộp trễ 45 ngày thì tiền chậm nộp là 50.000.000 x 0,03% x 45 = 675.000 đồng.","Tiền chậm nộp không được tính vào chi phí được trừ khi xác định thu nhập chịu thuế TNDN, hạch toán vào chi phí khác và loại ra khi quyết toán.","Hiểu lầm phổ biến: nghĩ rằng đã khai đúng hạn thì không bị tính; thực tế khai đúng hạn nhưng nộp tiền trễ vẫn phát sinh tiền chậm nộp."],"case":"Công ty TNHH Minh An khai thuế GTGT quý đúng hạn nhưng chuyển tiền 120 triệu đồng trễ 20 ngày do chờ khách thanh toán. Tiền chậm nộp phát sinh 120.000.000 x 0,03% x 20 = 720.000 đồng; kế toán hạch toán vào chi phí khác và loại khỏi chi phí được trừ khi quyết toán TNDN.","trend":"Cổng thuế điện tử ngày càng tự động tính và cập nhật tiền chậm nộp theo thời gian thực. Học viên nên tập thói quen đối chiếu định kỳ thay vì chờ thông báo cuối năm.","practice":"Dùng bảng tính của khoá, tính tiền chậm nộp cho 3 khoản: GTGT 80 triệu trễ 15 ngày, TNCN 12 triệu trễ 60 ngày, TNDN 200 triệu trễ 100 ngày; so sánh với kết quả tính tay.","takeaway":"Khai đúng hạn chưa đủ, tiền phải vào ngân sách đúng hạn."}},{"id":"KH046","code":"kh046","f":"THUE","fn":"Thuế","t":"Hộ kinh doanh 2026: bỏ thuế khoán, kê khai và hóa đơn","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học nhập môn giúp chủ hộ kinh doanh và người bán hàng online hiểu rõ nghĩa vụ thuế khi thuế khoán và lệ phí môn bài bị bãi bỏ từ 01/01/2026 theo NQ 198/2025/QH15. Học viên học qua ví dụ cửa hàng, quán ăn, shop online thật, kèm mẫu sổ doanh thu và lịch kê khai dùng ngay. Sau khoá học, bạn tự xác định được mình phải nộp gì, tự tính và kê khai được, dùng hóa đơn điện tử đúng cách và biết khi nào nên lên doanh nghiệp.","a":"Chủ hộ kinh doanh, người bán hàng trên sàn thương mại điện tử, mạng xã hội, livestream và người đang chuẩn bị mở cửa hàng, quán ăn, dịch vụ nhỏ.","o":["Xác định được mình là hộ kinh doanh hay cá nhân kinh doanh và có thuộc diện phải nộp thuế theo ngưỡng doanh thu hiện hành hay không.","Tự tính được thuế GTGT và TNCN theo tỷ lệ trên doanh thu cho từng nhóm ngành nghề.","Tách được phần doanh thu đã được sàn khấu trừ, nộp thay và phần doanh thu ngoài sàn phải tự kê khai.","Lập và gửi được hóa đơn điện tử, kể cả hóa đơn khởi tạo từ máy tính tiền khi thuộc diện áp dụng.","Ghi được sổ doanh thu, lưu chứng từ đơn giản mỗi ngày trong 10 phút và tự đánh giá được thời điểm nên chuyển lên doanh nghiệp."],"k":"Từ 2026 không còn thuế khoán: hộ kinh doanh phải tự kê khai, xuất hóa đơn và giữ sổ sách, bạn đã sẵn sàng chưa?","w":["NQ 198/2025/QH15 bỏ thuế khoán và lệ phí môn bài với hộ kinh doanh từ 01/01/2026, hộ chuyển sang tự kê khai theo doanh thu thực tế.","Sàn thương mại điện tử có chức năng thanh toán phải khấu trừ, nộp thay thuế cho hộ, cá nhân kinh doanh trên sàn theo NĐ 117/2025 từ 01/07/2025, dữ liệu doanh thu online ngày càng minh bạch.","Hóa đơn điện tử khởi tạo từ máy tính tiền và quy định hóa đơn mới tại NĐ 70/2025 (sửa NĐ 123/2020) khiến cơ quan thuế nắm doanh thu gần như theo thời gian thực."],"dl":["Mẫu Excel sổ doanh thu đa kênh (cửa hàng, sàn, mạng xã hội) tự cộng lũy kế và tính thuế theo tỷ lệ.","Checklist 30 việc cho hộ kinh doanh năm 2026: đăng ký, kê khai, hóa đơn, lưu chứng từ, tài khoản ngân hàng.","Lịch kê khai, nộp thuế 12 tháng dạng in được, kèm hướng dẫn tra cứu nghĩa vụ trên cổng thuế điện tử.","Bộ câu lệnh AI (prompt) giúp tổng hợp doanh thu từ file xuất sàn, phân loại ngành nghề và soạn tin nhắn trả lời khách hỏi hóa đơn."],"ls":["Hộ kinh doanh năm 2026: điều gì đã thay đổi và vì sao bạn phải quan tâm","Ngưỡng doanh thu và cách cộng doanh thu từ mọi kênh bán","Tính thuế theo tỷ lệ trên doanh thu: đơn giản, nhanh, chính xác","Bán trên sàn: khi nào sàn nộp thay, khi nào bạn tự khai","Đăng ký, kê khai và nộp thuế: tự làm từng bước trên cổng điện tử","Hóa đơn điện tử và máy tính tiền: bán hàng chuyên nghiệp, minh bạch","Sổ sách tối giản và ứng dụng AI cho hộ kinh doanh","Rủi ro thường gặp và thời điểm nên chuyển lên doanh nghiệp"],"l1":{"t":"Hộ kinh doanh năm 2026: điều gì đã thay đổi và vì sao bạn phải quan tâm","sum":"Bài mở đầu giải thích hộ kinh doanh, cá nhân kinh doanh và bức tranh chính sách mới năm 2026. Học viên hiểu vì sao cách làm cũ không còn phù hợp.","points":["Hộ kinh doanh do một cá nhân hoặc các thành viên hộ gia đình đăng ký, chịu trách nhiệm bằng toàn bộ tài sản; người bán online chưa đăng ký vẫn có nghĩa vụ thuế nếu doanh thu thuộc diện chịu thuế.","Từ 01/01/2026, thuế khoán được bãi bỏ theo NQ 198/2025/QH15, hộ kinh doanh chuyển sang tự khai, tự nộp theo doanh thu thực tế.","Lệ phí môn bài cũng được bãi bỏ từ 01/01/2026, hộ kinh doanh không còn phải nộp khoản này hằng năm.","Cơ quan thuế đối chiếu dữ liệu từ sàn thương mại điện tử, ngân hàng và hóa đơn điện tử, nên doanh thu khai thấp hơn thực tế rất dễ bị phát hiện.","Tự kê khai không có nghĩa là phức tạp: với sổ doanh thu chuẩn và lịch nộp rõ ràng, phần lớn hộ có thể tự làm mà không cần thuê dịch vụ."],"case":"Hộ kinh doanh tạp hóa Minh An trước đây nộp thuế khoán cố định mỗi tháng. Từ năm 2026, chủ hộ chuyển sang ghi sổ doanh thu hằng ngày từ máy bán hàng và tự kê khai theo kỳ, nhờ đó số thuế phản ánh đúng doanh thu thực tế, không lo bị truy thu khi cơ quan thuế đối chiếu dữ liệu.","trend":"Xu hướng 2026–2030 là quản lý thuế hộ kinh doanh dựa trên dữ liệu điện tử thay vì ấn định. Chủ hộ nên làm quen ngay với phần mềm bán hàng, tài khoản ngân hàng riêng cho kinh doanh và cổng thuế điện tử.","practice":"Viết một đoạn mô tả mô hình kinh doanh của bạn: kênh bán, mặt hàng, doanh thu bình quân tháng, cách thu tiền, và tự xác định bạn là hộ kinh doanh hay cá nhân kinh doanh.","takeaway":"Năm 2026, doanh thu thật là cơ sở duy nhất để tính thuế."}},{"id":"KH047","code":"kh047","f":"THUE","fn":"Thuế","t":"Hoạch định thuế hợp pháp và quản trị rủi ro thuế bằng dữ liệu","lv":5,"ln":"Chuyên gia","h":32,"p":499000,"d":"Khoá học giúp lãnh đạo tài chính xây kế hoạch thuế hợp pháp và hệ thống quản trị rủi ro thuế dựa trên dữ liệu, thay vì xử lý bị động cuối năm. Phương pháp học xoay quanh tình huống doanh nghiệp Việt Nam thật, mô hình so sánh phương án bằng Excel và bộ chỉ số rủi ro dùng ngay. Kết quả là học viên lập được kế hoạch thuế năm, chứng minh được tính hợp pháp của từng lựa chọn và giảm rủi ro bị truy thu, xử phạt.","a":"Giám đốc tài chính, kế toán trưởng, chuyên gia tư vấn thuế, chủ doanh nghiệp và nhà đầu tư muốn tối ưu thuế hợp pháp, minh bạch và bền vững.","o":["Phân biệt rõ hoạch định thuế hợp pháp, tránh thuế lạm dụng và trốn thuế, áp dụng được bộ tiêu chí kiểm tra thực chất kinh tế cho mọi phương án.","Lập được mô hình so sánh thuế và dòng tiền giữa các phương án: mô hình kinh doanh, cấu trúc thu nhập chủ sở hữu, chính sách lương thưởng.","Xây được kế hoạch thuế năm gồm dự báo nghĩa vụ, thời điểm ghi nhận, ưu đãi áp dụng và hồ sơ bảo vệ.","Thiết lập được bảng điều khiển ít nhất 12 chỉ số rủi ro thuế cập nhật hằng quý từ dữ liệu kế toán, hóa đơn và ngân hàng.","Trình bày được kế hoạch thuế và mức rủi ro cho ban giám đốc, hội đồng quản trị bằng báo cáo ngắn gọn, có số liệu."],"k":"Thuế là chi phí lớn có thể hoạch định: năm 2026, doanh nghiệp dùng dữ liệu để tối ưu hợp pháp sẽ đi trước đối thủ.","w":["Luật TNDN 67/2025/QH15 với thuế suất 15%, 17%, 20% theo quy mô doanh thu từ kỳ tính thuế 2025, Luật GTGT 48/2024/QH15 và quy định thanh toán không dùng tiền mặt từ 5 triệu đồng (NĐ 181/2025) tạo ra nhiều điểm lựa chọn mới cần hoạch định lại.","Thuế tối thiểu toàn cầu theo NQ 107/2023/QH15, yêu cầu công khai chủ sở hữu hưởng lợi theo Luật Doanh nghiệp sửa đổi 2025 khiến các cấu trúc thiếu thực chất kinh tế ngày càng rủi ro.","Cơ quan thuế phân tích rủi ro bằng dữ liệu hóa đơn điện tử và ngân hàng, nên doanh nghiệp cũng phải dùng dữ liệu để tự đo lường rủi ro và chứng minh tính hợp lý của kế hoạch thuế."],"dl":["Mô hình Excel so sánh phương án thuế: hộ kinh doanh và công ty, lương và cổ tức, thời điểm ghi nhận doanh thu, chi phí.","Mẫu kế hoạch thuế năm và hồ sơ bảo vệ (tax file) cho từng quyết định hoạch định quan trọng.","Bảng điều khiển rủi ro thuế với 12 chỉ số, ngưỡng cảnh báo và quy trình SOP rà soát hằng quý.","Bộ câu lệnh AI (prompt) phân tích dữ liệu hóa đơn, phát hiện bất thường, mô phỏng kịch bản thuế, kèm nguyên tắc kiểm chứng và bảo mật dữ liệu."],"ls":["Ranh giới vàng: hoạch định hợp pháp khác tránh thuế lạm dụng ở đâu","Chọn mô hình kinh doanh: hộ kinh doanh, công ty TNHH hay cổ phần","Cấu trúc thu nhập của chủ doanh nghiệp: lương, cổ tức hay lãi vay","Chính sách lương, thưởng, phúc lợi: tối ưu thuế cho người lao động","Hoạch định theo thời điểm: doanh thu, chi phí, khấu hao và chuyển lỗ","Tận dụng ưu đãi và chính sách hỗ trợ: đúng điều kiện, đủ hồ sơ","Giao dịch liên kết, tái cấu trúc và thuế tối thiểu toàn cầu","Quản trị rủi ro thuế bằng dữ liệu và kế hoạch thuế năm"],"l1":{"t":"Ranh giới vàng: hoạch định hợp pháp khác tránh thuế lạm dụng ở đâu","sum":"Bài nền tảng xác định ranh giới giữa hoạch định thuế, tránh thuế lạm dụng và trốn thuế. Học viên có bộ tiêu chí để thẩm định mọi đề xuất tối ưu thuế trước khi thực hiện.","points":["Hoạch định thuế hợp pháp là lựa chọn phương án kinh doanh có thực chất, tận dụng quy định ưu đãi, lựa chọn mà luật cho phép, minh bạch và có hồ sơ chứng minh.","Trốn thuế là hành vi vi phạm như khai sai doanh thu, sử dụng hóa đơn không hợp pháp, che giấu giao dịch; bị xử lý theo NĐ 125/2020 sửa bởi NĐ 310/2025 và có thể bị truy cứu theo pháp luật hình sự.","Vùng xám là các cấu trúc có hình thức hợp pháp nhưng thiếu mục đích kinh doanh, cơ quan thuế có thể xác định lại nghĩa vụ theo bản chất giao dịch.","Bộ 4 câu hỏi kiểm tra: giao dịch có mục đích kinh doanh ngoài thuế không, có thực hiện thực tế không, giá có phù hợp thị trường không, có chứng từ đầy đủ không.","Mọi phương án hoạch định phải được ghi thành văn bản: mục tiêu, căn cứ, rủi ro, số tiền tác động và người phê duyệt."],"case":"Công ty TNHH Minh An được đề xuất chuyển lợi nhuận sang một công ty dịch vụ do người nhà sở hữu bằng hợp đồng tư vấn 2 tỷ đồng/năm. Khi áp bộ 4 câu hỏi, giám đốc tài chính nhận thấy dịch vụ không có sản phẩm thực tế, giá không có cơ sở, nên từ chối phương án và chuyển sang tối ưu bằng ưu đãi đầu tư máy móc hợp pháp.","trend":"Xu hướng quốc tế 2026–2030 đề cao thực chất kinh tế và minh bạch thuế, gắn với tiêu chí quản trị trong báo cáo ESG. Học viên nên xây chính sách thuế nội bộ được ban giám đốc phê duyệt.","practice":"Liệt kê 5 ý tưởng tiết kiệm thuế đang được bàn trong doanh nghiệp hoặc thị trường, chấm điểm từng ý tưởng theo bộ 4 câu hỏi và xếp vào nhóm hợp pháp, vùng xám, vi phạm.","takeaway":"Tối ưu thuế bền vững luôn bắt đầu từ thực chất kinh doanh."}},{"id":"KH048","code":"kh048","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Bảo hiểm xã hội bắt buộc cho doanh nghiệp","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp doanh nghiệp nắm chắc nghĩa vụ BHXH, BHYT, BHTN bắt buộc và kinh phí công đoàn theo Luật BHXH 2024 (hiệu lực 01/07/2025): ai phải đóng, đóng trên khoản lương nào, tỷ lệ bao nhiêu và hạch toán ra sao. Mỗi bài đi kèm tình huống thật tại doanh nghiệp Việt Nam và bảng tính Excel dùng ngay. Học xong, bạn tự tính đúng số phải đóng hằng tháng, hạch toán chuẩn và chủ động phòng tránh truy thu, xử phạt.","a":"Kế toán, nhân sự tiền lương mới vào nghề và chủ doanh nghiệp nhỏ muốn tự quản lý bảo hiểm bắt buộc cho người lao động.","o":["Xác định đúng đối tượng phải tham gia BHXH, BHYT, BHTN bắt buộc cho từng loại hợp đồng và từng người trong danh sách nhân sự.","Tách được khoản thu nhập tính và không tính đóng bảo hiểm trong bảng lương thực tế.","Tính chính xác số đóng hằng tháng với tỷ lệ doanh nghiệp 21,5%, người lao động 10,5% và KPCĐ 2%.","Lập được bút toán trích, khấu trừ, nộp bảo hiểm và KPCĐ theo TT 133/2016 hoặc TT 99/2025.","Tự kiểm tra được rủi ro chậm đóng, trốn đóng và lập kế hoạch khắc phục trong 30 ngày."],"k":"Năm 2026, dữ liệu BHXH, thuế và hóa đơn đã liên thông: đóng sai một đồng bảo hiểm, doanh nghiệp có thể bị truy thu cả năm.","w":["Luật BHXH 2024 có hiệu lực từ 01/07/2025 mở rộng đối tượng tham gia và siết trách nhiệm chậm đóng, trốn đóng, nhiều doanh nghiệp vẫn áp dụng cách làm cũ.","Dữ liệu cơ quan BHXH, cơ quan thuế và dân cư ngày càng liên thông, sai lệch giữa quyết toán thuế TNCN và quỹ lương đóng bảo hiểm bị phát hiện nhanh hơn.","Người lao động tự tra cứu quá trình đóng trên ứng dụng VssID, doanh nghiệp đóng thiếu sẽ mất uy tín tuyển dụng và dễ phát sinh khiếu nại."],"dl":["Bộ mẫu Excel tính BHXH, BHYT, BHTN, KPCĐ hằng tháng có công thức tự động theo danh sách nhân sự.","Checklist 20 điểm rà soát tuân thủ bảo hiểm bắt buộc trước kỳ thanh tra.","Quy trình SOP hằng tháng từ chốt lương đến nộp tiền và đối chiếu số liệu bảo hiểm.","Bộ câu lệnh AI (prompt) hỗ trợ phân loại khoản thu nhập, soạn công văn giải trình và kiểm tra bảng lương."],"ls":["Bức tranh bảo hiểm bắt buộc 2026: hiểu đúng để không đóng sai","Ai phải đóng: xác định đối tượng tham gia theo từng loại hợp đồng","Tiền lương đóng bảo hiểm: khoản nào tính, khoản nào không","Tính số đóng hằng tháng: 21,5% + 10,5% + KPCĐ 2% không sai một đồng","Hạch toán bảo hiểm và KPCĐ chuẩn TT 133/2016 và TT 99/2025","Chậm đóng, trốn đóng và truy thu: nhận diện rủi ro trước khi bị kiểm tra","Số hóa quản lý bảo hiểm: VssID, giao dịch điện tử và dữ liệu nhân sự sạch","Trợ lý AI cho kế toán bảo hiểm: kiểm tra bảng lương và soạn giải trình nhanh"],"l1":{"t":"Bức tranh bảo hiểm bắt buộc 2026: hiểu đúng để không đóng sai","sum":"Bài hệ thống ba loại bảo hiểm bắt buộc, các quỹ thành phần và vai trò của doanh nghiệp. Học viên nắm được những điểm mới cốt lõi của Luật BHXH 2024 có hiệu lực từ 01/07/2025.","points":["Bảo hiểm bắt buộc gồm BHXH (ốm đau, thai sản, tai nạn lao động – bệnh nghề nghiệp, hưu trí, tử tuất), BHYT và BHTN; ngoài ra doanh nghiệp đóng kinh phí công đoàn 2% quỹ lương đóng bảo hiểm.","Tổng tỷ lệ đóng hiện hành: doanh nghiệp 21,5% và người lao động 10,5% trên tiền lương tháng đóng bảo hiểm.","Luật BHXH 2024 hiệu lực 01/07/2025 mở rộng nhóm đối tượng tham gia và quy định rõ hơn các hành vi chậm đóng, trốn đóng cùng biện pháp xử lý.","Doanh nghiệp là bên kê khai, khấu trừ phần của người lao động và nộp toàn bộ hằng tháng; người lao động không tự nộp phần bắt buộc.","Các chi tiết về mức hưởng, điều kiện hưởng từng chế độ áp dụng theo quy định hiện hành và văn bản hướng dẫn của cơ quan BHXH."],"case":"Công ty TNHH Minh An có 25 lao động nhưng chỉ đóng bảo hiểm cho 18 người vì cho rằng nhân viên thử việc xong mới phải đóng. Kế toán rà lại hợp đồng, phát hiện 7 người đã ký hợp đồng lao động từ đủ 1 tháng trở lên nên thuộc diện bắt buộc, công ty chủ động báo tăng và đóng bổ sung trước khi bị kiểm tra.","trend":"Giai đoạn 2026–2030, quản lý bảo hiểm được dự kiến tiếp tục số hóa và đối soát dữ liệu tự động với thuế, dân cư. Học viên nên chuẩn hóa dữ liệu nhân sự số ngay từ bây giờ.","practice":"Lập sơ đồ một trang tóm tắt ba loại bảo hiểm, tỷ lệ đóng của doanh nghiệp và người lao động, áp dụng cho doanh nghiệp bạn đang làm.","takeaway":"Hiểu đúng cấu trúc bảo hiểm là nền móng để mọi con số phía sau không sai."}},{"id":"KH049","code":"kh049","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Thủ tục BHXH: báo tăng, giảm lao động và đối chiếu C12","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học thực hành trọn vòng thủ tục BHXH hằng tháng của doanh nghiệp: đăng ký tham gia, báo tăng, báo giảm, điều chỉnh mức đóng, đối chiếu thông báo kết quả đóng C12 và chốt quá trình đóng. Bạn học trên tình huống thật, quy trình từng bước và bộ mẫu đối chiếu Excel dùng ngay. Kết quả là hồ sơ nộp đúng hạn, số liệu C12 khớp sổ sách và người lao động nghỉ việc được chốt sổ kịp thời.","a":"Nhân viên nhân sự, kế toán tiền lương và chủ doanh nghiệp nhỏ trực tiếp làm thủ tục BHXH cho người lao động.","o":["Thực hiện được hồ sơ đăng ký tham gia lần đầu cho doanh nghiệp và người lao động qua giao dịch điện tử.","Lập đúng hồ sơ báo tăng, báo giảm, điều chỉnh mức đóng theo từng tình huống biến động lao động.","Đối chiếu được thông báo C12 với bảng lương và sổ kế toán, chỉ ra nguyên nhân chênh lệch trong một buổi làm việc.","Xử lý chốt quá trình đóng cho người nghỉ việc, kể cả trường hợp doanh nghiệp còn nợ bảo hiểm.","Xây dựng được lịch công việc BHXH hằng tháng và rút ngắn thời gian xử lý thủ tục ít nhất 30%."],"k":"Một hồ sơ báo giảm trễ, một dòng C12 lệch số: người lao động không chốt được sổ, doanh nghiệp gánh nợ bảo hiểm.","w":["Luật BHXH 2024 hiệu lực 01/07/2025 siết trách nhiệm đóng đủ, đóng đúng hạn và quyền lợi của người lao động, kéo theo yêu cầu thủ tục chặt chẽ hơn.","Giao dịch BHXH đã chuyển gần như hoàn toàn sang điện tử, xác thực bằng dữ liệu dân cư; hồ sơ sai dữ liệu bị trả về ngay.","Người lao động theo dõi quá trình đóng qua VssID, mọi chậm trễ báo tăng, báo giảm đều hiện rõ và dễ thành khiếu nại."],"dl":["Bộ mẫu Excel đối chiếu C12 với bảng lương và TK 338, có cột tự động đánh dấu chênh lệch.","Checklist hồ sơ cho 12 tình huống biến động lao động thường gặp.","Quy trình SOP thủ tục BHXH hằng tháng từ nhận biến động nhân sự đến lưu hồ sơ.","Bộ câu lệnh AI (prompt) hỗ trợ đọc C12, tìm chênh lệch và soạn thông báo cho người lao động."],"ls":["Hạ tầng giao dịch BHXH điện tử: chuẩn bị đúng một lần, dùng lâu dài","Đăng ký tham gia lần đầu: doanh nghiệp mới và người lao động mới","Báo tăng, báo giảm, điều chỉnh: xử lý mọi biến động lao động","Đọc hiểu thông báo C12: từng dòng số liệu nói gì","Đối chiếu C12 với bảng lương và TK 338: khép kín ba nguồn số liệu","Chốt quá trình đóng và xử lý người lao động nghỉ việc","Lịch công việc BHXH tự động: quy trình chuẩn và công cụ nhắc việc","AI và dữ liệu trong thủ tục BHXH: đối chiếu nhanh, giao tiếp rõ"],"l1":{"t":"Hạ tầng giao dịch BHXH điện tử: chuẩn bị đúng một lần, dùng lâu dài","sum":"Bài giới thiệu cách doanh nghiệp giao dịch với cơ quan BHXH qua phương thức điện tử. Học viên chuẩn bị đầy đủ chữ ký số, tài khoản giao dịch và dữ liệu nền.","points":["Doanh nghiệp nộp hồ sơ qua Cổng dịch vụ công của BHXH Việt Nam hoặc phần mềm của tổ chức I-VAN, ký bằng chữ ký số còn hiệu lực.","Cần đăng ký giao dịch điện tử với cơ quan BHXH và quản lý tài khoản, mật khẩu theo phân quyền nội bộ, không dùng chung cá nhân.","Dữ liệu nền gồm mã đơn vị, danh sách lao động với số định danh cá nhân, mã số BHXH, chức danh, mức lương và phụ cấp.","Ứng dụng VssID giúp người lao động tự kiểm tra quá trình đóng; doanh nghiệp nên đưa bước hướng dẫn cài VssID vào thủ tục tiếp nhận nhân viên.","Lưu trữ toàn bộ hồ sơ điện tử theo cấu trúc năm/tháng/loại thủ tục để tra cứu khi đối chiếu hoặc thanh tra."],"case":"Công ty TNHH Minh An để chữ ký số hết hạn đúng tuần cần báo tăng 6 lao động mới. Hồ sơ nộp trễ sang tháng sau khiến người lao động thắc mắc vì không thấy quá trình đóng trên VssID; công ty lập lịch nhắc gia hạn chữ ký số trước 30 ngày.","trend":"Giao dịch hành chính được dự kiến tích hợp sâu với định danh điện tử và cổng dịch vụ công quốc gia. Học viên nên làm chủ các thao tác số và quản lý quyền truy cập an toàn.","practice":"Lập bảng kiểm hạ tầng gồm chữ ký số, tài khoản giao dịch, phần mềm I-VAN, người phụ trách và ngày hết hạn của từng hạng mục.","takeaway":"Hạ tầng sẵn sàng thì thủ tục không bao giờ chờ."}},{"id":"KH050","code":"kh050","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Chế độ ốm đau, thai sản, tai nạn lao động","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp doanh nghiệp giải quyết trọn vẹn ba nhóm chế độ ngắn hạn quan trọng nhất: ốm đau, thai sản, tai nạn lao động – bệnh nghề nghiệp theo Luật BHXH 2024 (hiệu lực 01/07/2025) và pháp luật an toàn, vệ sinh lao động. Phương pháp học dựa trên tình huống thật, quy trình hồ sơ từng bước và bảng tính mức hưởng dùng ngay. Học xong, bạn xác định đúng điều kiện, lập hồ sơ đầy đủ, hạch toán chính xác và tư vấn người lao động một cách chuyên nghiệp.","a":"Chuyên viên nhân sự C&B, kế toán tiền lương và quản lý doanh nghiệp đã nắm cơ bản về BHXH bắt buộc, muốn xử lý thành thạo các chế độ cho người lao động.","o":["Xác định đúng điều kiện hưởng chế độ ốm đau, thai sản, tai nạn lao động – bệnh nghề nghiệp cho từng tình huống.","Tính được mức hưởng dự kiến dựa trên tiền lương đóng bảo hiểm và tỷ lệ hưởng theo quy định hiện hành.","Lập và nộp hồ sơ đề nghị hưởng chế độ qua giao dịch điện tử, theo dõi đến khi nhận kết quả.","Hạch toán đúng khoản trợ cấp do quỹ BHXH chi trả và khoản doanh nghiệp tự chi trả khi xảy ra tai nạn lao động.","Xây dựng được quy trình nội bộ xử lý chế độ, rút ngắn thời gian hoàn thiện hồ sơ và giảm hồ sơ bị trả về."],"k":"Nhân viên nghỉ ốm, sinh con hay gặp tai nạn: doanh nghiệp xử lý sai một bước, người lao động mất quyền lợi, công ty mất niềm tin.","w":["Luật BHXH 2024 có hiệu lực từ 01/07/2025 điều chỉnh nhiều nội dung về điều kiện, thời gian và cách giải quyết chế độ ngắn hạn, quy trình cũ không còn phù hợp hoàn toàn.","Hồ sơ hưởng chế độ được giải quyết điện tử, dữ liệu khám chữa bệnh và giấy chứng nhận nghỉ việc liên thông, đòi hỏi doanh nghiệp làm đúng ngay từ đầu.","Chính sách phúc lợi và trải nghiệm nhân viên là lợi thế tuyển dụng; doanh nghiệp xử lý chế độ nhanh, chuẩn sẽ giữ chân người giỏi tốt hơn."],"dl":["Bộ mẫu Excel tính mức hưởng ốm đau, thai sản và theo dõi hồ sơ chế độ theo từng người lao động.","Checklist hồ sơ cho 10 tình huống chế độ thường gặp gồm ốm đau, con ốm, khám thai, sinh con, dưỡng sức, tai nạn lao động.","Quy trình SOP xử lý khi xảy ra tai nạn lao động từ sơ cứu, khai báo, điều tra đến giải quyết chế độ.","Bộ câu lệnh AI (prompt) soạn thông báo quyền lợi, trả lời câu hỏi người lao động và rà soát hồ sơ."],"ls":["Bản đồ chế độ ngắn hạn 2026: ai trả, trả bao nhiêu, khi nào","Chế độ ốm đau: điều kiện, thời gian và cách tính mức hưởng","Chế độ thai sản: đồng hành cùng người lao động từ khám thai đến trở lại làm việc","Dưỡng sức phục hồi sức khỏe và các tình huống chế độ đặc biệt","Tai nạn lao động – bệnh nghề nghiệp: trách nhiệm doanh nghiệp và quyền lợi người lao động","Lập, nộp và theo dõi hồ sơ chế độ trên môi trường điện tử","Hạch toán và đối chiếu chế độ BHXH trên sổ kế toán","Dịch vụ chế độ thông minh: AI, dữ liệu và trải nghiệm người lao động"],"l1":{"t":"Bản đồ chế độ ngắn hạn 2026: ai trả, trả bao nhiêu, khi nào","sum":"Bài hệ thống các chế độ ngắn hạn, nguồn chi trả và vai trò của doanh nghiệp. Học viên nắm được những thay đổi chính của Luật BHXH 2024 có hiệu lực từ 01/07/2025.","points":["Chế độ ngắn hạn gồm ốm đau, thai sản (chi từ quỹ ốm đau thai sản, doanh nghiệp đóng 3%) và tai nạn lao động – bệnh nghề nghiệp (quỹ riêng, doanh nghiệp đóng 0,5%).","Doanh nghiệp là đầu mối tiếp nhận giấy tờ, lập hồ sơ đề nghị, nhận và chi trả hoặc theo dõi việc cơ quan BHXH chi trả cho người lao động.","Căn cứ tính mức hưởng là tiền lương tháng đóng BHXH, vì vậy đóng đúng lương ngay từ đầu chính là bảo vệ quyền lợi người lao động.","Luật BHXH 2024 điều chỉnh một số điều kiện, thời gian hưởng và thủ tục; chi tiết từng chế độ áp dụng theo quy định hiện hành và văn bản hướng dẫn.","Người lao động nghỉ hưởng chế độ không hưởng lương từ doanh nghiệp cho những ngày đó, trừ khi quy chế nội bộ có chính sách hỗ trợ thêm."],"case":"Công ty TNHH Minh An trả nguyên lương cho nhân viên nghỉ ốm 5 ngày rồi vẫn làm hồ sơ hưởng ốm đau, dẫn đến trả trùng. Kế toán điều chỉnh: những ngày nghỉ hưởng chế độ không tính lương, công ty bổ sung khoản hỗ trợ ốm đau riêng trong quy chế phúc lợi nếu muốn chi thêm.","trend":"Giai đoạn 2026–2030, giải quyết chế độ được dự kiến ngày càng tự động dựa trên dữ liệu y tế và BHXH liên thông. Học viên nên quen quy trình số và kiểm soát dữ liệu đầu vào.","practice":"Lập bảng tổng hợp một trang về ba nhóm chế độ: quỹ chi trả, căn cứ tính, giấy tờ chính và người phụ trách trong doanh nghiệp.","takeaway":"Đóng đúng hôm nay là quyền lợi đầy đủ ngày mai."}},{"id":"KH051","code":"kh051","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Xây dựng bảng lương và quy chế lương thưởng","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học hướng dẫn doanh nghiệp xây dựng thang bảng lương và quy chế lương thưởng vừa tuân thủ Bộ luật Lao động 2019, vừa tạo động lực và tối ưu chi phí thuế, bảo hiểm. Bạn đi từ phân tích vị trí, định giá công việc, thiết kế cấu trúc lương 3P đến soạn quy chế và mô phỏng tác động tài chính trên tình huống doanh nghiệp Việt Nam, với bộ mẫu dùng ngay. Kết quả là một hệ thống lương minh bạch, có căn cứ pháp lý, dễ vận hành và sẵn sàng tự động hóa.","a":"Chủ doanh nghiệp, trưởng phòng nhân sự, chuyên viên C&B và kế toán tiền lương tại doanh nghiệp vừa và nhỏ muốn xây dựng hoặc tái cấu trúc hệ thống lương thưởng.","o":["Xây dựng được thang bảng lương có bậc, hệ số và khoảng lương phù hợp quy định và đặc thù doanh nghiệp.","Thiết kế được cơ cấu thu nhập gồm lương cơ bản, phụ cấp, lương hiệu quả và thưởng cho ít nhất 3 nhóm vị trí.","Soạn hoàn chỉnh quy chế lương thưởng làm căn cứ chi trả và tính chi phí được trừ khi tính thuế TNDN.","Mô phỏng được tác động của phương án lương đến chi phí doanh nghiệp, bảo hiểm và thuế TNCN của người lao động.","Thiết lập được bộ chỉ số theo dõi quỹ lương và kế hoạch rà soát lương hằng năm."],"k":"Lương trả cảm tính khiến người giỏi ra đi và chi phí bị loại khi quyết toán: năm 2026 là lúc dựng lại hệ thống lương bài bản.","w":["Giảm trừ gia cảnh thuế TNCN tăng lên 15,5 triệu đồng mỗi tháng cho bản thân và 6,2 triệu đồng cho người phụ thuộc từ kỳ 2026, cơ cấu thu nhập cần được thiết kế lại cho hợp lý.","Luật BHXH 2024 hiệu lực 01/07/2025 và việc liên thông dữ liệu thuế, bảo hiểm khiến cách đặt tên, chia nhỏ khoản lương để né đóng trở nên rủi ro cao.","Thị trường lao động cạnh tranh về kỹ năng số và AI, doanh nghiệp cần hệ thống trả lương theo năng lực và hiệu quả để giữ người giỏi."],"dl":["Bộ mẫu Excel xây dựng thang bảng lương, định giá công việc theo điểm và mô phỏng chi phí lương.","Mẫu quy chế lương thưởng có chú thích từng điều khoản, sẵn sàng tùy chỉnh theo doanh nghiệp.","Checklist tuân thủ pháp lý và thuế cho hệ thống lương gồm công khai, tham khảo ý kiến, hồ sơ chi phí.","Bộ câu lệnh AI (prompt) hỗ trợ viết mô tả công việc, phân tích dữ liệu lương thị trường và soạn thông báo chính sách."],"ls":["Khung pháp lý tiền lương 2026: quyền tự chủ đi kèm trách nhiệm","Phân tích và định giá công việc: nền móng của mọi thang lương","Thiết kế thang bảng lương: ngạch, bậc, khoảng lương và độ giãn cách","Cơ cấu thu nhập 3P: trả cho vị trí, năng lực và hiệu quả","Phụ cấp, phúc lợi và thưởng: tối ưu hợp pháp với thuế và bảo hiểm","Soạn quy chế lương thưởng: văn bản vận hành và bằng chứng pháp lý","Mô phỏng tài chính quỹ lương: chi phí, bảo hiểm và thuế trong một bảng","Hệ thống lương thông minh: AI, dữ liệu và tự động hóa bảng lương"],"l1":{"t":"Khung pháp lý tiền lương 2026: quyền tự chủ đi kèm trách nhiệm","sum":"Bài hệ thống các quy định của Bộ luật Lao động 2019 về tiền lương và những liên kết với BHXH, thuế. Học viên biết rõ doanh nghiệp được tự quyết điều gì và phải tuân thủ điều gì.","points":["Doanh nghiệp tự xây dựng thang lương, bảng lương và định mức lao động làm cơ sở tuyển dụng, thỏa thuận lương và trả lương theo Bộ luật Lao động 2019.","Khi xây dựng phải tham khảo ý kiến tổ chức đại diện người lao động tại cơ sở nếu có và công bố công khai tại nơi làm việc trước khi thực hiện.","Mức lương theo công việc hoặc chức danh không được thấp hơn mức lương tối thiểu vùng theo quy định hiện hành.","Trả lương làm thêm giờ ít nhất 150% ngày thường, 200% ngày nghỉ hằng tuần, 300% ngày lễ tết theo Bộ luật Lao động 2019; làm ban đêm có mức trả thêm theo quy định.","Thang bảng lương liên quan trực tiếp đến tiền lương đóng bảo hiểm và hồ sơ chi phí lương được trừ khi tính thuế TNDN."],"case":"Công ty TNHH Minh An có 40 lao động nhưng không có thang bảng lương, mỗi người một mức thỏa thuận riêng. Khi cơ quan thuế xem xét chi phí lương, công ty khó chứng minh căn cứ; sau đó công ty xây dựng thang bảng lương, lấy ý kiến người lao động và công bố công khai.","trend":"Xu hướng minh bạch tiền lương và công bằng thu nhập đang lan rộng trên thế giới. Doanh nghiệp Việt Nam nên chuẩn bị chính sách lương rõ ràng, giải thích được.","practice":"Rà soát hệ thống lương hiện tại của doanh nghiệp theo 8 câu hỏi tuân thủ pháp lý trong checklist và ghi lại các điểm thiếu.","takeaway":"Tự chủ về lương là quyền, minh bạch về lương là nghĩa vụ."}},{"id":"KH052","code":"kh052","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Hợp đồng lao động và nội quy lao động đúng luật","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp doanh nghiệp xây dựng bộ hợp đồng lao động, hợp đồng thử việc và nội quy lao động đúng Bộ luật Lao động 2019, đồng bộ với Luật BHXH 2024 và quy định bảo vệ dữ liệu cá nhân từ 2026. Mỗi bài đi kèm tình huống tranh chấp thật đã được ẩn danh và bộ mẫu có thể chỉnh sửa dùng ngay trong ngày. Kết thúc khoá, học viên tự tay hoàn thiện bộ hồ sơ lao động chuẩn cho chính doanh nghiệp mình.","a":"Dành cho nhân viên nhân sự, kế toán kiêm nhân sự và chủ doanh nghiệp nhỏ đang tự soạn và quản lý hồ sơ lao động.","o":["Chọn đúng loại hợp đồng lao động cho từng vị trí và lập được bảng theo dõi số lần ký, ngày hết hạn của toàn bộ nhân sự.","Soạn được hợp đồng lao động, hợp đồng thử việc và phụ lục đủ nội dung bắt buộc trong vòng 30 phút cho mỗi trường hợp.","Xây dựng được nội quy lao động đúng cấu trúc luật định và hoàn thiện hồ sơ đăng ký nội quy khi doanh nghiệp có từ 10 lao động.","Tự kiểm tra được ít nhất 15 lỗi phổ biến trong hồ sơ lao động hiện có và lập kế hoạch khắc phục.","Thiết lập được quy trình ký, lưu trữ hợp đồng lao động điện tử có điều khoản bảo vệ dữ liệu cá nhân."],"k":"Một bản hợp đồng lao động sao chép trên mạng có thể khiến doanh nghiệp thua kiện và truy đóng bảo hiểm hàng trăm triệu đồng.","w":["Luật BHXH 2024 có hiệu lực từ 01/07/2025 mở rộng đối tượng tham gia và siết xử lý trốn đóng, nên hợp đồng ghi sai bản chất hoặc tiền lương sẽ bị phát hiện nhanh hơn.","Luật Bảo vệ dữ liệu cá nhân (Luật 91/2025/QH15) hiệu lực từ 01/01/2026 buộc doanh nghiệp có điều khoản và quy trình xử lý dữ liệu của người lao động ngay từ khâu ký hợp đồng.","Hợp đồng lao động điện tử, ký số và quản lý hồ sơ trên nền tảng số đang trở thành chuẩn, doanh nghiệp chuẩn hóa mẫu sớm sẽ số hóa nhanh và ít rủi ro hơn."],"dl":["Bộ mẫu Word: hợp đồng lao động xác định và không xác định thời hạn, hợp đồng thử việc, 6 mẫu phụ lục thường dùng.","Mẫu nội quy lao động khung kèm hồ sơ đăng ký nội quy và biên bản lấy ý kiến tổ chức đại diện người lao động.","Checklist 40 điểm rà soát hồ sơ lao động và file Excel theo dõi hạn hợp đồng có cảnh báo tự động.","Bộ câu lệnh AI (prompt) để soạn, so sánh và rà soát điều khoản hợp đồng lao động an toàn, không lộ dữ liệu nhân viên."],"ls":["Quan hệ lao động 2026: vì sao hồ sơ chuẩn là lá chắn đầu tiên","Chọn đúng loại hợp đồng lao động cho từng vị trí","Nội dung bắt buộc và điều khoản bảo vệ doanh nghiệp","Thử việc đúng luật: ngắn, rõ, có đánh giá","Phụ lục, sửa đổi và tạm hoãn hợp đồng lao động","Nội quy lao động: luật chơi chung của doanh nghiệp","Đăng ký nội quy và hồ sơ đi kèm","Hợp đồng điện tử, AI và bộ hồ sơ lao động chuẩn"],"l1":{"t":"Quan hệ lao động 2026: vì sao hồ sơ chuẩn là lá chắn đầu tiên","sum":"Bài mở đầu xác định khi nào phát sinh quan hệ lao động và vì sao hồ sơ lao động là gốc của tính lương, BHXH, thuế TNCN và chi phí được trừ. Học viên nhận diện rủi ro khi gọi tên sai bản chất hợp đồng.","points":["Theo Bộ luật Lao động 2019, mọi thỏa thuận có việc làm có trả công, có sự quản lý, điều hành, giám sát đều được coi là hợp đồng lao động, dù đặt tên là hợp đồng dịch vụ hay cộng tác viên.","Hồ sơ lao động quyết định nghĩa vụ đóng BHXH, BHYT, BHTN với tỷ lệ doanh nghiệp 21,5% và người lao động 10,5%, cùng KPCĐ 2% do doanh nghiệp đóng.","Chi phí tiền lương chỉ được trừ khi tính thuế TNDN nếu có hợp đồng, quy chế, chứng từ chi trả hợp lệ; khoản chi từ 5 triệu đồng phải thanh toán không dùng tiền mặt theo NĐ 181/2025.","Thỏa thuận trái luật theo hướng bất lợi cho người lao động bị vô hiệu dù hai bên đã ký; thỏa thuận có lợi hơn luật thì được khuyến khích.","Bộ hồ sơ tối thiểu gồm: hồ sơ cá nhân, hợp đồng và phụ lục, quyết định lương, tờ khai BHXH, cam kết thuế TNCN (nếu có), bản đồng ý xử lý dữ liệu cá nhân."],"case":"Công ty TNHH Minh An ký 'hợp đồng cộng tác viên' với 6 nhân viên bán hàng làm toàn thời gian, chấm công hằng ngày, lương 9 triệu đồng/tháng. Khi thanh tra, cơ quan BHXH xác định đây là quan hệ lao động và yêu cầu truy đóng toàn bộ kèm tiền chậm đóng. Cách xử lý đúng: chuyển sang hợp đồng lao động, kê khai tăng lao động và lập quy chế lương làm căn cứ.","trend":"Dữ liệu BHXH, thuế và định danh điện tử đang được liên thông, xu hướng 2026–2030 là cơ quan quản lý tự động đối chiếu thu nhập với hồ sơ đóng bảo hiểm. Học viên nên chuẩn hóa dữ liệu nhân sự ngay từ bây giờ.","practice":"Liệt kê toàn bộ người đang làm việc cho doanh nghiệp, phân loại theo bản chất (lao động, dịch vụ, khoán việc) và đánh dấu trường hợp đặt tên sai.","takeaway":"Tên hợp đồng không quyết định bản chất, cách làm việc mới quyết định."}},{"id":"KH053","code":"kh053","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Chấm công, tính lương và phiếu lương thực hành","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học hướng dẫn trọn quy trình từ chấm công, tính lương, trích bảo hiểm, khấu trừ thuế TNCN đến lập phiếu lương và hạch toán, cập nhật mức giảm trừ gia cảnh mới từ 2026. Học viên thực hành trên file Excel mẫu với dữ liệu một doanh nghiệp 20 nhân sự, làm đến đâu kiểm tra đến đó. Kết quả là tự lập được bảng lương tháng chính xác, minh bạch và sẵn sàng tự động hóa.","a":"Dành cho người mới làm kế toán tiền lương, nhân viên hành chính nhân sự và chủ doanh nghiệp nhỏ tự tính lương.","o":["Lập được bảng chấm công tháng có phân loại ngày công, nghỉ phép, nghỉ lễ, làm thêm giờ.","Tính đúng lương thời gian, lương sản phẩm, tiền làm thêm giờ và các khoản phụ cấp cho 20 nhân sự trong 1 buổi.","Trích đúng BHXH, BHYT, BHTN, KPCĐ và khấu trừ thuế TNCN theo giảm trừ gia cảnh năm 2026.","Lập được phiếu lương cá nhân rõ ràng và gửi hàng loạt an toàn, bảo mật.","Hạch toán và đối chiếu được chi phí lương, các khoản trích theo lương với sổ sách cuối tháng."],"k":"Từ kỳ lương 2026, giảm trừ gia cảnh tăng lên 15,5 triệu đồng: bảng lương tính theo cách cũ sẽ khấu trừ sai thuế ngay tháng đầu.","w":["Từ kỳ tính thuế 2026, giảm trừ gia cảnh là 15,5 triệu đồng/tháng cho bản thân và 6,2 triệu đồng/tháng cho mỗi người phụ thuộc, bắt buộc cập nhật công thức bảng lương.","Luật BHXH 2024 hiệu lực từ 01/07/2025 thay đổi nhiều quy định về căn cứ đóng và quản lý thu, sai sót bảng lương sẽ bị đối chiếu nhanh trên hệ thống điện tử.","Chấm công bằng ứng dụng, khuôn mặt, GPS và bảng lương tự động đang phổ biến, người làm lương cần hiểu nghiệp vụ để thiết lập và kiểm soát máy chứ không chỉ nhập liệu."],"dl":["File Excel bảng lương mẫu có công thức tính BH, thuế TNCN biểu lũy tiến 7 bậc và giảm trừ 2026.","Mẫu bảng chấm công, phiếu lương cá nhân và bảng tổng hợp chi trả qua ngân hàng.","Checklist 20 điểm kiểm tra bảng lương trước khi trình ký và chi trả.","Bộ câu lệnh AI (prompt) để kiểm tra công thức Excel, giải thích phiếu lương và soạn thông báo lương."],"ls":["Bản đồ quy trình lương từ A đến Z","Chấm công và quản lý ngày nghỉ không sai một ngày","Lương thời gian, lương sản phẩm và tiền làm thêm giờ","Phụ cấp, thưởng và phúc lợi: khoản nào chịu BH, khoản nào chịu thuế","Trích bảo hiểm bắt buộc và kinh phí công đoàn","Khấu trừ thuế TNCN với giảm trừ gia cảnh 2026","Bảng lương, phiếu lương và tự động hóa bằng Excel","Kiểm tra, chi trả và hạch toán tiền lương"],"l1":{"t":"Bản đồ quy trình lương từ A đến Z","sum":"Bài vẽ toàn cảnh chu trình lương hàng tháng và vai trò của từng bộ phận. Học viên biết dữ liệu nào cần thu thập, khi nào và từ ai.","points":["Chu trình gồm 7 bước: chốt chấm công, tổng hợp biến động nhân sự, tính lương gộp, trích bảo hiểm, tính thuế TNCN, duyệt và chi trả, hạch toán và báo cáo.","Căn cứ pháp lý gồm hợp đồng lao động, quy chế lương thưởng, thang bảng lương, quyết định điều chỉnh lương và nội quy lao động.","Lập lịch lương cố định, ví dụ: ngày 1–3 chốt công, ngày 4–5 tính và kiểm tra, ngày 6 trình duyệt, ngày 8–10 chi trả.","Tiền lương phải trả đầy đủ, đúng hạn; trả qua tài khoản để có chứng từ và đáp ứng điều kiện thanh toán không dùng tiền mặt.","Phân quyền rõ người lập, người kiểm tra, người duyệt để hạn chế sai sót và gian lận."],"case":"Công ty TNHH Thực phẩm Tân Phú thường trả lương trễ 5–7 ngày vì các phòng gửi công rời rạc qua tin nhắn. Sau khi áp dụng lịch lương và biểu mẫu chốt công chung, việc trả lương đúng ngày 10 hàng tháng ổn định trong 3 tháng. Bài học: quy trình rõ quan trọng hơn công cụ.","trend":"Xu hướng 2026–2030 là bảng lương chạy tự động từ dữ liệu chấm công và hệ thống nhân sự. Người làm lương nên chuyển vai trò từ nhập liệu sang kiểm soát và phân tích.","practice":"Vẽ sơ đồ chu trình lương của doanh nghiệp bạn, ghi rõ người phụ trách và hạn chót từng bước.","takeaway":"Lương đúng bắt đầu từ lịch lương rõ."}},{"id":"KH054","code":"kh054","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Tuyển dụng và giữ chân nhân sự thế hệ Gen Z","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp doanh nghiệp vừa và nhỏ xây dựng quy trình tuyển dụng hiện đại và hệ thống giữ chân phù hợp tâm lý, kỳ vọng của thế hệ Gen Z. Phương pháp học dựa trên tình huống thật tại doanh nghiệp Việt, bộ mẫu mô tả công việc, kịch bản phỏng vấn và lộ trình hội nhập dùng ngay. Kết quả là giảm thời gian tuyển, tăng tỷ lệ nhân viên mới ở lại sau 12 tháng với ngân sách hợp lý.","a":"Dành cho chủ doanh nghiệp nhỏ, quản lý trực tiếp và chuyên viên nhân sự đang tuyển dụng, quản lý nhân viên trẻ.","o":["Lập được kế hoạch tuyển dụng năm gắn với kế hoạch kinh doanh và ngân sách.","Viết được mô tả công việc và tin tuyển dụng hấp dẫn Gen Z, đo được tỷ lệ ứng tuyển theo kênh.","Thực hiện phỏng vấn có cấu trúc với bộ câu hỏi hành vi và phiếu chấm điểm thống nhất.","Triển khai được chương trình hội nhập 90 ngày giúp giảm tỷ lệ nghỉ việc sớm.","Thiết kế được gói giữ chân gồm đãi ngộ, lộ trình phát triển và văn hóa phản hồi trong ngân sách nhỏ."],"k":"Gen Z đang chiếm phần lớn lực lượng lao động trẻ: tuyển được đã khó, giữ chân qua năm đầu còn khó hơn.","w":["Gen Z ưu tiên ý nghĩa công việc, sự linh hoạt và cơ hội học hỏi; doanh nghiệp chỉ cạnh tranh bằng lương sẽ liên tục mất người.","AI đang thay đổi tuyển dụng: sàng lọc hồ sơ tự động, phỏng vấn video, đánh giá kỹ năng trực tuyến, đòi hỏi nhà tuyển dụng dùng công nghệ có trách nhiệm.","Luật Bảo vệ dữ liệu cá nhân (Luật 91/2025/QH15) hiệu lực từ 01/01/2026 đặt ra nghĩa vụ mới khi thu thập, lưu trữ hồ sơ ứng viên."],"dl":["Bộ mẫu mô tả công việc, tin tuyển dụng và phiếu yêu cầu tuyển dụng.","Ngân hàng 60 câu hỏi phỏng vấn hành vi kèm phiếu chấm điểm và kịch bản phỏng vấn.","Checklist hội nhập 90 ngày và mẫu khảo sát gắn kết nhân viên định kỳ.","Bộ câu lệnh AI (prompt) viết tin tuyển dụng, tạo câu hỏi phỏng vấn, phân tích lý do nghỉ việc."],"ls":["Hiểu Gen Z: kỳ vọng thật đằng sau những định kiến","Hoạch định tuyển dụng gắn với kế hoạch kinh doanh","Mô tả công việc và thương hiệu nhà tuyển dụng","Kênh tuyển dụng số và sàng lọc với AI có trách nhiệm","Phỏng vấn có cấu trúc: chọn đúng người ngay lần đầu","Hội nhập 90 ngày: quyết định ở lại hay ra đi","Đãi ngộ và giữ chân với ngân sách nhỏ","Lộ trình phát triển và văn hóa phản hồi"],"l1":{"t":"Hiểu Gen Z: kỳ vọng thật đằng sau những định kiến","sum":"Bài phân tích đặc điểm, động lực và kỳ vọng của thế hệ Gen Z tại nơi làm việc. Học viên thay định kiến bằng dữ liệu để thiết kế chính sách phù hợp.","points":["Gen Z (sinh khoảng 1997–2012) lớn lên cùng internet, quen phản hồi nhanh, đánh giá cao sự minh bạch và tính xác thực của tổ chức.","Ba động lực thường gặp: được học hỏi và phát triển nhanh, linh hoạt về thời gian địa điểm, công việc có ý nghĩa và được ghi nhận.","Gen Z không ngại nghỉ việc nếu thấy văn hóa độc hại hoặc quản lý thiếu tôn trọng; người quản lý trực tiếp quyết định phần lớn trải nghiệm.","Sức khỏe tinh thần và cân bằng công việc – cuộc sống là chủ đề quan trọng; chính sách nghỉ ngơi hợp lý là điểm cộng lớn.","Tránh khái quát hóa: mỗi cá nhân khác nhau, nên dùng khảo sát nội bộ để hiểu nhân viên của chính doanh nghiệp."],"case":"Công ty TNHH Truyền thông Ánh Dương mất 5/8 nhân viên trẻ trong năm đầu dù trả lương cao hơn thị trường 10%. Khảo sát nghỉ việc cho thấy lý do chính là không có phản hồi định kỳ và không thấy lộ trình. Sau khi áp dụng họp 1-1 hai tuần một lần và lộ trình 12 tháng, tỷ lệ nghỉ sớm giảm rõ rệt.","trend":"Đến 2030, Gen Z và thế hệ Alpha dự kiến chiếm tỷ trọng lớn lực lượng lao động. Doanh nghiệp nên xây năng lực quản lý thế hệ trẻ cho đội ngũ trưởng nhóm ngay từ bây giờ.","practice":"Thực hiện khảo sát 10 câu với nhân viên trẻ hiện tại về điều họ đánh giá cao và điều khiến họ muốn rời đi.","takeaway":"Gen Z không khó giữ, chỉ khó giữ bằng cách cũ."}},{"id":"KH055","code":"kh055","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Đánh giá hiệu quả công việc bằng KPI và OKR","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp doanh nghiệp xây hệ thống quản trị hiệu suất kết hợp KPI và OKR, đi từ chiến lược xuống mục tiêu từng phòng ban, từng cá nhân và gắn với lương thưởng. Học viên làm việc trên tình huống thật, bộ thư viện KPI theo phòng ban và dashboard mẫu, có thể áp dụng ngay cho chu kỳ quý tới. Kết quả là một hệ thống đo lường minh bạch, được nhân viên chấp nhận và tạo động lực thật.","a":"Dành cho chủ doanh nghiệp, trưởng phòng, chuyên viên nhân sự và kế toán quản trị muốn triển khai KPI, OKR bài bản.","o":["Phân tầng được mục tiêu chiến lược thành KPI cấp công ty, phòng ban và cá nhân với tối đa 5–7 chỉ số mỗi vị trí.","Viết được OKR quý gồm 2–3 mục tiêu và 3–4 kết quả then chốt đo được cho một bộ phận.","Thiết lập được bảng theo dõi KPI tự động cập nhật từ dữ liệu sẵn có.","Tổ chức được đánh giá định kỳ và họp 1-1 theo kịch bản chuẩn.","Thiết kế được cơ chế thưởng gắn KPI có quy chế, vừa tạo động lực vừa là chi phí hợp lý."],"k":"Nhiều doanh nghiệp có KPI trên giấy nhưng không ai đạt, không ai tin: vấn đề nằm ở cách thiết kế, không phải ở con người.","w":["Môi trường kinh doanh 2026 biến động nhanh, chu kỳ mục tiêu năm cứng nhắc không còn phù hợp; OKR theo quý giúp doanh nghiệp điều chỉnh kịp thời.","Dữ liệu từ phần mềm kế toán, CRM, chấm công cho phép đo KPI tự động gần thời gian thực thay vì tổng hợp thủ công cuối tháng.","Làm việc kết hợp và đội ngũ trẻ đòi hỏi đánh giá dựa trên kết quả, minh bạch và phản hồi thường xuyên thay vì đánh giá theo cảm tính."],"dl":["Thư viện 150 KPI theo phòng ban: kinh doanh, kế toán, nhân sự, vận hành, marketing, chăm sóc khách hàng.","Mẫu Excel thẻ KPI cá nhân, bảng OKR quý và dashboard tổng hợp.","Quy trình SOP chu kỳ đánh giá hiệu suất và kịch bản họp 1-1.","Bộ câu lệnh AI (prompt) gợi ý KPI, kiểm tra tiêu chuẩn SMART và tóm tắt kết quả đánh giá."],"ls":["KPI, OKR, BSC: chọn công cụ nào cho doanh nghiệp bạn","Từ chiến lược đến mục tiêu phân tầng","Thiết kế KPI chuẩn SMART và có nguồn dữ liệu","OKR theo quý: đặt mục tiêu tham vọng mà vẫn đo được","Dashboard KPI tự động từ dữ liệu sẵn có","Đánh giá, phản hồi và họp 1-1 hiệu quả","Gắn KPI với lương thưởng đúng luật và tạo động lực","Triển khai hệ thống và tránh những sai lầm phổ biến"],"l1":{"t":"KPI, OKR, BSC: chọn công cụ nào cho doanh nghiệp bạn","sum":"Bài phân biệt bản chất, mục đích và giới hạn của ba công cụ quản trị theo kết quả. Học viên chọn được mô hình phù hợp quy mô và giai đoạn phát triển.","points":["KPI là chỉ số đo hiệu suất của hoạt động thường xuyên, thường gắn với đánh giá và thu nhập.","OKR gồm mục tiêu truyền cảm hứng và kết quả then chốt đo được, dùng cho cải tiến, đột phá theo quý, thường không gắn trực tiếp lương.","BSC (thẻ điểm cân bằng) nhìn doanh nghiệp từ 4 góc độ: tài chính, khách hàng, quy trình nội bộ, học hỏi và phát triển.","Doanh nghiệp nhỏ có thể dùng KPI cho vận hành và OKR cho 1–2 mục tiêu chiến lược, không cần áp dụng đầy đủ BSC ngay.","Sai lầm phổ biến là sao chép bộ KPI của doanh nghiệp khác mà không gắn với chiến lược của mình."],"case":"Công ty TNHH Nội thất Hoàng Gia áp dụng nguyên bộ 25 KPI cho mỗi nhân viên kinh doanh lấy từ tài liệu mạng. Nhân viên không biết ưu tiên, kết quả đánh giá ai cũng 80–90% nhưng doanh thu giảm. Sau khi rút gọn còn 5 KPI gắn doanh thu, biên lợi nhuận, công nợ và khách hàng mới, kết quả bám sát thực tế hơn.","trend":"Mô hình kết hợp KPI cho vận hành và OKR cho đổi mới đang phổ biến tại doanh nghiệp tăng trưởng nhanh. Học viên nên thử OKR ở một bộ phận trước khi nhân rộng.","practice":"Liệt kê các chỉ số doanh nghiệp đang theo dõi, phân loại vào KPI vận hành hay mục tiêu đột phá phù hợp OKR.","takeaway":"KPI giữ cho máy chạy đều, OKR giúp máy chạy xa hơn."}},{"id":"KH056","code":"kh056","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Chấm dứt hợp đồng, trợ cấp thôi việc và kỷ luật lao động","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp doanh nghiệp xử lý đúng luật mọi tình huống chấm dứt hợp đồng lao động, tính chính xác trợ cấp thôi việc, mất việc làm và tổ chức kỷ luật lao động đúng trình tự. Phương pháp học dựa trên các tình huống tranh chấp điển hình, bảng tính trợ cấp và bộ biểu mẫu từ thông báo đến biên bản họp kỷ luật. Học viên ra về với khả năng tự đánh giá rủi ro trước khi ký bất kỳ quyết định chấm dứt hay kỷ luật nào.","a":"Dành cho trưởng phòng nhân sự, chuyên viên quan hệ lao động, kế toán tiền lương và chủ doanh nghiệp trực tiếp xử lý nghỉ việc, kỷ luật.","o":["Xác định đúng căn cứ chấm dứt hợp đồng cho từng tình huống và thời hạn báo trước tương ứng.","Tính chính xác trợ cấp thôi việc, trợ cấp mất việc làm, tiền phép năm chưa nghỉ và các khoản thanh toán cuối cùng.","Hoàn tất thủ tục chốt sổ BHXH, quyết toán thuế TNCN và hồ sơ thanh toán trong thời hạn 14 ngày làm việc.","Tổ chức được phiên họp xử lý kỷ luật đúng trình tự, đúng thời hiệu, có biên bản hợp lệ.","Tự đánh giá được rủi ro tranh chấp và chuẩn bị phương án thương lượng, hòa giải."],"k":"Một quyết định cho thôi việc sai trình tự có thể buộc doanh nghiệp nhận lại người lao động và trả lương cho toàn bộ những ngày không được làm việc.","w":["Luật BHXH 2024 hiệu lực từ 01/07/2025 thay đổi một số quy định về bảo hiểm thất nghiệp và chốt sổ, ảnh hưởng trực tiếp thủ tục khi người lao động nghỉ việc.","Tái cấu trúc, tự động hóa và ứng dụng AI khiến nhiều doanh nghiệp phải cắt giảm hoặc thay đổi vị trí, đòi hỏi xử lý đúng quy định về thay đổi cơ cấu, công nghệ.","Người lao động ngày càng hiểu luật và dễ tiếp cận tư vấn trực tuyến, tranh chấp lao động có xu hướng tăng nếu doanh nghiệp xử lý cảm tính."],"dl":["Bộ 15 mẫu văn bản: thông báo chấm dứt, quyết định thôi việc, thỏa thuận chấm dứt, biên bản vi phạm, giấy triệu tập, biên bản họp kỷ luật, quyết định kỷ luật.","File Excel tính trợ cấp thôi việc, mất việc làm, phép năm và thanh toán cuối cùng.","Sơ đồ quyết định chọn căn cứ chấm dứt hợp đồng và checklist trình tự kỷ luật lao động.","Bộ câu lệnh AI (prompt) rà soát rủi ro quyết định chấm dứt, soạn thư thông báo nhân văn và chuẩn bị nội dung hòa giải."],"ls":["Bản đồ các trường hợp chấm dứt hợp đồng lao động","Người lao động đơn phương chấm dứt hợp đồng","Doanh nghiệp đơn phương chấm dứt: chỉ khi đủ căn cứ","Trợ cấp thôi việc, mất việc làm và các khoản thanh toán cuối","Thủ tục 14 ngày: thanh toán, chốt sổ BHXH và thuế TNCN","Kỷ luật lao động: nguyên tắc và hình thức","Trình tự xử lý kỷ luật và sa thải","Tranh chấp lao động và hệ thống phòng ngừa rủi ro"],"l1":{"t":"Bản đồ các trường hợp chấm dứt hợp đồng lao động","sum":"Bài hệ thống các căn cứ chấm dứt hợp đồng theo Bộ luật Lao động 2019 và hệ quả pháp lý của từng căn cứ. Học viên dùng sơ đồ để chọn đúng con đường.","points":["Nhóm căn cứ chính: hết hạn hợp đồng, hoàn thành công việc, hai bên thỏa thuận, người lao động đơn phương, người sử dụng lao động đơn phương, sa thải, thay đổi cơ cấu công nghệ hoặc lý do kinh tế, các trường hợp khách quan.","Mỗi căn cứ kéo theo nghĩa vụ khác nhau: báo trước, trợ cấp thôi việc hay mất việc làm, thủ tục.","Thỏa thuận chấm dứt là phương án an toàn nhất khi lập văn bản rõ ràng các khoản thanh toán và cam kết không khiếu nại.","Hết hạn hợp đồng vẫn phải thông báo bằng văn bản cho người lao động theo thời hạn quy định trước ngày hết hạn.","Chấm dứt trái pháp luật dẫn đến nghĩa vụ nhận lại người lao động, trả lương những ngày không được làm việc, đóng BHXH và bồi thường theo luật."],"case":"Công ty TNHH In ấn Hoàng Phát muốn cho một nhân viên nghỉ vì hiệu suất thấp, giám đốc yêu cầu ra quyết định thôi việc ngay. Do không có căn cứ đánh giá 'thường xuyên không hoàn thành công việc' theo quy chế, quyết định có rủi ro bị tuyên trái luật. Doanh nghiệp chuyển sang thương lượng thỏa thuận chấm dứt với khoản hỗ trợ 2 tháng lương và tránh được tranh chấp.","trend":"Tái cấu trúc do tự động hóa và AI dự kiến diễn ra mạnh 2026–2030. Doanh nghiệp nên có chính sách đào tạo lại và chuyển đổi vị trí trước khi cắt giảm.","practice":"Dùng sơ đồ quyết định để phân tích 3 tình huống nghỉ việc gần nhất tại doanh nghiệp và xác định căn cứ phù hợp.","takeaway":"Chọn sai căn cứ là thua ngay từ bước đầu."}},{"id":"KH057","code":"kh057","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"HR 4.0: số hóa hồ sơ, chấm công và lương","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp doanh nghiệp nhỏ và vừa chuyển đổi số công tác nhân sự: số hóa hồ sơ, chấm công thông minh, bảng lương tự động và cổng thông tin nhân viên. Học viên đi theo lộ trình từng bước với tình huống thật, bộ tiêu chí chọn phần mềm và mẫu dữ liệu chuẩn có thể dùng ngay. Kết quả là giảm mạnh thời gian xử lý thủ công, dữ liệu chính xác và tuân thủ quy định bảo vệ dữ liệu cá nhân từ 2026.","a":"Dành cho nhân viên hành chính nhân sự, kế toán kiêm nhân sự và chủ doanh nghiệp nhỏ muốn bắt đầu chuyển đổi số nhân sự.","o":["Chuẩn hóa được bộ dữ liệu nhân sự gốc với mã nhân viên và trường thông tin thống nhất.","Số hóa và sắp xếp được hồ sơ nhân sự theo cấu trúc thư mục có phân quyền truy cập.","Thiết lập được chấm công điện tử và quy trình đơn từ nghỉ phép trực tuyến.","Liên kết được dữ liệu chấm công với bảng lương tự động, giảm ít nhất một nửa thời gian tính lương.","Lựa chọn được phần mềm nhân sự phù hợp dựa trên bộ tiêu chí đánh giá rõ ràng."],"k":"Bộ phận nhân sự vẫn dành nhiều ngày mỗi tháng cho giấy tờ, chấm công và bảng lương thủ công trong khi công cụ số đã sẵn và chi phí ngày càng thấp.","w":["Luật Bảo vệ dữ liệu cá nhân (Luật 91/2025/QH15) hiệu lực từ 01/01/2026 buộc doanh nghiệp quản lý hồ sơ nhân sự có phân quyền, có sự đồng ý và biện pháp bảo vệ.","Hợp đồng điện tử, chữ ký số, giao dịch BHXH và thuế điện tử đã phổ biến; Luật Giao dịch điện tử 2023 công nhận giá trị pháp lý của thông điệp dữ liệu.","Phần mềm nhân sự trên nền tảng đám mây và trợ lý AI giúp doanh nghiệp nhỏ tự động hóa với chi phí thấp, ai đi trước sẽ tiết kiệm nhân lực rõ rệt."],"dl":["Mẫu Excel dữ liệu nhân sự gốc và cấu trúc thư mục hồ sơ số chuẩn.","Bảng tiêu chí so sánh và chọn phần mềm nhân sự, chấm công, tính lương.","Mẫu thông báo và văn bản đồng ý xử lý dữ liệu cá nhân của người lao động.","Bộ câu lệnh AI (prompt) cho nhân sự: soạn thông báo, trả lời câu hỏi chính sách, kiểm tra công thức lương."],"ls":["HR 4.0 là gì và bắt đầu từ đâu","Dữ liệu nhân sự gốc: một nguồn sự thật duy nhất","Số hóa hồ sơ nhân sự và bảo vệ dữ liệu cá nhân","Chấm công thông minh và đơn từ trực tuyến","Bảng lương tự động từ dữ liệu chấm công","Cổng thông tin nhân viên và trợ lý AI cho nhân sự","Chọn phần mềm nhân sự phù hợp và đúng ngân sách","Lộ trình chuyển đổi số nhân sự 90 ngày"],"l1":{"t":"HR 4.0 là gì và bắt đầu từ đâu","sum":"Bài giới thiệu khái niệm chuyển đổi số nhân sự, lợi ích và lộ trình phù hợp doanh nghiệp nhỏ. Học viên đánh giá được mức độ số hóa hiện tại của doanh nghiệp.","points":["HR 4.0 là việc dùng công nghệ số, dữ liệu và tự động hóa để quản lý vòng đời nhân viên từ tuyển dụng đến nghỉ việc.","Bốn cấp độ: giấy tờ thủ công, Excel rời rạc, phần mềm từng mảng, hệ thống tích hợp có dữ liệu liên thông.","Bắt đầu từ những việc lặp lại nhiều nhất: chấm công, nghỉ phép, tính lương, lưu hồ sơ.","Chuyển đổi số không phải mua phần mềm, mà là chuẩn hóa quy trình và dữ liệu trước rồi mới chọn công cụ.","Đo kết quả bằng chỉ số: số giờ xử lý mỗi tháng, số lỗi lương, thời gian phản hồi đơn từ."],"case":"Công ty TNHH Nhựa Tân Tiến có 60 nhân sự, nhân viên hành chính mất khoảng 5 ngày mỗi tháng tổng hợp công và đơn nghỉ phép giấy. Đánh giá cho thấy doanh nghiệp ở cấp độ 2 với 6 file Excel rời. Lộ trình được chọn: chuẩn hóa dữ liệu gốc, áp dụng chấm công điện tử, sau đó tự động hóa bảng lương.","trend":"Đến 2030, hệ thống nhân sự tích hợp AI dự kiến hỗ trợ trả lời câu hỏi nhân viên, dự báo nghỉ việc và gợi ý đào tạo. Doanh nghiệp nhỏ nên xây dữ liệu sạch từ bây giờ.","practice":"Tự chấm điểm mức độ số hóa nhân sự của doanh nghiệp theo bảng 4 cấp độ và liệt kê 3 việc tốn thời gian nhất.","takeaway":"Chuẩn hóa trước, mua phần mềm sau."}},{"id":"KH058","code":"kh058","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Lao động nước ngoài: giấy phép lao động và thuế","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học trang bị trọn bộ nghiệp vụ sử dụng lao động nước ngoài: giải trình nhu cầu, giấy phép lao động, thị thực, thẻ tạm trú, hợp đồng, bảo hiểm và đặc biệt là thuế TNCN, chi phí được trừ. Học viên giải các tình huống thật với chuyên gia, nhà quản lý, nhà đầu tư nước ngoài, thực hành quy đổi lương net sang gross và quyết toán thuế. Kết quả là doanh nghiệp tuân thủ đầy đủ, tối ưu chi phí hợp pháp và tự tin trước thanh tra lao động, thuế.","a":"Dành cho trưởng phòng nhân sự, kế toán trưởng, chuyên viên C&B và tư vấn viên phục vụ doanh nghiệp FDI hoặc doanh nghiệp có chuyên gia nước ngoài.","o":["Xác định đúng trường hợp phải cấp giấy phép lao động, trường hợp miễn và lập được kế hoạch hồ sơ theo thời gian.","Soạn được hợp đồng lao động với người nước ngoài đúng thời hạn giấy phép và có điều khoản lương net, phúc lợi rõ ràng.","Xác định được tình trạng cư trú thuế và tính đúng thuế TNCN cho người cư trú, không cư trú.","Quy đổi được lương net sang gross và xử lý đúng các khoản phúc lợi đặc thù như tiền nhà, học phí, vé máy bay.","Lập được hồ sơ quyết toán thuế, hồ sơ chứng minh chi phí được trừ và bộ kiểm soát rủi ro tổng hợp."],"k":"Một chuyên gia nước ngoài thiếu giấy phép lao động có thể kéo theo xử phạt, trục xuất và cả khoản lương hàng tỷ đồng bị loại khỏi chi phí.","w":["Dòng vốn FDI vào sản xuất công nghệ cao, bán dẫn, năng lượng xanh giai đoạn 2025–2030 kéo theo nhu cầu chuyên gia nước ngoài tăng mạnh.","Quy định về lao động nước ngoài, giấy phép lao động và thủ tục hành chính đang được cải cách, chuyển sang xử lý trực tuyến; doanh nghiệp cần cập nhật theo quy định hiện hành.","Cơ quan thuế tăng cường đối chiếu dữ liệu xuất nhập cảnh, BHXH và thuế TNCN của người nước ngoài; giảm trừ gia cảnh mới từ kỳ 2026 làm thay đổi cách quy đổi lương net."],"dl":["Sơ đồ quy trình và lịch hồ sơ: giải trình nhu cầu, giấy phép lao động, thị thực, thẻ tạm trú, gia hạn.","File Excel quy đổi net sang gross theo biểu lũy tiến và giảm trừ 2026, có xử lý tiền thuê nhà.","Mẫu hợp đồng lao động song ngữ và phụ lục phúc lợi cho người nước ngoài.","Checklist 30 điểm rủi ro lao động nước ngoài và bộ câu lệnh AI (prompt) tra cứu, soạn thư giải trình song ngữ."],"ls":["Khung pháp lý lao động nước ngoài và bức tranh 2026","Giải trình nhu cầu và hồ sơ cấp giấy phép lao động","Miễn giấy phép, thị thực và thẻ tạm trú","Hợp đồng lao động, BHXH và chế độ cho người nước ngoài","Cư trú thuế và nghĩa vụ thuế TNCN của người nước ngoài","Lương net, gross và phúc lợi đặc thù","Kê khai, quyết toán thuế và chi phí được trừ","Quản trị rủi ro và tình huống tổng hợp"],"l1":{"t":"Khung pháp lý lao động nước ngoài và bức tranh 2026","sum":"Bài hệ thống điều kiện, vị trí công việc và nghĩa vụ của doanh nghiệp khi sử dụng người nước ngoài theo Bộ luật Lao động 2019 và quy định hiện hành. Học viên có bản đồ văn bản cần theo dõi.","points":["Người lao động nước ngoài phải đủ 18 tuổi, có năng lực hành vi dân sự đầy đủ, có trình độ chuyên môn, kinh nghiệm, đủ sức khỏe và có giấy phép lao động trừ trường hợp được miễn.","Vị trí thường được chấp nhận: nhà quản lý, giám đốc điều hành, chuyên gia, lao động kỹ thuật theo tiêu chí quy định hiện hành.","Doanh nghiệp chỉ được tuyển người nước ngoài vào vị trí mà lao động Việt Nam chưa đáp ứng được theo nhu cầu sản xuất kinh doanh.","Ba nhóm văn bản cần theo dõi: lao động (giấy phép lao động), xuất nhập cảnh (thị thực, thẻ tạm trú), thuế và BHXH.","Doanh nghiệp phải báo cáo định kỳ tình hình sử dụng lao động nước ngoài theo quy định hiện hành."],"case":"Công ty TNHH Linh kiện Điện tử Bắc Giang Tech (vốn nước ngoài) đưa 8 kỹ sư sang lắp đặt dây chuyền nhưng chỉ làm thị thực du lịch. Khi kiểm tra, doanh nghiệp bị xử phạt và các kỹ sư phải xuất cảnh, dự án chậm 2 tháng. Cách đúng: lập kế hoạch giấy phép, thị thực lao động trước khi chuyên gia sang ít nhất vài tháng.","trend":"Thủ tục lao động nước ngoài đang chuyển sang nộp và trả kết quả trực tuyến, liên thông dữ liệu. Doanh nghiệp nên số hóa hồ sơ chuyên gia và theo dõi hạn bằng hệ thống nhắc việc.","practice":"Lập danh sách toàn bộ người nước ngoài đang làm việc, ghi vị trí, loại giấy tờ, ngày hết hạn và đánh dấu trường hợp rủi ro.","takeaway":"Giấy tờ đi trước, chuyên gia đến sau."}},{"id":"KH059","code":"kh059","f":"NS","fn":"Nhân sự - Lương - BHXH","t":"Quản trị nhân sự chiến lược cho chủ doanh nghiệp","lv":5,"ln":"Chuyên gia","h":32,"p":499000,"d":"Khoá học giúp chủ doanh nghiệp và lãnh đạo cấp cao biến nhân sự thành lợi thế cạnh tranh: gắn chiến lược con người với chiến lược kinh doanh, thiết kế tổ chức, hệ thống năng lực, đãi ngộ 3P, phát triển lãnh đạo và văn hóa. Phương pháp học dựa trên tình huống doanh nghiệp Việt đang tăng trưởng, công cụ phân tích dữ liệu nhân sự và bộ mẫu chiến lược có thể dùng ngay cho kỳ lập kế hoạch. Kết quả là một kế hoạch nhân sự chiến lược 3 năm có chỉ số đo lường, ngân sách và lộ trình chuẩn bị cho kỷ nguyên AI.","a":"Dành cho chủ doanh nghiệp, tổng giám đốc, giám đốc nhân sự và thành viên ban điều hành doanh nghiệp vừa và lớn.","o":["Xây dựng được bản đồ chiến lược nhân sự gắn với 3–5 ưu tiên kinh doanh trong 3 năm.","Thiết kế được cơ cấu tổ chức, ma trận phân quyền và hệ thống chức danh phù hợp giai đoạn phát triển.","Xây dựng được khung năng lực có nhóm năng lực số và AI, làm nền cho tuyển dụng, đào tạo, đánh giá.","Thiết kế được chính sách đãi ngộ tổng thể theo mô hình 3P và kế hoạch kế thừa cho các vị trí then chốt.","Lập được bảng chỉ số nhân sự chiến lược và kế hoạch 3 năm có ngân sách."],"k":"Chiến lược hay đến đâu cũng thất bại nếu doanh nghiệp không có đúng người, đúng năng lực, đúng thời điểm và AI đang làm khoảng cách đó rộng thêm.","w":["AI và tự động hóa đang thay đổi cấu trúc công việc; doanh nghiệp cần chiến lược nâng cấp kỹ năng và thiết kế lại vị trí thay vì chỉ cắt giảm hay tuyển thêm.","Báo cáo phát triển bền vững và ESG ngày càng yêu cầu công bố chỉ số về con người như đào tạo, đa dạng, an toàn, gắn kết.","Khung pháp lý về lao động, BHXH (Luật BHXH 2024) và bảo vệ dữ liệu cá nhân (Luật 91/2025/QH15) thay đổi, đòi hỏi quản trị nhân sự ở tầm chiến lược và tuân thủ."],"dl":["Bộ mẫu chiến lược nhân sự: phân tích hiện trạng, bản đồ chiến lược, kế hoạch 3 năm.","Mẫu ma trận phân quyền, khung năng lực và từ điển năng lực có nhóm năng lực số.","File Excel thiết kế thang lương 3P và dashboard chỉ số nhân sự chiến lược.","Bộ câu lệnh AI (prompt) phân tích dữ liệu nhân sự, mô phỏng kịch bản tác động AI đến vị trí công việc."],"ls":["Nhân sự chiến lược: từ hành chính đến đối tác kinh doanh","Gắn chiến lược con người với chiến lược kinh doanh","Thiết kế tổ chức và phân quyền cho tăng trưởng","Khung năng lực và hệ thống chức danh thời AI","Hệ thống lương 3P và đãi ngộ tổng thể","Phát triển lãnh đạo và kế hoạch kế thừa","Văn hóa doanh nghiệp và dẫn dắt chuyển đổi AI","Chỉ số nhân sự chiến lược và kế hoạch 3 năm"],"l1":{"t":"Nhân sự chiến lược: từ hành chính đến đối tác kinh doanh","sum":"Bài định vị lại vai trò nhân sự trong doanh nghiệp hiện đại và năng lực cần có của lãnh đạo nhân sự. Học viên đánh giá mức trưởng thành của chức năng nhân sự tại doanh nghiệp mình.","points":["Bốn vai trò của nhân sự: chuyên gia hành chính, người đại diện cho nhân viên, tác nhân thay đổi, đối tác chiến lược.","Mức trưởng thành: tuân thủ – chuyên nghiệp hóa quy trình – tích hợp với kinh doanh – dẫn dắt chiến lược dựa trên dữ liệu.","Lãnh đạo nhân sự chiến lược cần hiểu báo cáo tài chính, mô hình kinh doanh, dữ liệu và công nghệ.","Chủ doanh nghiệp là người chịu trách nhiệm cuối cùng về chiến lược con người, không thể khoán hoàn toàn cho phòng nhân sự.","Chi phí nhân sự thường là một trong các khoản chi lớn nhất; cần quản trị như một khoản đầu tư có đo lường hiệu quả."],"case":"Công ty CP Thực phẩm Đông Phương có 400 nhân sự nhưng phòng nhân sự chỉ làm hợp đồng, BHXH và lương. Khi mở thêm 3 nhà máy, doanh nghiệp thiếu quản lý cấp trung trầm trọng. Sau khi đưa giám đốc nhân sự vào ban điều hành và lập kế hoạch nguồn nhân lực gắn kế hoạch mở rộng, tình trạng thiếu người được kiểm soát.","trend":"Vai trò lãnh đạo nhân sự giai đoạn 2026–2030 dự kiến dịch chuyển mạnh sang phân tích dữ liệu con người và dẫn dắt chuyển đổi do AI. Học viên nên trang bị năng lực dữ liệu và quản trị thay đổi.","practice":"Đánh giá mức trưởng thành chức năng nhân sự của doanh nghiệp theo 4 cấp độ và xác định 3 khoảng cách lớn nhất.","takeaway":"Con người là chiến lược, không phải bộ phận hỗ trợ."}},{"id":"KH060","code":"kh060","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Thành lập doanh nghiệp: chọn loại hình và hồ sơ","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học hướng dẫn người khởi nghiệp và chủ hộ kinh doanh chọn đúng loại hình, chuẩn bị hồ sơ và hoàn tất mọi thủ tục sau thành lập để doanh nghiệp vận hành hợp pháp ngay từ ngày đầu. Học viên đi qua từng bước với tình huống thật, checklist và bộ hồ sơ mẫu, có thể tự nộp trên Cổng thông tin quốc gia về đăng ký doanh nghiệp. Kết quả là thành lập nhanh, đúng, tránh những sai lầm ban đầu gây tốn kém về thuế và pháp lý sau này.","a":"Dành cho người chuẩn bị khởi nghiệp, chủ hộ kinh doanh muốn chuyển lên doanh nghiệp và nhân viên văn phòng mới làm thủ tục pháp lý.","o":["So sánh và chọn được hình thức hộ kinh doanh hay loại hình doanh nghiệp phù hợp dựa trên 6 tiêu chí.","Đặt được tên doanh nghiệp hợp lệ, chọn mã ngành đúng và xác định điều kiện kinh doanh.","Chuẩn bị được bộ hồ sơ đăng ký doanh nghiệp đầy đủ, gồm thông tin chủ sở hữu hưởng lợi.","Hoàn tất được các việc sau thành lập: con dấu, tài khoản ngân hàng, chữ ký số, hóa đơn điện tử, kê khai thuế ban đầu.","Lập được checklist 30 ngày đầu tiên để doanh nghiệp không bị phạt vì quên nghĩa vụ."],"k":"Từ 2026 hộ kinh doanh không còn thuế khoán: đây là thời điểm nhiều người phải quyết định nên ở lại hộ hay lên doanh nghiệp.","w":["Từ 01/01/2026, NQ 198/2025/QH15 bỏ lệ phí môn bài và bỏ thuế khoán đối với hộ kinh doanh, hộ chuyển sang tự kê khai, khiến lợi thế đơn giản của hộ không còn nhiều.","Luật TNDN 67/2025/QH15 áp dụng thuế suất 15% cho doanh nghiệp doanh thu không quá 3 tỷ đồng và 17% cho doanh thu từ 3 đến 50 tỷ đồng, tạo động lực thành lập doanh nghiệp nhỏ.","Luật Doanh nghiệp sửa đổi 2025 bổ sung yêu cầu kê khai thông tin chủ sở hữu hưởng lợi từ 01/07/2025, đăng ký doanh nghiệp điện tử và định danh điện tử ngày càng là cách làm chính."],"dl":["Bảng so sánh hộ kinh doanh và 4 loại hình doanh nghiệp phổ biến theo thuế, trách nhiệm, huy động vốn.","Bộ hồ sơ mẫu đăng ký công ty TNHH một thành viên, hai thành viên và công ty cổ phần.","Checklist 30 ngày đầu sau thành lập và lịch nghĩa vụ thuế năm đầu.","Bộ câu lệnh AI (prompt) gợi ý tên, tra cứu mã ngành, soạn điều lệ nháp để luật sư hoặc tư vấn rà soát."],"ls":["Hộ kinh doanh hay doanh nghiệp: quyết định đúng thời điểm 2026","Chọn loại hình doanh nghiệp phù hợp","Đặt tên doanh nghiệp, chọn trụ sở và bảo vệ thương hiệu","Ngành nghề kinh doanh và điều kiện kinh doanh","Vốn điều lệ, thành viên và người đại diện theo pháp luật","Lập và nộp hồ sơ đăng ký doanh nghiệp trực tuyến","Con dấu, tài khoản ngân hàng, chữ ký số và hóa đơn điện tử","Thuế, kế toán và checklist 30 ngày đầu tiên"],"l1":{"t":"Hộ kinh doanh hay doanh nghiệp: quyết định đúng thời điểm 2026","sum":"Bài so sánh hộ kinh doanh và doanh nghiệp trong bối cảnh bỏ thuế khoán và thuế môn bài từ 2026. Học viên xác định thời điểm phù hợp để lên doanh nghiệp.","points":["Từ 01/01/2026 hộ kinh doanh không còn nộp thuế khoán mà tự kê khai theo NQ 198/2025/QH15; lệ phí môn bài cũng được bỏ cho cả hộ và doanh nghiệp.","Doanh nghiệp được tính thuế TNDN trên lợi nhuận với thuế suất 15% nếu doanh thu không quá 3 tỷ đồng, phù hợp mô hình có chi phí lớn.","Doanh nghiệp dễ ký hợp đồng với khách hàng tổ chức, xuất hóa đơn GTGT được khấu trừ, vay vốn và gọi vốn.","Hộ kinh doanh chịu trách nhiệm vô hạn bằng toàn bộ tài sản; công ty TNHH, công ty cổ phần chịu trách nhiệm trong phạm vi vốn góp.","Hộ bán hàng trên sàn thương mại điện tử được sàn khấu trừ, nộp thay thuế theo NĐ 117/2025 từ 01/07/2025; doanh nghiệp tự kê khai và có chế độ kế toán đầy đủ."],"case":"Hộ kinh doanh mỹ phẩm của chị Lan có doanh thu khoảng 2,5 tỷ đồng/năm, khách hàng spa lớn yêu cầu hóa đơn GTGT để khấu trừ. Phân tích cho thấy lợi nhuận thực tế thấp do chi phí nhập hàng, quảng cáo cao, nếu thành lập công ty TNHH và hạch toán đầy đủ thì thuế TNDN 15% trên lợi nhuận hợp lý hơn. Chị Lan quyết định thành lập công ty và giữ hộ kinh doanh cho cửa hàng nhỏ trong giai đoạn chuyển tiếp.","trend":"Quản lý thuế số đối chiếu dữ liệu ngân hàng, hóa đơn và sàn thương mại điện tử đang làm thu hẹp khoảng cách giữa hộ và doanh nghiệp. Học viên nên tính toán phương án dựa trên số liệu thật thay vì thói quen.","practice":"Lập bảng so sánh nghĩa vụ thuế và chi phí tuân thủ một năm giữa hộ kinh doanh và công ty TNHH cho mô hình kinh doanh của bạn.","takeaway":"Chọn mô hình theo số liệu, không theo thói quen."}},{"id":"KH061","code":"kh061","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Thay đổi đăng ký doanh nghiệp: vốn, địa chỉ, người đại diện","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học hướng dẫn trọn quy trình thay đổi nội dung đăng ký doanh nghiệp: vốn điều lệ, trụ sở, người đại diện, chủ sở hữu, thành viên, ngành nghề, tên và loại hình, cùng toàn bộ việc cập nhật sau thay đổi. Học viên thực hành trên hồ sơ mẫu và tình huống thật, kèm phân tích tác động thuế và kế toán của từng loại thay đổi. Kết quả là tự thực hiện được thủ tục đúng hạn, nhất quán giữa đăng ký kinh doanh, thuế, hóa đơn, ngân hàng và hợp đồng.","a":"Dành cho nhân viên pháp chế, hành chính, kế toán doanh nghiệp và chủ doanh nghiệp đang cần thay đổi thông tin đăng ký.","o":["Xác định đúng loại thủ tục, hồ sơ và thời hạn cho 10 loại thay đổi phổ biến.","Lập được hồ sơ tăng, giảm vốn điều lệ kèm nghị quyết, quyết định và hạch toán kế toán tương ứng.","Thực hiện được thủ tục chuyển trụ sở cùng tỉnh và khác tỉnh, bao gồm thủ tục với cơ quan thuế.","Phân tích được nghĩa vụ thuế khi thay đổi chủ sở hữu, thành viên, cổ đông.","Hoàn tất checklist cập nhật sau thay đổi gồm hóa đơn, ngân hàng, chữ ký số, hợp đồng, con dấu, BHXH."],"k":"Đổi địa chỉ, tăng vốn hay thay giám đốc chỉ là một tờ đơn, nhưng quên cập nhật thuế, hóa đơn, ngân hàng sau đó mới là nơi rủi ro bắt đầu.","w":["Luật Doanh nghiệp sửa đổi 2025 bổ sung nghĩa vụ kê khai, cập nhật thông tin chủ sở hữu hưởng lợi từ 01/07/2025, khiến nhiều thay đổi sở hữu phải kèm cập nhật thông tin này.","Sắp xếp lại đơn vị hành chính năm 2025 làm thay đổi tên phường, xã, tỉnh trên địa chỉ của rất nhiều doanh nghiệp; cần theo dõi hướng dẫn cập nhật để đồng bộ hóa đơn, hợp đồng.","Dữ liệu đăng ký doanh nghiệp, thuế và ngân hàng ngày càng liên thông; thông tin lệch nhau sẽ bị phát hiện nhanh và gây gián đoạn giao dịch."],"dl":["Bộ mẫu hồ sơ thay đổi: thông báo thay đổi, nghị quyết, quyết định, biên bản họp cho TNHH và cổ phần.","Bảng tra 10 loại thay đổi: hồ sơ, thời hạn, cơ quan, tác động thuế và kế toán.","Checklist 25 điểm cập nhật sau thay đổi và mẫu thông báo gửi khách hàng, nhà cung cấp.","Bộ câu lệnh AI (prompt) soạn nghị quyết, kiểm tra tính nhất quán hồ sơ và soạn thư thông báo thay đổi."],"ls":["Bản đồ thủ tục thay đổi đăng ký doanh nghiệp","Tăng vốn điều lệ: thủ tục, kế toán và tác động","Giảm vốn điều lệ và điều chỉnh vốn chưa góp đủ","Chuyển trụ sở chính và cập nhật địa chỉ hành chính mới","Thay đổi người đại diện theo pháp luật và chủ sở hữu","Thay đổi thành viên, cổ đông và ngành nghề kinh doanh","Đổi tên, chuyển đổi loại hình, chi nhánh và địa điểm kinh doanh","Cập nhật sau thay đổi và quản trị hồ sơ pháp lý số"],"l1":{"t":"Bản đồ thủ tục thay đổi đăng ký doanh nghiệp","sum":"Bài hệ thống các loại thay đổi, phân biệt thay đổi nội dung đăng ký và thông báo thay đổi nội dung đăng ký. Học viên nắm nguyên tắc thời hạn và thẩm quyền quyết định nội bộ.","points":["Doanh nghiệp phải đăng ký, thông báo thay đổi trong thời hạn 10 ngày kể từ ngày có thay đổi theo Luật Doanh nghiệp.","Mỗi thay đổi cần quyết định nội bộ đúng thẩm quyền: chủ sở hữu, Hội đồng thành viên, Đại hội đồng cổ đông hoặc Hội đồng quản trị theo điều lệ.","Hồ sơ nộp trực tuyến qua Cổng thông tin quốc gia về đăng ký doanh nghiệp, thời hạn xử lý thường 3 ngày làm việc khi hồ sơ hợp lệ.","Một số thay đổi dẫn đến cấp Giấy chứng nhận mới, một số chỉ cập nhật thông tin và cấp giấy xác nhận.","Chậm đăng ký thay đổi bị xử phạt theo quy định xử phạt vi phạm hành chính về đăng ký doanh nghiệp."],"case":"Công ty TNHH Thương mại Bình An Phát bổ nhiệm giám đốc mới từ tháng 1 nhưng đến tháng 5 mới đăng ký thay đổi người đại diện. Trong thời gian đó, giám đốc mới ký nhiều hợp đồng, ngân hàng từ chối giao dịch vì thông tin không khớp và doanh nghiệp bị xử phạt chậm đăng ký. Bài học: lập quy trình nội bộ để mọi thay đổi được đăng ký trong 10 ngày.","trend":"Đăng ký doanh nghiệp điện tử với xác thực định danh điện tử ngày càng phổ biến, giúp rút ngắn thời gian. Doanh nghiệp nên chuẩn hóa mẫu nghị quyết, quyết định để tận dụng.","practice":"Lập bảng tra cho 5 thay đổi doanh nghiệp bạn có thể gặp: thẩm quyền quyết định, hồ sơ, thời hạn.","takeaway":"Mười ngày kể từ khi thay đổi, không phải mười ngày kể từ khi nhớ ra."}},{"id":"KH062","code":"kh062","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Hợp đồng thương mại: soạn thảo và rà soát rủi ro","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp doanh nghiệp soạn thảo và rà soát hợp đồng thương mại một cách bài bản, kết nối chặt giữa pháp lý, thuế – hóa đơn và quản trị dòng tiền. Học viên làm việc với hợp đồng thật đã ẩn danh, thư viện điều khoản mẫu và quy trình rà soát rủi ro có ứng dụng AI. Kết quả là tự tin đàm phán, ký kết và quản lý hợp đồng, giảm rủi ro tranh chấp và chi phí bị loại khi quyết toán thuế.","a":"Dành cho nhân viên pháp chế, kế toán, nhân viên kinh doanh, mua hàng và chủ doanh nghiệp thường xuyên ký hợp đồng.","o":["Soạn được hợp đồng mua bán, dịch vụ theo cấu trúc chuẩn, đầy đủ điều khoản bảo vệ doanh nghiệp.","Viết được điều khoản giá, thanh toán, hóa đơn đáp ứng điều kiện khấu trừ thuế và chi phí được trừ.","Thiết kế được điều khoản giao nhận, nghiệm thu, phạt vi phạm, bồi thường, chấm dứt có thể thực thi.","Rà soát được hợp đồng của đối tác bằng checklist 50 điểm và bộ prompt AI, phân loại rủi ro cao, trung bình, thấp.","Thiết lập được quy trình quản lý hợp đồng sau ký: theo dõi nghĩa vụ, hạn thanh toán, gia hạn, lưu trữ."],"k":"Phần lớn tranh chấp thương mại bắt nguồn từ vài dòng điều khoản viết vội: thanh toán, nghiệm thu, phạt vi phạm.","w":["Luật Giao dịch điện tử 2023 công nhận hợp đồng điện tử và chữ ký điện tử, hợp đồng ký số đang trở thành chuẩn giao dịch giữa doanh nghiệp.","Quy định mới về thuế GTGT (Luật 48/2024/QH15), thanh toán không dùng tiền mặt từ 5 triệu đồng (NĐ 181/2025) và hóa đơn điện tử (NĐ 70/2025) đòi hỏi điều khoản thanh toán, hóa đơn chặt chẽ hơn.","AI rà soát hợp đồng giúp phát hiện rủi ro nhanh, nhưng người làm hợp đồng cần nền tảng pháp lý vững để đặt câu hỏi đúng và kiểm chứng kết quả."],"dl":["Thư viện 60 điều khoản mẫu có chú giải theo phía bán và phía mua.","Bộ mẫu hợp đồng: mua bán hàng hóa, cung cấp dịch vụ, đại lý, phân phối, nguyên tắc khung, phụ lục.","Checklist 50 điểm rà soát hợp đồng và mẫu bảng theo dõi nghĩa vụ sau ký.","Bộ câu lệnh AI (prompt) rà soát rủi ro, so sánh phiên bản, tóm tắt nghĩa vụ hợp đồng, có hướng dẫn bảo mật."],"ls":["Nền tảng pháp lý của hợp đồng thương mại","Cấu trúc hợp đồng và kỹ thuật soạn thảo chính xác","Giá, thanh toán và điều khoản thuế – hóa đơn","Giao nhận, chuyển rủi ro, nghiệm thu và bảo hành","Phạt vi phạm, bồi thường thiệt hại và chấm dứt hợp đồng","Bất khả kháng, bảo mật, dữ liệu và giải quyết tranh chấp","Các loại hợp đồng thương mại thường gặp","Rà soát hợp đồng với AI và quản lý sau ký"],"l1":{"t":"Nền tảng pháp lý của hợp đồng thương mại","sum":"Bài hệ thống các nguồn luật điều chỉnh hợp đồng thương mại và điều kiện để hợp đồng có hiệu lực. Học viên tránh những lỗi làm hợp đồng vô hiệu.","points":["Nguồn luật chính: Bộ luật Dân sự 2015, Luật Thương mại 2005, Luật Giao dịch điện tử 2023 và luật chuyên ngành tùy lĩnh vực.","Điều kiện hiệu lực: chủ thể có năng lực, người ký có thẩm quyền, tự nguyện, mục đích và nội dung không vi phạm điều cấm, hình thức phù hợp khi luật yêu cầu.","Kiểm tra thẩm quyền người ký: người đại diện theo pháp luật hoặc người được ủy quyền hợp lệ, phạm vi ủy quyền phù hợp giá trị hợp đồng.","Hợp đồng điện tử ký bằng chữ ký điện tử hợp lệ có giá trị pháp lý như hợp đồng giấy.","Giao dịch với người có liên quan có thể cần chấp thuận của Hội đồng thành viên hoặc Hội đồng quản trị theo Luật Doanh nghiệp."],"case":"Công ty TNHH Vật liệu Xây dựng Sơn Hà ký hợp đồng 3 tỷ đồng do trưởng phòng kinh doanh của đối tác ký, giấy ủy quyền chỉ cho phép ký đến 500 triệu đồng. Khi đối tác không giao hàng, tranh chấp phát sinh về hiệu lực hợp đồng. Bài học: luôn kiểm tra phạm vi ủy quyền trước khi ký.","trend":"Hợp đồng điện tử và xác thực danh tính số đang giúp kiểm tra thẩm quyền người ký nhanh hơn. Doanh nghiệp nên xây danh mục ủy quyền nội bộ có hạn mức rõ ràng.","practice":"Kiểm tra 3 hợp đồng gần nhất của doanh nghiệp bạn về thẩm quyền người ký và phạm vi ủy quyền.","takeaway":"Hợp đồng đúng nội dung vẫn có thể hỏng vì sai người ký."}},{"id":"KH063","code":"kh063","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Quản trị công ty TNHH và công ty cổ phần","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp chủ doanh nghiệp, thành viên góp vốn và người làm pháp chế, kế toán hiểu và vận hành đúng bộ máy quản trị của công ty TNHH và công ty cổ phần theo Luật Doanh nghiệp. Phương pháp học dựa trên tình huống tranh chấp nội bộ điển hình, bộ mẫu nghị quyết, biên bản, quy chế và điều lệ có chú giải. Kết quả là doanh nghiệp có bộ máy ra quyết định rõ ràng, hợp lệ, minh bạch và sẵn sàng đón nhà đầu tư.","a":"Dành cho chủ doanh nghiệp, thành viên, cổ đông, thư ký công ty, nhân viên pháp chế và kế toán trưởng.","o":["Vẽ được sơ đồ bộ máy quản trị và thẩm quyền quyết định của từng cơ quan trong công ty TNHH và công ty cổ phần.","Tổ chức được cuộc họp Hội đồng thành viên, Đại hội đồng cổ đông đúng trình tự, tỷ lệ biểu quyết, có biên bản hợp lệ.","Nhận diện và xử lý đúng giao dịch với người có liên quan.","Thực hiện đúng điều kiện phân chia lợi nhuận, trả cổ tức và quản lý sổ sách, sổ đăng ký thành viên, cổ đông.","Rà soát và đề xuất sửa đổi điều lệ, quy chế nội bộ, thỏa thuận thành viên phù hợp doanh nghiệp."],"k":"Nhiều doanh nghiệp gia đình tan rã không phải vì thua lỗ mà vì thiếu luật chơi giữa những người góp vốn.","w":["Luật Doanh nghiệp sửa đổi 2025 bổ sung quy định về chủ sở hữu hưởng lợi từ 01/07/2025, đòi hỏi doanh nghiệp quản lý minh bạch thông tin sở hữu.","Nhà đầu tư, ngân hàng và đối tác quốc tế ngày càng yêu cầu quản trị công ty tốt và thông tin ESG trước khi rót vốn hay ký hợp đồng lớn.","Họp trực tuyến, biểu quyết điện tử và lưu trữ biên bản số được luật cho phép, giúp vận hành bộ máy quản trị nhanh và chi phí thấp nếu làm đúng."],"dl":["Bảng tra thẩm quyền và tỷ lệ biểu quyết của các cơ quan quản trị trong công ty TNHH và công ty cổ phần.","Bộ mẫu thông báo mời họp, biên bản, nghị quyết, phiếu lấy ý kiến bằng văn bản, sổ đăng ký thành viên, cổ đông.","Điều lệ mẫu có chú giải và mẫu quy chế quản trị nội bộ, thỏa thuận cổ đông.","Bộ câu lệnh AI (prompt) soạn biên bản họp, rà soát điều lệ, kiểm tra tỷ lệ biểu quyết."],"ls":["Quản trị công ty: vì sao doanh nghiệp nhỏ cũng cần","Công ty TNHH một thành viên: chủ sở hữu và người điều hành","Công ty TNHH hai thành viên trở lên: Hội đồng thành viên","Công ty cổ phần: Đại hội đồng cổ đông","Hội đồng quản trị, Ban kiểm soát và Giám đốc","Giao dịch với người có liên quan và xung đột lợi ích","Phân chia lợi nhuận, cổ tức và sổ sách công ty","Điều lệ, quy chế nội bộ và thỏa thuận thành viên"],"l1":{"t":"Quản trị công ty: vì sao doanh nghiệp nhỏ cũng cần","sum":"Bài giới thiệu khái niệm, nguyên tắc quản trị công ty và lợi ích thực tế với doanh nghiệp vừa và nhỏ. Học viên đánh giá được điểm yếu quản trị của doanh nghiệp mình.","points":["Quản trị công ty là hệ thống quy tắc phân định quyền và trách nhiệm giữa chủ sở hữu, bộ máy quản lý và các bên liên quan.","Nguyên tắc cốt lõi: minh bạch, trách nhiệm giải trình, đối xử công bằng giữa các chủ sở hữu, kiểm soát xung đột lợi ích.","Luật Doanh nghiệp quy định khung; điều lệ và quy chế nội bộ chi tiết hóa cho từng doanh nghiệp.","Quản trị tốt giúp ra quyết định nhanh, giảm tranh chấp, tăng uy tín với ngân hàng và nhà đầu tư.","Dấu hiệu quản trị yếu: quyết định miệng, không có biên bản, tài sản cá nhân và công ty lẫn lộn, không có báo cáo định kỳ cho thành viên."],"case":"Công ty TNHH Thương mại Gia Bảo do 3 anh em góp vốn, mọi quyết định đều miệng. Khi một người muốn rút vốn, không có biên bản nào chứng minh tỷ lệ góp và các quyết định chia lợi nhuận trước đó, tranh chấp kéo dài 2 năm. Bài học: quy trình họp và biên bản là bảo hiểm cho quan hệ giữa các chủ sở hữu.","trend":"Quản trị công ty và minh bạch là một trụ cột (G) trong ESG; doanh nghiệp nhỏ có quản trị tốt sẽ dễ tiếp cận vốn xanh và chuỗi cung ứng quốc tế.","practice":"Tự đánh giá doanh nghiệp theo 15 câu hỏi quản trị và xác định 3 điểm cần cải thiện.","takeaway":"Quản trị tốt giữ được cả công ty lẫn tình thân."}},{"id":"KH064","code":"kh064","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Góp vốn, chuyển nhượng vốn và cổ phần","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học hướng dẫn trọn vòng đời giao dịch vốn: góp vốn bằng tiền và tài sản, xử lý vốn chưa góp đủ, chuyển nhượng phần vốn góp và cổ phần, định giá, nghĩa vụ thuế và hạch toán. Học viên giải các tình huống thật từ khởi nghiệp, gọi vốn đến chuyển nhượng doanh nghiệp gia đình, với bảng tính thuế và bộ hồ sơ mẫu. Kết quả là thực hiện giao dịch vốn hợp pháp, minh bạch, tính đúng thuế và bảo vệ được quyền lợi các bên.","a":"Dành cho chủ doanh nghiệp, nhà đầu tư cá nhân, kế toán trưởng, nhân viên pháp chế và tư vấn viên thực hiện giao dịch vốn.","o":["Lập được hồ sơ góp vốn bằng tiền và bằng tài sản, kèm biên bản định giá và chứng từ chuyển quyền sở hữu.","Xử lý đúng trường hợp thành viên, cổ đông không góp đủ vốn đúng hạn.","Thực hiện được thủ tục chuyển nhượng phần vốn góp trong công ty TNHH và cổ phần trong công ty cổ phần đúng trình tự ưu tiên.","Tính đúng thuế TNCN, TNDN của giao dịch chuyển nhượng vốn cho cá nhân và tổ chức.","Hạch toán và lưu trữ được bộ hồ sơ giao dịch vốn hoàn chỉnh cho cả bên chuyển nhượng, bên nhận và công ty."],"k":"Giao dịch vốn ghi giá bằng mệnh giá để 'tránh thuế' đang là một trong những điểm cơ quan thuế soi kỹ nhất.","w":["Luật Doanh nghiệp sửa đổi 2025 bổ sung yêu cầu kê khai chủ sở hữu hưởng lợi từ 01/07/2025, mỗi giao dịch vốn làm thay đổi sở hữu cần được cập nhật minh bạch.","Hoạt động mua bán, sáp nhập và gọi vốn khởi nghiệp tại Việt Nam được dự báo tiếp tục sôi động, đòi hỏi kỹ năng định giá, thẩm định và cấu trúc giao dịch.","Cơ quan thuế tăng cường đối chiếu dữ liệu đăng ký doanh nghiệp, ngân hàng và báo cáo tài chính để phát hiện giao dịch chuyển nhượng khai giá thấp."],"dl":["Bộ mẫu: biên bản góp vốn, biên bản định giá tài sản góp vốn, hợp đồng chuyển nhượng phần vốn góp, hợp đồng chuyển nhượng cổ phần, biên bản thanh lý.","File Excel tính thuế chuyển nhượng vốn cho cá nhân, tổ chức và mô hình định giá đơn giản.","Checklist thẩm định trước khi mua phần vốn góp, cổ phần và lịch thủ tục sau giao dịch.","Bộ câu lệnh AI (prompt) soạn hợp đồng chuyển nhượng, lập danh mục thẩm định, tóm tắt rủi ro giao dịch."],"ls":["Vốn điều lệ, phần vốn góp và cổ phần: hiểu đúng bản chất","Góp vốn bằng tiền và bằng tài sản","Không góp đủ vốn và điều chỉnh vốn điều lệ","Chuyển nhượng phần vốn góp trong công ty TNHH","Chuyển nhượng cổ phần trong công ty cổ phần","Định giá giao dịch vốn và thẩm định trước khi mua","Nghĩa vụ thuế khi chuyển nhượng vốn","Hạch toán và hồ sơ giao dịch vốn hoàn chỉnh"],"l1":{"t":"Vốn điều lệ, phần vốn góp và cổ phần: hiểu đúng bản chất","sum":"Bài phân biệt vốn điều lệ, phần vốn góp, cổ phần và các loại cổ phần. Học viên hiểu quyền gắn với từng loại vốn.","points":["Vốn điều lệ là tổng giá trị tài sản các thành viên, cổ đông đã góp hoặc cam kết góp khi thành lập hoặc đã mua khi công ty cổ phần chào bán.","Công ty TNHH chia vốn thành phần vốn góp, công ty cổ phần chia vốn thành cổ phần có mệnh giá.","Công ty cổ phần có cổ phần phổ thông bắt buộc và có thể có cổ phần ưu đãi: ưu đãi biểu quyết, ưu đãi cổ tức, ưu đãi hoàn lại và loại khác theo điều lệ.","Quyền của thành viên, cổ đông gồm biểu quyết, nhận lợi nhuận, ưu tiên góp thêm, chuyển nhượng, nhận tài sản còn lại khi giải thể.","Giá trị sổ sách, giá trị thị trường và mệnh giá là ba khái niệm khác nhau, quan trọng khi định giá và tính thuế."],"case":"Công ty CP Khởi nghiệp Giáo dục Tương Lai phát hành cổ phần mệnh giá 10.000 đồng cho nhà đầu tư với giá 50.000 đồng/cổ phần. Kế toán ghi nhận toàn bộ vào vốn góp của chủ sở hữu, sai bản chất. Cách đúng: phần mệnh giá ghi vào vốn góp, phần chênh lệch ghi vào thặng dư vốn cổ phần.","trend":"Cổ phần ưu đãi, quyền chọn cho nhân viên và các công cụ vốn linh hoạt đang được startup sử dụng nhiều hơn. Người làm kế toán, pháp chế cần hiểu để ghi nhận và quản trị đúng.","practice":"Phân tích cơ cấu vốn của một công ty cổ phần giả định có 2 loại cổ phần và lập bảng quyền của từng nhóm cổ đông.","takeaway":"Mệnh giá không phải giá trị thật của cổ phần."}},{"id":"KH065","code":"kh065","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Tạm ngừng, giải thể và phá sản doanh nghiệp","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học hướng dẫn doanh nghiệp chọn đúng phương án khi muốn dừng hoạt động: tạm ngừng, giải thể hay phá sản, và thực hiện thủ tục đúng luật, đúng trình tự với cơ quan đăng ký kinh doanh, thuế, BHXH và người lao động. Học viên đi qua tình huống thật, checklist từng bước và bộ hồ sơ mẫu. Kết quả là đóng hoặc tạm dừng doanh nghiệp gọn gàng, giảm chi phí, tránh rủi ro pháp lý cho chủ sở hữu và người quản lý.","a":"Dành cho chủ doanh nghiệp, kế toán, nhân viên pháp chế và tư vấn viên đang xử lý doanh nghiệp tạm ngừng hoặc chấm dứt hoạt động.","o":["So sánh và chọn được phương án tạm ngừng, giải thể, bán doanh nghiệp hay phá sản theo tình hình thực tế.","Thực hiện được thủ tục tạm ngừng, tiếp tục kinh doanh trước hạn đúng thời hạn thông báo.","Lập được kế hoạch giải thể gồm thanh lý tài sản, thanh toán nợ theo đúng thứ tự ưu tiên và giải quyết quyền lợi người lao động.","Hoàn tất được quyết toán thuế, chấm dứt hiệu lực mã số thuế và chốt BHXH khi giải thể.","Tổ chức được lưu trữ hồ sơ kế toán, pháp lý sau khi doanh nghiệp chấm dứt hoạt động."],"k":"Bỏ mặc một công ty không hoạt động không làm nó biến mất: nợ thuế, tiền phạt và trách nhiệm cá nhân vẫn tiếp tục lớn lên.","w":["Từ 01/01/2026 bỏ lệ phí môn bài theo NQ 198/2025/QH15, nhưng nghĩa vụ kê khai thuế, báo cáo tài chính và BHXH vẫn tiếp tục nếu doanh nghiệp không làm thủ tục tạm ngừng hay giải thể.","Xử phạt vi phạm hành chính về thuế, hóa đơn theo NĐ 125/2020 sửa bởi NĐ 310/2025 (hiệu lực 16/01/2026) và tiền chậm nộp 0,03%/ngày khiến chi phí 'bỏ mặc' doanh nghiệp tăng theo thời gian.","Liên thông dữ liệu giữa đăng ký kinh doanh, thuế, BHXH và ngân hàng giúp thủ tục trực tuyến nhanh hơn, đồng thời làm doanh nghiệp bỏ trốn khỏi địa chỉ dễ bị phát hiện."],"dl":["Sơ đồ quyết định chọn phương án dừng hoạt động và bảng so sánh chi phí, thời gian, rủi ro.","Bộ mẫu: thông báo tạm ngừng, quyết định và nghị quyết giải thể, phương án thanh toán nợ, thông báo cho chủ nợ, người lao động.","Checklist giải thể 40 bước với cơ quan đăng ký kinh doanh, thuế, BHXH, ngân hàng.","Bộ câu lệnh AI (prompt) lập kế hoạch giải thể, soạn thông báo chủ nợ, rà soát nghĩa vụ còn treo."],"ls":["Bốn con đường khi doanh nghiệp muốn dừng lại","Thủ tục tạm ngừng và tiếp tục kinh doanh","Nghĩa vụ trong thời gian tạm ngừng","Giải thể: điều kiện và trình tự chuẩn","Thanh toán nợ và quyền lợi người lao động khi giải thể","Quyết toán thuế, hóa đơn và chấm dứt mã số thuế","Phá sản doanh nghiệp: khi không còn khả năng thanh toán","Lưu trữ hồ sơ và hoàn tất sau khi đóng doanh nghiệp"],"l1":{"t":"Bốn con đường khi doanh nghiệp muốn dừng lại","sum":"Bài so sánh các phương án tạm ngừng, giải thể, bán hoặc chuyển nhượng doanh nghiệp và phá sản. Học viên chọn được phương án phù hợp với tình hình tài chính.","points":["Tạm ngừng kinh doanh khi muốn dừng tạm thời, giữ pháp nhân để quay lại sau.","Giải thể khi muốn chấm dứt vĩnh viễn và doanh nghiệp còn đủ khả năng thanh toán hết các khoản nợ.","Bán doanh nghiệp hoặc chuyển nhượng vốn khi pháp nhân, giấy phép, khách hàng còn giá trị với người khác.","Phá sản khi doanh nghiệp mất khả năng thanh toán và được Tòa án tuyên bố phá sản theo Luật Phá sản 2014.","Không làm thủ tục mà bỏ địa chỉ kinh doanh có thể bị khóa mã số thuế, xử phạt và ảnh hưởng đến người quản lý, chủ sở hữu."],"case":"Công ty TNHH Thời trang Trẻ Sài Gòn ngừng bán hàng từ giữa năm nhưng không làm thủ tục, kế toán nghỉ việc. Một năm sau, doanh nghiệp bị xử phạt chậm nộp nhiều tờ khai, mã số thuế bị chuyển trạng thái và chủ sở hữu gặp khó khi thành lập công ty mới. Nếu tạm ngừng ngay từ đầu, chi phí tuân thủ sẽ thấp hơn nhiều.","trend":"Dữ liệu doanh nghiệp liên thông giúp cơ quan quản lý phát hiện nhanh doanh nghiệp ngừng hoạt động không khai báo. Chủ doanh nghiệp nên chủ động làm thủ tục thay vì để tồn tại 'trên giấy'.","practice":"Dùng sơ đồ quyết định phân tích một doanh nghiệp giả định đang thua lỗ để chọn phương án và nêu lý do.","takeaway":"Dừng đúng cách rẻ hơn rất nhiều so với dừng im lặng."}},{"id":"KH066","code":"kh066","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Văn bản hành chính theo Nghị định 30/2020","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học hướng dẫn soạn thảo văn bản hành chính chuẩn theo Nghị định 30/2020/NĐ-CP về công tác văn thư: thể thức, kỹ thuật trình bày, các loại văn bản thường dùng, ký số và quản lý văn bản điện tử. Học viên thực hành trên bộ mẫu Word chuẩn và bộ câu lệnh AI để soạn nhanh mà vẫn đúng quy định. Kết quả là soạn được văn bản đẹp, chuẩn, nhất quán trong toàn doanh nghiệp và sẵn sàng chuyển sang văn bản điện tử.","a":"Dành cho nhân viên hành chính, văn thư, thư ký, kế toán và nhân sự thường xuyên soạn văn bản cho doanh nghiệp.","o":["Trình bày đúng 9 thành phần thể thức chính của văn bản hành chính theo Nghị định 30/2020.","Thiết lập được bộ mẫu Word chuẩn: khổ giấy, lề, phông chữ, cỡ chữ, vị trí các thành phần.","Soạn được quyết định, thông báo, công văn, tờ trình, báo cáo, biên bản đúng cấu trúc trong vòng 20 phút mỗi văn bản.","Thực hiện đúng quy tắc ký, ký thay, đóng dấu, ký số và sao văn bản.","Tổ chức được sổ đăng ký văn bản đi, đến và lập hồ sơ công việc theo năm."],"k":"Một công văn sai thể thức đủ để đối tác, ngân hàng hay cơ quan nhà nước đánh giá thấp sự chuyên nghiệp của cả doanh nghiệp.","w":["Doanh nghiệp ngày càng giao dịch với cơ quan nhà nước, ngân hàng, đối tác bằng văn bản điện tử ký số; văn bản chuẩn thể thức giúp được tiếp nhận nhanh và chuyên nghiệp.","AI có thể soạn nháp văn bản trong vài giây, nhưng người dùng cần nắm chuẩn Nghị định 30/2020 để kiểm tra và chỉnh sửa đúng.","Luật Giao dịch điện tử 2023 và xu hướng số hóa lưu trữ khiến việc quản lý văn bản đi, đến trên hệ thống điện tử trở thành kỹ năng bắt buộc."],"dl":["Bộ mẫu Word chuẩn Nghị định 30/2020 cho 12 loại văn bản doanh nghiệp thường dùng.","Bảng tra nhanh thể thức và kỹ thuật trình bày (vị trí, phông, cỡ chữ, kiểu chữ).","Mẫu sổ đăng ký văn bản đi, đến dạng Excel và quy trình SOP quản lý văn bản.","Bộ câu lệnh AI (prompt) soạn quyết định, công văn, tờ trình, biên bản đúng thể thức."],"ls":["Nghị định 30/2020 và vì sao doanh nghiệp nên áp dụng","Thể thức văn bản: 9 thành phần chính","Kỹ thuật trình bày: khổ giấy, phông chữ, căn lề","Số, ký hiệu và trích yếu văn bản","Soạn quyết định, quy chế và thông báo","Soạn công văn, tờ trình, báo cáo và biên bản","Ký, đóng dấu, bản sao và văn bản điện tử","Quản lý văn bản đi, đến và lập hồ sơ số"],"l1":{"t":"Nghị định 30/2020 và vì sao doanh nghiệp nên áp dụng","sum":"Bài giới thiệu phạm vi, đối tượng áp dụng và các loại văn bản hành chính theo Nghị định 30/2020. Học viên hiểu giá trị của việc chuẩn hóa văn bản trong doanh nghiệp tư nhân.","points":["Nghị định 30/2020/NĐ-CP quy định về công tác văn thư, áp dụng với cơ quan, tổ chức nhà nước và doanh nghiệp nhà nước; tổ chức, doanh nghiệp khác có thể vận dụng.","Nghị định quy định 29 loại văn bản hành chính như quyết định, quy chế, thông báo, kế hoạch, báo cáo, biên bản, tờ trình, hợp đồng, công văn, giấy ủy quyền, giấy mời, giấy giới thiệu.","Nội dung chính gồm: thể thức và kỹ thuật trình bày, soạn thảo và ký ban hành, quản lý văn bản đi, đến, lập hồ sơ, quản lý con dấu và thiết bị lưu khóa bí mật.","Doanh nghiệp chuẩn hóa văn bản giúp nhất quán hình ảnh, giảm sai sót và thuận lợi khi làm việc với cơ quan nhà nước.","Nên ban hành quy chế công tác văn thư nội bộ dựa trên Nghị định 30/2020 và điều chỉnh phù hợp."],"case":"Công ty CP Đầu tư Xây dựng Hưng Long gửi công văn đề nghị cơ quan quản lý gia hạn thủ tục nhưng văn bản thiếu số, ký hiệu và không có trích yếu. Văn bản bị yêu cầu bổ sung, mất thêm 1 tuần. Sau khi chuẩn hóa mẫu theo Nghị định 30/2020, các hồ sơ sau được tiếp nhận ngay.","trend":"Văn bản điện tử ký số và liên thông đang trở thành kênh giao tiếp chính giữa doanh nghiệp và cơ quan nhà nước. Doanh nghiệp nên chuẩn hóa mẫu để sẵn sàng.","practice":"Thu thập 5 văn bản doanh nghiệp đã ban hành và đánh dấu các điểm chưa đúng chuẩn Nghị định 30/2020.","takeaway":"Văn bản chuẩn là danh thiếp bằng giấy của doanh nghiệp."}},{"id":"KH067","code":"kh067","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Sở hữu trí tuệ và bảo hộ thương hiệu","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp doanh nghiệp nhận diện, đăng ký, khai thác và bảo vệ tài sản trí tuệ: nhãn hiệu, quyền tác giả, phần mềm, nội dung số, sáng chế, kiểu dáng và bí mật kinh doanh. Học viên thực hành tra cứu nhãn hiệu, phân nhóm sản phẩm, lập hồ sơ đơn và xây chính sách bảo vệ tài sản trí tuệ nội bộ, kèm phân tích thuế, kế toán khi chuyển giao. Kết quả là doanh nghiệp có chiến lược bảo hộ rõ ràng, chi phí hợp lý và sẵn sàng cho kinh doanh số, xuất khẩu.","a":"Dành cho chủ doanh nghiệp, nhà sáng lập startup, nhân viên marketing, pháp chế và kế toán quản lý tài sản vô hình.","o":["Lập được danh mục tài sản trí tuệ của doanh nghiệp và phân loại theo hình thức bảo hộ phù hợp.","Tra cứu được nhãn hiệu và đánh giá sơ bộ khả năng đăng ký trước khi nộp đơn.","Chuẩn bị được hồ sơ đăng ký nhãn hiệu với danh mục sản phẩm, dịch vụ phân nhóm đúng theo bảng phân loại Nice.","Xây dựng được điều khoản sở hữu trí tuệ trong hợp đồng lao động, hợp đồng dịch vụ và chính sách bảo mật bí mật kinh doanh.","Lập được kế hoạch phản ứng khi bị xâm phạm và chiến lược bảo hộ 3 năm có ngân sách."],"k":"Bạn có thể xây thương hiệu suốt nhiều năm rồi mất nó trong một ngày, chỉ vì người khác nộp đơn đăng ký nhãn hiệu trước bạn.","w":["Thương mại điện tử và mạng xã hội khiến hàng giả, sao chép thương hiệu, nội dung lan rộng rất nhanh; chỉ chủ sở hữu có văn bằng mới có công cụ pháp lý mạnh để xử lý.","AI tạo sinh đặt ra câu hỏi mới về quyền tác giả của nội dung, hình ảnh, mã nguồn do AI hỗ trợ tạo ra, doanh nghiệp cần chính sách sử dụng và sở hữu rõ ràng.","Hội nhập qua các hiệp định thương mại thế hệ mới nâng chuẩn bảo hộ sở hữu trí tuệ; doanh nghiệp xuất khẩu cần đăng ký thương hiệu tại thị trường mục tiêu trước khi bán hàng."],"dl":["Mẫu danh mục tài sản trí tuệ và bảng đánh giá giá trị, rủi ro.","Bộ mẫu: tờ khai đăng ký nhãn hiệu tham khảo, hợp đồng li-xăng, hợp đồng chuyển nhượng, điều khoản sở hữu trí tuệ, cam kết bảo mật.","Checklist tra cứu nhãn hiệu, quy trình xử lý xâm phạm trên sàn thương mại điện tử và mạng xã hội.","Bộ câu lệnh AI (prompt) gợi ý danh mục sản phẩm, rà soát hợp đồng li-xăng, soạn thư cảnh báo xâm phạm."],"ls":["Tài sản trí tuệ: kho báu vô hình của doanh nghiệp","Nhãn hiệu: điều kiện bảo hộ và nguyên tắc nộp đơn đầu tiên","Tra cứu nhãn hiệu và phân nhóm sản phẩm, dịch vụ","Hồ sơ, quy trình đăng ký và duy trì nhãn hiệu","Quyền tác giả, phần mềm, nội dung số và AI","Sáng chế, kiểu dáng công nghiệp và bí mật kinh doanh","Khai thác, chuyển giao và hạch toán tài sản trí tuệ","Xử lý xâm phạm và chiến lược bảo hộ 3 năm"],"l1":{"t":"Tài sản trí tuệ: kho báu vô hình của doanh nghiệp","sum":"Bài giới thiệu các đối tượng sở hữu trí tuệ theo Luật Sở hữu trí tuệ và giá trị của chúng với doanh nghiệp. Học viên lập danh mục tài sản trí tuệ đầu tiên.","points":["Ba nhóm quyền: quyền tác giả và quyền liên quan; quyền sở hữu công nghiệp (nhãn hiệu, sáng chế, kiểu dáng công nghiệp, tên thương mại, chỉ dẫn địa lý, bí mật kinh doanh…); quyền đối với giống cây trồng.","Một số quyền phát sinh tự động (quyền tác giả, bí mật kinh doanh, tên thương mại khi sử dụng hợp pháp), một số phải đăng ký để được cấp văn bằng (nhãn hiệu, sáng chế, kiểu dáng).","Tài sản trí tuệ tạo giá trị qua: độc quyền khai thác, li-xăng thu phí, góp vốn, tăng giá trị khi gọi vốn, mua bán doanh nghiệp.","Doanh nghiệp vừa và nhỏ thường sở hữu: thương hiệu, logo, website, nội dung, phần mềm, công thức, danh sách khách hàng, quy trình.","Cơ quan chính: Cục Sở hữu trí tuệ với sở hữu công nghiệp; Cục Bản quyền tác giả với quyền tác giả."],"case":"Công ty TNHH Bánh Kẹo Gia Truyền Hương Xưa có công thức bánh 30 năm, logo và tên gọi nổi tiếng địa phương nhưng chưa từng bảo hộ gì. Khi kiểm kê, doanh nghiệp xác định 6 tài sản trí tuệ quan trọng và ưu tiên đăng ký nhãn hiệu, đồng thời xây quy trình bảo mật công thức. Khi đàm phán với nhà đầu tư, các tài sản này được đánh giá cao.","trend":"Giá trị doanh nghiệp ngày càng dịch chuyển sang tài sản vô hình như thương hiệu, dữ liệu, phần mềm. Chủ doanh nghiệp nên quản trị tài sản trí tuệ như quản trị tài sản cố định.","practice":"Lập danh mục tài sản trí tuệ của doanh nghiệp bạn với tối thiểu 8 mục, ghi hình thức bảo hộ và tình trạng hiện tại.","takeaway":"Thứ có giá trị nhất của doanh nghiệp thường không nằm trong kho."}},{"id":"KH068","code":"kh068","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Đầu tư nước ngoài vào Việt Nam: thủ tục và lưu ý","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học hệ thống hoá toàn bộ hành trình đưa vốn nước ngoài vào Việt Nam: chọn hình thức đầu tư, xin Giấy chứng nhận đăng ký đầu tư (IRC), đăng ký doanh nghiệp (ERC), mở tài khoản vốn, góp vốn và tuân thủ sau cấp phép. Mỗi bài đi kèm tình huống hồ sơ thật, bộ mẫu dùng ngay và checklist rà soát trước khi nộp. Kết thúc khoá, học viên tự lập được lộ trình cấp phép và lịch tuân thủ cho một dự án FDI hoàn chỉnh.","a":"Dành cho chuyên viên tư vấn pháp lý – kế toán, kế toán trưởng doanh nghiệp FDI và nhà đầu tư nước ngoài muốn tự vận hành thủ tục tại Việt Nam.","o":["Chọn được hình thức đầu tư phù hợp (thành lập mới, góp vốn/mua cổ phần, hợp đồng BCC) cho từng tình huống và giải thích được lý do.","Lập được trọn bộ hồ sơ xin IRC và ERC kèm dự toán thời gian, chi phí và danh mục giấy tờ hợp pháp hóa.","Vận hành đúng tài khoản vốn đầu tư trực tiếp: góp vốn đúng hạn, chuyển lợi nhuận ra nước ngoài hợp lệ.","Tự xây được lịch tuân thủ sau cấp phép gồm báo cáo đầu tư, thuế, kế toán, lao động người nước ngoài.","Tự kiểm tra được 10 rủi ro phổ biến của doanh nghiệp FDI trước khi cơ quan quản lý phát hiện."],"k":"Dòng vốn FDI dịch chuyển mạnh vào Việt Nam, nhưng một sai sót nhỏ ở hồ sơ IRC có thể khiến dự án chậm cả quý.","w":["Việt Nam đang trong làn sóng dịch chuyển chuỗi cung ứng, nhu cầu tư vấn thủ tục FDI chuẩn, nhanh và minh bạch tăng rõ rệt từ 2026.","Thuế tối thiểu toàn cầu (NQ 107/2023/QH15) và quy định về chủ sở hữu hưởng lợi khiến nhà đầu tư phải thiết kế cấu trúc ngay từ đầu, không thể sửa sau.","Thủ tục đầu tư, đăng ký doanh nghiệp và báo cáo đang được số hóa trên các hệ thống thông tin quốc gia, người làm hồ sơ phải thành thạo nộp và theo dõi trực tuyến."],"dl":["Bộ mẫu hồ sơ IRC – ERC song ngữ Việt – Anh kèm hướng dẫn điền từng mục.","Checklist 40 điểm rà soát hồ sơ trước khi nộp và sau khi nhận giấy phép.","File Excel lịch tuân thủ FDI 12 tháng tự nhắc hạn báo cáo đầu tư, thuế, lao động.","Bộ câu lệnh AI (prompt) soạn đề xuất dự án, thư giải trình và email làm việc với nhà đầu tư."],"ls":["Bản đồ pháp lý FDI: đọc đúng luật trước khi tư vấn","Chọn hình thức đầu tư: thành lập mới, góp vốn hay BCC","Hồ sơ IRC chuẩn ngay lần đầu","Từ IRC đến ERC: đăng ký doanh nghiệp, con dấu và tài khoản","Tài khoản vốn đầu tư trực tiếp, góp vốn và chuyển lợi nhuận","Thuế và kế toán đặc thù của doanh nghiệp FDI","Lao động người nước ngoài và báo cáo định kỳ","Ứng dụng AI và bộ công cụ tư vấn FDI chuyên nghiệp"],"l1":{"t":"Bản đồ pháp lý FDI: đọc đúng luật trước khi tư vấn","sum":"Bài nền tảng giúp học viên định vị các văn bản chính điều chỉnh đầu tư nước ngoài và cơ quan nào quản lý việc gì. Hiểu đúng bản đồ này giúp tránh tư vấn sai từ bước đầu tiên.","points":["Luật Đầu tư 2020 và nghị định hướng dẫn điều chỉnh thủ tục đầu tư; Luật Doanh nghiệp 2020 (sửa đổi 2025) điều chỉnh việc thành lập và quản trị công ty.","Nhà đầu tư nước ngoài phải tra cứu Danh mục ngành, nghề hạn chế tiếp cận thị trường và cam kết WTO, FTA liên quan trước khi chọn ngành.","Cơ quan tiếp nhận thường là Sở Tài chính (sau sắp xếp bộ máy) hoặc Ban quản lý khu công nghiệp, khu kinh tế tùy địa điểm dự án.","Ngành có điều kiện (giáo dục, logistics, phân phối bán lẻ…) cần thêm giấy phép con, phải dự trù thời gian riêng.","Luôn kiểm tra hiệu lực văn bản tại thời điểm nộp hồ sơ vì khung pháp lý đầu tư đang được sửa đổi, cập nhật liên tục."],"case":"Công ty TNHH Tư vấn Minh An nhận hồ sơ của nhà đầu tư Hàn Quốc muốn mở chuỗi bán lẻ mỹ phẩm. Chuyên viên phát hiện hoạt động bán lẻ cần giấy phép kinh doanh riêng cho từng cơ sở, nên tách lộ trình thành 3 giai đoạn và báo trước khách hàng thêm khoảng 30 ngày, tránh cam kết sai tiến độ.","trend":"Giai đoạn 2026–2030, thủ tục đầu tư được dự kiến tiếp tục đơn giản hóa và liên thông trực tuyến; người tư vấn cần thành thạo tra cứu văn bản gốc và các cổng dịch vụ công quốc gia.","practice":"Chọn một ngành bất kỳ, tra cứu điều kiện tiếp cận thị trường cho nhà đầu tư nước ngoài và lập bảng 1 trang: ngành, mã ngành, điều kiện, giấy phép con, cơ quan cấp.","takeaway":"Tư vấn FDI đúng bắt đầu từ việc đọc đúng ngành, không phải điền đúng mẫu."}},{"id":"KH069","code":"kh069","f":"PL","fn":"Pháp lý doanh nghiệp","t":"Tuân thủ pháp lý 2026: chủ sở hữu hưởng lợi, định danh điện tử, dữ liệu","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp doanh nghiệp nhỏ và vừa nắm trọn các nghĩa vụ tuân thủ mới từ 2025–2026: thông tin chủ sở hữu hưởng lợi, định danh điện tử, bảo vệ dữ liệu cá nhân, hóa đơn – thanh toán, lao động – bảo hiểm. Mỗi bài đi kèm tình huống thật, mẫu biểu và checklist dùng ngay. Kết thúc khoá, học viên tự lập được bản đồ tuân thủ và lịch kiểm soát hàng tháng cho chính doanh nghiệp mình.","a":"Dành cho chủ doanh nghiệp nhỏ, kế toán, nhân sự hành chính và người phụ trách pháp chế kiêm nhiệm muốn cập nhật nhanh nghĩa vụ tuân thủ 2026.","o":["Lập được bản đồ nghĩa vụ pháp lý 2026 cho doanh nghiệp theo 6 nhóm: đăng ký, thuế, hóa đơn, lao động, dữ liệu, báo cáo.","Xác định và kê khai đúng thông tin chủ sở hữu hưởng lợi, lưu hồ sơ chứng minh.","Thiết lập được tài khoản định danh điện tử và phân quyền giao dịch số an toàn cho doanh nghiệp.","Xây được bộ chính sách bảo vệ dữ liệu cá nhân tối thiểu: thông báo, đồng ý, phân quyền, xử lý sự cố.","Vận hành được lịch tuân thủ tháng – quý – năm, giảm rủi ro bị phạt do quên hạn."],"k":"Năm 2026, doanh nghiệp không chỉ nộp thuế đúng hạn: còn phải minh bạch chủ sở hữu, định danh điện tử và bảo vệ dữ liệu.","w":["Luật Doanh nghiệp sửa đổi 2025 bổ sung nghĩa vụ cung cấp, lưu giữ thông tin chủ sở hữu hưởng lợi từ 01/07/2025.","Luật Bảo vệ dữ liệu cá nhân (Luật 91/2025/QH15) có hiệu lực từ 01/01/2026, áp dụng cho mọi doanh nghiệp xử lý dữ liệu khách hàng, nhân viên.","Giao dịch với cơ quan nhà nước đang chuyển mạnh sang định danh điện tử và dữ liệu liên thông, sai lệch thông tin sẽ bị phát hiện nhanh hơn trước."],"dl":["Bản đồ tuân thủ 2026 dạng Excel với hơn 60 nghĩa vụ, hạn, căn cứ và người phụ trách.","Mẫu biểu kê khai và sổ lưu giữ thông tin chủ sở hữu hưởng lợi.","Bộ mẫu chính sách bảo vệ dữ liệu cá nhân: thông báo xử lý, phiếu đồng ý, quy trình xử lý sự cố.","Bộ câu lệnh AI (prompt) rà soát hợp đồng, nội quy và chính sách theo checklist tuân thủ."],"ls":["Bức tranh tuân thủ 2026: những gì đã thay đổi","Chủ sở hữu hưởng lợi: hiểu đúng, kê khai đúng","Định danh điện tử và giao dịch số an toàn","Bảo vệ dữ liệu cá nhân: việc của mọi doanh nghiệp từ 2026","Hóa đơn điện tử, chứng từ và thanh toán đúng luật","Lao động, bảo hiểm và nội quy theo luật mới","Thay đổi đăng ký, báo cáo định kỳ và lưu trữ hồ sơ","Hệ thống tuân thủ số: lịch, dashboard và trợ lý AI"],"l1":{"t":"Bức tranh tuân thủ 2026: những gì đã thay đổi","sum":"Bài mở đầu tổng hợp các thay đổi pháp lý quan trọng có hiệu lực 2025–2026 ảnh hưởng trực tiếp đến doanh nghiệp nhỏ. Học viên biết ưu tiên việc gì trước.","points":["Thuế: TNDN 15%/17%/20% theo doanh thu từ kỳ 2025 (Luật 67/2025/QH15); VAT 8% đến hết 31/12/2026 trừ một số ngành (NQ 204/2025/QH15).","Thanh toán không dùng tiền mặt để được khấu trừ GTGT và tính chi phí áp dụng cho hóa đơn từ 5 triệu đồng từ 01/07/2025.","Bỏ lệ phí môn bài và bỏ thuế khoán hộ kinh doanh từ 01/01/2026 (NQ 198/2025/QH15).","Xử phạt vi phạm về thuế, hóa đơn: NĐ 125/2020 sửa bởi NĐ 310/2025, hiệu lực 16/01/2026; tiền chậm nộp 0,03%/ngày.","Pháp lý doanh nghiệp: thông tin chủ sở hữu hưởng lợi, bảo vệ dữ liệu cá nhân, Luật BHXH 2024 hiệu lực 01/07/2025."],"case":"Công ty TNHH Thương mại Minh An vẫn tách hóa đơn mua hàng 6 triệu đồng thành 2 lần trả tiền mặt như thói quen cũ. Kế toán rà soát theo checklist 2026 và phát hiện khoản này không đủ điều kiện khấu trừ thuế GTGT. Doanh nghiệp chuyển toàn bộ thanh toán nhà cung cấp sang chuyển khoản từ tháng sau.","trend":"Giai đoạn 2026–2030, quản lý nhà nước dự kiến dựa ngày càng nhiều vào dữ liệu số liên thông; doanh nghiệp nên xem tuân thủ là hệ thống vận hành, không phải việc đối phó cuối năm.","practice":"Liệt kê 10 thay đổi pháp lý 2025–2026 và đánh giá mức ảnh hưởng (cao, trung bình, thấp) đến doanh nghiệp của bạn, chọn 3 việc phải làm ngay.","takeaway":"Biết luật đổi gì là bước đầu tiên để không trả giá cho thói quen cũ."}},{"id":"KH070","code":"kh070","f":"TC","fn":"Tài chính - Quản trị","t":"Tài chính cho người không chuyên","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp người không học tài chính hiểu và dùng được các con số cốt lõi của doanh nghiệp: doanh thu, chi phí, lợi nhuận, dòng tiền, tài sản và nợ. Mỗi bài dùng ví dụ đời thường, tình huống cửa hàng – công ty nhỏ có số liệu thật và mẫu Excel dùng ngay. Sau 8 giờ, học viên tự đọc được báo cáo cơ bản và ra quyết định kinh doanh dựa trên con số thay vì cảm tính.","a":"Dành cho chủ doanh nghiệp, quản lý kinh doanh, trưởng bộ phận và người mới khởi nghiệp chưa có nền tảng tài chính – kế toán.","o":["Phân biệt được doanh thu, lợi nhuận và dòng tiền, giải thích được vì sao có lãi vẫn có thể hết tiền.","Tự đọc được 3 báo cáo tài chính cơ bản ở mức tổng quan và chỉ ra 3 điểm cần hỏi kế toán.","Tính được 6 chỉ số tài chính dễ dùng: biên lợi nhuận gộp, biên lợi nhuận ròng, vòng quay hàng tồn kho, số ngày thu tiền, khả năng thanh toán, tỷ lệ nợ.","Tính được điểm hòa vốn cho một sản phẩm hoặc cửa hàng.","Lập được bảng theo dõi tài chính 1 trang hàng tháng cho bộ phận hoặc doanh nghiệp."],"k":"Bạn giỏi bán hàng, giỏi vận hành, nhưng mỗi lần nghe kế toán báo cáo lại thấy như nghe ngoại ngữ? Khoá này dành cho bạn.","w":["Từ 2026, hộ kinh doanh bỏ thuế khoán chuyển sang tự kê khai (NQ 198/2025/QH15), người kinh doanh nhỏ buộc phải hiểu số liệu của chính mình.","Các công cụ AI và phần mềm kế toán online giúp có báo cáo trong vài phút, nhưng chỉ người hiểu con số mới dùng được báo cáo đó.","Thị trường cạnh tranh và chi phí vốn biến động khiến quyết định cảm tính ngày càng đắt giá; quản lý cần tư duy tài chính để tồn tại."],"dl":["Mẫu Excel 'Bảng tài chính 1 trang' tự tính lợi nhuận, dòng tiền và chỉ số chính.","Từ điển 50 thuật ngữ tài chính – kế toán giải thích bằng ngôn ngữ đời thường.","Checklist 15 câu hỏi nên hỏi kế toán khi nhận báo cáo hàng tháng.","Bộ câu lệnh AI (prompt) giải thích báo cáo tài chính và gợi ý câu hỏi phân tích."],"ls":["Tư duy tài chính: mọi quyết định đều có giá","Doanh thu, chi phí, lợi nhuận: ba con số nền móng","Dòng tiền: vì sao có lãi mà vẫn hết tiền","Tài sản, nợ và vốn: doanh nghiệp đang sở hữu gì","Ba báo cáo tài chính trong 30 phút","Sáu chỉ số tài chính dễ dùng mỗi tháng","Chi phí cố định, biến đổi và điểm hòa vốn","Ra quyết định bằng con số với trợ lý AI"],"l1":{"t":"Tư duy tài chính: mọi quyết định đều có giá","sum":"Bài mở đầu giúp người không chuyên hiểu tài chính là ngôn ngữ của quyết định, không phải việc riêng của kế toán. Học viên làm quen với 3 câu hỏi tài chính cốt lõi.","points":["Ba câu hỏi cốt lõi: doanh nghiệp có lãi không, có đủ tiền không, có đang mạnh lên không.","Kế toán ghi chép quá khứ, tài chính dùng số liệu để quyết định tương lai; người quản lý cần cả hai.","Mỗi quyết định (tuyển người, giảm giá, mở chi nhánh) đều có chi phí cơ hội: số tiền đó có thể dùng vào việc khác.","Tách bạch tiền cá nhân và tiền doanh nghiệp là nguyên tắc đầu tiên, kể cả với hộ kinh doanh.","Con số chỉ có ý nghĩa khi so sánh: với tháng trước, với kế hoạch, với đối thủ."],"case":"Chị Lan chủ cửa hàng Mỹ phẩm Hoa Mai dùng chung tài khoản cá nhân cho cả bán hàng và chi tiêu gia đình. Cuối năm chị không biết cửa hàng lãi bao nhiêu. Sau khi tách tài khoản và ghi chép riêng 3 tháng, chị phát hiện cửa hàng lãi khoảng 18 triệu/tháng chứ không phải 30 triệu như vẫn nghĩ.","trend":"Từ 2026, hộ kinh doanh tự kê khai thuế và giao dịch không tiền mặt phổ biến; tách bạch tài chính và ghi chép số không còn là lựa chọn mà là điều kiện tồn tại.","practice":"Viết ra 3 quyết định gần nhất bạn đã đưa ra trong công việc và ước tính chi phí, lợi ích bằng tiền của từng quyết định.","takeaway":"Không đo được bằng tiền thì khó quản trị được."}},{"id":"KH071","code":"kh071","f":"TC","fn":"Tài chính - Quản trị","t":"Quản lý dòng tiền doanh nghiệp nhỏ","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp doanh nghiệp nhỏ kiểm soát dòng tiền từ ghi chép hàng ngày đến dự báo 13 tuần và xử lý khủng hoảng thiếu tiền. Phương pháp học dựa trên tình huống thật của cửa hàng, công ty dịch vụ, thương mại cùng bộ mẫu Excel và quy trình dùng ngay. Kết thúc khoá, học viên có hệ thống theo dõi, dự báo và cảnh báo dòng tiền vận hành được hàng tuần.","a":"Dành cho chủ doanh nghiệp nhỏ, hộ kinh doanh chuyển đổi, kế toán tổng hợp và quản lý tài chính kiêm nhiệm.","o":["Thiết lập được sổ thu chi và quy trình đối chiếu ngân hàng hàng ngày, sai lệch bằng 0 cuối tuần.","Tính được chu kỳ chuyển đổi tiền mặt và chỉ ra 2 đòn bẩy rút ngắn chu kỳ.","Lập được dự báo dòng tiền 13 tuần cập nhật cuốn chiếu mỗi tuần.","Rút ngắn được số ngày thu tiền và xây chính sách thanh toán nhà cung cấp hợp lý.","Xây được kế hoạch ứng phó khi thiếu hụt dòng tiền với 3 cấp độ hành động."],"k":"Báo cáo vẫn lãi nhưng cuối tháng lại chạy vạy tiền lương? Vấn đề nằm ở dòng tiền, và nó sửa được.","w":["Từ 01/07/2025, hóa đơn từ 5 triệu đồng phải thanh toán không dùng tiền mặt để được khấu trừ GTGT và tính chi phí (NĐ 181/2025), buộc dòng tiền đi qua ngân hàng minh bạch hơn.","Hộ kinh doanh bỏ thuế khoán từ 01/01/2026 và chuyển sang tự kê khai, cần ghi chép thu chi chuẩn ngay từ đầu.","Ngân hàng số, kết nối sao kê tự động và AI giúp dự báo dòng tiền gần như theo thời gian thực, doanh nghiệp nào nắm sớm sẽ chủ động hơn trước biến động thị trường."],"dl":["Mẫu Excel dự báo dòng tiền 13 tuần có biểu đồ và cảnh báo tự động.","Mẫu sổ thu chi – đối chiếu ngân hàng hàng ngày cho doanh nghiệp nhỏ.","Checklist 20 điểm kiểm soát dòng tiền và kế hoạch ứng phó thiếu hụt.","Bộ câu lệnh AI (prompt) phân tích sao kê ngân hàng và soạn email nhắc nợ chuyên nghiệp."],"ls":["Bản chất dòng tiền và 7 sai lầm khiến doanh nghiệp nhỏ cạn tiền","Thu chi hàng ngày và đối chiếu ngân hàng không sai một đồng","Chu kỳ chuyển đổi tiền mặt: đo xem tiền bị kẹt bao lâu","Thu tiền nhanh hơn: quản lý công nợ phải thu","Tồn kho và phải trả: hai van điều tiết dòng tiền","Dự báo dòng tiền 13 tuần: nhìn trước để không bị bất ngờ","Thiếu tiền: kế hoạch ứng phó 3 cấp độ","Dashboard dòng tiền và trợ lý AI cho chủ doanh nghiệp"],"l1":{"t":"Bản chất dòng tiền và 7 sai lầm khiến doanh nghiệp nhỏ cạn tiền","sum":"Bài nền tảng giúp học viên phân biệt lợi nhuận và dòng tiền, đồng thời nhận diện các sai lầm phổ biến làm doanh nghiệp nhỏ thiếu tiền dù bán được hàng.","points":["Dòng tiền là tiền thực vào – ra tài khoản và quỹ; lợi nhuận là con số kế toán theo nguyên tắc dồn tích.","Sai lầm phổ biến: trộn tiền cá nhân và doanh nghiệp, bán chịu không giới hạn, nhập hàng theo cảm tính.","Dùng vốn ngắn hạn để đầu tư dài hạn (mua xe, sửa mặt bằng) làm doanh nghiệp hụt vốn lưu động.","Không dự trù các khoản lớn theo mùa: thuế quý, lương tháng 13, thưởng Tết, tiền thuê nhà trả trước.","Không có quỹ dự phòng: nguyên tắc tối thiểu là đủ chi phí cố định 2–3 tháng."],"case":"Cửa hàng Vật liệu Minh An dùng 400 triệu tiền thu bán hàng để mua xe tải giao hàng. Tháng sau đến kỳ nhập hàng Tết, cửa hàng không đủ tiền nhập và mất doanh thu cao điểm. Chủ cửa hàng chuyển sang vay trung hạn cho xe và giữ tiền bán hàng làm vốn lưu động.","trend":"Thanh toán không tiền mặt và ngân hàng số giúp mọi dòng tiền được ghi nhận tự động; doanh nghiệp nhỏ có cơ hội quản lý tiền chuyên nghiệp với chi phí rất thấp.","practice":"Rà soát 3 tháng gần nhất của doanh nghiệp bạn, đánh dấu những sai lầm nào trong 7 sai lầm đã xảy ra và ước tính số tiền bị 'kẹt'.","takeaway":"Lợi nhuận là ý kiến, tiền mặt là sự thật."}},{"id":"KH072","code":"kh072","f":"TC","fn":"Tài chính - Quản trị","t":"Lập kế hoạch tài chính và ngân sách năm","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học hướng dẫn lập kế hoạch tài chính và ngân sách năm từ chiến lược đến từng con số: doanh thu, giá vốn, nhân sự, vận hành, đầu tư, dòng tiền và báo cáo dự kiến. Học viên thực hành trên mô hình Excel liên kết hoàn chỉnh, tình huống doanh nghiệp Việt Nam thật và quy trình phê duyệt chuẩn. Kết thúc khoá, học viên tự lập, theo dõi và dự báo cuốn chiếu được ngân sách cho doanh nghiệp hoặc bộ phận.","a":"Dành cho kế toán trưởng, chuyên viên kế hoạch tài chính (FP&A), trưởng bộ phận và chủ doanh nghiệp vừa và nhỏ.","o":["Chuyển được mục tiêu chiến lược thành bộ giả định ngân sách có thể đo lường.","Lập được ngân sách doanh thu, giá vốn, nhân sự, chi phí vận hành và đầu tư liên kết trên một mô hình Excel.","Lập được báo cáo kết quả kinh doanh, bảng cân đối và ngân sách dòng tiền dự kiến 12 tháng.","Phân tích được chênh lệch thực tế – ngân sách theo giá, lượng, cơ cấu và đề xuất hành động.","Vận hành được dự báo cuốn chiếu hàng quý và kịch bản tốt – cơ sở – xấu."],"k":"Ngân sách làm xong rồi cất ngăn kéo là ngân sách vô dụng; năm 2026 cần một ngân sách sống, cập nhật theo thị trường.","w":["Thuế TNDN phân tầng 15%/17%/20% theo doanh thu từ kỳ 2025 và VAT 8% đến hết 2026 làm thay đổi giả định lợi nhuận và giá bán, ngân sách cũ không còn đúng.","Mức giảm trừ gia cảnh mới từ 2026 và Luật BHXH 2024 ảnh hưởng trực tiếp đến chi phí nhân sự và thu nhập thực nhận của người lao động.","Các công cụ dự báo dựa trên dữ liệu và AI cho phép chuyển từ ngân sách tĩnh sang dự báo cuốn chiếu, xu hướng tất yếu của quản trị tài chính hiện đại."],"dl":["Mô hình Excel ngân sách năm liên kết 9 sheet: giả định, doanh thu, giá vốn, nhân sự, vận hành, đầu tư, KQKD, CĐKT, dòng tiền.","Mẫu báo cáo phân tích chênh lệch ngân sách hàng tháng có biểu đồ.","Quy trình SOP lập – phê duyệt – theo dõi ngân sách kèm lịch thời gian.","Bộ câu lệnh AI (prompt) xây kịch bản, kiểm tra giả định và viết thuyết minh ngân sách."],"ls":["Từ chiến lược đến kế hoạch tài chính","Ngân sách doanh thu: điểm xuất phát của mọi con số","Ngân sách giá vốn, mua hàng và tồn kho","Ngân sách nhân sự và chi phí vận hành","Ngân sách đầu tư và nguồn vốn","Báo cáo dự kiến và ngân sách dòng tiền","Phân tích chênh lệch: từ con số đến hành động","Dự báo cuốn chiếu, kịch bản và AI trong FP&A"],"l1":{"t":"Từ chiến lược đến kế hoạch tài chính","sum":"Bài nền tảng giúp học viên nối chiến lược với con số: ngân sách là bản dịch chiến lược sang ngôn ngữ tiền. Học viên xây được bộ giả định gốc cho mô hình.","points":["Quy trình chuẩn: mục tiêu chiến lược, giả định chính, ngân sách bộ phận, tổng hợp, phê duyệt, theo dõi.","Giả định chính gồm tăng trưởng thị trường, giá bán, sản lượng, lạm phát chi phí, tăng lương, tỷ giá, lãi suất.","Có hai cách tiếp cận: từ trên xuống (ban giám đốc đặt mục tiêu) và từ dưới lên (bộ phận đề xuất); nên kết hợp cả hai.","Mỗi giả định phải có nguồn và người chịu trách nhiệm, đặt tập trung trên một sheet để thay đổi dễ dàng.","Lịch lập ngân sách nên bắt đầu từ tháng 9–10 để kịp phê duyệt trước năm mới."],"case":"Công ty TNHH Thực phẩm Minh An đặt mục tiêu tăng trưởng 25% nhưng các bộ phận lập ngân sách rời rạc, tổng hợp chỉ tăng 12% còn chi phí tăng 30%. Kế toán trưởng dựng sheet giả định chung, tổ chức 2 vòng điều chỉnh, ngân sách cuối cùng thống nhất mức tăng 20% với biên lợi nhuận được bảo vệ.","trend":"FP&A hiện đại chuyển từ 'lập ngân sách' sang 'quản trị hiệu suất liên tục'; dự kiến đến 2030 nhiều doanh nghiệp vừa sẽ dùng nền tảng lập kế hoạch đám mây kết nối dữ liệu thời gian thực.","practice":"Viết 3 mục tiêu chiến lược năm tới của doanh nghiệp và chuyển thành 10 giả định ngân sách có con số cụ thể trên sheet giả định của mô hình mẫu.","takeaway":"Ngân sách tốt bắt đầu từ giả định rõ ràng, không phải từ số năm ngoái cộng 10%."}},{"id":"KH073","code":"kh073","f":"TC","fn":"Tài chính - Quản trị","t":"Phân tích điểm hòa vốn và định giá sản phẩm","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp doanh nghiệp nhỏ tính đúng điểm hòa vốn, lợi nhuận mục tiêu và xây chính sách giá có lãi cho từng sản phẩm, dịch vụ. Học viên thực hành trên bảng tính định giá – hòa vốn dùng ngay với tình huống cửa hàng, nhà hàng, công ty dịch vụ tại Việt Nam. Kết thúc khoá, học viên tự định giá, tính tác động của khuyến mãi, chiết khấu, thuế và ra quyết định giá có căn cứ.","a":"Dành cho chủ doanh nghiệp nhỏ, người kinh doanh online, quản lý bán hàng và kế toán muốn hỗ trợ quyết định giá.","o":["Phân loại được chi phí cố định, biến đổi và tính được lãi trên biến phí cho từng sản phẩm.","Tính được sản lượng, doanh thu hòa vốn và lợi nhuận mục tiêu cho doanh nghiệp đơn sản phẩm và đa sản phẩm.","Lập được bảng giá theo 3 phương pháp: chi phí cộng lãi, giá trị khách hàng, cạnh tranh.","Tính được tác động của chiết khấu, khuyến mãi, phí sàn và thuế đến lợi nhuận trước khi triển khai.","Xây được bảng tính định giá – hòa vốn tự động cho doanh nghiệp mình."],"k":"Định giá theo đối thủ hay theo cảm tính là cách nhanh nhất để bán càng nhiều càng lỗ. Hãy để con số quyết định giá.","w":["VAT 8% đến hết 31/12/2026 (NQ 204/2025/QH15) và thuế TNDN phân tầng theo doanh thu từ 2025 làm thay đổi giá bán và lợi nhuận sau thuế, cần tính lại bảng giá.","Sàn thương mại điện tử khấu trừ, nộp thay thuế cho hộ, cá nhân kinh doanh (NĐ 117/2025) cùng phí sàn ngày càng cao khiến người bán online phải định giá chính xác từng kênh.","Định giá động dựa trên dữ liệu và AI đang trở thành vũ khí cạnh tranh, doanh nghiệp nhỏ cần nền tảng hòa vốn vững để không bị cuốn vào cuộc đua giảm giá."],"dl":["Bảng tính Excel định giá – hòa vốn đa sản phẩm có mô phỏng kịch bản.","Công cụ tính giá bán theo kênh: cửa hàng, sàn thương mại điện tử, đại lý.","Checklist 12 câu hỏi trước khi chạy khuyến mãi.","Bộ câu lệnh AI (prompt) phân tích giá đối thủ và gợi ý gói sản phẩm."],"ls":["Phân loại chi phí để ra quyết định","Lãi trên biến phí: con số quan trọng nhất bạn chưa theo dõi","Tính điểm hòa vốn trong 10 phút","Lợi nhuận mục tiêu, số dư an toàn và đòn bẩy hoạt động","Hòa vốn cho doanh nghiệp nhiều sản phẩm","Ba phương pháp định giá và cách kết hợp","Thuế, phí sàn, chiết khấu và khuyến mãi trong định giá","Bảng tính định giá – hòa vốn thông minh với AI"],"l1":{"t":"Phân loại chi phí để ra quyết định","sum":"Bài nền tảng giúp học viên nhìn chi phí theo cách nhà quản trị: cố định hay biến đổi, liên quan hay không liên quan đến quyết định.","points":["Chi phí biến đổi thay đổi theo sản lượng: nguyên vật liệu, bao bì, hoa hồng, phí giao hàng, phí sàn theo đơn.","Chi phí cố định không đổi trong phạm vi hoạt động: thuê mặt bằng, lương cố định, khấu hao, phần mềm.","Chi phí hỗn hợp (điện, nhân công có lương cứng + thưởng) cần tách bằng phương pháp cực đại – cực tiểu hoặc hồi quy.","Chi phí chìm (đã chi, không thu hồi) không nên ảnh hưởng đến quyết định hiện tại.","Phân loại đúng chi phí là điều kiện tiên quyết để tính hòa vốn và định giá chính xác."],"case":"Nhà hàng Bếp Việt có tiền điện 25 triệu tháng thấp điểm (800 suất) và 37 triệu tháng cao điểm (2.000 suất). Tách theo phương pháp cực đại – cực tiểu: biến phí 10.000 đồng/suất, định phí 17 triệu/tháng. Nhờ đó chủ nhà hàng tính đúng giá vốn từng suất ăn.","trend":"Phần mềm kế toán và bán hàng hiện đại cho phép gắn mã chi phí theo sản phẩm, đơn hàng; dữ liệu chi phí chi tiết sẽ là nền tảng cho định giá thông minh.","practice":"Liệt kê 15 khoản chi phí của doanh nghiệp bạn, phân loại cố định – biến đổi – hỗn hợp và tách chi phí hỗn hợp lớn nhất bằng phương pháp cực đại – cực tiểu.","takeaway":"Chi phí được phân loại đúng thì quyết định mới đúng."}},{"id":"KH074","code":"kh074","f":"TC","fn":"Tài chính - Quản trị","t":"Quản trị chi phí và tối ưu lợi nhuận","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học trang bị hệ thống quản trị chi phí hiện đại: mã chi phí, giá thành, chi phí dựa trên hoạt động (ABC), phân tích lợi nhuận theo sản phẩm – khách hàng – kênh và chương trình tối ưu lợi nhuận. Học viên thực hành trên dữ liệu doanh nghiệp sản xuất, thương mại, dịch vụ Việt Nam với mô hình Excel và quy trình dùng ngay. Kết thúc khoá, học viên chỉ ra được đâu là chi phí tạo giá trị, đâu là lãng phí, và triển khai được kế hoạch tăng lợi nhuận đo lường được.","a":"Dành cho kế toán quản trị, kế toán trưởng, giám đốc tài chính, quản lý vận hành và chủ doanh nghiệp vừa và nhỏ.","o":["Thiết kế được hệ thống trung tâm chi phí và mã chi phí phục vụ quản trị.","Tính được giá thành sản phẩm, dịch vụ theo phương pháp truyền thống và ABC, giải thích được chênh lệch.","Lập được báo cáo lợi nhuận theo sản phẩm, khách hàng, kênh và xác định nhóm lỗ ẩn.","Phân tích được chênh lệch chi phí định mức – thực tế theo giá và lượng.","Triển khai được chương trình tối ưu lợi nhuận 90 ngày với KPI đo lường."],"k":"Cắt giảm chi phí theo kiểu đồng loạt 10% thường cắt nhầm vào chính nguồn tạo ra lợi nhuận. Có cách làm thông minh hơn.","w":["Thuế TNDN phân tầng theo doanh thu và quy định chặt về điều kiện chi phí được trừ (thanh toán không dùng tiền mặt từ 5 triệu) đòi hỏi quản trị chi phí gắn với tuân thủ thuế.","Chi phí nhân công, năng lượng, logistics có xu hướng tăng; doanh nghiệp không còn tăng trưởng bằng giá rẻ mà phải bằng hiệu quả.","Tự động hóa, AI và dữ liệu chi tiết cho phép phân tích chi phí đến từng đơn hàng, từng khách hàng, mở ra dư địa tối ưu chưa từng có."],"dl":["Mô hình Excel tính giá thành ABC và lợi nhuận theo khách hàng – kênh.","Mẫu hệ thống mã chi phí và trung tâm trách nhiệm cho doanh nghiệp vừa và nhỏ.","Bộ 30 sáng kiến tối ưu chi phí theo nhóm kèm cách đo lường.","Bộ câu lệnh AI (prompt) phân tích chi phí bất thường và xây kế hoạch tối ưu."],"ls":["Tư duy quản trị chi phí hiện đại: chi tiêu để tạo giá trị","Trung tâm chi phí và hệ thống mã chi phí","Tính giá thành sản phẩm và dịch vụ","Chi phí dựa trên hoạt động (ABC): tìm ra lỗ ẩn","Lợi nhuận theo sản phẩm, khách hàng và kênh","Chi phí định mức và phân tích chênh lệch","Tối ưu chi phí bằng tự động hóa, AI và chuẩn ESG","Chương trình tối ưu lợi nhuận 90 ngày"],"l1":{"t":"Tư duy quản trị chi phí hiện đại: chi tiêu để tạo giá trị","sum":"Bài mở đầu thay đổi góc nhìn từ cắt giảm chi phí sang quản trị chi phí chiến lược: giữ chi phí tạo giá trị, loại bỏ lãng phí.","points":["Phân loại chi phí theo giá trị: tạo giá trị khách hàng, cần thiết nhưng không tạo giá trị, lãng phí.","Cắt giảm đồng loạt dễ làm tổn hại năng lực cạnh tranh (đào tạo, marketing, chất lượng).","Chi phí được quản lý tốt nhất ở nơi phát sinh, bởi người ra quyết định chi tiêu.","Kết nối quản trị chi phí với chiến lược: dẫn đầu chi phí hay khác biệt hóa đòi hỏi cấu trúc chi phí khác nhau.","Chi phí cũng phải hợp lệ về thuế: có hóa đơn, chứng từ, thanh toán không dùng tiền mặt từ 5 triệu đồng và phục vụ hoạt động kinh doanh."],"case":"Công ty TNHH Thời trang Minh An cắt 30% ngân sách marketing để giảm chi phí, doanh thu quý sau giảm 18% và lợi nhuận còn thấp hơn trước. Năm sau, doanh nghiệp phân loại chi phí theo giá trị, giữ marketing hiệu quả, cắt chi phí kho bãi dư thừa và đạt mục tiêu lợi nhuận.","trend":"Quản trị chi phí chiến lược kết hợp dữ liệu thời gian thực đang thay thế mô hình kiểm soát chi phí cuối kỳ; ESG cũng đưa thêm chi phí năng lượng, phát thải vào phạm vi quản trị.","practice":"Liệt kê 20 khoản chi phí lớn nhất năm qua và phân loại theo 3 nhóm giá trị; chọn 3 khoản lãng phí để xử lý.","takeaway":"Mục tiêu không phải chi ít nhất, mà là mỗi đồng chi ra tạo nhiều giá trị nhất."}},{"id":"KH075","code":"kh075","f":"TC","fn":"Tài chính - Quản trị","t":"Đọc báo cáo tài chính dành cho chủ doanh nghiệp","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp chủ doanh nghiệp đọc hiểu bộ báo cáo tài chính mà không cần học kế toán: kết quả kinh doanh, bảng cân đối, lưu chuyển tiền tệ và thuyết minh. Học viên thực hành trên báo cáo thật của doanh nghiệp Việt Nam (đã ẩn danh), với checklist đọc nhanh và bộ câu hỏi dùng ngay khi làm việc với kế toán. Kết thúc khoá, học viên tự đánh giá được sức khỏe tài chính, phát hiện dấu hiệu rủi ro thuế và dùng báo cáo để ra quyết định.","a":"Dành cho chủ doanh nghiệp, giám đốc điều hành, nhà đầu tư cá nhân và quản lý cấp cao không có nền tảng kế toán.","o":["Đọc được Báo cáo kết quả kinh doanh và chỉ ra nguồn gốc lợi nhuận hoặc thua lỗ.","Đọc được Bảng cân đối kế toán và đánh giá khả năng thanh toán, mức độ vay nợ.","Đọc được Báo cáo lưu chuyển tiền tệ và giải thích vì sao lợi nhuận khác dòng tiền.","Tính và diễn giải được 10 chỉ số tài chính cốt lõi.","Nhận diện được 8 dấu hiệu cảnh báo rủi ro tài chính và rủi ro thuế trên báo cáo."],"k":"Bạn ký báo cáo tài chính mỗi năm, nhưng có thật sự hiểu nó đang nói gì về doanh nghiệp của mình không?","w":["Từ 01/01/2026, TT 99/2025 thay TT 200/2014 cho doanh nghiệp áp dụng chế độ kế toán doanh nghiệp, mẫu báo cáo và cách trình bày có thay đổi cần nắm.","Cơ quan thuế ngày càng dùng dữ liệu hóa đơn điện tử và phân tích rủi ro để đối chiếu với báo cáo tài chính; chủ doanh nghiệp ký báo cáo phải chịu trách nhiệm về số liệu.","AI có thể tóm tắt báo cáo trong vài giây, nhưng chỉ người hiểu bản chất mới đặt được câu hỏi đúng và tránh bị dẫn sai."],"dl":["Checklist đọc báo cáo tài chính trong 30 phút dành cho chủ doanh nghiệp.","File Excel tự tính 10 chỉ số tài chính từ báo cáo nhập vào, có nhận xét tự động.","Bộ 25 câu hỏi nên hỏi kế toán, kiểm toán viên trước khi ký báo cáo.","Bộ câu lệnh AI (prompt) phân tích báo cáo tài chính và so sánh nhiều năm."],"ls":["Bộ báo cáo tài chính gồm những gì và ai chịu trách nhiệm","Đọc Báo cáo kết quả kinh doanh: lợi nhuận đến từ đâu","Đọc Bảng cân đối kế toán: doanh nghiệp đứng vững đến đâu","Đọc Báo cáo lưu chuyển tiền tệ: sự thật về tiền","Thuyết minh báo cáo tài chính: nơi chứa câu trả lời","Mười chỉ số tài chính chủ doanh nghiệp cần biết","Dấu hiệu cảnh báo và rủi ro thuế trên báo cáo","Dùng báo cáo tài chính và AI để ra quyết định"],"l1":{"t":"Bộ báo cáo tài chính gồm những gì và ai chịu trách nhiệm","sum":"Bài nền tảng giới thiệu cấu trúc bộ báo cáo tài chính theo chế độ kế toán Việt Nam và trách nhiệm của người ký.","points":["Bộ báo cáo gồm Báo cáo tình hình tài chính (Bảng cân đối kế toán), Báo cáo kết quả hoạt động kinh doanh, Báo cáo lưu chuyển tiền tệ và Thuyết minh.","Doanh nghiệp nhỏ và vừa thường áp dụng TT 133/2016; doanh nghiệp khác áp dụng TT 99/2025 thay TT 200/2014 từ 01/01/2026.","Người đại diện theo pháp luật ký báo cáo và chịu trách nhiệm về tính trung thực, kể cả khi thuê dịch vụ kế toán.","Báo cáo tài chính năm nộp cùng quyết toán thuế TNDN chậm nhất ngày cuối tháng thứ 3 sau khi kết thúc năm tài chính.","Một số doanh nghiệp bắt buộc kiểm toán (ví dụ doanh nghiệp có vốn đầu tư nước ngoài); báo cáo kiểm toán tăng độ tin cậy với ngân hàng, đối tác."],"case":"Bà Hạnh, giám đốc Công ty TNHH Thương mại Minh An, ký báo cáo tài chính do dịch vụ kế toán lập mà không đọc. Khi cơ quan thuế kiểm tra, phát hiện doanh thu trên báo cáo thấp hơn tổng hóa đơn đầu ra 600 triệu. Bà phải giải trình và chịu truy thu, phạt. Từ đó bà yêu cầu buổi rà soát 1 giờ trước mỗi lần ký.","trend":"Dữ liệu hóa đơn, tờ khai và báo cáo tài chính dự kiến được đối chiếu tự động ngày càng sâu; chữ ký của chủ doanh nghiệp sẽ mang trách nhiệm rõ ràng hơn bao giờ hết.","practice":"Lấy bộ báo cáo tài chính gần nhất của doanh nghiệp bạn, xác định doanh nghiệp đang áp dụng chế độ kế toán nào và liệt kê đủ các thành phần của bộ báo cáo.","takeaway":"Ký vào báo cáo là nhận trách nhiệm về từng con số trong đó."}},{"id":"KH076","code":"kh076","f":"TC","fn":"Tài chính - Quản trị","t":"Vay vốn ngân hàng: hồ sơ và phương án kinh doanh","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp doanh nghiệp hiểu ngân hàng thẩm định như thế nào, chuẩn bị hồ sơ pháp lý – tài chính minh bạch và xây phương án kinh doanh thuyết phục. Học viên thực hành trên hồ sơ vay thật (đã ẩn danh), mô hình dòng tiền trả nợ Excel và checklist làm việc với cán bộ tín dụng. Kết thúc khoá, học viên tự lập được bộ hồ sơ vay hoàn chỉnh, đàm phán điều kiện tốt hơn và quản lý khoản vay an toàn.","a":"Dành cho chủ doanh nghiệp vừa và nhỏ, kế toán trưởng, giám đốc tài chính và chuyên viên tư vấn tài chính doanh nghiệp.","o":["Giải thích được quy trình và tiêu chí thẩm định tín dụng của ngân hàng thương mại.","Chọn được sản phẩm tín dụng phù hợp với nhu cầu vốn lưu động, đầu tư hoặc bảo lãnh.","Lập được bộ hồ sơ pháp lý – tài chính – tài sản đảm bảo đầy đủ, nhất quán.","Xây được phương án kinh doanh và mô hình dòng tiền trả nợ với các chỉ số ngân hàng quan tâm.","Đàm phán được điều kiện vay và lập kế hoạch quản lý khoản vay, tránh nợ quá hạn."],"k":"Ngân hàng không từ chối doanh nghiệp nhỏ, họ từ chối hồ sơ không chứng minh được dòng tiền trả nợ. Hãy học cách nói ngôn ngữ của họ.","w":["Ngân hàng đang chuyển sang thẩm định dựa trên dữ liệu: hóa đơn điện tử, tờ khai thuế, sao kê, dữ liệu chủ sở hữu hưởng lợi; hồ sơ thiếu minh bạch bị loại nhanh hơn.","Từ 2026, chuẩn mực trình bày báo cáo và quy định thuế mới (TNDN phân tầng, thanh toán không tiền mặt từ 5 triệu) làm thay đổi cách ngân hàng đọc báo cáo của doanh nghiệp.","Tín dụng xanh, tài trợ chuỗi cung ứng và cho vay dựa trên dòng tiền số đang mở rộng, tạo cơ hội vốn mới cho doanh nghiệp chuẩn bị tốt."],"dl":["Mẫu phương án kinh doanh vay vốn lưu động và phương án vay đầu tư dự án.","Mô hình Excel dòng tiền trả nợ tính DSCR, kế hoạch vay – trả theo tháng.","Checklist 50 đầu mục hồ sơ vay theo nhóm pháp lý, tài chính, tài sản đảm bảo.","Bộ câu lệnh AI (prompt) soạn thuyết minh phương án và chuẩn bị câu hỏi phỏng vấn tín dụng."],"ls":["Ngân hàng thẩm định doanh nghiệp như thế nào","Chọn đúng sản phẩm tín dụng cho đúng nhu cầu","Hồ sơ pháp lý và tài chính: minh bạch là lợi thế","Tài sản đảm bảo: định giá, thế chấp và rủi ro","Phương án kinh doanh vay vốn thuyết phục","Dòng tiền trả nợ và các chỉ số ngân hàng quan tâm","Đàm phán hợp đồng tín dụng và giải ngân","Quản lý khoản vay và quan hệ tín dụng dài hạn với AI"],"l1":{"t":"Ngân hàng thẩm định doanh nghiệp như thế nào","sum":"Bài nền tảng giúp học viên nhìn khoản vay từ góc độ ngân hàng: rủi ro, khả năng trả nợ và tài sản đảm bảo. Hiểu điều này là bước đầu để chuẩn bị hồ sơ đúng trọng tâm.","points":["Khung 5C: năng lực pháp lý và uy tín (Character), năng lực trả nợ (Capacity), vốn chủ (Capital), tài sản đảm bảo (Collateral), điều kiện thị trường (Conditions).","Nguồn trả nợ chính phải là dòng tiền kinh doanh; tài sản đảm bảo chỉ là nguồn trả nợ thứ cấp.","Ngân hàng tra cứu lịch sử tín dụng tại trung tâm thông tin tín dụng (CIC); nợ nhóm 2 trở lên ảnh hưởng nghiêm trọng đến hồ sơ.","Xếp hạng tín dụng nội bộ dựa trên chỉ tiêu tài chính và phi tài chính quyết định hạn mức, lãi suất.","Quy trình chung: tiếp nhận, thẩm định, phê duyệt, ký hợp đồng, giải ngân, giám sát sau vay."],"case":"Công ty TNHH Thương mại Minh An bị từ chối vay 3 tỷ dù có tài sản đảm bảo giá trị 5 tỷ, vì báo cáo tài chính lỗ 2 năm và giám đốc có khoản nợ thẻ tín dụng cá nhân quá hạn. Doanh nghiệp xử lý dứt điểm nợ cá nhân, chuẩn hóa báo cáo năm sau và được duyệt vay.","trend":"Ngân hàng đang ứng dụng chấm điểm tín dụng tự động dựa trên dữ liệu số; dự kiến lịch sử thanh toán, dữ liệu hóa đơn và hành vi giao dịch sẽ ngày càng quyết định khả năng vay.","practice":"Tự chấm doanh nghiệp của bạn theo khung 5C với thang điểm 1–5 cho từng tiêu chí và liệt kê 3 điểm yếu cần cải thiện trước khi vay.","takeaway":"Ngân hàng cho vay dòng tiền, tài sản đảm bảo chỉ là chiếc dù dự phòng."}},{"id":"KH077","code":"kh077","f":"TC","fn":"Tài chính - Quản trị","t":"Kiểm soát nội bộ cho doanh nghiệp vừa và nhỏ","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học giúp doanh nghiệp vừa và nhỏ xây hệ thống kiểm soát nội bộ thực dụng theo khung COSO: đánh giá rủi ro, phân quyền phê duyệt, kiểm soát các chu trình mua – bán – tiền – kho – lương và phòng chống gian lận. Học viên thực hành trên ma trận rủi ro – kiểm soát, quy trình SOP và tình huống gian lận thật tại doanh nghiệp Việt Nam. Kết thúc khoá, học viên thiết kế, triển khai và tự đánh giá được hệ thống kiểm soát phù hợp quy mô, có ứng dụng dữ liệu và tự động hóa.","a":"Dành cho kế toán trưởng, giám đốc tài chính, kiểm soát viên nội bộ, chủ doanh nghiệp vừa và nhỏ đang mở rộng quy mô.","o":["Đánh giá được hệ thống kiểm soát nội bộ hiện tại theo 5 thành phần COSO.","Lập được ma trận rủi ro – kiểm soát cho 5 chu trình chính của doanh nghiệp.","Thiết kế được ma trận phân quyền, hạn mức phê duyệt và tách biệt nhiệm vụ phù hợp quy mô nhỏ.","Nhận diện được 15 dấu hiệu gian lận phổ biến và thiết lập kiểm soát phát hiện.","Xây được kế hoạch giám sát, kiểm toán nội bộ và kiểm soát liên tục bằng dữ liệu."],"k":"Phần lớn vụ thất thoát ở doanh nghiệp nhỏ không đến từ người lạ, mà từ quy trình để một người làm từ đầu đến cuối.","w":["Quy định xử phạt thuế, hóa đơn sửa đổi (NĐ 310/2025 hiệu lực 16/01/2026) và điều kiện thanh toán không tiền mặt từ 5 triệu khiến sai sót quy trình chuyển thành chi phí thật.","Luật Bảo vệ dữ liệu cá nhân hiệu lực 01/01/2026 bổ sung một nhóm rủi ro mới mà hệ thống kiểm soát phải bao quát.","Số hóa và tự động hóa cho phép kiểm soát liên tục bằng dữ liệu thay vì kiểm tra thủ công cuối kỳ, nhưng cũng tạo ra rủi ro mới về phân quyền hệ thống và gian lận số."],"dl":["Mẫu ma trận rủi ro – kiểm soát (RCM) cho 5 chu trình: mua hàng, bán hàng, tiền, kho – tài sản, nhân sự – lương.","Bộ quy trình SOP và ma trận phân quyền phê duyệt mẫu cho doanh nghiệp 20–200 nhân sự.","Checklist tự đánh giá kiểm soát nội bộ 80 câu hỏi theo COSO.","Bộ câu lệnh AI (prompt) và công thức Excel phát hiện giao dịch bất thường."],"ls":["Khung COSO thu gọn cho doanh nghiệp vừa và nhỏ","Đánh giá rủi ro và ma trận rủi ro – kiểm soát","Phân quyền, phê duyệt và tách biệt nhiệm vụ","Kiểm soát chu trình mua hàng – thanh toán","Kiểm soát chu trình bán hàng – thu tiền","Kiểm soát tiền, hàng tồn kho và tài sản cố định","Nhân sự – tiền lương và phòng chống gian lận","Giám sát liên tục, kiểm toán nội bộ và kiểm soát bằng dữ liệu"],"l1":{"t":"Khung COSO thu gọn cho doanh nghiệp vừa và nhỏ","sum":"Bài nền tảng giới thiệu khung kiểm soát nội bộ COSO và cách áp dụng thực dụng cho doanh nghiệp có nguồn lực hạn chế.","points":["Năm thành phần COSO: môi trường kiểm soát, đánh giá rủi ro, hoạt động kiểm soát, thông tin và truyền thông, giám sát.","Môi trường kiểm soát bắt đầu từ thái độ của chủ doanh nghiệp: tự mình tuân thủ quy trình thì nhân viên mới tuân thủ.","Kiểm soát nội bộ chỉ đem lại sự đảm bảo hợp lý, không tuyệt đối; chi phí kiểm soát không nên vượt lợi ích.","Ba tuyến phòng vệ: bộ phận vận hành, bộ phận kiểm soát (kế toán, pháp chế), kiểm toán nội bộ hoặc thuê ngoài.","Doanh nghiệp nhỏ bù đắp thiếu nhân sự bằng giám sát trực tiếp của chủ và kiểm soát tự động trên phần mềm."],"case":"Công ty TNHH Phân phối Minh An tăng từ 15 lên 80 nhân sự trong 2 năm nhưng giám đốc vẫn tự duyệt mọi khoản chi. Hàng tồn kho chênh lệch 700 triệu không giải thích được. Doanh nghiệp đánh giá theo COSO, phát hiện điểm yếu ở hoạt động kiểm soát kho và giám sát, rồi ưu tiên khắc phục 2 thành phần này.","trend":"Khung COSO đang được mở rộng áp dụng cho rủi ro ESG, an ninh mạng và dữ liệu; doanh nghiệp vừa và nhỏ dự kiến sẽ phải chứng minh kiểm soát nội bộ khi làm việc với ngân hàng, nhà đầu tư.","practice":"Dùng checklist 80 câu của khoá tự đánh giá doanh nghiệp theo 5 thành phần COSO, chấm điểm và chọn 2 thành phần yếu nhất.","takeaway":"Kiểm soát nội bộ bắt đầu từ tấm gương của người đứng đầu."}},{"id":"KH078","code":"kh078","f":"TC","fn":"Tài chính - Quản trị","t":"Quản trị công nợ và rủi ro tín dụng khách hàng","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học xây hệ thống quản trị công nợ phải thu từ chính sách tín dụng, thẩm định và cấp hạn mức khách hàng, theo dõi tuổi nợ đến thu hồi, dự phòng và xử lý pháp lý. Học viên thực hành trên mô hình chấm điểm tín dụng, báo cáo tuổi nợ Excel và kịch bản thu nợ dùng ngay từ tình huống doanh nghiệp Việt Nam. Kết thúc khoá, học viên giảm được số ngày thu tiền, tỷ lệ nợ quá hạn và chủ động xử lý nợ xấu đúng luật, đúng thuế.","a":"Dành cho kế toán công nợ, kế toán trưởng, quản lý bán hàng, giám đốc tài chính và chủ doanh nghiệp bán hàng trả chậm.","o":["Ban hành được chính sách tín dụng khách hàng gồm tiêu chí, hạn mức, điều khoản thanh toán và thẩm quyền phê duyệt.","Chấm điểm và cấp hạn mức tín dụng cho khách hàng bằng mô hình định lượng.","Lập và phân tích được báo cáo tuổi nợ, số ngày thu tiền (DSO) hàng tuần.","Vận hành được quy trình thu nợ 5 bước với kịch bản nhắc nợ chuẩn.","Trích lập dự phòng, xử lý nợ khó đòi đúng chế độ kế toán, thuế và chuẩn bị hồ sơ pháp lý khi cần."],"k":"Mỗi khoản nợ khó đòi xóa sổ có thể nuốt mất lợi nhuận của nhiều đơn hàng tốt. Quản trị công nợ là bảo vệ chính lợi nhuận của bạn.","w":["Dữ liệu hóa đơn điện tử, thanh toán số và thông tin chủ sở hữu hưởng lợi giúp thẩm định khách hàng chính xác hơn bao giờ hết, doanh nghiệp nào khai thác sớm sẽ giảm rủi ro nợ xấu.","Chi phí vốn và áp lực dòng tiền khiến bán chịu không kiểm soát trở thành rủi ro sống còn, đặc biệt với doanh nghiệp nhỏ có biên lợi nhuận mỏng.","Nhắc nợ tự động, chấm điểm tín dụng bằng dữ liệu và AI đang thay đổi cách thu hồi công nợ; quy trình thủ công sẽ ngày càng kém hiệu quả."],"dl":["Mẫu chính sách tín dụng khách hàng và quy trình phê duyệt hạn mức.","Mô hình Excel chấm điểm tín dụng khách hàng và báo cáo tuổi nợ tự động.","Bộ kịch bản và mẫu thư nhắc nợ 5 cấp độ, mẫu biên bản đối chiếu công nợ.","Bộ câu lệnh AI (prompt) phân tích rủi ro khách hàng và soạn nội dung nhắc nợ cá nhân hóa."],"ls":["Công nợ phải thu: tài sản hay rủi ro?","Chính sách tín dụng khách hàng: luật chơi rõ ràng","Thẩm định khách hàng và cấp hạn mức bằng dữ liệu","Theo dõi công nợ và báo cáo tuổi nợ","Quy trình thu nợ 5 bước chuyên nghiệp","Công cụ giảm rủi ro tín dụng","Nợ khó đòi: dự phòng, xử lý kế toán và thuế","Biện pháp pháp lý và hệ thống quản trị công nợ số"],"l1":{"t":"Công nợ phải thu: tài sản hay rủi ro?","sum":"Bài nền tảng giúp học viên hiểu chi phí thật của bán chịu và mối liên hệ giữa công nợ, dòng tiền và lợi nhuận.","points":["Bán chịu giúp tăng doanh số nhưng phát sinh chi phí vốn, chi phí quản lý và rủi ro mất trắng.","Chi phí vốn của bán chịu = Phải thu bình quân × Lãi suất vốn; một khoản phải thu treo lâu đang 'ăn' dần lợi nhuận.","Mất 100 triệu nợ xấu với biên lợi nhuận ròng 5% tương đương mất lợi nhuận của 2 tỷ doanh thu.","Số ngày thu tiền (DSO) = Phải thu cuối kỳ / Doanh thu bán chịu × số ngày trong kỳ.","Quản trị công nợ là trách nhiệm chung của kinh doanh và tài chính, không riêng kế toán."],"case":"Công ty TNHH Vật liệu Minh An có biên lợi nhuận ròng 4%, năm qua xóa 240 triệu nợ không đòi được, tương đương lợi nhuận của 6 tỷ doanh thu. Giám đốc yêu cầu đưa tỷ lệ thu hồi công nợ vào KPI của nhân viên kinh doanh, không chỉ doanh số.","trend":"Doanh nghiệp đang chuyển từ KPI doanh số sang KPI doanh thu đã thu tiền; dự kiến dữ liệu công nợ thời gian thực sẽ được dùng trực tiếp để tính thưởng kinh doanh.","practice":"Tính DSO 12 tháng qua của doanh nghiệp bạn và quy đổi tổng nợ quá hạn ra số doanh thu tương đương cần bán thêm để bù lợi nhuận.","takeaway":"Doanh số chưa thu được tiền chỉ là lời hứa."}},{"id":"KH079","code":"kh079","f":"TC","fn":"Tài chính - Quản trị","t":"Định giá doanh nghiệp nhập môn","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học trang bị nền tảng định giá doanh nghiệp bài bản: chuẩn hóa báo cáo tài chính, phương pháp tài sản thuần, chiết khấu dòng tiền (DCF), so sánh bội số và tổng hợp kết quả cho đàm phán. Học viên thực hành trên mô hình Excel định giá hoàn chỉnh với số liệu doanh nghiệp Việt Nam vừa và nhỏ. Kết thúc khoá, học viên tự xây được mô hình định giá, bảo vệ được giả định và hiểu các vấn đề thuế khi chuyển nhượng vốn.","a":"Dành cho giám đốc tài chính, kế toán trưởng, chuyên viên tư vấn tài chính – M&A, nhà đầu tư và chủ doanh nghiệp chuẩn bị gọi vốn hoặc chuyển nhượng.","o":["Chuẩn hóa được báo cáo tài chính doanh nghiệp nhỏ trước khi định giá.","Định giá được doanh nghiệp bằng phương pháp tài sản thuần có điều chỉnh.","Xây được mô hình DCF hoàn chỉnh: dự báo dòng tiền tự do, WACC, giá trị cuối kỳ.","Định giá được bằng bội số thị trường (P/E, EV/EBITDA) với điều chỉnh phù hợp.","Tổng hợp được khoảng giá trị, phân tích độ nhạy và chuẩn bị luận điểm đàm phán."],"k":"Gọi vốn, bán cổ phần hay mua lại doanh nghiệp, câu hỏi đầu tiên luôn là: doanh nghiệp này đáng giá bao nhiêu, và vì sao?","w":["Hoạt động M&A, gọi vốn khởi nghiệp và chuyển giao thế hệ doanh nghiệp gia đình tại Việt Nam dự kiến tiếp tục sôi động, nhu cầu định giá chuyên nghiệp tăng mạnh.","Quy định minh bạch chủ sở hữu hưởng lợi (Luật Doanh nghiệp sửa đổi 2025) và thuế tối thiểu toàn cầu (NQ 107/2023/QH15) ảnh hưởng đến cấu trúc giao dịch và giá trị.","Mô hình tài chính hỗ trợ bởi AI và dữ liệu thị trường giúp định giá nhanh hơn, nhưng đòi hỏi người định giá hiểu sâu bản chất để kiểm soát giả định."],"dl":["Mô hình Excel định giá 3 phương pháp liên kết: tài sản thuần, DCF, bội số.","Checklist chuẩn hóa báo cáo tài chính và thẩm định nhanh trước định giá.","Mẫu báo cáo định giá 10 trang với cấu trúc chuyên nghiệp.","Bộ câu lệnh AI (prompt) kiểm tra giả định, viết thuyết minh và chuẩn bị câu hỏi đàm phán."],"ls":["Giá trị, giá cả và mục đích định giá","Chuẩn hóa báo cáo tài chính trước khi định giá","Phương pháp tài sản thuần có điều chỉnh","Dòng tiền tự do và dự báo tài chính","Chi phí vốn (WACC) và giá trị cuối kỳ","Hoàn thiện mô hình DCF và kiểm định","Phương pháp so sánh bội số thị trường","Tổng hợp kết quả, đàm phán và thuế chuyển nhượng"],"l1":{"t":"Giá trị, giá cả và mục đích định giá","sum":"Bài nền tảng phân biệt giá trị và giá cả, các mục đích định giá khác nhau và nguyên tắc chọn phương pháp phù hợp.","points":["Giá trị là ước tính dựa trên phân tích; giá là con số thỏa thuận cuối cùng giữa người mua và người bán.","Mục đích định giá: gọi vốn, mua bán – sáp nhập, chuyển nhượng nội bộ, phân chia tài sản, vay vốn, tái cấu trúc.","Ba cách tiếp cận chính: tài sản (doanh nghiệp có gì), thu nhập (doanh nghiệp tạo ra bao nhiêu tiền), thị trường (doanh nghiệp tương tự được trả bao nhiêu).","Giá trị doanh nghiệp (EV) = Giá trị vốn chủ sở hữu + Nợ vay ròng; cần phân biệt khi đàm phán.","Định giá luôn gắn với một thời điểm, một bộ giả định và một góc nhìn (người mua chiến lược hay nhà đầu tư tài chính)."],"case":"Hai cổ đông Công ty CP Thực phẩm Minh An tranh cãi khi một người muốn rút vốn: người bán đòi theo giá kỳ vọng tương lai, người mua muốn theo sổ sách. Chuyên gia định giá làm rõ mục đích là chuyển nhượng nội bộ, đề xuất kết hợp tài sản thuần và DCF, đưa ra khoảng giá hợp lý được hai bên chấp nhận.","trend":"Định giá ngày càng chú trọng tài sản vô hình (dữ liệu, thương hiệu, công nghệ) và yếu tố ESG; người định giá cần mở rộng phạm vi phân tích ngoài báo cáo tài chính.","practice":"Với 3 tình huống (gọi vốn startup, bán công ty gia đình, mua lại nhà phân phối), xác định mục đích, góc nhìn và phương pháp định giá phù hợp nhất.","takeaway":"Hỏi đúng mục đích định giá là đã đi được nửa đường."}},{"id":"KH080","code":"kh080","f":"TC","fn":"Tài chính - Quản trị","t":"Mô hình kinh doanh số và tăng trưởng bền vững","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp doanh nghiệp thiết kế và kiểm chứng mô hình kinh doanh số: từ Business Model Canvas, kinh tế đơn vị (CAC, LTV, biên đóng góp), con đường tăng trưởng đến tài chính cho tăng trưởng và thực thi bằng OKR. Học viên thực hành trên tình huống doanh nghiệp Việt Nam chuyển đổi số, với mô hình Excel kinh tế đơn vị và bộ công cụ chiến lược dùng ngay. Kết thúc khoá, học viên xây được kế hoạch tăng trưởng có số liệu, có lãi và phù hợp xu hướng ESG.","a":"Dành cho chủ doanh nghiệp, giám đốc kinh doanh – marketing, quản lý chiến lược, nhà sáng lập startup và giám đốc tài chính.","o":["Mô tả được mô hình kinh doanh hiện tại bằng Business Model Canvas và chỉ ra 3 điểm yếu.","Tính được kinh tế đơn vị: CAC, LTV, tỷ lệ LTV/CAC, thời gian hoàn vốn CAC, biên đóng góp.","Lựa chọn được con đường tăng trưởng phù hợp dựa trên ma trận Ansoff và dữ liệu.","Lập được kế hoạch tài chính cho tăng trưởng với nhu cầu vốn và kịch bản.","Thiết lập được hệ thống OKR – KPI và nhịp quản trị để thực thi chiến lược."],"k":"Tăng trưởng nhanh bằng đốt tiền đã hết thời; năm 2026 thị trường thưởng cho mô hình số có lãi và bền vững.","w":["Thương mại điện tử và nền tảng số tăng trưởng mạnh, cùng quy định sàn khấu trừ thuế thay hộ, cá nhân kinh doanh (NĐ 117/2025) thay đổi cách tính lợi nhuận kênh online.","AI tạo sinh và tự động hóa đang tái định hình chi phí, cách bán hàng và trải nghiệm khách hàng; mô hình kinh doanh cũ có nguy cơ bị thay thế nhanh.","Nhà đầu tư, ngân hàng và khách hàng lớn ngày càng đòi hỏi tăng trưởng có lãi, minh bạch dữ liệu và tiêu chí ESG."],"dl":["Mẫu Business Model Canvas và Value Proposition Canvas có hướng dẫn điền.","Mô hình Excel kinh tế đơn vị và kế hoạch tăng trưởng 3 năm.","Bộ thư viện 20 mô hình kinh doanh số kèm ví dụ ứng dụng tại Việt Nam.","Bộ câu lệnh AI (prompt) phân tích đối thủ, tạo ý tưởng đổi mới mô hình và soạn OKR."],"ls":["Mô hình kinh doanh: doanh nghiệp tạo, trao và thu giá trị thế nào","Business Model Canvas và đề xuất giá trị","Kinh tế đơn vị: kiểm chứng mô hình bằng con số","Phân tích môi trường và lợi thế cạnh tranh","Các con đường tăng trưởng và thử nghiệm nhanh","Đổi mới mô hình kinh doanh với AI và ESG","Tài chính cho chiến lược tăng trưởng","Thực thi chiến lược: OKR, KPI và nhịp quản trị số"],"l1":{"t":"Mô hình kinh doanh: doanh nghiệp tạo, trao và thu giá trị thế nào","sum":"Bài nền tảng định nghĩa mô hình kinh doanh và phân biệt với chiến lược, kế hoạch. Học viên nhận diện các kiểu mô hình kinh doanh số phổ biến.","points":["Mô hình kinh doanh trả lời 3 câu hỏi: tạo giá trị gì, trao giá trị cho ai và bằng cách nào, thu giá trị (doanh thu, lợi nhuận) ra sao.","Các mô hình số phổ biến: thuê bao (subscription), nền tảng hai mặt, freemium, thương mại điện tử trực tiếp (D2C), trả theo mức sử dụng.","Mô hình số có chi phí biên thấp, khả năng mở rộng nhanh nhưng cạnh tranh khốc liệt và phụ thuộc dữ liệu.","Chiến lược là lựa chọn cách cạnh tranh; mô hình kinh doanh là cỗ máy thực hiện lựa chọn đó.","Doanh nghiệp truyền thống có thể bổ sung lớp số (bán online, dịch vụ thuê bao, dữ liệu) thay vì thay đổi toàn bộ."],"case":"Công ty TNHH Lọc nước Minh An trước đây chỉ bán máy lọc nước một lần. Doanh nghiệp bổ sung gói thuê bao thay lõi lọc định kỳ 150.000 đồng/tháng. Sau 2 năm, doanh thu định kỳ chiếm 35% tổng doanh thu và giúp dòng tiền ổn định hơn hẳn.","trend":"Kinh tế thuê bao và dịch vụ hóa sản phẩm (product-as-a-service) dự kiến lan rộng sang nhiều ngành truyền thống giai đoạn 2026–2030.","practice":"Mô tả mô hình kinh doanh của doanh nghiệp bạn trong 3 câu theo khung tạo – trao – thu giá trị, và đề xuất 1 lớp số có thể bổ sung.","takeaway":"Sản phẩm tốt chưa đủ, cần một cỗ máy kiếm tiền tốt bao quanh nó."}},{"id":"KH081","code":"kh081","f":"TC","fn":"Tài chính - Quản trị","t":"Quản trị tài chính doanh nghiệp nâng cao","lv":5,"ln":"Chuyên gia","h":32,"p":499000,"d":"Khoá học chuyên gia dành cho người dẫn dắt tài chính doanh nghiệp: quản trị giá trị, cấu trúc vốn, thẩm định dự án nâng cao, quyền chọn thực, chính sách phân phối, quản trị rủi ro tỷ giá – lãi suất – hàng hóa, tái cấu trúc và M&A. Học viên thực hành trên mô hình tài chính chuyên sâu và tình huống doanh nghiệp Việt Nam quy mô vừa và lớn. Kết thúc khoá, học viên đủ năng lực tư vấn chiến lược tài chính cho ban điều hành, hội đồng quản trị và dẫn dắt chuyển đổi tài chính số.","a":"Dành cho giám đốc tài chính (CFO), kế toán trưởng cấp cao, trưởng FP&A, chuyên viên tư vấn tài chính – M&A và thành viên ban điều hành.","o":["Đo lường và quản trị được giá trị doanh nghiệp bằng ROIC, EVA và các động lực giá trị.","Thiết kế được cấu trúc vốn tối ưu và ước tính chi phí vốn cho từng dự án, đơn vị.","Thẩm định được dự án đầu tư nâng cao với phân tích rủi ro, mô phỏng và quyền chọn thực.","Xây được chính sách quản trị rủi ro tỷ giá, lãi suất, hàng hóa bằng công cụ phái sinh phù hợp.","Dẫn dắt được tái cấu trúc tài chính, giao dịch M&A và tích hợp sau sáp nhập."],"k":"CFO năm 2026 không chỉ giữ sổ sách và tiền: họ kiến tạo giá trị, dẫn dắt dữ liệu và bảo vệ doanh nghiệp trước biến động.","w":["Luật TNDN 67/2025/QH15, thuế tối thiểu toàn cầu (NQ 107/2023/QH15) và TT 99/2025 thay TT 200/2014 từ 2026 thay đổi căn bản cách tính lợi nhuận, ưu đãi và cấu trúc tập đoàn.","Lộ trình áp dụng IFRS (QĐ 345/QĐ-BTC) và yêu cầu minh bạch từ nhà đầu tư quốc tế buộc CFO nâng chuẩn báo cáo và quản trị.","AI, dữ liệu thời gian thực và biến động vĩ mô (tỷ giá, lãi suất, chuỗi cung ứng) đang biến CFO thành người dẫn dắt chiến lược và chuyển đổi số."],"dl":["Mô hình Excel quản trị giá trị (ROIC – EVA – cây động lực giá trị) và cấu trúc vốn tối ưu.","Mô hình thẩm định dự án nâng cao có phân tích độ nhạy, kịch bản và mô phỏng Monte Carlo.","Mẫu chính sách quản trị rủi ro tài chính và bộ hồ sơ tái cấu trúc, tích hợp sau M&A.","Bộ câu lệnh AI (prompt) cho CFO: phân tích chiến lược, báo cáo hội đồng quản trị, kiểm tra mô hình."],"ls":["CFO kiến tạo giá trị: ROIC, EVA và cây động lực giá trị","Cấu trúc vốn tối ưu và chi phí sử dụng vốn","Thẩm định dự án đầu tư nâng cao","Phân tích rủi ro dự án và quyền chọn thực","Chính sách phân phối lợi nhuận và quản lý vốn chủ","Quản trị rủi ro tỷ giá, lãi suất và giá hàng hóa","Tái cấu trúc tài chính và doanh nghiệp gặp khó khăn","M&A, hợp nhất và tích hợp sau sáp nhập trong kỷ nguyên số"],"l1":{"t":"CFO kiến tạo giá trị: ROIC, EVA và cây động lực giá trị","sum":"Bài mở đầu định vị vai trò CFO hiện đại và các thước đo giá trị kinh tế. Học viên xây cây động lực giá trị cho doanh nghiệp.","points":["Doanh nghiệp tạo giá trị khi ROIC (lợi nhuận hoạt động sau thuế / vốn đầu tư) lớn hơn WACC.","EVA = NOPAT – WACC × Vốn đầu tư; EVA dương cho thấy lợi nhuận vượt chi phí cơ hội của vốn.","Cây động lực giá trị phân rã ROIC thành biên lợi nhuận và vòng quay vốn, rồi đến các chỉ số vận hành.","Tăng trưởng chỉ tạo giá trị khi ROIC của khoản đầu tư mới vượt WACC.","Vai trò CFO mở rộng: chiến lược, dữ liệu, rủi ro, ESG, quan hệ nhà đầu tư, dẫn dắt chuyển đổi số."],"case":"Công ty CP Nhựa Minh An tăng doanh thu 25%/năm nhưng ROIC chỉ 8% so với WACC 12%. Phân tích cây giá trị chỉ ra vòng quay vốn thấp do tồn kho và đầu tư dàn trải. CFO đề xuất dừng 2 dây chuyền ROIC thấp và tối ưu vốn lưu động, ROIC tăng lên 13% sau 2 năm.","trend":"Nhà đầu tư dự kiến chú trọng hơn vào ROIC và chất lượng tăng trưởng; CFO giai đoạn 2026–2030 sẽ cần thêm năng lực dữ liệu, ESG và quản trị chuyển đổi.","practice":"Tính ROIC, EVA của doanh nghiệp mẫu cho 3 năm và xây cây động lực giá trị 3 tầng, chỉ ra 2 đòn bẩy tạo giá trị lớn nhất.","takeaway":"Lợi nhuận chưa đủ, lợi nhuận phải vượt chi phí vốn mới là tạo giá trị."}},{"id":"KH082","code":"kh082","f":"TC","fn":"Tài chính - Quản trị","t":"Tài chính cá nhân và quản lý tiền thông minh","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp người đi làm và người kinh doanh nhỏ làm chủ tài chính cá nhân: lập bức tranh tài sản ròng, ngân sách chi tiêu, quỹ khẩn cấp, quản lý nợ và thẻ tín dụng, hiểu lương thực nhận – thuế TNCN và bắt đầu tiết kiệm, đầu tư đúng cách. Học viên thực hành trên file Excel quản lý tiền cá nhân và tình huống thật của người Việt. Kết thúc khoá, học viên có kế hoạch tài chính 12 tháng rõ ràng và thói quen quản lý tiền bền vững.","a":"Dành cho người đi làm, sinh viên năm cuối, gia đình trẻ, freelancer và người kinh doanh nhỏ muốn quản lý tiền chủ động.","o":["Lập được bảng tài sản ròng và dòng tiền cá nhân hàng tháng.","Xây được ngân sách chi tiêu theo quy tắc phù hợp và theo dõi được trong 3 tháng liên tục.","Thiết lập được quỹ khẩn cấp và đánh giá được nhu cầu bảo hiểm cơ bản.","Lập được kế hoạch trả nợ, sử dụng thẻ tín dụng không mất lãi.","Tự tính được lương thực nhận, thuế TNCN và lập kế hoạch tài chính 12 tháng."],"k":"Thu nhập tăng mà cuối tháng vẫn hết tiền? Vấn đề không nằm ở bạn kiếm bao nhiêu, mà ở cách bạn quản lý nó.","w":["Từ kỳ tính thuế 2026, mức giảm trừ gia cảnh tăng lên 15,5 triệu/tháng cho bản thân và 6,2 triệu/tháng mỗi người phụ thuộc, thay đổi lương thực nhận của nhiều người.","Thanh toán số, ví điện tử và mua trước trả sau khiến chi tiêu dễ dàng hơn bao giờ hết, đồng thời dễ mất kiểm soát và rơi vào nợ.","Ứng dụng tài chính, ngân hàng số và AI giúp theo dõi tiền tự động; người biết dùng đúng sẽ tiết kiệm được nhiều thời gian và tiền bạc."],"dl":["File Excel quản lý tài chính cá nhân: tài sản ròng, ngân sách, nợ, mục tiêu tiết kiệm.","Công cụ tính lương gross – net và thuế TNCN theo giảm trừ gia cảnh 2026.","Checklist 20 thói quen tài chính lành mạnh và kế hoạch 12 tháng mẫu.","Bộ câu lệnh AI (prompt) phân tích chi tiêu, lập ngân sách và nhắc mục tiêu tài chính."],"ls":["Tư duy tài chính cá nhân: tiền là công cụ, không phải mục đích","Bức tranh tài chính: tài sản ròng và dòng tiền","Lập ngân sách chi tiêu thực tế và bền vững","Quỹ khẩn cấp và bảo hiểm: lá chắn tài chính","Quản lý nợ, thẻ tín dụng và mua trước trả sau","Hiểu lương thực nhận và thuế TNCN 2026","Tiết kiệm và đầu tư cơ bản: an toàn trước, sinh lời sau","Kế hoạch tài chính cá nhân 12 tháng với trợ lý AI"],"l1":{"t":"Tư duy tài chính cá nhân: tiền là công cụ, không phải mục đích","sum":"Bài mở đầu giúp học viên nhìn lại mối quan hệ với tiền và xác định mục tiêu tài chính rõ ràng theo nguyên tắc SMART.","points":["Tài chính cá nhân gồm 5 trụ cột: thu nhập, chi tiêu, tiết kiệm – đầu tư, bảo vệ (bảo hiểm, quỹ khẩn cấp), nợ.","Nguyên tắc 'trả cho mình trước': trích tiết kiệm ngay khi nhận lương, không phải phần còn thừa cuối tháng.","Mục tiêu tài chính nên cụ thể, đo được, có thời hạn: ví dụ 60 triệu quỹ khẩn cấp trong 12 tháng.","Phân biệt nhu cầu và mong muốn trước mỗi khoản chi lớn; áp dụng quy tắc chờ 48 giờ.","Lãi kép là đồng minh khi tiết kiệm sớm và là kẻ thù khi nợ tiêu dùng lãi cao."],"case":"Anh Minh, 28 tuổi, lương 20 triệu nhưng không tiết kiệm được đồng nào sau 3 năm. Sau khi đặt mục tiêu cụ thể và cài lệnh chuyển tự động 3 triệu sang tài khoản tiết kiệm ngay ngày nhận lương, sau 12 tháng anh có 36 triệu cộng lãi và không thấy cuộc sống bị ảnh hưởng nhiều.","trend":"Ngân hàng số và ứng dụng tài chính dự kiến tích hợp trợ lý AI gợi ý tiết kiệm, phân loại chi tiêu tự động; người dùng cần nền tảng kiến thức để đánh giá gợi ý.","practice":"Viết 3 mục tiêu tài chính SMART cho 12 tháng tới (ngắn, trung, dài hạn) và cài 1 lệnh chuyển tiền tiết kiệm tự động.","takeaway":"Hãy trả lương cho chính mình trước khi trả cho bất kỳ ai."}},{"id":"KH083","code":"kh083","f":"TC","fn":"Tài chính - Quản trị","t":"Lập kế hoạch kinh doanh cho startup","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học hướng dẫn người khởi nghiệp đi từ ý tưởng đến kế hoạch kinh doanh hoàn chỉnh: kiểm chứng cơ hội, nghiên cứu thị trường, mô hình kinh doanh, marketing – bán hàng, vận hành, pháp lý – thuế, dự báo tài chính và gọi vốn. Học viên thực hành theo từng bước trên bộ mẫu kế hoạch và mô hình tài chính Excel, với tình huống startup Việt Nam thật. Kết thúc khoá, học viên có bản kế hoạch kinh doanh và bộ slide gọi vốn sẵn sàng trình bày.","a":"Dành cho người chuẩn bị khởi nghiệp, nhà sáng lập giai đoạn đầu, hộ kinh doanh muốn lên doanh nghiệp và sinh viên có ý tưởng kinh doanh.","o":["Kiểm chứng được ý tưởng kinh doanh bằng phỏng vấn khách hàng và thử nghiệm nhỏ.","Phân tích được thị trường, đối thủ và xác định được phân khúc mục tiêu.","Thiết kế được mô hình kinh doanh, kế hoạch marketing – bán hàng và vận hành.","Chọn được loại hình pháp lý phù hợp và nắm được nghĩa vụ thuế, kế toán ban đầu.","Lập được dự báo tài chính 3 năm, nhu cầu vốn và bộ slide gọi vốn 12 trang."],"k":"Ý tưởng hay chưa đủ để khởi nghiệp; một kế hoạch kinh doanh có số liệu mới thuyết phục được khách hàng, đối tác và nhà đầu tư.","w":["Bỏ lệ phí môn bài và bỏ thuế khoán hộ kinh doanh từ 01/01/2026 (NQ 198/2025/QH15), cùng thuế TNDN 15% cho doanh nghiệp doanh thu năm không quá 3 tỷ, tạo môi trường thuận lợi hơn cho khởi nghiệp chính thức.","AI tạo sinh giúp nghiên cứu thị trường, làm MVP và marketing với chi phí thấp, mở ra cơ hội khởi nghiệp tinh gọn chưa từng có.","Nhà đầu tư giai đoạn 2026 trở đi ưu tiên startup có kinh tế đơn vị rõ ràng, dữ liệu kiểm chứng và tuân thủ pháp lý ngay từ đầu."],"dl":["Mẫu kế hoạch kinh doanh 20 trang có hướng dẫn từng phần.","Mô hình Excel dự báo tài chính startup 3 năm: doanh thu, chi phí, dòng tiền, điểm hòa vốn, nhu cầu vốn.","Checklist pháp lý – thuế khi thành lập doanh nghiệp và mẫu slide gọi vốn 12 trang.","Bộ câu lệnh AI (prompt) nghiên cứu thị trường, phân tích đối thủ, viết kế hoạch và luyện pitching."],"ls":["Từ ý tưởng đến cơ hội kinh doanh được kiểm chứng","Nghiên cứu thị trường và đối thủ thông minh","Mô hình kinh doanh và đề xuất giá trị khác biệt","Kế hoạch marketing và bán hàng chi phí thấp","Kế hoạch vận hành, đội ngũ và công cụ số","Pháp lý và thuế khi thành lập: đúng từ ngày đầu","Dự báo tài chính và nhu cầu vốn","Hoàn thiện kế hoạch kinh doanh và gọi vốn với AI"],"l1":{"t":"Từ ý tưởng đến cơ hội kinh doanh được kiểm chứng","sum":"Bài nền tảng giúp phân biệt ý tưởng và cơ hội kinh doanh, đồng thời hướng dẫn kiểm chứng nhanh trước khi bỏ tiền.","points":["Cơ hội tốt = Vấn đề thật + Khách hàng sẵn sàng trả tiền + Đủ lớn + Bạn có lợi thế để làm.","Phỏng vấn ít nhất 20 khách hàng tiềm năng về vấn đề của họ, không phải về sản phẩm của bạn.","Đo mức độ nghiêm trọng của vấn đề: khách đang tự giải quyết thế nào, tốn bao nhiêu tiền và thời gian.","Kiểm chứng bằng hành động: đặt cọc, đăng ký trước, mua thử, không chỉ bằng lời khen.","Đánh giá năng lực sáng lập: kỹ năng, mạng lưới, nguồn lực tài chính và thời gian cam kết."],"case":"Bạn Nam muốn mở ứng dụng đặt lịch cắt tóc. Sau 25 cuộc phỏng vấn, Nam phát hiện chủ tiệm tóc không thiếu khách mà thiếu công cụ quản lý thợ và hoa hồng. Nam chuyển hướng sang phần mềm quản lý tiệm, có 12 tiệm đặt cọc dùng thử trước khi viết dòng code đầu tiên.","trend":"AI giúp tổng hợp phỏng vấn, phân tích phản hồi và tạo trang đăng ký thử nghiệm trong vài giờ; chu kỳ kiểm chứng ý tưởng dự kiến rút ngắn mạnh giai đoạn 2026–2030.","practice":"Viết bản mô tả vấn đề khách hàng 1 trang, soạn 10 câu hỏi phỏng vấn và thực hiện ít nhất 5 cuộc phỏng vấn trong tuần.","takeaway":"Hãy yêu vấn đề của khách hàng, đừng yêu giải pháp của mình."}},{"id":"KH084","code":"kh084","f":"TC","fn":"Tài chính - Quản trị","t":"CFO thời đại số: dashboard, dự báo và ra quyết định bằng dữ liệu","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học giúp bạn chuyển vai trò tài chính từ người ghi chép sang người dẫn dắt quyết định: xây hệ thống KPI, dashboard theo cấp quản lý, mô hình dự báo dòng tiền cuốn chiếu và kịch bản. Bạn học qua tình huống doanh nghiệp Việt Nam thật, dùng ngay bộ mẫu Excel – Power BI – prompt AI được thiết kế sẵn. Kết thúc khoá, bạn vận hành được một bộ công cụ CFO hoàn chỉnh: dữ liệu chuẩn, dashboard cảnh báo sớm, dự báo 13 tuần và đề xuất quyết định có số liệu.","a":"Dành cho giám đốc tài chính, kế toán trưởng, kế toán quản trị và chủ doanh nghiệp muốn điều hành bằng dữ liệu thay vì cảm tính.","o":["Lập được bộ 15–20 KPI tài chính và phi tài chính có định nghĩa, công thức, nguồn dữ liệu và ngưỡng cảnh báo rõ ràng.","Xây được dashboard 3 cấp (HĐQT – Ban giám đốc – trưởng bộ phận) cập nhật tự động từ dữ liệu kế toán.","Lập được mô hình dự báo dòng tiền 13 tuần và dự báo cuốn chiếu 12 tháng với 3 kịch bản.","Rút ngắn thời gian lập báo cáo quản trị tháng xuống còn tối đa 3 ngày làm việc sau khoá sổ.","Trình bày được một đề xuất quyết định (đầu tư, cắt giảm, giá bán) bằng phân tích độ nhạy và điểm hoà vốn."],"k":"Năm 2026, ban giám đốc không cần thêm báo cáo dày; họ cần một màn hình nói rõ tiền đang ở đâu và tuần sau nên làm gì.","w":["TT 99/2025 thay TT 200/2014 từ 01/01/2026 và lộ trình IFRS buộc dữ liệu kế toán phải chuẩn hoá lại; đây là thời điểm vàng để dựng lại hệ thống báo cáo quản trị từ gốc.","AI và công cụ BI giá rẻ đã khiến dashboard, dự báo tự động trở thành tiêu chuẩn tối thiểu; CFO không dùng dữ liệu sẽ bị thay bằng người làm được.","Lãi vay, chi phí vốn và áp lực dòng tiền 2026–2030 dự kiến biến động mạnh; doanh nghiệp cần dự báo cuốn chiếu và kịch bản thay cho kế hoạch năm đóng băng."],"dl":["Bộ mẫu Excel KPI Dictionary: 40 chỉ số có công thức, nguồn tài khoản theo TT 99/2025 và TT 133/2016, ngưỡng cảnh báo gợi ý.","File mẫu dashboard Power BI/Looker Studio 3 cấp kèm mô hình dữ liệu chuẩn (bảng ngày, tài khoản, bộ phận).","Mô hình Excel dự báo dòng tiền 13 tuần và rolling forecast 12 tháng có sẵn kịch bản tốt – cơ sở – xấu.","Bộ 30 câu lệnh AI (prompt) cho CFO: phân tích biến động, viết bình luận dashboard, rà soát giả định dự báo."],"ls":["CFO thời đại số: từ người giữ sổ đến người dẫn dắt quyết định","Nền móng dữ liệu: chuẩn hoá sổ kế toán thành dữ liệu phân tích","Bộ KPI tài chính cốt lõi: thanh khoản, hiệu quả, sinh lời, đòn bẩy","KPI phi tài chính và chỉ số dẫn dắt: nhìn trước kết quả","Thiết kế dashboard 3 cấp: một màn hình, một thông điệp","Dự báo dòng tiền 13 tuần và rolling forecast 12 tháng","Phân tích kịch bản, độ nhạy và ra quyết định đầu tư","Vận hành văn phòng CFO số: AI, cảnh báo tự động và quản trị rủi ro"],"l1":{"t":"CFO thời đại số: từ người giữ sổ đến người dẫn dắt quyết định","sum":"Bài mở đầu định vị lại vai trò tài chính trong doanh nghiệp năm 2026. Học viên hiểu bốn vai trò của CFO hiện đại và tự đánh giá mức trưởng thành dữ liệu của doanh nghiệp mình.","points":["Bốn vai trò của CFO: người gác cổng (kiểm soát, tuân thủ), người vận hành (khoá sổ, báo cáo), chiến lược gia (vốn, đầu tư) và chất xúc tác (thúc đẩy thay đổi). Doanh nghiệp vừa và nhỏ thường kẹt ở hai vai trò đầu.","Thang trưởng thành dữ liệu 5 bậc: báo cáo thủ công – báo cáo định kỳ chuẩn hoá – dashboard tự động – dự báo – khuyến nghị hành động. Mục tiêu khoá học là đưa bạn lên bậc 4.","Quy tắc 80/20 của thời gian tài chính: nếu hơn 60% thời gian dùng để thu thập và đối chiếu số, bạn chưa có thời gian để phân tích; tự động hoá là điều kiện tiên quyết.","Câu hỏi quyết định trước, chỉ số sau: mỗi báo cáo phải trả lời một quyết định cụ thể (tăng giá, tuyển người, vay vốn), không làm báo cáo để lưu trữ.","Nền tảng tuân thủ vẫn là gốc: số liệu quản trị phải khớp sổ sách theo chế độ kế toán đang áp dụng (TT 133/2016 hoặc TT 99/2025), nếu không dashboard sẽ mất niềm tin ngay tháng đầu."],"case":"Công ty TNHH Minh An (phân phối thiết bị, doanh thu 120 tỷ) có kế toán trưởng mất 9 ngày mỗi tháng để làm báo cáo quản trị bằng tay, giám đốc nhận số khi đã quá muộn để điều chỉnh. Sau khi lập danh sách 6 quyết định hằng tháng của giám đốc và chỉ giữ báo cáo phục vụ 6 quyết định đó, khối lượng báo cáo giảm 50%, thời gian còn 4 ngày.","trend":"Giai đoạn 2026–2030, vai trò CFO dự kiến dịch chuyển mạnh sang phân tích và quản trị rủi ro khi AI đảm nhận phần lớn khâu ghi nhận. Học viên nên đầu tư sớm vào kỹ năng mô hình hoá và kể chuyện bằng số liệu.","practice":"Liệt kê 10 quyết định quan trọng ban giám đốc ra mỗi tháng/quý và ghi bên cạnh số liệu cần có để ra quyết định đó. Đầu ra: bảng Quyết định – Câu hỏi – Dữ liệu cần thiết.","takeaway":"Báo cáo không phục vụ quyết định nào là chi phí, không phải tài sản."}},{"id":"KH085","code":"kh085","f":"CN","fn":"Công cụ số & AI","t":"Excel cho kế toán: hàm và bảng tính thiết yếu","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp kế toán mới và người chuyển ngành làm chủ Excel ở mức dùng được ngay trong công việc: tổ chức bảng tính chuẩn, hàm điều kiện, tổng hợp, tra cứu và kiểm tra số liệu. Mỗi bài học gắn với một tình huống kế toán thật như bảng kê hoá đơn, công nợ, lương, kèm file mẫu làm theo từng bước. Kết thúc khoá, bạn tự xây được bảng theo dõi công nợ có đối chiếu tự động và biết dùng AI để hỏi, sửa công thức nhanh.","a":"Dành cho sinh viên, kế toán mới đi làm, nhân viên hành chính – bán hàng cần xử lý số liệu và chủ hộ kinh doanh mới chuyển sang tự kê khai.","o":["Tổ chức được bảng tính kế toán theo chuẩn dữ liệu phẳng, dễ lọc, dễ tổng hợp và dễ bàn giao.","Viết đúng các hàm IF, SUMIFS, COUNTIFS, XLOOKUP, IFERROR, TEXT, EOMONTH trong tình huống kế toán thực tế.","Lập được bảng tổng hợp công nợ theo khách hàng và tuổi nợ từ danh sách hoá đơn trong dưới 30 phút.","Tự kiểm tra được sai lệch giữa hai nguồn số liệu (sổ chi tiết và sao kê) bằng công thức đối chiếu.","Dùng được trợ lý AI để giải thích, viết và sửa công thức Excel, tiết kiệm ít nhất 2 giờ mỗi tuần."],"k":"Kế toán năm 2026 vẫn dò số bằng mắt và gõ tay từng dòng đang mất mỗi tháng vài ngày công vào việc Excel làm trong vài giây.","w":["Từ 01/01/2026 hộ kinh doanh bỏ thuế khoán, chuyển sang tự kê khai (NQ 198/2025/QH15); nhu cầu người biết lập bảng kê, sổ theo dõi doanh thu – chi phí bằng Excel tăng mạnh.","Dữ liệu hoá đơn điện tử và sao kê ngân hàng đều xuất ra Excel; ai biết xử lý nhanh dữ liệu này sẽ làm được việc gấp nhiều lần.","Excel đã tích hợp trợ lý AI và các hàm mới như XLOOKUP, FILTER, UNIQUE; người học bài bản từ đầu sẽ tận dụng được ngay, tránh thói quen làm thủ công."],"dl":["Bộ 8 file Excel mẫu thực hành: bảng kê hoá đơn, sổ quỹ, công nợ, bảng lương đơn giản, đối chiếu ngân hàng.","Bảng tra cứu 40 hàm Excel thường dùng cho kế toán, có ví dụ và lỗi hay gặp.","Checklist 15 điểm kiểm tra bảng tính trước khi gửi sếp hoặc nộp báo cáo.","Bộ 20 câu lệnh AI (prompt) để viết, giải thích và gỡ lỗi công thức Excel."],"ls":["Bảng tính chuẩn kế toán: thiết kế đúng ngay từ đầu","Nhập liệu sạch: số, ngày tháng, định dạng và kiểm soát dữ liệu","Công thức nền tảng: địa chỉ ô, làm tròn và tính thuế đúng","Hàm điều kiện: IF, IFS, AND, OR, IFERROR trong nghiệp vụ","Tổng hợp có điều kiện: SUMIFS, COUNTIFS, AVERAGEIFS","Tra cứu thông minh: XLOOKUP, VLOOKUP, INDEX-MATCH","Sắp xếp, lọc, PivotTable nhập môn và trình bày báo cáo","Dự án cuối khoá: bảng công nợ tự động và trợ lý AI cho Excel"],"l1":{"t":"Bảng tính chuẩn kế toán: thiết kế đúng ngay từ đầu","sum":"Phần lớn lỗi Excel đến từ cách tổ chức bảng chứ không phải từ hàm. Bài học xây nguyên tắc dữ liệu phẳng và bố cục file làm việc chuyên nghiệp.","points":["Nguyên tắc dữ liệu phẳng: một dòng là một nghiệp vụ, một cột là một thuộc tính (ngày, số hoá đơn, khách hàng, số tiền); không gộp ô, không dòng trống, không dòng tổng xen giữa.","Tách file thành 3 vùng: sheet dữ liệu gốc, sheet tính toán, sheet báo cáo; người xem chỉ cần mở sheet báo cáo.","Đặt tên sheet và file có quy tắc, ví dụ CONGNO_2026_T09_v1; ghi rõ người lập, ngày cập nhật ở góc trên.","Dùng Ctrl+T để chuyển vùng dữ liệu thành Table: tự mở rộng công thức, tự kéo định dạng, đặt tên cột rõ ràng.","Không gõ số trực tiếp vào công thức (hard-code) như thuế suất 8%; đặt tham số ở ô riêng để khi chính sách thay đổi (VAT 8% áp dụng đến hết 31/12/2026) chỉ cần sửa một chỗ."],"case":"Cửa hàng Vật liệu Tân Phú theo dõi bán hàng trên một sheet có gộp ô, dòng tổng xen giữa từng tháng nên không lọc được theo khách. Kế toán chuyển sang bảng phẳng dạng Table, thêm cột tháng bằng công thức, thời gian làm báo cáo doanh thu theo khách giảm từ 3 giờ xuống 10 phút.","trend":"Dữ liệu chuẩn phẳng là điều kiện để dùng PivotTable, Power Query và AI phân tích trong 2026–2030. Học viên nên tập thói quen thiết kế bảng đúng chuẩn ngay từ bây giờ.","practice":"Lấy một file Excel đang dùng ở công việc, sửa lại thành bảng phẳng dạng Table, tách sheet tham số. Đầu ra: file trước và sau kèm 3 điểm đã cải tiến.","takeaway":"Bảng đúng cấu trúc thì hàm đơn giản cũng đủ mạnh."}},{"id":"KH086","code":"kh086","f":"CN","fn":"Công cụ số & AI","t":"Phân tích dữ liệu kế toán với Power Query và Power BI","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học giúp kế toán chuyển từ làm báo cáo thủ công sang hệ thống báo cáo tự động: Power Query làm sạch và gộp dữ liệu, Data Model và DAX tính chỉ số, Power BI trình bày dashboard. Học viên thực hành trên dữ liệu kế toán thật như sổ nhật ký chung, bảng kê hoá đơn điện tử, sao kê ngân hàng nhiều tài khoản. Kết quả là một hệ thống báo cáo tháng tự cập nhật, có kiểm tra đối chiếu và chia sẻ an toàn cho ban giám đốc.","a":"Dành cho kế toán tổng hợp, kế toán quản trị, kiểm soát viên tài chính đã dùng Excel thành thạo và muốn tự động hoá báo cáo.","o":["Xây được truy vấn Power Query tự động gộp 12 file dữ liệu tháng và làm sạch theo quy tắc cố định.","Thiết kế được mô hình dữ liệu dạng sao với bảng ngày, tài khoản, bộ phận và viết 15 công thức DAX cơ bản.","Lập được báo cáo kết quả kinh doanh quản trị so sánh thực tế – kế hoạch – cùng kỳ tự cập nhật.","Tự động đối chiếu được sổ sách với sao kê ngân hàng và bảng kê hoá đơn, chỉ ra chênh lệch.","Giảm ít nhất 70% thời gian lập bộ báo cáo tháng so với cách làm thủ công."],"k":"Mỗi tháng copy – dán hàng chục file để làm báo cáo? Với Power Query, việc đó chỉ còn một cú bấm Refresh.","w":["Dữ liệu hoá đơn điện tử, sao kê ngân hàng và phần mềm kế toán đều xuất được tự động; doanh nghiệp 2026 kỳ vọng báo cáo có ngay sau khoá sổ chứ không phải sau một tuần.","Chuyển đổi sang TT 99/2025 từ 01/01/2026 buộc ánh xạ lại hệ thống tài khoản; Power Query giúp làm việc này một lần, dùng mãi.","Power BI và Copilot đang cho phép hỏi đáp dữ liệu bằng ngôn ngữ tự nhiên; ai nắm mô hình dữ liệu sẽ tận dụng AI hiệu quả nhất."],"dl":["Bộ dữ liệu thực hành: sổ nhật ký chung 12 tháng, bảng kê hoá đơn, sao kê 3 tài khoản ngân hàng đã ẩn danh.","File mẫu Power BI báo cáo tháng gồm 4 trang: tổng quan, KQKD, dòng tiền, công nợ.","Thư viện 30 công thức DAX cho kế toán (lũy kế, cùng kỳ, biến động, tỷ trọng) có giải thích.","Bộ prompt AI hỗ trợ viết M code, DAX và bình luận báo cáo."],"ls":["Tư duy báo cáo tự động: từ dữ liệu thô đến quyết định","Power Query căn bản: nhập và làm sạch dữ liệu kế toán","Gộp nhiều file và kết hợp bảng: Append, Merge, thư mục","Mô hình dữ liệu và bảng ngày: nền móng cho phân tích","DAX cho kế toán: lũy kế, cùng kỳ, biến động, tỷ trọng","Đối chiếu tự động: sổ sách, ngân hàng và hoá đơn điện tử","Power BI: dashboard tài chính và chia sẻ an toàn","Dự án cuối khoá: hệ thống báo cáo tháng tự động có AI hỗ trợ"],"l1":{"t":"Tư duy báo cáo tự động: từ dữ liệu thô đến quyết định","sum":"Bài mở đầu xây quy trình ETL (lấy – làm sạch – nạp) cho bộ phận kế toán. Học viên đánh giá hiện trạng báo cáo và thiết kế luồng dữ liệu mục tiêu.","points":["Ba tầng của hệ thống báo cáo: nguồn dữ liệu (phần mềm, ngân hàng, hoá đơn), tầng xử lý (Power Query, mô hình dữ liệu), tầng trình bày (Excel, Power BI).","Nguyên tắc không chạm tay vào dữ liệu gốc: mọi thao tác làm sạch phải ghi lại thành bước trong truy vấn để lặp lại được và kiểm tra được.","Chuẩn hoá thư mục nguồn: mỗi loại dữ liệu một thư mục, mỗi tháng một file cùng cấu trúc; đây là điều kiện để gộp tự động.","Xác định độ chi tiết (granularity) của báo cáo: theo ngày, bút toán hay tháng; chi tiết quá thấp sẽ không truy ngược được nguyên nhân.","Bản đồ báo cáo: liệt kê từng báo cáo, người dùng, tần suất, nguồn dữ liệu, thời gian làm hiện tại để chọn báo cáo tự động hoá trước."],"case":"Phòng kế toán Công ty CP Dược Thiên Phúc làm 14 báo cáo tháng, mất 6 ngày công. Sau khi lập bản đồ báo cáo, họ phát hiện 9 báo cáo dùng chung 3 nguồn dữ liệu; tự động hoá 3 nguồn này trước giúp tiết kiệm 4 ngày công mỗi tháng.","trend":"Doanh nghiệp đang chuyển dần sang mô hình dữ liệu tài chính tập trung, kết nối API với ngân hàng và hệ thống hoá đơn. Học viên nên quen tư duy luồng dữ liệu để thích ứng khi công cụ thay đổi.","practice":"Lập bản đồ báo cáo của phòng bạn gồm tên báo cáo, nguồn, tần suất, thời gian làm và mức ưu tiên tự động hoá. Đầu ra: bảng bản đồ báo cáo và 3 báo cáo ưu tiên.","takeaway":"Tự động hoá bắt đầu từ việc chuẩn hoá nguồn dữ liệu, không phải từ công cụ."}},{"id":"KH087","code":"kh087","f":"CN","fn":"Công cụ số & AI","t":"Phần mềm kế toán online ACCA Smart từ A đến Z","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học hướng dẫn sử dụng phần mềm kế toán online ACCA Smart từ khai báo hệ thống đến lập tờ khai 01/GTGT và báo cáo tài chính. Học viên làm trọn một bộ dữ liệu mẫu của doanh nghiệp nhỏ: nhập danh mục, số dư, ghi nhận nghiệp vụ quỹ, ngân hàng, mua hàng, bán hàng, kết chuyển cuối kỳ. Kết thúc khoá, bạn tự vận hành được sổ sách cho một doanh nghiệp nhỏ hoặc hộ kinh doanh trên nền tảng online, dữ liệu lưu máy chủ theo tài khoản, truy cập mọi lúc.","a":"Dành cho người mới học kế toán, kế toán doanh nghiệp nhỏ, chủ hộ kinh doanh chuyển sang tự kê khai và kế toán dịch vụ cần công cụ gọn nhẹ.","o":["Tự khai báo được thông tin doanh nghiệp, kỳ kế toán, danh mục và số dư đầu kỳ trên ACCA Smart.","Ghi nhận đúng các nghiệp vụ thu chi tiền mặt, tiền gửi, mua hàng, bán hàng kèm công nợ.","Lập được tờ khai 01/GTGT và bảng kê hoá đơn mua vào, bán ra từ dữ liệu đã nhập.","Thực hiện được kết chuyển cuối kỳ và xem nhật ký chung, sổ cái, bảng cân đối phát sinh.","Xuất được bộ báo cáo KQKD, CĐKT và tự kiểm tra khớp số liệu trước khi nộp."],"k":"Chỉ cần trình duyệt và tài khoản, bạn có thể làm trọn một kỳ kế toán từ phiếu thu đến báo cáo tài chính trong 8 giờ học.","w":["Từ 01/01/2026, hộ kinh doanh bỏ thuế khoán, chuyển sang tự kê khai (NQ 198/2025/QH15); nhu cầu một phần mềm đơn giản, chi phí thấp để ghi sổ và lên tờ khai tăng mạnh.","Phần mềm online lưu máy chủ giúp làm việc từ xa, chia sẻ với kế toán dịch vụ và hạn chế mất dữ liệu do hỏng máy hay mã độc.","Hoá đơn điện tử, ngân hàng số và báo cáo thuế đều đã số hoá; kế toán thạo phần mềm online sẽ dễ dàng kết nối tự động trong 2026–2030."],"dl":["Bộ dữ liệu thực hành 1 tháng của doanh nghiệp thương mại nhỏ (40 nghiệp vụ) kèm đáp án sổ sách.","Hướng dẫn từng bước có hình cho 10 phân hệ ACCA Smart.","Checklist khoá sổ cuối tháng 20 bước trên phần mềm.","Bộ prompt AI giúp định khoản nhanh và giải thích nghiệp vụ trước khi nhập phần mềm."],"ls":["Bắt đầu với ACCA Smart: truy cập, Tổng quan và Hệ thống","Danh mục và số dư đầu kỳ: nền móng của bộ sổ","Phân hệ Quỹ: phiếu thu, phiếu chi và kiểm soát tiền mặt","Phân hệ Ngân hàng: thu chi qua tài khoản và đối chiếu sao kê","Phân hệ Mua hàng: hoá đơn đầu vào và công nợ phải trả","Phân hệ Bán hàng: doanh thu, giá vốn và công nợ phải thu","Phân hệ Thuế: tờ khai 01/GTGT và bảng kê hoá đơn","Phân hệ Tổng hợp và Báo cáo: kết chuyển, sổ sách, báo cáo tài chính"],"l1":{"t":"Bắt đầu với ACCA Smart: truy cập, Tổng quan và Hệ thống","sum":"Bài học hướng dẫn truy cập phần mềm từ accavn.com, mục Kho phần mềm online, và thiết lập ban đầu. Học viên làm quen màn hình Tổng quan và phân hệ Hệ thống.","points":["Truy cập accavn.com, chọn Kho phần mềm online, mở ACCA Smart và đăng nhập bằng tài khoản; dữ liệu được lưu trên máy chủ theo tài khoản nên đổi máy vẫn làm tiếp được.","Phân hệ Hệ thống: khai báo tên doanh nghiệp, mã số thuế, địa chỉ, kỳ kế toán, chế độ kế toán áp dụng (TT 133/2016 cho doanh nghiệp nhỏ và vừa).","Màn hình Tổng quan hiển thị nhanh tiền mặt, tiền gửi, công nợ, doanh thu; đây là nơi kiểm tra sức khoẻ số liệu mỗi ngày.","Nguyên tắc vận hành phần mềm: mọi số liệu đi vào từ chứng từ, báo cáo được tổng hợp tự động; không sửa số trực tiếp trên báo cáo.","Bảo mật tài khoản: đặt mật khẩu mạnh, không dùng chung tài khoản, đăng xuất khi dùng máy công cộng."],"case":"Hộ kinh doanh Điện máy Ngọc Lan chuyển sang tự kê khai từ 2026 nhưng chưa có phần mềm. Chủ hộ đăng nhập ACCA Smart, khai báo thông tin trong 20 phút và cho phép kế toán dịch vụ cùng theo dõi số liệu từ xa.","trend":"Phần mềm kế toán đang dịch chuyển hoàn toàn lên nền tảng online, cập nhật tự động theo chính sách. Kế toán nên làm quen làm việc trên trình duyệt, cộng tác thời gian thực.","practice":"Đăng nhập ACCA Smart, khai báo thông tin doanh nghiệp mẫu và chụp màn hình Tổng quan. Đầu ra: ảnh màn hình hệ thống đã khai báo đúng.","takeaway":"Khai báo đúng ngay từ đầu giúp mọi báo cáo về sau đúng theo."}},{"id":"KH088","code":"kh088","f":"CN","fn":"Công cụ số & AI","t":"Phần mềm kế toán MISA thực hành","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học thực hành phần mềm kế toán MISA trên một bộ dữ liệu doanh nghiệp thương mại – dịch vụ hoàn chỉnh, từ tạo dữ liệu đến báo cáo tài chính và tờ khai thuế. Mỗi phân hệ được học theo quy trình nghiệp vụ thật: chứng từ gốc, kiểm tra, nhập liệu, đối chiếu, kèm các lỗi thường gặp và cách sửa. Kết thúc khoá, bạn tự làm được sổ sách một tháng, lập tờ khai GTGT, xử lý lương – bảo hiểm và cập nhật đúng chế độ kế toán 2026.","a":"Dành cho sinh viên kế toán, kế toán mới đi làm, kế toán chuyển từ Excel sang phần mềm và kế toán dịch vụ nhận nhiều khách dùng MISA.","o":["Tạo được dữ liệu kế toán mới đúng chế độ (TT 133/2016 hoặc TT 99/2025) và khai báo hệ thống, danh mục, số dư.","Hạch toán đúng nghiệp vụ quỹ, ngân hàng, mua bán, kho, tài sản cố định, công cụ dụng cụ và chi phí trả trước.","Lập được bảng lương có bảo hiểm 21,5% – 10,5%, KPCĐ 2% và thuế TNCN với giảm trừ gia cảnh 15,5 triệu đồng/6,2 triệu đồng.","Thực hiện được các bút toán cuối kỳ và xuất bộ báo cáo tài chính, tờ khai 01/GTGT khớp sổ.","Tự phát hiện và sửa được 10 lỗi nhập liệu thường gặp bằng công cụ kiểm tra của phần mềm và đối chiếu chéo."],"k":"Nhà tuyển dụng hỏi 'bạn dùng được MISA chưa' trước cả khi hỏi bằng cấp; khoá này giúp bạn trả lời bằng một bộ sổ hoàn chỉnh.","w":["TT 99/2025 thay TT 200/2014 từ 01/01/2026; doanh nghiệp đang chuyển đổi dữ liệu trên phần mềm và cần kế toán hiểu cả nghiệp vụ lẫn thao tác thiết lập.","Hoá đơn điện tử, ngân hàng số đã kết nối với phần mềm kế toán; kế toán biết khai thác các tính năng nhận dữ liệu tự động sẽ làm nhanh gấp nhiều lần.","Chính sách lương, bảo hiểm và thuế TNCN thay đổi từ 2025–2026 (Luật BHXH 2024, giảm trừ gia cảnh mới); bảng lương trên phần mềm phải được thiết lập lại đúng."],"dl":["Bộ dữ liệu thực hành 1 tháng của doanh nghiệp thương mại – dịch vụ (70 nghiệp vụ) kèm chứng từ gốc mô phỏng và đáp án.","Bảng định khoản mẫu 80 nghiệp vụ phổ biến theo TT 133/2016 và lưu ý khác biệt TT 99/2025.","Checklist khoá sổ tháng và checklist kiểm tra trước khi nộp tờ khai.","Bảng tổng hợp 10 lỗi thường gặp trên phần mềm và cách sửa, kèm prompt AI hỗ trợ tra cứu định khoản."],"ls":["Tạo dữ liệu và thiết lập hệ thống đúng chế độ 2026","Danh mục, số dư đầu kỳ và kết nối hoá đơn điện tử","Quỹ, ngân hàng và nghiệp vụ thanh toán","Mua hàng, bán hàng và quản lý kho","Tiền lương, bảo hiểm và thuế TNCN theo chính sách 2026","Tài sản cố định, công cụ dụng cụ và chi phí trả trước","Nghiệp vụ cuối kỳ, báo cáo tài chính và tờ khai thuế","Kiểm tra, sửa lỗi dữ liệu và trợ lý AI cho người dùng phần mềm"],"l1":{"t":"Tạo dữ liệu và thiết lập hệ thống đúng chế độ 2026","sum":"Bài học tạo dữ liệu kế toán mới và các thiết lập quyết định chất lượng sổ sách về sau. Học viên chọn chế độ kế toán, phương pháp tính giá và tuỳ chọn hệ thống phù hợp.","points":["Chọn chế độ kế toán: doanh nghiệp nhỏ và vừa thường dùng TT 133/2016; doanh nghiệp áp dụng TT 99/2025 (thay TT 200/2014 từ 01/01/2026) cần kiểm tra hệ thống tài khoản mới trên phần mềm.","Thiết lập năm tài chính, đồng tiền hạch toán, phương pháp tính giá xuất kho (bình quân cuối kỳ, bình quân tức thời, nhập trước xuất trước) và nhất quán trong năm.","Phương pháp tính thuế GTGT (khấu trừ hay trực tiếp) và kỳ kê khai tháng hoặc quý theo quy định hiện hành.","Phân quyền người dùng: kế toán viên nhập chứng từ, kế toán trưởng duyệt và khoá sổ; không dùng chung tài khoản quản trị.","Sao lưu dữ liệu định kỳ và trước mỗi thao tác lớn (khoá sổ, chuyển đổi năm) để có điểm khôi phục."],"case":"Công ty TNHH Thương mại Kim Ngân tạo dữ liệu chọn sai phương pháp tính giá, đến cuối năm muốn đổi thì phải tính lại toàn bộ giá vốn. Bài học rút ra: lập checklist thiết lập 12 mục và để kế toán trưởng duyệt trước khi nhập nghiệp vụ.","trend":"Các phần mềm kế toán đang chuyển sang nền tảng đám mây và cập nhật chế độ tự động. Kế toán vẫn cần hiểu bản chất thiết lập để không bị phụ thuộc vào mặc định của phần mềm.","practice":"Tạo dữ liệu mới cho doanh nghiệp mẫu theo checklist 12 mục thiết lập và sao lưu bản đầu tiên. Đầu ra: ảnh chụp thiết lập và file sao lưu.","takeaway":"Thiết lập sai một lần, sửa mệt cả năm."}},{"id":"KH089","code":"kh089","f":"CN","fn":"Công cụ số & AI","t":"AI trong kế toán – thuế 2026: trợ lý AI và AI agent","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp kế toán dùng AI tạo sinh như một trợ lý thực thụ: viết prompt chuẩn, tra cứu và giải thích quy định, xử lý chứng từ, Excel, soạn văn bản, rồi tiến lên thiết kế AI agent tự thực hiện chuỗi công việc có kiểm soát. Mỗi bài học có tình huống kế toán – thuế thật, bộ prompt dùng ngay và nguyên tắc kiểm chứng để tránh 'AI bịa'. Kết thúc khoá, bạn có quy trình làm việc có AI hỗ trợ, tiết kiệm được nhiều giờ mỗi tuần mà vẫn bảo mật dữ liệu và chịu trách nhiệm nghề nghiệp.","a":"Dành cho kế toán viên, kế toán trưởng, nhân viên thuế – tài chính và chủ doanh nghiệp nhỏ muốn ứng dụng AI vào công việc hằng ngày một cách an toàn.","o":["Viết được prompt theo cấu trúc vai trò – bối cảnh – nhiệm vụ – định dạng – kiểm tra cho 20 tình huống kế toán – thuế.","Tự kiểm chứng được câu trả lời của AI về quy định thuế bằng cách đối chiếu văn bản gốc, không dùng thông tin chưa xác minh.","Dùng AI trích xuất dữ liệu từ hoá đơn, chứng từ và đề xuất định khoản với độ chính xác được kiểm tra.","Thiết kế được một AI agent đơn giản thực hiện chuỗi công việc có điểm phê duyệt của con người.","Tiết kiệm tối thiểu 5 giờ mỗi tuần cho các việc soạn thảo, tổng hợp, kiểm tra số liệu."],"k":"AI sẽ không thay thế kế toán, nhưng kế toán biết giao việc cho AI agent đang làm được khối lượng của ba người.","w":["Năm 2026, AI tạo sinh đã tích hợp vào Excel, email, phần mềm kế toán; người không biết dùng sẽ chậm hơn rõ rệt so với đồng nghiệp.","AI agent có khả năng tự đọc chứng từ, tra cứu, điền bảng và gửi báo cáo đang chuyển từ thử nghiệm sang ứng dụng thực tế trong 2026–2030.","Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 hiệu lực 01/01/2026 đặt ra yêu cầu rõ ràng khi đưa dữ liệu khách hàng, nhân viên vào công cụ AI."],"dl":["Thư viện 100 prompt kế toán – thuế theo nhóm việc: tra cứu, Excel, chứng từ, văn bản, phân tích.","Mẫu quy trình (SOP) làm việc có AI: phân loại dữ liệu được phép đưa vào AI, bước kiểm chứng, lưu vết.","Bản thiết kế mẫu AI agent xử lý hoá đơn đầu vào kèm sơ đồ luồng và điểm kiểm soát.","Checklist 12 điểm kiểm chứng câu trả lời AI về pháp luật thuế."],"ls":["AI tạo sinh và AI agent: hiểu đúng để dùng đúng","Kỹ thuật prompt chuyên nghiệp cho kế toán","Tra cứu, giải thích quy định thuế bằng AI và kiểm chứng","AI cho Excel và phân tích số liệu","Đọc chứng từ, hoá đơn và đề xuất định khoản bằng AI","Soạn email, công văn giải trình và báo cáo với AI","Bảo mật dữ liệu, đạo đức nghề nghiệp và quản trị rủi ro AI","Thiết kế AI agent cho quy trình kế toán có kiểm soát"],"l1":{"t":"AI tạo sinh và AI agent: hiểu đúng để dùng đúng","sum":"Bài mở đầu giải thích cách AI tạo sinh hoạt động, điểm mạnh, giới hạn và sự khác biệt giữa trợ lý AI và AI agent. Học viên xác định việc nào nên giao cho AI.","points":["Mô hình ngôn ngữ lớn dự đoán văn bản dựa trên dữ liệu học, không 'biết' luật thuế như cơ sở dữ liệu; vì vậy có thể trả lời tự tin nhưng sai (hiện tượng bịa thông tin).","Trợ lý AI trả lời theo từng lệnh; AI agent nhận mục tiêu, tự lập kế hoạch, dùng công cụ (đọc file, tra web, điền bảng) và thực hiện nhiều bước.","Việc AI làm tốt: tóm tắt, soạn nháp, phân loại, trích xuất dữ liệu, viết công thức, giải thích khái niệm; việc cần con người: phán đoán nghề nghiệp, ký duyệt, chịu trách nhiệm pháp lý.","Ma trận chọn việc: tần suất cao + quy tắc rõ + rủi ro thấp là ứng viên tự động hoá đầu tiên.","Nguyên tắc vàng: AI đề xuất, kế toán kiểm tra và quyết định; mọi số liệu nộp cơ quan thuế phải được người có thẩm quyền rà soát."],"case":"Kế toán Công ty TNHH Thương mại Việt Hưng hỏi AI về thuế suất một mặt hàng và nhận câu trả lời sai do AI dùng quy định cũ. Từ đó công ty lập quy định: mọi câu trả lời về thuế suất, ngưỡng, thời hạn phải đối chiếu văn bản gốc trước khi áp dụng.","trend":"Giai đoạn 2026–2030, AI agent dự kiến được tích hợp sẵn trong phần mềm kế toán và bộ công cụ văn phòng. Kế toán nên chuẩn bị tư duy quản lý và kiểm soát agent như quản lý một nhân viên mới.","practice":"Liệt kê 15 việc bạn làm mỗi tuần, chấm điểm tần suất – mức quy tắc – rủi ro và chọn 3 việc giao cho AI trước. Đầu ra: ma trận 15 việc và kế hoạch 3 việc ưu tiên.","takeaway":"Giao việc cho AI như giao cho nhân viên mới: rõ ràng, có kiểm tra."}},{"id":"KH090","code":"kh090","f":"CN","fn":"Công cụ số & AI","t":"Tự động hóa công việc văn phòng với Google Workspace","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học hướng dẫn tận dụng Google Workspace (Drive, Sheets, Forms, Gmail, Calendar, Apps Script và tính năng AI tích hợp) để tự động hoá công việc văn phòng và kế toán. Học viên xây các quy trình thật như đề nghị thanh toán qua Form, lưu chứng từ tự động, nhắc hạn nộp thuế, gửi email hàng loạt, tất cả với chi phí gần như bằng 0. Kết thúc khoá, bạn có một hệ thống đề nghị – phê duyệt – thanh toán chạy tự động và bộ mẫu dùng ngay cho doanh nghiệp nhỏ.","a":"Dành cho kế toán, hành chính – nhân sự, trợ lý giám đốc và chủ doanh nghiệp nhỏ đang dùng Gmail hoặc Google Workspace.","o":["Tổ chức được Drive dùng chung theo cấu trúc chuẩn và phân quyền theo vai trò, không còn link 'ai có link cũng xem được' với dữ liệu nhạy cảm.","Xây được form đề nghị thanh toán tự động lưu dữ liệu, đính kèm chứng từ vào đúng thư mục.","Thiết lập được lịch hạn nộp thuế, bảo hiểm trên Calendar có nhắc tự động cho cả nhóm.","Viết được script Apps Script đơn giản để gửi email hàng loạt, tạo văn bản từ mẫu và lưu PDF.","Vận hành được quy trình đề nghị – phê duyệt – thanh toán khép kín, giảm ít nhất 50% thời gian xử lý."],"k":"Đề nghị thanh toán vẫn chạy bằng giấy và tin nhắn? Google Workspace có thể biến nó thành quy trình tự động trong một buổi chiều.","w":["Doanh nghiệp nhỏ năm 2026 cần số hoá quy trình với chi phí thấp; Google Workspace và Apps Script cho phép tự động hoá mà không cần mua phần mềm riêng.","AI tích hợp trong Gmail, Docs, Sheets giúp soạn thảo, tóm tắt, phân tích nhanh; người biết khai thác sẽ có lợi thế năng suất rõ rệt.","Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 hiệu lực 01/01/2026 buộc doanh nghiệp quản lý phân quyền chia sẻ file chặt chẽ hơn, tránh lộ dữ liệu qua đường link."],"dl":["Mẫu cấu trúc thư mục Drive cho phòng kế toán – hành chính và bảng phân quyền.","Bộ Google Sheets mẫu: theo dõi đề nghị thanh toán, lịch thuế, công nợ có hàm QUERY, IMPORTRANGE.","Thư viện 10 đoạn Apps Script có chú thích tiếng Việt: gửi mail, tạo PDF, lưu file, nhắc hạn.","Bộ prompt AI để dùng Gemini/AI trong Workspace và để nhờ AI viết, sửa Apps Script."],"ls":["Google Workspace cho doanh nghiệp: bản đồ công cụ và quy trình","Drive dùng chung, cấu trúc thư mục và phân quyền an toàn","Google Sheets cộng tác: QUERY, IMPORTRANGE, FILTER","Google Forms: thu thập đề nghị thanh toán và chứng từ","Gmail và Calendar: quản lý thư, lịch hạn thuế và nhắc việc","Apps Script nhập môn cho người không biết lập trình","Tự động gửi email, tạo văn bản từ mẫu và lưu PDF","Dự án: quy trình đề nghị – phê duyệt – thanh toán tự động"],"l1":{"t":"Google Workspace cho doanh nghiệp: bản đồ công cụ và quy trình","sum":"Bài mở đầu giới thiệu hệ sinh thái Google Workspace và cách chúng kết nối thành quy trình. Học viên xác định quy trình nào trong công ty nên số hoá trước.","points":["Vai trò từng công cụ: Drive lưu trữ, Sheets dữ liệu, Forms thu thập, Gmail giao tiếp, Calendar lịch, Docs văn bản, Apps Script tự động hoá.","Khác biệt Gmail cá nhân và Workspace doanh nghiệp: tên miền riêng, Drive dùng chung, quản trị tài khoản tập trung, thu hồi dữ liệu khi nhân viên nghỉ.","Tư duy quy trình: đầu vào (Form) – xử lý (Sheets, Script) – phê duyệt (email) – lưu trữ (Drive) – nhắc việc (Calendar).","Chọn quy trình số hoá trước: lặp lại nhiều, nhiều người tham gia, hay thất lạc giấy tờ như đề nghị thanh toán, tạm ứng, nghỉ phép.","Đặt chủ sở hữu dữ liệu là tài khoản công ty, không phải tài khoản cá nhân, để không mất dữ liệu khi thay người."],"case":"Công ty TNHH Du lịch Biển Xanh lưu chứng từ trên Drive cá nhân của kế toán; khi kế toán nghỉ việc, công ty mất truy cập 2 năm hồ sơ. Sau sự cố, công ty chuyển toàn bộ sang Drive dùng chung thuộc tài khoản doanh nghiệp.","trend":"Bộ công cụ văn phòng đám mây đang tích hợp AI sâu vào mọi ứng dụng. Doanh nghiệp nhỏ có thể tự động hoá đáng kể mà không cần đầu tư phần mềm lớn trong 2026–2030.","practice":"Vẽ sơ đồ quy trình đề nghị thanh toán hiện tại của công ty bạn và đánh dấu các điểm có thể số hoá bằng Workspace. Đầu ra: sơ đồ hiện tại và sơ đồ mục tiêu.","takeaway":"Dữ liệu công ty phải thuộc tài khoản công ty."}},{"id":"KH091","code":"kh091","f":"CN","fn":"Công cụ số & AI","t":"Số hóa chứng từ, lưu trữ điện tử và OCR bằng AI","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp doanh nghiệp xây hệ thống chứng từ số hoàn chỉnh: chuẩn pháp lý, cấu trúc lưu trữ khoa học, nhận dạng chứng từ bằng OCR và AI, liên kết chứng từ với sổ sách. Học viên thực hành trên chứng từ thật như hoá đơn điện tử XML, sao kê, hợp đồng scan, biên lai giấy và xây quy trình số hoá hằng ngày. Kết quả là kho chứng từ tra cứu tức thì, sẵn sàng cho kiểm tra thuế, kiểm toán và bàn giao, đồng thời bảo mật đúng quy định.","a":"Dành cho kế toán, nhân viên hành chính – văn thư, kế toán dịch vụ và quản lý muốn số hoá hồ sơ tài chính của doanh nghiệp.","o":["Thiết kế được cấu trúc lưu trữ và quy tắc đặt tên chứng từ thống nhất cho toàn doanh nghiệp.","Số hoá được chứng từ giấy bằng scan và OCR/AI, trích xuất dữ liệu ra bảng với tỷ lệ chính xác được kiểm soát.","Liên kết được từng bút toán hoặc dòng bảng kê với file chứng từ gốc, truy xuất bằng một cú bấm.","Xây được quy trình luân chuyển và số hoá chứng từ hằng ngày có người chịu trách nhiệm.","Chuẩn bị được bộ hồ sơ phục vụ kiểm tra thuế, kiểm toán hoặc bàn giao trong vòng 1 ngày."],"k":"Khi đoàn kiểm tra thuế đến, bạn tìm một chứng từ năm 2022 mất 2 giây hay 2 ngày? Khoá này quyết định câu trả lời.","w":["Hoá đơn điện tử, bao gồm hoá đơn khởi tạo từ máy tính tiền, đã phổ biến theo NĐ 123/2020 sửa bởi NĐ 70/2025 (từ 01/06/2025); lưu trữ phải chuyển từ tủ hồ sơ sang hệ thống số.","AI và OCR thế hệ mới đọc được chứng từ tiếng Việt với độ chính xác cao, chi phí thấp; thời điểm 2026 là lúc doanh nghiệp nhỏ cũng số hoá được.","Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 hiệu lực 01/01/2026 yêu cầu kho chứng từ chứa dữ liệu cá nhân phải được phân quyền, bảo vệ, ghi nhận truy cập."],"dl":["Mẫu cấu trúc thư mục lưu trữ chứng từ 10 năm và bảng quy tắc đặt tên file.","File Excel bảng kê chứng từ có cột link mở file gốc và công thức kiểm tra thiếu chứng từ.","Quy trình (SOP) số hoá – luân chuyển – lưu trữ chứng từ hằng ngày và checklist kiểm tra tháng.","Bộ prompt AI trích xuất dữ liệu hoá đơn, hợp đồng, biên lai và mẫu bảng kiểm tra kết quả."],"ls":["Chứng từ điện tử: giá trị pháp lý và yêu cầu lưu trữ","Thiết kế kho lưu trữ và quy tắc đặt tên chứng từ","Scan và nhận dạng văn bản: OCR truyền thống và AI","Quản lý hoá đơn điện tử đầu vào, đầu ra và máy tính tiền","Liên kết chứng từ với sổ sách và bảng kê","Quy trình luân chuyển và số hoá chứng từ hằng ngày","Bảo mật, phân quyền, sao lưu và bảo vệ dữ liệu cá nhân","Sẵn sàng cho kiểm tra thuế, kiểm toán và bàn giao hồ sơ"],"l1":{"t":"Chứng từ điện tử: giá trị pháp lý và yêu cầu lưu trữ","sum":"Bài học làm rõ nền tảng pháp lý của chứng từ, hoá đơn điện tử và yêu cầu lưu trữ. Học viên phân biệt chứng từ gốc điện tử và bản số hoá từ giấy.","points":["Hoá đơn điện tử theo NĐ 123/2020 sửa bởi NĐ 70/2025: bản gốc là file điện tử (XML), bản PDF hay bản in chỉ là bản thể hiện; lưu trữ phải giữ file gốc.","Chứng từ giấy được scan là bản sao số hoá; bản gốc giấy vẫn cần lưu theo quy định trừ khi có hướng dẫn khác cho phép thay thế.","Theo Luật Kế toán, chứng từ kế toán dùng trực tiếp để ghi sổ và lập báo cáo tài chính phải lưu tối thiểu 10 năm; thời hạn cụ thể của từng loại theo quy định hiện hành.","Yêu cầu với lưu trữ điện tử: bảo đảm toàn vẹn, truy cập được khi cần, có sao lưu, chống sửa đổi trái phép.","Hoá đơn khởi tạo từ máy tính tiền, chứng từ khấu trừ thuế điện tử, biên lai điện tử đều cần nằm trong hệ thống lưu trữ thống nhất."],"case":"Công ty TNHH Thương mại Hải Nam chỉ lưu bản PDF hoá đơn đầu vào tải từ email, khi kiểm tra không xuất trình được file XML gốc của một số hoá đơn. Công ty bổ sung quy trình tải XML từ hệ thống hoá đơn điện tử về kho lưu trữ mỗi tuần.","trend":"Chứng từ số gốc (không giấy) đang mở rộng từ hoá đơn sang hợp đồng điện tử, chứng từ ngân hàng, chứng từ khấu trừ thuế. Doanh nghiệp nên chuẩn bị hệ thống lưu trữ thống nhất cho mọi loại chứng từ số.","practice":"Liệt kê toàn bộ loại chứng từ doanh nghiệp bạn đang phát sinh, phân loại điện tử gốc hay giấy và thời hạn lưu trữ. Đầu ra: bảng danh mục chứng từ có cột hình thức và thời hạn lưu.","takeaway":"Hoá đơn điện tử thì file gốc là XML, không phải PDF."}},{"id":"KH092","code":"kh092","f":"CN","fn":"Công cụ số & AI","t":"Báo cáo quản trị trực quan với Google Looker Studio","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học hướng dẫn xây báo cáo quản trị trực quan bằng Google Looker Studio từ dữ liệu kế toán trên Google Sheets và các nguồn khác. Học viên chuẩn hoá dữ liệu, tạo trường tính toán, thiết kế dashboard doanh thu – chi phí – công nợ – dòng tiền, cài bộ lọc tương tác và chia sẻ an toàn. Kết thúc khoá, bạn có một hệ thống báo cáo quản trị tháng hoàn chỉnh, chi phí công cụ gần như bằng 0 và cập nhật không cần làm tay.","a":"Dành cho kế toán tổng hợp, kế toán quản trị, chủ doanh nghiệp nhỏ và vừa, kế toán dịch vụ muốn cung cấp báo cáo trực quan cho khách hàng.","o":["Chuẩn hoá được dữ liệu kế toán trên Google Sheets thành nguồn dữ liệu sạch cho dashboard.","Tạo được trường tính toán cho biên lợi nhuận, tuổi nợ, tăng trưởng và so sánh kế hoạch.","Thiết kế được dashboard 3 trang (tổng quan, công nợ, dòng tiền) đúng nguyên tắc trực quan hoá.","Cài đặt được bộ lọc, tham số, phân quyền và lịch gửi báo cáo tự động qua email.","Giảm thời gian lập báo cáo quản trị tháng từ vài ngày xuống dưới 2 giờ."],"k":"Một dashboard miễn phí, cập nhật tự động, mở trên điện thoại giám đốc mỗi sáng: Looker Studio làm được, và kế toán hoàn toàn tự dựng được.","w":["Doanh nghiệp vừa và nhỏ năm 2026 cần báo cáo quản trị nhanh nhưng không có ngân sách cho phần mềm BI đắt tiền; Looker Studio miễn phí và dễ học.","Dữ liệu kế toán, bán hàng, quảng cáo đều đã nằm trên đám mây; kết nối chúng thành một màn hình là lợi thế cạnh tranh của kế toán hiện đại.","Trợ lý AI cho phép hỏi dữ liệu bằng lời đang được tích hợp vào công cụ BI; dữ liệu được chuẩn hoá sớm sẽ khai thác AI tốt hơn trong 2026–2030."],"dl":["Bộ Google Sheets mẫu: sổ nhật ký chung phẳng, bảng mapping chỉ tiêu, bảng công nợ, bảng kế hoạch.","Template Looker Studio 3 trang dùng ngay chỉ cần thay nguồn dữ liệu.","Thư viện 25 công thức trường tính toán cho báo cáo tài chính quản trị.","Checklist thiết kế dashboard 15 điểm và bộ prompt AI viết bình luận báo cáo."],"ls":["Looker Studio và tư duy báo cáo trực quan cho kế toán","Chuẩn bị dữ liệu kế toán trên Google Sheets","Kết nối nguồn dữ liệu, kết hợp bảng và trường tính toán","Biểu đồ đúng mục đích và bố cục dashboard chuyên nghiệp","Bộ lọc, tham số và tương tác cho người dùng","Dashboard công nợ, dòng tiền và nghĩa vụ thuế","Chia sẻ, phân quyền, gửi báo cáo tự động và bảo mật dữ liệu","Dự án: hệ thống báo cáo quản trị tháng có AI bình luận"],"l1":{"t":"Looker Studio và tư duy báo cáo trực quan cho kế toán","sum":"Bài mở đầu giới thiệu Looker Studio và nguyên tắc biến số liệu kế toán thành thông điệp. Học viên xác định người dùng và câu hỏi của dashboard.","points":["Looker Studio là công cụ trực quan hoá miễn phí của Google, kết nối Sheets, BigQuery, Google Analytics và nhiều nguồn khác; chia sẻ như Google Docs.","Bắt đầu từ câu hỏi quản trị: tháng này lãi hay lỗ, vì sao; khách nào nợ quá hạn; tiền đủ chi bao lâu.","Nguyên tắc 5 giây: người xem phải nắm thông điệp chính trong 5 giây đầu; chỉ số quan trọng nhất đặt góc trên trái.","Phân biệt báo cáo vận hành (chi tiết, hằng ngày) và báo cáo quản trị (tổng hợp, tháng/quý) để thiết kế phù hợp.","Số liệu dashboard phải khớp sổ sách; mỗi trang có dòng ghi chú nguồn và thời điểm cập nhật."],"case":"Giám đốc Công ty TNHH Thực phẩm Sạch Xanh Việt nhận báo cáo Excel 12 sheet mỗi tháng nhưng chỉ xem trang đầu. Kế toán phỏng vấn giám đốc, rút ra 7 câu hỏi quan trọng và thiết kế dashboard 1 trang trả lời đúng 7 câu đó.","trend":"Báo cáo trực quan, cập nhật liên tục đang thay thế báo cáo tĩnh gửi qua email. Học viên nên rèn tư duy 'câu hỏi trước, biểu đồ sau'.","practice":"Phỏng vấn người dùng báo cáo (sếp hoặc khách hàng), ghi 7 câu hỏi quản trị và chỉ số trả lời tương ứng. Đầu ra: bảng câu hỏi – chỉ số – biểu đồ dự kiến.","takeaway":"Dashboard tốt trả lời câu hỏi trước khi người xem kịp hỏi."}},{"id":"KH093","code":"kh093","f":"CN","fn":"Công cụ số & AI","t":"Tự động hóa quy trình kế toán bằng n8n","lv":4,"ln":"Nâng cao","h":24,"p":399000,"d":"Khoá học nâng cao hướng dẫn xây dựng các workflow tự động hoá quy trình kế toán bằng n8n, nền tảng tự động hoá mã nguồn mở có thể tự lưu trữ. Học viên thiết kế, xây và vận hành các luồng thực tế: thu thập hoá đơn, đối chiếu dữ liệu, tích hợp AI đọc chứng từ, kết nối API phần mềm kế toán, cảnh báo và báo cáo tự động. Kết thúc khoá, bạn vận hành được một hệ thống workflow có giám sát lỗi, phân quyền và kiểm soát nội bộ, sẵn sàng mở rộng thành AI agent.","a":"Dành cho kế toán trưởng, kế toán tổng hợp có tư duy hệ thống, chuyên viên chuyển đổi số tài chính, chủ văn phòng kế toán dịch vụ muốn tự động hoá quy mô lớn.","o":["Cài đặt và cấu hình được n8n (đám mây hoặc tự lưu trữ) an toàn, quản lý thông tin xác thực đúng cách.","Xây được tối thiểu 5 workflow kế toán: thu thập hoá đơn, lưu trữ chứng từ, đối chiếu ngân hàng, nhắc hạn, báo cáo tự động.","Tích hợp được AI vào workflow để đọc chứng từ, phân loại và soạn văn bản với bước kiểm tra của con người.","Kết nối được webhook và API với phần mềm kế toán, Google Sheets, email, công cụ nhắn tin.","Thiết lập được giám sát lỗi, nhật ký và phân quyền để workflow đáp ứng yêu cầu kiểm soát nội bộ."],"k":"Hoá đơn tự về đúng thư mục, đối chiếu ngân hàng tự chạy lúc 6 giờ sáng, sếp nhận báo cáo trước khi bạn đến văn phòng: đó là kế toán với n8n.","w":["Khối lượng dữ liệu điện tử (hoá đơn, sao kê, chứng từ) tăng nhanh từ 2025–2026; tự động hoá theo luồng là cách duy nhất để không phải tăng người tương ứng.","n8n cho phép kết hợp tự động hoá truyền thống với AI và AI agent, tự lưu trữ để kiểm soát dữ liệu; phù hợp yêu cầu bảo mật tài chính.","Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 hiệu lực 01/01/2026 khiến doanh nghiệp ưu tiên giải pháp kiểm soát được nơi dữ liệu đi qua, thay vì gửi dữ liệu qua nhiều dịch vụ trung gian."],"dl":["Bộ 8 workflow n8n mẫu (file JSON nhập được) cho các quy trình kế toán phổ biến.","Tài liệu thiết kế workflow chuẩn: sơ đồ, đầu vào – đầu ra, xử lý lỗi, điểm phê duyệt.","Checklist bảo mật và kiểm soát nội bộ cho hệ thống tự động hoá tài chính.","Bộ prompt AI dùng trong node AI: trích xuất hoá đơn, phân loại chi phí, soạn email, tóm tắt báo cáo."],"ls":["Tư duy tự động hoá quy trình kế toán và chọn quy trình đúng","Cài đặt, cấu hình và bảo mật n8n","Node cơ bản: trigger, xử lý dữ liệu, rẽ nhánh và vòng lặp","Workflow thu thập, kiểm tra và lưu trữ hoá đơn điện tử","Đối chiếu tự động: ngân hàng, công nợ và dữ liệu hoá đơn","Tích hợp AI và AI agent vào workflow kế toán","API, webhook và kết nối phần mềm kế toán","Vận hành, giám sát lỗi và kiểm soát nội bộ cho hệ thống tự động"],"l1":{"t":"Tư duy tự động hoá quy trình kế toán và chọn quy trình đúng","sum":"Bài mở đầu xây tư duy thiết kế quy trình trước khi chạm vào công cụ. Học viên lập danh mục quy trình và chấm điểm ưu tiên tự động hoá.","points":["Mô hình của mọi workflow: sự kiện kích hoạt – lấy dữ liệu – xử lý, kiểm tra – hành động – ghi nhật ký; vẽ ra giấy trước khi xây.","Tiêu chí chọn quy trình: lặp lại nhiều, quy tắc rõ, dữ liệu số, rủi ro sai sót thấp hoặc kiểm soát được.","Chuẩn hoá trước, tự động sau: tự động hoá một quy trình lộn xộn chỉ làm sai nhanh hơn.","Xác định điểm con người phê duyệt: thanh toán, nộp tờ khai, sửa dữ liệu đã khoá sổ luôn phải có người duyệt.","Ước tính lợi ích: giờ công tiết kiệm mỗi tháng, lỗi giảm được, rủi ro giảm được; dùng để ưu tiên và báo cáo ban giám đốc."],"case":"Văn phòng Kế toán Thịnh Vượng liệt kê 26 công việc lặp lại hằng tháng cho 60 khách hàng. Chấm điểm cho thấy 5 quy trình (gom hoá đơn, nhắc chứng từ, đối chiếu ngân hàng, nhắc hạn, gửi báo cáo) chiếm 45% giờ công, được chọn tự động hoá đầu tiên.","trend":"Tự động hoá quy trình (workflow automation) kết hợp AI đang trở thành hạ tầng của phòng tài chính hiện đại 2026–2030. Kế toán biết thiết kế quy trình sẽ trở thành người dẫn dắt chuyển đổi số.","practice":"Lập danh mục 15 quy trình lặp lại của bạn, chấm điểm theo 4 tiêu chí và vẽ sơ đồ workflow cho quy trình ưu tiên số 1. Đầu ra: bảng chấm điểm và sơ đồ.","takeaway":"Vẽ quy trình trên giấy trước, rồi mới xây trên công cụ."}},{"id":"KH094","code":"kh094","f":"CN","fn":"Công cụ số & AI","t":"An ninh mạng và bảo vệ dữ liệu cá nhân cho kế toán","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học trang bị cho kế toán kỹ năng nhận diện và phòng chống các mối đe doạ an ninh mạng nhắm vào tài chính: lừa đảo qua email, giả mạo lãnh đạo và đối tác, deepfake giọng nói, mã độc tống tiền, rò rỉ dữ liệu. Học viên thực hành trên tình huống thật, xây quy trình xác minh thanh toán, quản lý chữ ký số, token ngân hàng và tuân thủ Luật Bảo vệ dữ liệu cá nhân. Kết thúc khoá, bạn có bộ quy trình và checklist an toàn thông tin áp dụng ngay cho phòng kế toán.","a":"Dành cho kế toán, thủ quỹ, nhân viên hành chính – nhân sự, kế toán trưởng và chủ doanh nghiệp nắm quyền phê duyệt thanh toán.","o":["Nhận diện được ít nhất 10 dấu hiệu email, tin nhắn, cuộc gọi lừa đảo nhắm vào bộ phận tài chính.","Áp dụng được quy trình xác minh hai kênh cho mọi yêu cầu thanh toán mới hoặc thay đổi tài khoản thụ hưởng.","Thiết lập được quản lý mật khẩu, xác thực hai lớp và phân quyền cho tài khoản ngân hàng, thuế, hoá đơn.","Xây được kế hoạch sao lưu và ứng phó sự cố mã độc tống tiền cho dữ liệu kế toán.","Rà soát được việc xử lý dữ liệu cá nhân trong phòng kế toán theo yêu cầu của Luật 91/2025/QH15."],"k":"Một email giả danh giám đốc lúc 4 giờ chiều thứ Sáu có thể lấy đi số tiền bằng lợi nhuận cả năm; kế toán là tuyến phòng thủ cuối cùng.","w":["Lừa đảo giả mạo bằng AI (email viết hoàn hảo, deepfake giọng nói, video) đang tăng mạnh từ 2025–2026, nhắm trực tiếp vào bộ phận có quyền chuyển tiền.","Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 hiệu lực 01/01/2026: dữ liệu lương, hồ sơ nhân viên, khách hàng mà kế toán nắm giữ phải được bảo vệ đúng quy định.","Hoá đơn điện tử, ngân hàng số, chữ ký số đều trực tuyến; một tài khoản bị chiếm có thể gây thiệt hại tài chính và pháp lý nghiêm trọng."],"dl":["Quy trình (SOP) xác minh thanh toán và thay đổi thông tin tài khoản thụ hưởng.","Checklist an toàn thông tin 25 điểm cho phòng kế toán, tự đánh giá hằng quý.","Bảng kiểm kê tài khoản, chữ ký số, token và người nắm giữ kèm mẫu biên bản bàn giao.","Kịch bản ứng phó sự cố (mất tiền, mã độc, lộ dữ liệu) và bộ mẫu email cảnh báo nội bộ."],"ls":["Vì sao phòng kế toán là mục tiêu số một của tội phạm mạng","Lừa đảo qua email, giả mạo lãnh đạo, đối tác và deepfake","Quy trình xác minh thanh toán và kiểm soát thay đổi tài khoản","Mật khẩu, xác thực hai lớp, chữ ký số và token ngân hàng","Mã độc tống tiền, an toàn máy tính và sao lưu dữ liệu kế toán","Bảo vệ dữ liệu cá nhân trong công việc kế toán theo Luật 91/2025/QH15","An toàn khi làm việc từ xa, dùng đám mây và công cụ AI","Ứng phó sự cố và xây văn hoá an toàn thông tin"],"l1":{"t":"Vì sao phòng kế toán là mục tiêu số một của tội phạm mạng","sum":"Bài mở đầu phân tích động cơ và phương thức tấn công nhắm vào bộ phận tài chính. Học viên tự đánh giá mức độ rủi ro của phòng mình.","points":["Kế toán nắm ba thứ tội phạm muốn: quyền chuyển tiền, dữ liệu tài chính và dữ liệu cá nhân (lương, CCCD, tài khoản ngân hàng).","Các kiểu tấn công phổ biến: lừa đảo qua email (phishing), giả mạo lãnh đạo (CEO fraud), giả mạo nhà cung cấp đổi tài khoản, mã độc tống tiền, chiếm tài khoản.","Tội phạm khai thác áp lực thời gian và thứ bậc: 'gấp, bí mật, sếp đang họp không gọi được'.","Rủi ro không chỉ là mất tiền: còn là gián đoạn khoá sổ, nộp chậm tờ khai, lộ dữ liệu cá nhân và trách nhiệm pháp lý.","Con người là lớp phòng thủ quan trọng nhất; công nghệ chỉ giảm rủi ro, không loại bỏ được."],"case":"Kế toán Công ty TNHH Xuất khẩu Thủy sản Biển Đông nhận email 'giám đốc' yêu cầu chuyển gấp 1,2 tỷ đồng đặt cọc lô hàng, kèm lời dặn không trao đổi với ai. Kế toán gọi điện xác minh qua số máy đã lưu, phát hiện email giả mạo từ tên miền gần giống.","trend":"AI giúp tội phạm viết email không lỗi chính tả, cá nhân hoá theo thông tin công khai của doanh nghiệp. Dấu hiệu 'sai chính tả' không còn đáng tin; kế toán cần dựa vào quy trình xác minh.","practice":"Tự đánh giá phòng kế toán theo 10 câu hỏi rủi ro (ai có quyền chuyển tiền, ai giữ token, có xác minh hai kênh không…). Đầu ra: bảng đánh giá và 3 rủi ro lớn nhất.","takeaway":"Gấp và bí mật là hai từ khoá cần dừng lại kiểm tra ngay."}},{"id":"KH095","code":"kh095","f":"CN","fn":"Công cụ số & AI","t":"Kế toán 2030: kỹ năng và lộ trình nghề trong kỷ nguyên AI","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học giúp người mới và người đang làm kế toán nhìn rõ nghề kế toán đến năm 2030: việc gì sẽ được tự động hoá, kỹ năng nào tăng giá trị và lộ trình phát triển cụ thể. Học viên được trang bị nền tảng làm việc chuyên nghiệp, kỹ năng số, tư duy dữ liệu và đạo đức nghề nghiệp thông qua tình huống thật và bài tự đánh giá. Kết thúc khoá, bạn có bản đồ năng lực cá nhân và kế hoạch phát triển 12 tháng rõ ràng để không bị bỏ lại phía sau.","a":"Dành cho sinh viên kế toán – tài chính, kế toán mới đi làm, người chuyển ngành và kế toán lâu năm muốn định hướng lại sự nghiệp.","o":["Mô tả được bức tranh nghề kế toán 2026–2030 và các vai trò mới đang hình thành.","Tự đánh giá được năng lực theo khung 4 nhóm: nghiệp vụ, công nghệ, kỹ năng mềm, đạo đức nghề nghiệp.","Tổ chức được công việc theo chu kỳ ngày – tháng – năm và tự kiểm tra số liệu trước khi nộp.","Sử dụng được AI như trợ lý học tập và làm việc an toàn ngay từ đầu sự nghiệp.","Lập được kế hoạch phát triển nghề nghiệp 12 tháng với mục tiêu, khoá học, chứng chỉ và chỉ số đo."],"k":"AI đang làm phần nhập liệu nhanh hơn bạn; câu hỏi của năm 2026 là bạn sẽ làm phần việc nào mà AI không thay được.","w":["Từ 2026, chế độ kế toán thay đổi (TT 99/2025 thay TT 200/2014), hộ kinh doanh bỏ thuế khoán chuyển sang tự kê khai, tạo nhu cầu lớn về kế toán vững nghiệp vụ và thạo công nghệ.","AI và tự động hoá đang đảm nhận phần lớn khâu nhập liệu, đối chiếu; vai trò kế toán dịch chuyển sang phân tích, kiểm soát và tư vấn.","Lộ trình áp dụng IFRS (QĐ 345/QĐ-BTC năm 2020) và xu hướng báo cáo bền vững mở ra cơ hội cho người có chứng chỉ và kỹ năng quốc tế."],"dl":["Khung năng lực kế toán 2030 và bảng tự đánh giá 40 tiêu chí.","Lịch công việc kế toán chuẩn theo ngày – tuần – tháng – quý – năm kèm hạn nghĩa vụ thuế.","Mẫu kế hoạch phát triển cá nhân 12 tháng và bản đồ lộ trình nghề 5 hướng đi.","Bộ 30 prompt AI giúp học nghiệp vụ, ôn chứng chỉ và tự kiểm tra công việc."],"ls":["Nghề kế toán đến năm 2030: việc gì mất đi, việc gì lên ngôi","Khung năng lực kế toán 2030: nghiệp vụ, công nghệ, kỹ năng, đạo đức","Nền tảng làm việc chuyên nghiệp: chu kỳ công việc và lịch nghĩa vụ","Chứng từ, hồ sơ và tự kiểm tra số liệu trước khi nộp","Kỹ năng số thiết yếu: Excel, phần mềm, dữ liệu và an toàn thông tin","Làm việc cùng AI: trợ lý học tập và trợ lý công việc","Giao tiếp, phối hợp và đạo đức nghề nghiệp","Lộ trình nghề và kế hoạch phát triển 12 tháng"],"l1":{"t":"Nghề kế toán đến năm 2030: việc gì mất đi, việc gì lên ngôi","sum":"Bài mở đầu phân tích tác động của AI, tự động hoá và chính sách mới lên nghề kế toán. Học viên nhìn rõ phần việc sẽ thay đổi và cơ hội mới.","points":["Việc dễ tự động hoá: nhập chứng từ, phân loại, đối chiếu ngân hàng, lập bảng kê, báo cáo định kỳ theo mẫu.","Việc tăng giá trị: phán đoán nghề nghiệp, kiểm soát nội bộ, phân tích và tư vấn, xử lý tình huống thuế phức tạp, giao tiếp với các bên.","Thay đổi chính sách 2025–2026 làm tăng nhu cầu: TNDN 15%/17%/20% theo doanh thu (Luật 67/2025/QH15), hộ kinh doanh tự kê khai, ngưỡng thanh toán không tiền mặt từ 5 triệu đồng (NĐ 181/2025).","Vai trò mới đang hình thành: kế toán phân tích dữ liệu, chuyên viên tự động hoá tài chính, kế toán ESG, tư vấn thuế cho hộ kinh doanh và thương mại điện tử.","Dự báo là xu hướng, không phải định mệnh: người chủ động học sẽ hưởng lợi từ thay đổi."],"case":"Phòng kế toán Công ty CP Thương mại Hòa An có 6 người, trong đó 4 người chủ yếu nhập liệu. Sau khi triển khai nhận hoá đơn tự động, 2 người được đào tạo lại làm phân tích công nợ và kiểm soát chi phí, giá trị đóng góp của phòng tăng rõ rệt mà không cắt giảm nhân sự.","trend":"Giai đoạn 2026–2030, các tổ chức nghề nghiệp quốc tế dự kiến tiếp tục đưa dữ liệu, công nghệ và bền vững vào chương trình chứng chỉ. Học viên nên định hướng sớm để không học lại từ đầu.","practice":"Liệt kê công việc hiện tại hoặc công việc mong muốn, phân loại thành 'dễ tự động hoá' và 'tăng giá trị'. Đầu ra: bảng phân loại và 3 kỹ năng cần đầu tư.","takeaway":"Đừng cạnh tranh với AI ở việc nhập liệu; hãy cạnh tranh ở phán đoán."}},{"id":"KH096","code":"kh096","f":"CN","fn":"Công cụ số & AI","t":"Giao tiếp và thuyết trình số liệu cho kế toán","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học giúp kế toán biến số liệu thành thông điệp thuyết phục: hiểu người nghe, xây câu chuyện số liệu, trực quan hoá đúng, thiết kế slide, thuyết trình trực tiếp và trực tuyến, xử lý câu hỏi khó. Học viên luyện tập trên tình huống thật như báo cáo kết quả kinh doanh, giải thích biến động thuế, đề xuất cắt giảm chi phí, kèm mẫu slide và kịch bản dùng ngay. Kết thúc khoá, bạn trình bày được một báo cáo tài chính 10 phút rõ ràng, tự tin và dẫn đến quyết định.","a":"Dành cho kế toán viên, kế toán trưởng, kế toán quản trị, kiểm toán viên và nhân viên tài chính thường xuyên báo cáo cho quản lý, khách hàng hoặc đối tác.","o":["Xác định được người nghe, mục tiêu và thông điệp chính của mỗi báo cáo trong 1 câu.","Xây được câu chuyện số liệu theo cấu trúc tình hình – vấn đề – nguyên nhân – đề xuất.","Chọn đúng biểu đồ và thiết kế slide báo cáo tài chính rõ ràng, tối đa 10 slide cho 10 phút.","Thuyết trình tự tin trực tiếp và trực tuyến, xử lý được câu hỏi khó và báo tin xấu một cách chuyên nghiệp.","Viết được email, thuyết minh số liệu ngắn gọn khiến người đọc hành động."],"k":"Số liệu đúng nhưng không ai hành động thì vẫn là số liệu vô ích; kế toán giỏi năm 2026 là người khiến ban giám đốc hiểu và quyết.","w":["Khi AI và tự động hoá đảm nhận phần lập báo cáo, giá trị của kế toán chuyển sang diễn giải và tư vấn; kỹ năng giao tiếp số liệu trở thành năng lực cạnh tranh chính.","Họp trực tuyến, dashboard và báo cáo trên điện thoại đòi hỏi cách trình bày ngắn gọn, trực quan hơn trước.","Chính sách thuế và kế toán thay đổi nhiều trong 2025–2026 (TNDN theo doanh thu, TT 99/2025, hộ kinh doanh tự kê khai); kế toán cần giải thích tác động cho lãnh đạo, khách hàng dễ hiểu."],"dl":["Bộ template slide báo cáo tài chính quản trị 12 trang (KQKD, dòng tiền, công nợ, thuế, đề xuất).","Thẻ hướng dẫn chọn biểu đồ cho 10 loại thông điệp tài chính.","Kịch bản mẫu cho 5 tình huống: báo lãi, báo lỗ, giải trình thuế, đề xuất cắt giảm chi phí, xin ngân sách.","Bộ prompt AI hỗ trợ dựng dàn ý, viết tiêu đề slide, luyện trả lời câu hỏi khó."],"ls":["Vì sao số liệu đúng vẫn chưa đủ: kế toán là người kể chuyện","Hiểu người nghe và điều chỉnh ngôn ngữ tài chính","Cấu trúc câu chuyện số liệu: tình hình – vấn đề – nguyên nhân – đề xuất","Trực quan hoá số liệu đúng cách","Thiết kế slide báo cáo tài chính chuyên nghiệp","Thuyết trình trực tiếp và trực tuyến tự tin","Trả lời câu hỏi khó và báo tin xấu","Viết email, báo cáo và thuyết minh số liệu khiến người đọc hành động"],"l1":{"t":"Vì sao số liệu đúng vẫn chưa đủ: kế toán là người kể chuyện","sum":"Bài mở đầu chỉ ra khoảng cách giữa báo cáo đúng và báo cáo được dùng. Học viên nhận diện lỗi giao tiếp số liệu phổ biến của kế toán.","points":["Lỗi phổ biến: trình bày theo thứ tự tài khoản thay vì theo câu hỏi của người nghe, quá nhiều số, thiếu kết luận và đề xuất.","Người nghe quản lý quan tâm ba câu hỏi: chuyện gì đang xảy ra, vì sao, cần làm gì.","Nguyên tắc 'kết luận trước': nói thông điệp chính trong 30 giây đầu, chi tiết để phía sau hoặc phụ lục.","Mỗi con số cần ngữ cảnh: so với kế hoạch, cùng kỳ, ngành hoặc ngưỡng; một con số đơn lẻ không có ý nghĩa.","Uy tín đến từ chính xác và rõ ràng: thà nói 'cần kiểm tra thêm' còn hơn đưa số chưa chắc chắn."],"case":"Kế toán trưởng Công ty TNHH Phân phối Nước giải khát Mát Lành trình bày 25 phút đọc từng chỉ tiêu báo cáo, giám đốc hỏi 'vậy cuối cùng tháng này tốt hay xấu'. Lần sau, chị mở đầu bằng 1 câu kết luận và 3 nguyên nhân chính, cuộc họp rút còn 10 phút và ra được quyết định.","trend":"Khi dashboard tự động trả lời 'con số là bao nhiêu', câu hỏi dành cho kế toán là 'con số có ý nghĩa gì'. Kỹ năng diễn giải sẽ là trọng tâm nghề nghiệp 2026–2030.","practice":"Lấy một báo cáo bạn từng gửi, viết lại thông điệp chính trong 1 câu và 3 ý hỗ trợ. Đầu ra: bản tóm tắt 4 dòng trước – sau.","takeaway":"Nói kết luận trước, rồi mới chứng minh bằng số."}},{"id":"KH097","code":"kh097","f":"CN","fn":"Công cụ số & AI","t":"Chuyển đổi số phòng kế toán: từ giấy tờ đến tự động hóa","lv":1,"ln":"Nhập môn","h":8,"p":99000,"d":"Khoá học hướng dẫn từng bước chuyển đổi số phòng kế toán cho doanh nghiệp vừa và nhỏ: đánh giá hiện trạng, chuẩn hoá quy trình, số hoá chứng từ, chọn phần mềm và công cụ, tự động hoá việc lặp lại, ứng dụng AI và quản lý thay đổi. Học viên làm việc trên tình huống thực tế với bảng đánh giá, sơ đồ quy trình, ma trận chọn công cụ và kế hoạch triển khai mẫu. Kết thúc khoá, bạn có lộ trình chuyển đổi số 90 ngày khả thi cho phòng kế toán của mình.","a":"Dành cho kế toán trưởng, kế toán viên, chủ doanh nghiệp nhỏ và vừa, quản lý văn phòng kế toán dịch vụ muốn hiện đại hoá cách làm việc.","o":["Đánh giá được mức độ số hoá của phòng kế toán theo thang 5 bậc và xác định 5 điểm nghẽn lớn nhất.","Vẽ được sơ đồ quy trình hiện tại và quy trình mục tiêu cho 3 quy trình kế toán cốt lõi.","Chọn được bộ công cụ phù hợp (phần mềm kế toán, lưu trữ, tự động hoá, AI) theo ma trận tiêu chí.","Lập được kế hoạch chuyển đổi số 90 ngày với mục tiêu, người phụ trách, chỉ số đo.","Tính được lợi ích chuyển đổi số bằng giờ công tiết kiệm, lỗi giảm và rủi ro tuân thủ giảm."],"k":"Phòng kế toán vẫn chạy bằng giấy, Excel rời rạc và tin nhắn? Chuyển đổi số không cần ngân sách lớn, chỉ cần một lộ trình đúng.","w":["Hoá đơn điện tử (gồm hoá đơn từ máy tính tiền), ngân hàng số, nộp thuế điện tử đã phổ biến; quy trình giấy không còn theo kịp tốc độ và khối lượng dữ liệu năm 2026.","Từ 01/01/2026, TT 99/2025 thay TT 200/2014 và hộ kinh doanh chuyển sang tự kê khai; nhiều đơn vị phải thiết lập lại hệ thống, đây là thời điểm thuận lợi để số hoá cùng lúc.","AI và công cụ tự động hoá chi phí thấp giúp doanh nghiệp nhỏ cũng chuyển đổi số được; người đi trước sẽ có lợi thế chi phí và tốc độ."],"dl":["Bảng tự đánh giá mức độ số hoá phòng kế toán 30 tiêu chí.","Bộ mẫu sơ đồ quy trình (mua hàng – thanh toán, bán hàng – thu tiền, khoá sổ – báo cáo) hiện tại và mục tiêu.","Ma trận chọn công cụ và mẫu kế hoạch triển khai 90 ngày.","Bộ prompt AI hỗ trợ vẽ quy trình, soạn SOP, viết thông báo thay đổi cho nhân viên."],"ls":["Chuyển đổi số phòng kế toán là gì và bắt đầu từ đâu","Chuẩn hoá quy trình trước khi số hoá","Số hoá chứng từ và lưu trữ điện tử","Chọn phần mềm kế toán và bộ công cụ số phù hợp","Tự động hoá việc lặp lại: từ quy tắc đơn giản đến workflow","Ứng dụng AI an toàn trong phòng kế toán","Quản lý thay đổi: đưa con người đi cùng công nghệ","Lộ trình chuyển đổi số 90 ngày và đo lường kết quả"],"l1":{"t":"Chuyển đổi số phòng kế toán là gì và bắt đầu từ đâu","sum":"Bài mở đầu làm rõ chuyển đổi số không chỉ là mua phần mềm. Học viên hiểu ba tầng số hoá và tự đánh giá hiện trạng.","points":["Ba tầng: số hoá dữ liệu (giấy thành file), số hoá quy trình (luồng công việc trên hệ thống), chuyển đổi cách làm (dữ liệu và tự động hoá dẫn dắt quyết định).","Thang 5 bậc: giấy tờ – Excel rời rạc – phần mềm kế toán – quy trình liên thông – tự động hoá và phân tích.","Sai lầm phổ biến: mua phần mềm đắt nhưng giữ quy trình cũ, không đào tạo, không có người phụ trách.","Bắt đầu từ điểm đau lớn nhất: thất lạc chứng từ, khoá sổ chậm, đối chiếu mất thời gian, trễ hạn nộp.","Chuyển đổi số là hành trình liên tục; mỗi giai đoạn 90 ngày cần có kết quả đo được."],"case":"Công ty TNHH Nội thất Gỗ Phố Hiến mua phần mềm kế toán mới nhưng nhân viên vẫn ghi sổ tay rồi nhập lại cuối tháng. Sau khi đánh giá theo thang 5 bậc, công ty nhận ra mình ở bậc 2 về quy trình và bắt đầu từ chuẩn hoá luồng chứng từ trước.","trend":"Giai đoạn 2026–2030, doanh nghiệp dự kiến phải kết nối dữ liệu với cơ quan thuế, ngân hàng và đối tác nhiều hơn. Phòng kế toán chưa số hoá sẽ trở thành điểm nghẽn của cả doanh nghiệp.","practice":"Hoàn thành bảng tự đánh giá 30 tiêu chí và xác định 5 điểm đau lớn nhất của phòng kế toán. Đầu ra: bảng đánh giá và danh sách điểm đau có xếp hạng.","takeaway":"Chuyển đổi số bắt đầu từ quy trình, không bắt đầu từ phần mềm."}},{"id":"KH098","code":"kh098","f":"CN","fn":"Công cụ số & AI","t":"Xây dựng dịch vụ kế toán tự do (freelance)","lv":3,"ln":"Trung cấp","h":16,"p":299000,"d":"Khoá học hướng dẫn xây dựng dịch vụ kế toán tự do bài bản: hiểu giới hạn pháp lý, định vị và chọn khách hàng, thiết kế gói và định giá, hợp đồng phân định trách nhiệm, tìm khách, vận hành nhiều khách bằng công cụ số và AI, quản lý rủi ro và nghĩa vụ thuế của chính mình. Học viên làm việc với bộ mẫu thật: bảng giá, hợp đồng, quy trình tiếp nhận khách, lịch hạn nộp tổng. Kết thúc khoá, bạn có kế hoạch kinh doanh dịch vụ 12 tháng và bộ công cụ vận hành sẵn sàng nhận khách đầu tiên.","a":"Dành cho kế toán có kinh nghiệm muốn làm thêm hoặc làm tự do, kế toán đang làm dịch vụ nhỏ lẻ muốn chuyên nghiệp hoá và người định hướng mở văn phòng kế toán.","o":["Xác định được phạm vi dịch vụ được phép cung cấp theo năng lực, chứng chỉ và quy định hiện hành.","Thiết kế được 3 gói dịch vụ và bảng giá dựa trên khối lượng công việc và giá trị cho khách hàng.","Soạn được hợp đồng dịch vụ phân định rõ trách nhiệm, phạm vi, phí và bảo mật.","Xây được quy trình vận hành phục vụ đồng thời 10–20 khách với lịch hạn nộp tổng và công cụ số.","Lập được kế hoạch tìm khách và mục tiêu doanh thu 12 tháng."],"k":"Năm 2026, hàng triệu hộ kinh doanh chuyển sang tự kê khai và cần người làm sổ; đây là thời điểm vàng để kế toán xây dịch vụ của riêng mình.","w":["Từ 01/01/2026 bỏ thuế khoán và lệ phí môn bài, hộ kinh doanh chuyển sang tự kê khai (NQ 198/2025/QH15); nhu cầu dịch vụ kế toán – thuế cho hộ và doanh nghiệp siêu nhỏ tăng mạnh.","Kinh doanh trên sàn thương mại điện tử, nền tảng số với cơ chế sàn khấu trừ nộp thay (NĐ 117/2025) tạo ra nhóm khách hàng mới cần tư vấn đối chiếu và quyết toán.","Phần mềm online, chữ ký số, AI và tự động hoá giúp một kế toán phục vụ nhiều khách hơn với chất lượng cao, chi phí khởi nghiệp thấp."],"dl":["Mẫu bảng giá 3 gói dịch vụ cho hộ kinh doanh, doanh nghiệp siêu nhỏ, doanh nghiệp nhỏ kèm file tính giá.","Mẫu hợp đồng dịch vụ kế toán – thuế và biên bản bàn giao chứng từ, hồ sơ.","Bộ quy trình vận hành: tiếp nhận khách, checklist chứng từ tháng, lịch hạn nộp tổng cho danh mục khách.","Bộ prompt AI cho kế toán dịch vụ: soạn bài đăng, email tư vấn, nhắc chứng từ, báo cáo tháng cho khách."],"ls":["Mô hình kế toán tự do và giới hạn pháp lý cần biết","Định vị dịch vụ và chọn khách hàng mục tiêu","Thiết kế gói dịch vụ và định giá có lãi","Hợp đồng dịch vụ và phân định trách nhiệm","Tìm khách hàng và xây thương hiệu cá nhân bằng nội dung số","Vận hành nhiều khách hàng bằng quy trình và công cụ số","Quản lý rủi ro nghề nghiệp, bảo mật và kiểm soát chất lượng","Nghĩa vụ thuế của chính bạn và kế hoạch phát triển 12 tháng"],"l1":{"t":"Mô hình kế toán tự do và giới hạn pháp lý cần biết","sum":"Bài mở đầu làm rõ các mô hình hành nghề và ranh giới pháp lý. Học viên xác định mình được làm gì, cần điều kiện gì và rủi ro nếu làm sai.","points":["Các mô hình: làm thêm theo hợp đồng cá nhân, hộ kinh doanh dịch vụ kế toán, doanh nghiệp dịch vụ kế toán, cộng tác với đại lý thuế hoặc văn phòng kế toán.","Kinh doanh dịch vụ kế toán và dịch vụ làm thủ tục về thuế có điều kiện về chứng chỉ, đăng ký hành nghề theo Luật Kế toán và Luật Quản lý thuế 38/2019/QH14; cần tra cứu điều kiện hiện hành trước khi cung cấp dịch vụ.","Phân biệt làm kế toán cho một doanh nghiệp theo hợp đồng lao động hoặc hợp đồng dịch vụ với việc cung cấp dịch vụ công khai cho nhiều khách.","Trách nhiệm nghề nghiệp: sai sót gây thiệt hại cho khách có thể dẫn tới bồi thường; cần hợp đồng rõ ràng và quy trình kiểm soát chất lượng.","Lộ trình hợp lý: bắt đầu làm thêm với ít khách, tích luỹ kinh nghiệm, hoàn thiện điều kiện hành nghề rồi mở rộng."],"case":"Chị Thảo, kế toán tổng hợp 6 năm, nhận làm sổ cho 5 hộ kinh doanh vào buổi tối. Trước khi mở rộng lên 15 khách, chị rà soát điều kiện hành nghề, hoàn thiện chứng chỉ và đăng ký hình thức phù hợp, đồng thời chuẩn hoá hợp đồng cho tất cả khách.","trend":"Nhu cầu dịch vụ kế toán – thuế cho hộ kinh doanh và doanh nghiệp siêu nhỏ dự kiến tăng mạnh 2026–2030. Thị trường cũng sẽ đòi hỏi chuyên nghiệp hơn, ưu tiên người hành nghề hợp pháp, minh bạch.","practice":"Liệt kê dịch vụ bạn định cung cấp, đối chiếu với năng lực, chứng chỉ hiện có và điều kiện cần bổ sung. Đầu ra: bảng dịch vụ – điều kiện – kế hoạch hoàn thiện.","takeaway":"Hành nghề đúng luật là nền móng đầu tiên của uy tín."}},{"id":"KH099","code":"kh099","f":"CN","fn":"Công cụ số & AI","t":"Tiếng Anh chuyên ngành kế toán, thuế","lv":2,"ln":"Cơ bản","h":12,"p":199000,"d":"Khoá học trang bị tiếng Anh chuyên ngành kế toán – thuế theo tình huống công việc thật: đọc hiểu báo cáo tài chính, thuật ngữ theo phần hành, giải thích hệ thống thuế Việt Nam, viết email, làm việc với kiểm toán và họp trực tuyến. Mỗi bài học có bảng thuật ngữ song ngữ, mẫu câu dùng ngay, bài luyện viết – nói và cách dùng AI để luyện tập, kiểm tra. Kết thúc khoá, bạn tự tin trao đổi công việc với công ty mẹ, kiểm toán và đối tác nước ngoài.","a":"Dành cho kế toán làm tại doanh nghiệp FDI, công ty có đối tác nước ngoài, kế toán dịch vụ phục vụ khách nước ngoài và sinh viên định hướng chứng chỉ quốc tế.","o":["Sử dụng đúng khoảng 300 thuật ngữ kế toán, thuế, kiểm toán thông dụng theo từng phần hành.","Đọc hiểu và tóm tắt được báo cáo tài chính, thuyết minh bằng tiếng Anh.","Giải thích được các loại thuế chính của Việt Nam năm 2026 (CIT, VAT, PIT, FCT, social insurance) bằng tiếng Anh chính xác.","Viết được email báo cáo, giải trình, yêu cầu thông tin chuyên nghiệp theo mẫu chuẩn.","Trình bày được số liệu tháng và trả lời câu hỏi của kiểm toán, công ty mẹ trong cuộc họp trực tuyến."],"k":"Kế toán biết tiếng Anh chuyên ngành ở doanh nghiệp FDI thường có thu nhập và cơ hội thăng tiến vượt trội; rào cản chỉ là vài trăm thuật ngữ và mẫu câu đúng.","w":["Lộ trình áp dụng IFRS (QĐ 345/QĐ-BTC năm 2020) và TT 99/2025 thay TT 200/2014 từ 01/01/2026 khiến thuật ngữ quốc tế xuất hiện ngày càng nhiều trong công việc kế toán Việt Nam.","Dòng vốn FDI và chuỗi cung ứng quốc tế, cùng thuế tối thiểu toàn cầu (NQ 107/2023/QH15) cho tập đoàn lớn, đòi hỏi kế toán giải thích được số liệu và chính sách thuế Việt Nam bằng tiếng Anh.","AI dịch thuật và trợ lý viết giúp luyện tiếng Anh nhanh hơn bao giờ hết, nhưng chỉ người nắm thuật ngữ mới kiểm tra được bản dịch đúng hay sai."],"dl":["Từ điển thuật ngữ song ngữ 300 mục theo phần hành, có ví dụ câu và phát âm.","Bộ 25 mẫu email tiếng Anh cho kế toán: báo cáo, giải trình, yêu cầu chứng từ, trả lời kiểm toán.","Bảng giải thích hệ thống thuế Việt Nam 2026 bằng tiếng Anh (1 trang) dùng gửi công ty mẹ.","Bộ prompt AI để luyện hội thoại, sửa email, kiểm tra thuật ngữ và mô phỏng phỏng vấn tiếng Anh."],"ls":["Thuật ngữ nền tảng và phương trình kế toán bằng tiếng Anh","Đọc hiểu báo cáo tài chính và thuyết minh bằng tiếng Anh","Từ vựng theo phần hành: tiền, công nợ, kho, tài sản, chi phí","Giải thích hệ thống thuế Việt Nam 2026 bằng tiếng Anh","Lương, bảo hiểm, hợp đồng lao động và báo cáo nhân sự","Viết email và báo cáo công việc bằng tiếng Anh chuyên nghiệp","Làm việc với kiểm toán và trả lời câu hỏi bằng tiếng Anh","Thuyết trình số liệu và họp trực tuyến bằng tiếng Anh"],"l1":{"t":"Thuật ngữ nền tảng và phương trình kế toán bằng tiếng Anh","sum":"Bài mở đầu xây vốn thuật ngữ cốt lõi để đọc mọi tài liệu kế toán tiếng Anh. Học viên nắm cách gọi các yếu tố của báo cáo và nguyên tắc kế toán cơ bản.","points":["Phương trình kế toán: Assets = Liabilities + Equity; các yếu tố Revenue, Expenses, Profit/Loss.","Thuật ngữ ghi sổ: debit, credit, journal entry, general ledger, trial balance, chart of accounts, accrual, prepayment.","Nguyên tắc cơ bản: accrual basis (cơ sở dồn tích), going concern (hoạt động liên tục), consistency (nhất quán), prudence (thận trọng), materiality (trọng yếu).","Phân biệt cách dùng: 'account' (tài khoản), 'accounts' (báo cáo/sổ sách), 'accountant' (kế toán viên), 'accounting' (công tác kế toán).","Viết số và ngày trong tiếng Anh: dấu phẩy phân cách hàng nghìn, dấu chấm thập phân, ngược với cách viết tiếng Việt; ghi rõ VND và đơn vị (thousand, million, billion)."],"case":"Kế toán Công ty TNHH Linh kiện Điện tử Việt Nhật gửi báo cáo cho công ty mẹ ghi '1.250.000' khiến bên nhận hiểu là 1,25. Sau khi chuẩn hoá cách viết số theo chuẩn tiếng Anh (1,250,000 VND) và ghi đơn vị rõ ràng, không còn hiểu nhầm.","trend":"Báo cáo song ngữ và dữ liệu tài chính chia sẻ xuyên biên giới ngày càng phổ biến trong 2026–2030. Kế toán cần chuẩn hoá cả thuật ngữ lẫn định dạng số liệu.","practice":"Dịch 20 thuật ngữ cốt lõi và viết 5 câu ví dụ dùng trong công việc; nhờ AI kiểm tra và tự đối chiếu với từ điển khoá học. Đầu ra: bảng 20 thuật ngữ và 5 câu.","takeaway":"Sai một dấu phân cách số có thể sai cả nghìn lần giá trị."}}];
